package com.hdmapreforged;

import lombok.*;

/**
 * One of the maps, in world tile coordinates: the game's own world maps, the map of everything, and our maps of the
 * dungeons the game's map lacks, which show the map of everything's tiles ({@code tiles}).
 */
@RequiredArgsConstructor
final class BaseMap
{
    static final int SURFACE = 0;
    static final int FULL = -1;

    final int id;
    final String name;
    final int minX;
    final int minY;
    final int maxX;
    final int maxY;
    final int centerX;
    final int centerY;
    /** The map whose tiles draw this one: itself, or {@link #FULL}. */
    final int tiles;
    /** The map list it is of (set by it): its region table tells on which floor it draws some ground. */
    BaseMaps maps;

    boolean contains(int x, int y)
    {
        return x >= minX && x < maxX && y >= minY && y < maxY;
    }

    long area()
    {
        return (long) (maxX - minX) * (maxY - minY);
    }

    public String toString()
    {
        return name;
    }
}

package com.hdmapreforged;

import static com.hdmapreforged.BaseMap.*;

import com.hdmapreforged.route.*;
import com.google.gson.*;
import java.io.*;
import java.util.*;
import java.util.function.*;
import net.runelite.api.coords.*;

/** A map version's map list (our map server's maps.json); its region table decides where bounds overlap. */
final class BaseMaps
{
    final List<BaseMap> sorted;
    final Map<Integer, BaseMap> byId = new HashMap<>();
    RegionTable regions = new RegionTable();
    /** The map version they are of; null when not known. */
    String version;

    BaseMaps(List<BaseMap> maps)
    {
        var list = new ArrayList<BaseMap>(maps);
        // Surface first, then the combined map, then alphabetical.
        list.sort(Comparator.comparingInt((BaseMap m) -> m.id == SURFACE ? 0 : m.id == FULL ? 1 : 2)
            .thenComparing(m -> m.name, String.CASE_INSENSITIVE_ORDER));
        sorted = Collections.unmodifiableList(list);
        for (var map : list)
        {
            byId.put(map.id, map);
            map.maps = this;
        }
    }

    static final int MAX_COORDINATE = 20_000;
    static final int MAX_NAME = 100;

    /** Implausible entries are left out, not the whole list; an unreadable list gives no maps. */
    static BaseMaps parse(Gson gson, Reader json)
    {
        JsonArray array;
        try
        {
            array = gson.fromJson(json, JsonArray.class);
        }
        catch (RuntimeException e)
        {
            return new BaseMaps(Collections.emptyList());
        }
        var maps = new ArrayList<BaseMap>();
        var ids = new HashSet<Integer>();
        for (var element : array == null ? new JsonArray() : array)
        {
            var map = map(element);
            if (map != null && ids.add(map.id))
            {
                maps.add(map);
            }
        }
        return new BaseMaps(maps);
    }

    static BaseMap map(JsonElement element)
    {
        try
        {
            JsonObject o = element.getAsJsonObject();
            var bounds = o.getAsJsonArray("bounds");
            var min = bounds.get(0).getAsJsonArray();
            var max = bounds.get(1).getAsJsonArray();
            var center = o.has("center") ? o.getAsJsonArray("center") : null;
            int minX = min.get(0).getAsInt();
            int minY = min.get(1).getAsInt();
            int maxX = max.get(0).getAsInt();
            int maxY = max.get(1).getAsInt();
            int id = o.get("mapId").getAsInt();
            String name = o.get("name").getAsString();
            int tiles = o.has("tiles") ? o.get("tiles").getAsInt() : id;
            if (!inWorld(minX) || !inWorld(minY) || !inWorld(maxX) || !inWorld(maxY) || maxX <= minX || maxY <= minY
                || id < FULL || name.trim().isEmpty() || name.length() > MAX_NAME
                || tiles != id && tiles != FULL)
            {
                return null;
            }
            int centerX = center != null ? center.get(0).getAsInt() : (minX + maxX) / 2;
            int centerY = center != null ? center.get(1).getAsInt() : (minY + maxY) / 2;
            if (!inWorld(centerX) || !inWorld(centerY))
            {
                centerX = (minX + maxX) / 2;
                centerY = (minY + maxY) / 2;
            }
            return new BaseMap(id, name, minX, minY, maxX, maxY, centerX, centerY, tiles);
        }
        catch (RuntimeException e)
        {
            return null;
        }
    }

    static boolean inWorld(int coordinate)
    {
        return coordinate >= 0 && coordinate <= MAX_COORDINATE;
    }

    BaseMap byId(int id)
    {
        return byId.get(id);
    }

    BaseMap surface()
    {
        var surface = byId.get(SURFACE);
        return surface != null ? surface : sorted.get(0);
    }

    /** One of the maps drawing the point's region (maps may share one), or the map {@link #find} gives. */
    boolean draws(BaseMap map, int x, int y)
    {
        if (map == null || !map.contains(x, y))
        {
            return false;
        }
        var owners = drawers(x, y);
        return owners != null && Arrays.stream(owners).anyMatch(id -> id == map.id) || find(x, y) == map;
    }

    /** The owners of the spot's 8×8 zone where known, else the region's owners; null when not known. */
    int[] drawers(int x, int y)
    {
        var zone = regions.zoneOwners(x, y);
        return zone != null ? zone : regions.owners(RegionTable.regionId(x, y));
    }

    /**
     * The map that draws the ground of a game point's floor where the zone's own map does not draw it on that floor (the
     * region table's floor lines), or null.
     */
    BaseMap floorMap(WorldPoint game)
    {
        var found = regions.floorOverride(game.getX(), game.getY(), game.getPlane());
        var map = found == null ? null : byId(found[0]);
        return map != null && (map.id == FULL || map.contains(game.getX(), game.getY())) ? map : null;
    }

    /**
     * The floor {@code on} draws a game point's ground on where the region table says it is not the point's own (the
     * Brimhaven Dungeon's raised paths, walked on floor 2, drawn on floor 1), or -1. Any map drawn with the same tiles
     * draws it there.
     */
    int drawnFloor(BaseMap on, WorldPoint game)
    {
        var found = on == null ? null : regions.floorOverride(game.getX(), game.getY(), game.getPlane());
        var map = found == null ? null : byId(found[0]);
        return map != null && map.tiles == on.tiles ? found[1] : -1;
    }

    /**
     * The game's floor a spot of a map's drawn floor stands for: {@code game} (where the map's moves put it), unless that
     * is no ground ({@code ground}) and a floor the region table draws on {@code drawnFloor} there is: then that floor.
     */
    WorldPoint gameFloor(BaseMap on, WorldPoint game, int drawnFloor, Predicate<WorldPoint> ground)
    {
        if (on == null || ground == null || ground.test(game))
        {
            return game;
        }
        for (int d = 1; d < 4; d++)
        {
            for (int floor : new int[]{game.getPlane() - d, game.getPlane() + d})
            {
                var other = floor < 0 || floor > 3 ? null : new WorldPoint(game.getX(), game.getY(), floor);
                if (other != null && drawnFloor(on, other) == drawnFloor && ground.test(other))
                {
                    return other;
                }
            }
        }
        return game;
    }

    /** The map drawing a game point elsewhere when one does (the Kalphite Lair), else {@link #find(int, int)}. */
    BaseMap find(WorldPoint game)
    {
        if (HousePlan.contains(game.getX(), game.getY()))
        {
            // One's house is drawn at the surface map's edge.
            return byId(SURFACE);
        }
        var floor = floorMap(game);
        if (floor != null)
        {
            return floor;
        }
        var drawn = WorldMapMoves.drawn(game);
        var moved = drawn == null ? null : byId(drawn.map);
        // Some moves put a place outside the bounds of the map they name.
        if (moved != null && moved.contains(drawn.point.getX(), drawn.point.getY()))
        {
            return moved;
        }
        var found = find(game.getX(), game.getY());
        if (found != null && WorldMapMoves.covers(found.id, game.getX(), game.getY()))
        {
            // That map shows a moved place here: the smallest other map that draws the spot.
            BaseMap other = null;
            for (var map : sorted)
            {
                if (map != found && map.id != FULL && map.contains(game.getX(), game.getY())
                    && !WorldMapMoves.covers(map.id, game.getX(), game.getY())
                    && (other == null || map.area() < other.area()))
                {
                    other = map;
                }
            }
            return other != null ? other : byId(FULL);
        }
        return found;
    }

    /** Whether a map shows this game point where it is, not a moved place instead. */
    boolean drawsGame(BaseMap map, WorldPoint game)
    {
        if (map != null && regions.floorOverride(game.getX(), game.getY(), game.getPlane()) != null)
        {
            // Its floor's ground is drawn by the map the table names (and every map with the same tiles).
            return map.contains(game.getX(), game.getY()) && drawnFloor(map, game) >= 0;
        }
        return map != null && draws(map, game.getX(), game.getY())
            && !WorldMapMoves.covers(map.id, game.getX(), game.getY());
    }

    /**
     * The smallest map drawing the point's region; the map of everything where the region has none; else the smallest
     * map containing the point, and the map of everything last. Null when no map holds it.
     */
    BaseMap find(int x, int y)
    {
        var full = byId.get(FULL);
        boolean fullDraws = full != null && full.contains(x, y);
        var owners = drawers(x, y);
        BaseMap best = null;
        if (owners != null)
        {
            for (int id : owners)
            {
                var map = byId.get(id);
                if (map != null && map.contains(x, y) && (best == null || map.area() < best.area()))
                {
                    best = map;
                }
            }
            if (best != null || owners.length == 0 && fullDraws)
            {
                return best != null ? best : full;
            }
        }
        for (var map : sorted)
        {
            if (map.id != FULL && map.contains(x, y) && (best == null || map.area() < best.area()))
            {
                best = map;
            }
        }
        // The map of everything draws all of the game's ground: where no other map does, it shows the spot.
        return best != null ? best : fullDraws ? full : null;
    }
}

package com.hdmapreforged;

import com.hdmapreforged.route.*;
import java.util.*;
import java.util.regex.*;
import lombok.*;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.*;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.*;

/**
 * The route's next fairy ring in the ring's travel log, as Shortest Path shows its own: its code in green, scrolled to.
 * Only the log's look changes; nothing is dialled or clicked.
 */
@RequiredArgsConstructor
final class FairyRingLog
{
    static final int GREEN = 0x00FF00;
    /** "Fairy ring: CKS", "House fairy ring: BKS", "Fairy ring: AIR, DLR, DJQ, then AJS". */
    static final Pattern RING = Pattern.compile("airy ring: ((?:[A-Z]{3}(?:, then |, )?)+)");
    static final Pattern CODE = Pattern.compile("[A-Z]{3}");

    final RouteFeature routes;
    boolean open;

    /** The codes of the route's first fairy ring step, in the order dialled; empty without one. */
    static List<String> codes(Route route)
    {
        for (var step : route == null ? List.<Route.Step>of() : route.steps)
        {
            Matcher ring = step.name == null ? null : RING.matcher(step.name);
            if (ring != null && ring.find())
            {
                var codes = new ArrayList<String>();
                Matcher code = CODE.matcher(ring.group(1));
                while (code.find())
                {
                    codes.add(code.group());
                }
                return codes;
            }
        }
        return List.of();
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event)
    {
        open |= event.getGroupId() == InterfaceID.FAIRYRINGS_LOG;
    }

    @Subscribe
    public void onWidgetClosed(WidgetClosed event)
    {
        open &= event.getGroupId() != InterfaceID.FAIRYRINGS_LOG;
    }

    /**
     * Every frame while the log is open, as Shortest Path does: the game draws its list again (on opening, searching,
     * sorting) and puts back the scroll it keeps itself.
     */
    @Subscribe
    public void onPostClientTick(PostClientTick event)
    {
        List<String> codes = open ? codes(routes.shown) : List.of();
        if (codes.isEmpty())
        {
            return;
        }
        Client client = routes.client;
        Widget contents = client.getWidget(InterfaceID.FairyringsLog.CONTENTS);
        // Favourites' codes in green too; the list scrolls to the first code's row.
        Widget faves = client.getWidget(InterfaceID.FairyringsLog.FAVES);
        mark(faves == null ? null : faves.getStaticChildren(), codes);
        Widget first = mark(contents == null ? null : contents.getDynamicChildren(), codes);
        if (first == null)
        {
            return;
        }
        int scroll = Math.max(0, Math.min(first.getRelativeY(), contents.getScrollHeight() - contents.getHeight()));
        // No client script for the scrollbar's thumb: reviewers flag running them.
        contents.setScrollY(scroll);
        contents.revalidateScroll();
    }

    /** Colours the codes among these widgets green; the first code's widget, or null. */
    static Widget mark(Widget[] widgets, List<String> codes)
    {
        Widget first = null;
        for (Widget widget : widgets == null ? new Widget[0] : widgets)
        {
            // The game writes the codes spaced out: "B K R".
            int at = widget == null ? -1 : codes.indexOf(String.valueOf(widget.getText()).replace(" ", ""));
            if (at >= 0)
            {
                widget.setTextColor(GREEN);
                first = at == 0 ? widget : first;
            }
        }
        return first;
    }
}

package com.hdmapreforged;

import java.awt.*;
import javax.swing.*;

/** Takes the scroll pane's width; scrolls only up and down. */
class Fitted extends JPanel implements Scrollable
{
    /** What a page's scroll keeps in view of the page before. */
    final int overlap;

    Fitted(LayoutManager layout, int overlap)
    {
        super(layout);
        this.overlap = overlap;
    }

    public Dimension getPreferredScrollableViewportSize()
    {
        return getPreferredSize();
    }

    public int getScrollableUnitIncrement(Rectangle visible, int orientation, int direction)
    {
        return 16;
    }

    public int getScrollableBlockIncrement(Rectangle visible, int orientation, int direction)
    {
        return visible.height - overlap;
    }

    public boolean getScrollableTracksViewportWidth()
    {
        return true;
    }

    public boolean getScrollableTracksViewportHeight()
    {
        return false;
    }
}

package com.hdmapreforged;

import java.awt.*;
import javax.swing.*;
import net.runelite.client.ui.*;

/** A panel floating over the map (card, search results, custom routes): a title bar with fold and close buttons. */
final class Floating extends JPanel
{
    static final int BAR = 24;
    /** The soft white of names and buttons on the map. */
    static final Color LIGHT = new Color(200, 200, 205);

    final JPanel bar = new JPanel(new BorderLayout(4, 0));
    final JButton fold = small("–", "Fold up");
    JComponent content;
    boolean folded;

    Floating(String title, Runnable close)
    {
        super(new BorderLayout());
        setBorder(BorderFactory.createLineBorder(MapView.CONTROL_EDGE));
        setBackground(ColorScheme.DARKER_GRAY_COLOR);
        bar.setBackground(new Color(24, 26, 30));
        bar.setBorder(BorderFactory.createEmptyBorder(0, 8, 0, 2));
        JLabel name = new JLabel(title);
        name.setForeground(LIGHT);
        name.setFont(name.getFont().deriveFont(Font.BOLD));
        bar.add(name, BorderLayout.CENTER);
        JPanel buttons = new JPanel(new BorderLayout(2, 0));
        buttons.setOpaque(false);
        fold.addActionListener(e -> setFolded(!folded));
        buttons.add(fold, BorderLayout.WEST);
        JButton shut = small("×", "Close");
        shut.addActionListener(e -> close.run());
        buttons.add(shut, BorderLayout.EAST);
        bar.add(buttons, BorderLayout.EAST);
        bar.setPreferredSize(new Dimension(10, BAR));
        add(bar, BorderLayout.NORTH);
    }

    /** Replaces the content below the bar, matching the current fold state. */
    void setContent(JComponent shown)
    {
        if (content != null && content.getParent() == this)
        {
            remove(content);
        }
        content = shown;
        add(shown, BorderLayout.CENTER);
        shown.setVisible(!folded);
        revalidate();
    }

    void setFolded(boolean fold)
    {
        folded = fold;
        this.fold.setText(fold ? "+" : "–");
        this.fold.setToolTipText(fold ? "Unfold" : "Fold up");
        if (content != null)
        {
            content.setVisible(!fold);
        }
        firePropertyChange("folded", !fold, fold);
        revalidate();
        repaint();
    }

    /** Only its bar when folded, else the bar and {@code contentHeight}. */
    int height(int contentHeight)
    {
        return BAR + 2 + (folded ? 0 : contentHeight);
    }

    static JButton small(String text, String tip)
    {
        JButton button = new JButton(text);
        button.setFocusable(false);
        button.setMargin(new Insets(0, 6, 0, 6));
        button.setBorderPainted(false);
        button.setContentAreaFilled(false);
        button.setForeground(LIGHT);
        button.setToolTipText(tip);
        return button;
    }
}

package com.hdmapreforged;

import static java.lang.Math.*;
import static com.hdmapreforged.MapView.*;

import java.text.*;
import net.runelite.api.*;
import java.awt.*;
import java.awt.geom.*;
import java.awt.image.*;
import java.util.*;
import java.util.List;
import java.util.function.*;
import lombok.*;
import net.runelite.api.coords.*;

/** The friends button at the map's bottom left, opening into the party list and a member's details. Swing thread only. */
@RequiredArgsConstructor
final class FriendsWidget implements Widget
{
    @RequiredArgsConstructor
    static final class Member
    {
        final long id;
        final String name;
    }

    @RequiredArgsConstructor
    static final class Row
    {
        final String name;
        final int world;
        final WorldPoint point;
        final Color color;
        /** The party member's id, or -1 for a friend from the game's list. */
        final long id;
    }

    interface Images
    {
        BufferedImage item(int id, int quantity);

        BufferedImage skill(int ordinal);

        default BufferedImage sprite(int id)
        {
            return null;
        }
    }

    static final Color OTHER_WORLD = new Color(255, 190, 120);
    static final Color FRIEND = new Color(150, 150, 160);
    static final Color WORLD = new Color(190, 190, 195);
    static final Font ROW = new Font(Font.SANS_SERIF, Font.PLAIN, 13);
    static final int WIDTH = 256;
    static final int LEFT = 12;
    static final int ROW_HEIGHT = 22;
    static final NumberFormat AMOUNT = NumberFormat.getIntegerInstance();

    final Supplier<List<PartyMapMembers.Marker>> party;
    final Supplier<List<Member>> group;
    final BooleanSupplier inGroup;
    final IntSupplier myWorld;
    final Supplier<Boolean> enabled;
    final Consumer<Row> focus;
    final Runnable repaint;
    /** Repaints while drops rise; made by the caller with the same repaint. */
    final PartyMapOverlay.Ticker ticker;
    boolean dropsMoving;
    boolean open;
    long selected = -1;
    int page;
    boolean folded;
    LongFunction<PartyMapMembers.Gear> gear = id -> null;
    Images images;

    LongFunction<List<PartyMapMembers.Drop>> drops = id -> Collections.emptyList();

    long selected()
    {
        return open ? selected : -1;
    }

    BooleanSupplier canJoin = () -> false;
    Runnable join = () -> { };

    void show(long id)
    {
        open = true;
        selected = id;
    }

    static List<Row> rows(List<PartyMapMembers.Marker> party, List<Member> group)
    {
        var rows = new ArrayList<Row>();
        var seen = new HashSet<String>();
        var ids = new HashSet<Long>();
        for (var marker : party)
        {
            String name = marker.name != null ? marker.name : "Party member";
            if (seen.add(PartyMapOverlay.nameKey(name)))
            {
                ids.add(marker.id);
                rows.add(new Row(name, marker.world, marker.point, PartyMapOverlay.color(marker.id), marker.id));
            }
        }
        for (Member member : group)
        {
            // Not logged in: nothing to show.
            if (member.name == null)
            {
                continue;
            }
            String name = member.name;
            if (!ids.contains(member.id) && seen.add(PartyMapOverlay.nameKey(name)))
            {
                rows.add(new Row(name, 0, null, null, member.id));
            }
        }
        return rows;
    }

    public void paint(Graphics2D g, int width, int height, int bottom, Clicks clicks)
    {
        dropsMoving = false;
        try
        {
            paintWidget(g, width, bottom, clicks);
        }
        finally
        {
            ticker.painted(dropsMoving);
        }
    }

    List<Member> groupNow()
    {
        try
        {
            return group.get();
        }
        catch (ConcurrentModificationException e)
        {
            // Changed on another thread while read; the next frame has them.
            return Collections.emptyList();
        }
    }

    void paintWidget(Graphics2D g, int width, int bottom, Clicks clicks)
    {
        if (!enabled.get())
        {
            return;
        }
        var rows = rows(party.get(), groupNow());
        if (rows.isEmpty() && !inGroup.getAsBoolean())
        {
            if (canJoin.getAsBoolean())
            {
                clicks.add(tab(g, bottom, clicks, "Rejoin party"), join, "Join your last party again");
            }
            return;
        }
        int w = min(WIDTH, width - 24);
        var tab = tab(g, bottom, clicks, "Party · " + rows.size() + (open ? "  ▾" : "  ▴"));
        double tabTop = tab.getY();
        clicks.add(tab, () -> {
            open = !open;
            repaint.run();
        }, open ? "Close the list" : "Your party: click someone to see where they are");
        if (!open)
        {
            return;
        }
        Row chosen = null;
        for (Row row : rows)
        {
            chosen = row.id == selected && selected >= 0 && images != null ? row : chosen;
        }
        selected = chosen != null ? selected : -1;
        if (rows.isEmpty())
        {
            String text = "No one else in your party yet";
            g.setFont(ROW);
            double boxWidth = max(w, g.getFontMetrics().stringWidth(text) + 20);
            var alone = new RoundRectangle2D.Double(LEFT, tabTop - 4 - ROW_HEIGHT - 6, boxWidth,
                ROW_HEIGHT + 6, 10, 10);
            box(g, alone, CONTROL_FILL, CONTROL_EDGE);
            g.setColor(FRIEND);
            g.drawString(text, LEFT + 10, middle(alone.getCenterY(), g.getFontMetrics()));
            return;
        }
        // Opens upwards, as many rows as fit (with room for a chosen one's folded details above, so one can switch
        // between them); the last line then says how many more.
        int fit = max(1, (int) ((tabTop - 60 - (chosen != null ? 34 + STATUS_H : 0)) / ROW_HEIGHT));
        var shown = rows.size() > fit ? rows.subList(0, max(1, fit - 1)) : rows;
        int more = rows.size() - shown.size();
        int lines = shown.size() + (more > 0 ? 1 : 0);
        double listTop = tabTop - 4 - lines * ROW_HEIGHT - 6;
        var list = new RoundRectangle2D.Double(LEFT, listTop, w, lines * ROW_HEIGHT + 6, 10, 10);
        box(g, list, CONTROL_FILL, CONTROL_EDGE);
        g.setFont(ROW);
        var metrics = g.getFontMetrics();
        int mine = myWorld.getAsInt();
        for (int i = 0; i < shown.size(); i++)
        {
            Row row = shown.get(i);
            double top = listTop + 3 + i * ROW_HEIGHT;
            var area = new RoundRectangle2D.Double(LEFT + 3, top, w - 6, ROW_HEIGHT, 8, 8);
            if (row.point != null || row.id >= 0)
            {
                if (clicks.hovered(area) || row == chosen)
                {
                    g.setColor(CONTROL_HOVER);
                    g.fill(area);
                }
                clicks.add(area, () -> {
                    if (row.point != null)
                    {
                        focus.accept(row);
                    }
                    if (row.id >= 0)
                    {
                        selected = row.id;
                        repaint.run();
                    }
                }, "Look at " + row.name + (row.id >= 0 ? " and what they carry" : ""));
            }
            double cy = top + ROW_HEIGHT / 2.0;
            dot(g, row.color, LEFT + 10, cy - 4);
            String world = row.world > 0 ? "W" + row.world : "";
            int worldWidth = metrics.stringWidth(world);
            g.setColor(row.world > 0 && mine > 0 && row.world != mine ? OTHER_WORLD : WORLD);
            g.drawString(world, LEFT + w - 10 - worldWidth, middle(cy, metrics));
            g.setColor(row.point != null ? Color.WHITE : FRIEND);
            String name = fit(row.name, metrics, w - 38 - worldWidth);
            g.drawString(name, LEFT + 24, middle(cy, metrics));
        }
        if (more > 0)
        {
            double cy = listTop + 3 + shown.size() * ROW_HEIGHT + ROW_HEIGHT / 2.0;
            g.setColor(FRIEND);
            g.drawString("+" + more + " more", LEFT + 24, middle(cy, metrics));
        }
        if (chosen != null)
        {
            paintDetails(g, chosen, LEFT, w, listTop - 4, clicks);
        }
    }

    /** A member's pages, here and in the sidebar. */
    static final String[] PAGES = {"Items", "Worn", "Skills"};
    static final Color BOOSTED = new Color(120, 220, 120);
    static final Color DRAINED = new Color(230, 120, 110);
    static final int SLOT_W = 48;
    static final int SLOT_H = 40;
    static final int SKILL_W = 74;
    static final int SKILL_H = 30;
    /** Every page as tall as the inventory, so switching pages moves nothing. */
    static final int BODY_H = 7 * SLOT_H;
    static final int STATUS_H = Orbs.HEIGHT + 6;
    /** Column and row of each equipment slot, as in the game's worn items tab. */
    static final int[][] WORN = {{1, 0}, {0, 1}, {1, 1}, {0, 2}, {1, 2}, {2, 2}, null, {1, 3}, null, {0, 4},
        {1, 4}, null, {2, 4}, {2, 1}};

    void paintDetails(Graphics2D g, Row row, double x0, int w, double bottomY, Clicks clicks)
    {
        var shared = gear.apply(row.id);
        int panelW = max(w, 4 * Orbs.WIDTH + 3 * 4 + 16);
        int full = 30 + 26 + STATUS_H + BODY_H + 10;
        // Folded (or the map too low for all of it): the name and the orbs only.
        boolean cramped = bottomY - full < 44;
        boolean compact = folded || cramped;
        int height = compact ? 30 + STATUS_H + 4 : full;
        double top = bottomY - height;
        var panel = new RoundRectangle2D.Double(x0, top, panelW, height, 12, 12);
        box(g, panel, CONTROL_FILL, CONTROL_EDGE);
        g.setFont(CONTROL_FONT);
        var title = g.getFontMetrics();
        if (row.point != null)
        {
            // The name looks at them again, as the panel stays open after one looks elsewhere.
            var name = new RoundRectangle2D.Double(x0 + 4, top + 4, panelW - (cramped ? 32 : 54), 22, 8, 8);
            if (clicks.hovered(name))
            {
                g.setColor(CONTROL_HOVER);
                g.fill(name);
            }
            clicks.add(name, () -> focus.accept(row), "Follow " + row.name);
        }
        dot(g, row.color, x0 + 12, top + 11);
        g.setColor(Color.WHITE);
        text(g, fit(row.name, title, panelW - 130), x0 + 26, top + 19);
        if (row.world > 0)
        {
            String world = "W" + row.world;
            g.setFont(ROW);
            var rowMetrics = g.getFontMetrics();
            int mine = myWorld.getAsInt();
            boolean elsewhere = mine > 0 && row.world != mine;
            double right = x0 + panelW - (cramped ? 34 : 56);
            g.setColor(elsewhere ? OTHER_WORLD : WORLD);
            text(g, world, right - rowMetrics.stringWidth(world), top + 20);
        }
        titleButton(g, clicks, title, x0 + panelW - 26, top, "×", () -> {
            selected = -1;
            repaint.run();
        }, "Close");
        if (!cramped)
        {
            titleButton(g, clicks, title, x0 + panelW - 48, top, folded ? "+" : "\u2013", () -> {
                folded = !folded;
                repaint.run();
            }, folded ? "Unfold" : "Fold up: the name and the orbs only");
        }
        if (compact)
        {
            paintStatus(g, shared, x0 + 8, top + 28, panelW - 16);
            paintDrops(g, row.id, x0, top + height - 6, panelW);
            return;
        }
        double tabW = (panelW - 16) / 3.0;
        g.setFont(ROW);
        var metrics = g.getFontMetrics();
        for (int k = 0; k < PAGES.length; k++)
        {
            var tabShape = new RoundRectangle2D.Double(x0 + 8 + k * tabW, top + 30, tabW - 4, 20, 8, 8);
            g.setColor(k == page ? new Color(70, 76, 88, 235) : clicks.hovered(tabShape) ? CONTROL_HOVER : new Color(40, 43, 50, 220));
            g.fill(tabShape);
            g.setColor(k == page ? Color.WHITE : new Color(180, 180, 186));
            text(g, PAGES[k], tabShape.getCenterX() - metrics.stringWidth(PAGES[k]) / 2.0, top + 44);
            int chosen = k;
            clicks.add(tabShape, () -> {
                page = chosen;
                repaint.run();
            }, PAGES[k]);
        }
        paintStatus(g, shared, x0 + 8, top + 56, panelW - 16);
        double y0 = top + 56 + STATUS_H;
        if (shared == null)
        {
            g.setColor(FRIEND);
            text(g, "Nothing shared yet.", x0 + 12, y0 + 16);
            text(g, "They share it with this plugin's setting.", x0 + 12, y0 + 32);
            return;
        }
        double gridLeft = x0 + (panelW - (page == 2 ? 3 * SKILL_W : (page == 0 ? 4 : 3) * SLOT_W)) / 2.0;
        if (page == 0)
        {
            for (int k = 0; k < HdMapPartyGear.INVENTORY; k++)
            {
                slot(g, gridLeft + (k % 4) * SLOT_W, y0 + (k / 4) * SLOT_H, shared.inventory[k], shared.quantities[k]);
            }
        }
        else if (page == 1)
        {
            for (int k = 0; k < WORN.length; k++)
            {
                if (WORN[k] == null)
                {
                    continue;
                }
                double sx = gridLeft + WORN[k][0] * SLOT_W;
                double sy = y0 + WORN[k][1] * SLOT_H;
                g.setColor(new Color(255, 255, 255, 18));
                g.fill(new RoundRectangle2D.Double(sx + 2, sy + 1, SLOT_W - 4, SLOT_H - 2, 8, 8));
                slot(g, sx, sy, shared.equipment[k], 1);
            }
        }
        else
        {
            g.setFont(ROW);
            for (int k = 0; k < HdMapPartyGear.SKILLS; k++)
            {
                double sx = gridLeft + (k % 3) * SKILL_W;
                double sy = y0 + (k / 3) * SKILL_H;
                BufferedImage icon = images.skill(k);
                if (icon != null)
                {
                    g.drawImage(icon, (int) sx + 2, (int) sy + 3, 16, 16, null);
                }
                g.setColor(levelColor(shared.boosted[k], shared.levels[k]));
                text(g, level(shared.boosted[k], shared.levels[k]), sx + 22, sy + 16);
            }
        }
        paintDrops(g, row.id, x0, top + 110, panelW);
    }

    static RoundRectangle2D tab(Graphics2D g, int bottom, Clicks clicks, String label)
    {
        g.setFont(CONTROL_FONT);
        var metrics = g.getFontMetrics();
        int tabWidth = floorGroupWidth(metrics);
        double tabTop = bottom - 2 * CONTROL - 6;
        var tab = new RoundRectangle2D.Double(LEFT, tabTop, tabWidth, CONTROL, 10, 10);
        box(g, tab, clicks.hovered(tab) ? CONTROL_HOVER : CONTROL_FILL, CONTROL_EDGE);
        g.setColor(Color.WHITE);
        text(g, label, LEFT + (tabWidth - metrics.stringWidth(label)) / 2.0, middle(tabTop + CONTROL / 2.0, metrics));
        return tab;
    }

    void paintStatus(Graphics2D g, PartyMapMembers.Gear shared, double x, double y, double width)
    {
        if (shared == null)
        {
            return;
        }
        double gap = (width - 4 * Orbs.WIDTH) / 3.0;
        IntFunction<BufferedImage> sprites = images == null ? id -> null : images::sprite;
        int[][] orbs = orbs(shared);
        for (int k = 0; k < orbs.length; k++)
        {
            Orbs.paint(g, (int) (x + k * (Orbs.WIDTH + gap)), (int) y + 2, Orbs.Kind.values()[k], orbs[k][0], orbs[k][1],
                sprites);
        }
    }

    /** Hitpoints, prayer, run energy, special attack: value and most. */
    static int[][] orbs(PartyMapMembers.Gear shared)
    {
        int hp = Skill.HITPOINTS.ordinal();
        int prayer = Skill.PRAYER.ordinal();
        return new int[][]{{shared.boosted[hp], shared.levels[hp]}, {shared.boosted[prayer], shared.levels[prayer]},
            {shared.run, 100}, {shared.special, 100}};
    }

    void paintDrops(Graphics2D g, long id, double x0, double start, int panelW)
    {
        var showing = drops.apply(id);
        if (showing.isEmpty())
        {
            return;
        }
        long now = System.currentTimeMillis();
        g.setFont(CONTROL_FONT);
        var metrics = g.getFontMetrics();
        for (int k = 0; k < showing.size(); k++)
        {
            var drop = showing.get(k);
            double t = min(1, (now - drop.at) / (double) PartyMapMembers.DROP_MS);
            double rise = 1 - pow(1 - t, 3);
            float alpha = (float) (t < 0.7 ? 1 : 1 - (t - 0.7) / 0.3);
            String text = "+" + AMOUNT.format(drop.amount);
            double tx = x0 + panelW - 14 - metrics.stringWidth(text);
            double ty = start + (showing.size() - 1 - k) * 18 - rise * 60;
            Composite old = g.getComposite();
            g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, max(0, alpha)));
            BufferedImage icon = images == null ? null : images.skill(drop.skill);
            if (icon != null)
            {
                g.drawImage(icon, (int) tx - 19, (int) ty - 13, 16, 16, null);
            }
            g.setColor(new Color(0, 0, 0, 180));
            text(g, text, tx + 1, ty + 1);
            g.setColor(Color.WHITE);
            text(g, text, tx, ty);
            g.setComposite(old);
        }
        dropsMoving = true;
    }

    void slot(Graphics2D g, double x, double y, int id, int quantity)
    {
        if (id < 0)
        {
            return;
        }
        BufferedImage image = images.item(id, max(1, quantity));
        if (image != null)
        {
            g.drawImage(image, (int) (x + (SLOT_W - image.getWidth()) / 2.0), (int) (y + (SLOT_H - image.getHeight()) / 2.0),
                null);
        }
    }

    static void dot(Graphics2D g, Color color, double x, double y)
    {
        g.setColor(color != null ? color : FRIEND);
        g.fill(new Ellipse2D.Double(x, y, 8, 8));
    }

    static void titleButton(Graphics2D g, Clicks clicks, FontMetrics title, double x, double top,
        String mark, Runnable action, String tip)
    {
        var button = new RoundRectangle2D.Double(x, top + 5, 20, 20, 8, 8);
        if (clicks.hovered(button))
        {
            g.setColor(CONTROL_HOVER);
            g.fill(button);
        }
        g.setColor(Floating.LIGHT);
        g.setFont(CONTROL_FONT);
        text(g, mark, button.getCenterX() - title.stringWidth(mark) / 2.0, top + 20);
        clicks.add(button, action, tip);
    }

    /** A skill as shown, boosted over real when they differ. */
    static String level(int now, int real)
    {
        return now == real ? String.valueOf(real) : now + "/" + real;
    }

    static Color levelColor(int now, int real)
    {
        return now > real ? BOOSTED : now < real ? DRAINED : Color.WHITE;
    }

    static String fit(String text, FontMetrics metrics, int width)
    {
        if (metrics.stringWidth(text) <= width)
        {
            return text;
        }
        String cut = text;
        while (cut.length() > 1 && metrics.stringWidth(cut + "…") > width)
        {
            cut = cut.substring(0, cut.length() - 1);
        }
        return cut + "…";
    }
}

package com.hdmapreforged;

import static java.awt.Cursor.*;
import static java.lang.Math.*;

import java.awt.*;
import java.awt.Point;
import java.awt.event.*;
import java.awt.geom.*;
import java.util.*;
import java.util.function.*;
import javax.swing.*;
import javax.swing.text.*;
import lombok.*;
import net.runelite.api.*;

/**
 * The map over the game view: a window of its own, owned by the client's (RuneLite's own window is never changed).
 * Not drawn in the game because Stretched Mode would blur it. Takes the keyboard only while its search is typed in;
 * never moves, resizes or focuses the client window. Swing thread only.
 */
final class FullMapWindow implements MapView.WindowControls
{
    static final Color GRIP_DOTS = new Color(255, 255, 255, 90);
    static final int EDGE = 8;
    /** Thicker than the sides: easy to take hold of. */
    static final int BOTTOM = 12;
    static final int MIN_WIDTH = 320;
    static final int MIN_HEIGHT = 240;
    static final Color FRAME = new Color(30, 32, 37);
    /** By the edges a point is on (see edgesAt). */
    static final int[] CURSORS = {DEFAULT_CURSOR, W_RESIZE_CURSOR, E_RESIZE_CURSOR,
        DEFAULT_CURSOR, N_RESIZE_CURSOR, NW_RESIZE_CURSOR, NE_RESIZE_CURSOR,
        DEFAULT_CURSOR, S_RESIZE_CURSOR, SW_RESIZE_CURSOR, SE_RESIZE_CURSOR};

    final Client client;
    final MapScreen screen;
    final Consumer<String> saveBounds;
    final Predicate<KeyEvent> isMapKey;
    JWindow window;
    Canvas watchedCanvas;
    Window watchedFrame;
    /** Fractions of the game view, or null for the default. */
    Rectangle2D relative;
    boolean maximised;
    final ComponentListener follower = new ComponentAdapter()
    {
        public void componentMoved(ComponentEvent e)
        {
            place();
        }

        public void componentResized(ComponentEvent e)
        {
            place();
        }

        public void componentHidden(ComponentEvent e)
        {
            close();
        }
    };

    FullMapWindow(Client client, MapScreen screen, String savedBounds, Consumer<String> saveBounds,
        Predicate<KeyEvent> isMapKey)
    {
        this.client = client;
        this.screen = screen;
        this.saveBounds = saveBounds;
        this.isMapKey = isMapKey;
        screen.view.setWindowControls(this);
        var decoded = decode(savedBounds);
        if (decoded != null)
        {
            relative = (Rectangle2D) decoded[0];
            maximised = (Boolean) decoded[1];
        }
        screen.setScreenLayout(MapScreen.Layout.FULL);
        screen.view.addMouseListener(new MouseAdapter()
        {
            public void mouseReleased(MouseEvent e)
            {
                SwingUtilities.invokeLater(FullMapWindow.this::giveKeysBack);
            }
        });
    }

    public boolean isMaximised()
    {
        return maximised;
    }

    boolean isOpen()
    {
        return window != null && window.isVisible();
    }

    void setHostBounds(Rectangle screenBounds)
    {
        if (!window.getBounds().equals(screenBounds))
        {
            window.setBounds(screenBounds);
            window.validate();
        }
    }

    static boolean menuOpen()
    {
        return MenuSelectionManager.defaultManager().getSelectedPath().length > 0;
    }

    static Rectangle onScreen(Component c)
    {
        return new Rectangle(c.getLocationOnScreen(), c.getSize());
    }

    void toggle()
    {
        if (isOpen())
        {
            close();
        }
        else
        {
            open();
        }
    }

    void open()
    {
        Canvas canvas = client.getCanvas();
        if (canvas == null || !canvas.isShowing())
        {
            return;
        }
        if (window == null)
        {
            window = new JWindow(SwingUtilities.getWindowAncestor(canvas));
            // A utility window: left out of the taskbar and alt-tab, raised and lowered with the game.
            window.setType(Window.Type.UTILITY);
            // Some window managers still focus it on click; then Escape and the map key must work here too.
            window.setAutoRequestFocus(false);
            // Never focusable, so the desktop (KWin) keeps the game active; only while typing (see typable).
            window.setFocusableWindowState(false);
            window.addWindowFocusListener(new WindowAdapter()
            {
                public void windowLostFocus(WindowEvent e)
                {
                    window.setFocusableWindowState(false);
                }
            });
            window.setContentPane(frame());
        }
        watch(canvas);
        place();
        if (!window.isVisible())
        {
            window.setVisible(true);
            // Some window managers place a new window themselves.
            SwingUtilities.invokeLater(this::place);
            screen.opened();
        }
    }

    public void close()
    {
        if (window != null && window.isVisible())
        {
            // No longer focusable, a focused window hands the keyboard back to the game's (setFocusableWindowState).
            window.setFocusableWindowState(false);
            window.setVisible(false);
        }
    }

    public void toggleMaximised()
    {
        maximised = !maximised;
        save();
        place();
        screen.view.repaint();
    }

    /**
     * Escape and the map key close the map while one of its parts has the keyboard (the game sees no keys then). While
     * typing or in a menu, keys are theirs: Escape closes the menu, letters type.
     */
    boolean closeKey(KeyEvent e)
    {
        Object owner = e.getSource();
        if (!isOpen() || menuOpen() || owner instanceof JTextComponent && (e.getKeyCode() != KeyEvent.VK_ESCAPE
            || !((JTextComponent) owner).getText().isEmpty()))
        {
            return false;
        }
        if (e.getKeyCode() == KeyEvent.VK_ESCAPE || isMapKey.test(e))
        {
            close();
            return true;
        }
        return false;
    }

    /** In a window kept unfocusable (see open), a click in {@code field} lets the window take the keyboard to type. */
    static void typable(JTextComponent field)
    {
        field.addMouseListener(new MouseAdapter()
        {
            public void mousePressed(MouseEvent e)
            {
                Window host = SwingUtilities.getWindowAncestor(field);
                if (host != null && !host.getFocusableWindowState())
                {
                    host.setFocusableWindowState(true);
                    SwingUtilities.invokeLater(field::requestFocus);
                }
            }
        });
    }

    /** After a click on the map itself, the keyboard goes back to the game. */
    void giveKeysBack()
    {
        Canvas canvas = watchedCanvas;
        // Open, and its window has the keyboard.
        if (isOpen() && window.getFocusOwner() != null && !menuOpen() && canvas != null && canvas.isShowing())
        {
            window.setFocusableWindowState(false);
        }
    }

    JPanel frame()
    {
        JPanel root = new JPanel(new BorderLayout())
        {
            protected boolean processKeyBinding(KeyStroke ks, KeyEvent e, int condition, boolean pressed)
            {
                return pressed && closeKey(e) || super.processKeyBinding(ks, e, condition, pressed);
            }

            protected void paintComponent(Graphics graphics)
            {
                super.paintComponent(graphics);
                var g = (Graphics2D) graphics.create();
                g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g.setColor(GRIP_DOTS);
                int right = getWidth() - 3;
                int bottom = getHeight() - 3;
                for (int row = 0; row < 3; row++)
                {
                    for (int col = 0; col <= row; col++)
                    {
                        g.fillOval(right - col * 4 - 2, bottom - (row - col) * 4 - 2, 2, 2);
                    }
                }
                g.dispose();
            }
        };
        root.setBackground(FRAME);
        root.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(255, 255, 255, 40)),
            BorderFactory.createEmptyBorder(0, EDGE - 1, BOTTOM - 1, EDGE - 1)));
        root.add(new Grip(), BorderLayout.NORTH);
        root.add(screen, BorderLayout.CENTER);
        var resizer = new Resizer(root);
        root.addMouseListener(resizer);
        root.addMouseMotionListener(resizer);
        return root;
    }

    void place()
    {
        Canvas canvas = watchedCanvas;
        if (window == null || canvas == null)
        {
            return;
        }
        if (!canvas.isShowing())
        {
            close();
            return;
        }
        Rectangle view = onScreen(canvas);
        setHostBounds(maximised ? view : fit(relative, view));
    }

    /** Screen bounds for fractions of the game view (null: the default), inside the view, at least the minimum size. */
    static Rectangle fit(Rectangle2D relative, Rectangle view)
    {
        var r = relative != null ? relative : new Rectangle2D.Double(0.08, 0.06, 0.84, 0.88);
        int width = (int) round(r.getWidth() * view.width);
        int height = (int) round(r.getHeight() * view.height);
        width = min(view.width, max(min(MIN_WIDTH, view.width), width));
        height = min(view.height, max(min(MIN_HEIGHT, view.height), height));
        int x = view.x + (int) round(r.getX() * view.width);
        int y = view.y + (int) round(r.getY() * view.height);
        x = max(view.x, min(view.x + view.width - width, x));
        y = max(view.y, min(view.y + view.height - height, y));
        return new Rectangle(x, y, width, height);
    }

    void setFromScreen(Rectangle bounds)
    {
        Canvas canvas = watchedCanvas;
        if (canvas == null || !canvas.isShowing() || canvas.getWidth() <= 0 || canvas.getHeight() <= 0)
        {
            return;
        }
        Rectangle view = onScreen(canvas);
        Rectangle fitted = fit(fraction(bounds, view), view);
        relative = fraction(fitted, view);
        maximised = false;
        setHostBounds(fitted);
    }

    /** Screen bounds as fractions of the game view. */
    static Rectangle2D fraction(Rectangle r, Rectangle view)
    {
        return new Rectangle2D.Double((r.x - view.x) / (double) view.width, (r.y - view.y) / (double) view.height,
            r.width / (double) view.width, r.height / (double) view.height);
    }

    void save()
    {
        saveBounds.accept(encode(relative, maximised));
    }

    static String encode(Rectangle2D relative, boolean maximised)
    {
        if (relative == null)
        {
            return maximised ? "max" : "";
        }
        return String.format(Locale.ROOT, "%.4f,%.4f,%.4f,%.4f%s", relative.getX(), relative.getY(), relative.getWidth(),
            relative.getHeight(), maximised ? ",max" : "");
    }

    /** {bounds or null, maximised}, or null when nothing usable was saved. */
    static Object[] decode(String saved)
    {
        if (saved == null || saved.trim().isEmpty())
        {
            return null;
        }
        var parts = saved.trim().split(",");
        if (parts.length == 1 && "max".equals(parts[0]))
        {
            return new Object[]{null, true};
        }
        if (parts.length != 4 && parts.length != 5)
        {
            return null;
        }
        try
        {
            double x = Double.parseDouble(parts[0]);
            double y = Double.parseDouble(parts[1]);
            double w = Double.parseDouble(parts[2]);
            double h = Double.parseDouble(parts[3]);
            if (!(w > 0.05 && w <= 1 && h > 0.05 && h <= 1 && x >= -1 && x <= 1 && y >= -1 && y <= 1))
            {
                return null;
            }
            return new Object[]{new Rectangle2D.Double(x, y, w, h), parts.length == 5 && "max".equals(parts[4])};
        }
        catch (NumberFormatException e)
        {
            return null;
        }
    }

    void watch(Canvas canvas)
    {
        if (canvas == watchedCanvas)
        {
            return;
        }
        unwatch();
        watchedCanvas = canvas;
        canvas.addComponentListener(follower);
        watchedFrame = SwingUtilities.getWindowAncestor(canvas);
        if (watchedFrame != null)
        {
            watchedFrame.addComponentListener(follower);
        }
    }

    void unwatch()
    {
        if (watchedCanvas != null)
        {
            watchedCanvas.removeComponentListener(follower);
        }
        if (watchedFrame != null)
        {
            watchedFrame.removeComponentListener(follower);
        }
        watchedCanvas = null;
        watchedFrame = null;
    }

    void dispose()
    {
        close();
        unwatch();
        if (window != null)
        {
            window.dispose();
            window = null;
        }
    }

    /** A mouse drag that moves or resizes the map; saved once let go. */
    abstract class Drag extends MouseAdapter
    {
        Point grab;
        Rectangle start;

        void grab(MouseEvent e)
        {
            grab = e.getLocationOnScreen();
            start = window.getBounds();
        }

        public void mouseReleased(MouseEvent e)
        {
            if (grab != null)
            {
                grab = null;
                save();
            }
        }
    }

    final class Grip extends JComponent
    {
        Grip()
        {
            // The grip's height: 10 pixels.
            setPreferredSize(new Dimension(100, 10));
            setCursor(getPredefinedCursor(MOVE_CURSOR));
            setToolTipText("Drag to move; double-click to fill the game view");
            Drag mouse = new Drag()
            {
                public void mousePressed(MouseEvent e)
                {
                    if (SwingUtilities.isLeftMouseButton(e))
                    {
                        grab(e);
                    }
                }

                public void mouseDragged(MouseEvent e)
                {
                    if (grab == null)
                    {
                        return;
                    }
                    if (maximised)
                    {
                        Canvas canvas = watchedCanvas;
                        if (canvas == null || !canvas.isShowing())
                        {
                            return;
                        }
                        // Dragging a maximised window restores it under the mouse.
                        Rectangle restored = fit(relative, onScreen(canvas));
                        double along = (grab.x - start.x) / (double) max(1, start.width);
                        start = new Rectangle(grab.x - (int) (restored.width * along), start.y, restored.width, restored.height);
                        maximised = false;
                    }
                    Point now = e.getLocationOnScreen();
                    setFromScreen(new Rectangle(start.x + now.x - grab.x, start.y + now.y - grab.y, start.width, start.height));
                }

                public void mouseClicked(MouseEvent e)
                {
                    if (e.getClickCount() == 2)
                    {
                        toggleMaximised();
                    }
                }
            };
            addMouseListener(mouse);
            addMouseMotionListener(mouse);
        }

        protected void paintComponent(Graphics graphics)
        {
            var g = (Graphics2D) graphics.create();
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.setColor(FRAME);
            g.fillRect(0, 0, getWidth(), getHeight());
            g.setColor(GRIP_DOTS);
            double cx = getWidth() / 2.0;
            double cy = getHeight() / 2.0;
            for (int i = -3; i <= 3; i++)
            {
                g.fill(new Ellipse2D.Double(cx + i * 7 - 1.5, cy - 1.5, 3, 3));
            }
            g.dispose();
        }
    }

    @RequiredArgsConstructor
    final class Resizer extends Drag
    {
        final JComponent root;
        int edges;

        /** Bits: 1 left, 2 right, 4 top, 8 bottom. */
        int edgesAt(Point p)
        {
            int corner = EDGE * 4;
            int w = root.getWidth();
            int h = root.getHeight();
            return (p.x < EDGE || p.x < corner && p.y >= h - corner ? 1 : 0)
                | (p.x >= w - EDGE || p.x >= w - corner && p.y >= h - corner ? 2 : 0)
                | (p.y < 3 ? 4 : 0)
                | (p.y >= h - BOTTOM || p.y >= h - corner && (p.x < corner || p.x >= w - corner) ? 8 : 0);
        }

        public void mouseMoved(MouseEvent e)
        {
            int at = edgesAt(e.getPoint());
            root.setCursor(getPredefinedCursor(at < CURSORS.length ? CURSORS[at] : DEFAULT_CURSOR));
        }

        public void mouseExited(MouseEvent e)
        {
            if (grab == null)
            {
                root.setCursor(getDefaultCursor());
            }
        }

        public void mousePressed(MouseEvent e)
        {
            edges = edgesAt(e.getPoint());
            if (edges != 0 && SwingUtilities.isLeftMouseButton(e))
            {
                grab(e);
            }
        }

        public void mouseDragged(MouseEvent e)
        {
            if (grab == null)
            {
                return;
            }
            Point now = e.getLocationOnScreen();
            int dx = now.x - grab.x;
            int dy = now.y - grab.y;
            Rectangle r = new Rectangle(start);
            if ((edges & 1) != 0)
            {
                int width = max(MIN_WIDTH, start.width - dx);
                r.x = start.x + start.width - width;
                r.width = width;
            }
            if ((edges & 2) != 0)
            {
                r.width = max(MIN_WIDTH, start.width + dx);
            }
            if ((edges & 4) != 0)
            {
                int height = max(MIN_HEIGHT, start.height - dy);
                r.y = start.y + start.height - height;
                r.height = height;
            }
            if ((edges & 8) != 0)
            {
                r.height = max(MIN_HEIGHT, start.height + dy);
            }
            setFromScreen(r);
        }
    }
}

package com.hdmapreforged;

import java.awt.image.*;
import java.util.*;
import java.util.concurrent.*;
import net.runelite.api.*;
import net.runelite.api.worldmap.*;

/** The game's own world map icons, read from the client: drawn as the game's icons, and so our icons look like them. */
final class GameIconSprites
{
    static final Map<PoiType, BufferedImage> SPRITES = new ConcurrentHashMap<>();
    static final Map<Integer, BufferedImage> ELEMENT_SPRITES = new ConcurrentHashMap<>();

    static boolean hasElements()
    {
        return !ELEMENT_SPRITES.isEmpty();
    }

    static BufferedImage element(int id)
    {
        return id < 0 ? null : ELEMENT_SPRITES.get(id);
    }

    /** Map elements read per call (each client tick): all of them, hundreds, in one tick made a hitch. */
    static final int SLICE = 50;

    /**
     * Client thread only: reads up to {@link #SLICE} of {@code ids}, taking them off it; false until none are left, or
     * while the game has not loaded its data yet.
     */
    static boolean loadElements(Client client, Collection<Integer> ids)
    {
        var left = ids.iterator();
        for (int n = 0; n < SLICE && left.hasNext(); n++)
        {
            int id = left.next();
            if (!ELEMENT_SPRITES.containsKey(id))
            {
                var config = config(client, id);
                if (config == null && waiting(client))
                {
                    return false;
                }
                BufferedImage image = config == null ? null : icon(config);
                if (image != null)
                {
                    ELEMENT_SPRITES.put(id, image);
                }
            }
            left.remove();
        }
        return ids.isEmpty();
    }

    /** Null for an id the game does not know (or not yet). */
    static MapElementConfig config(Client client, int id)
    {
        try
        {
            return client.getMapElementConfig(id);
        }
        catch (RuntimeException e)
        {
            return null;
        }
    }

    /** Still null once logged in: an id gone after a game update, not worth retrying every tick. */
    static boolean waiting(Client client)
    {
        return client.getGameState() != GameState.LOGGED_IN;
    }

    static BufferedImage icon(MapElementConfig config)
    {
        var pixels = config.getMapIcon(false);
        BufferedImage image = pixels == null ? null : pixels.toBufferedImage();
        return image != null && image.getWidth() > 0 && image.getHeight() > 0 ? image : null;
    }

    /** Null when not loaded yet, or a type we draw ourselves. */
    static BufferedImage get(PoiType type)
    {
        return SPRITES.get(type);
    }

    static void clear()
    {
        SPRITES.clear();
        ELEMENT_SPRITES.clear();
    }

    /** Client thread only; false while the game has not loaded its data yet. */
    static boolean load(Client client)
    {
        for (var type : PoiType.values())
        {
            if (type.element < 0)
            {
                continue;
            }
            var config = config(client, type.element);
            if (config == null)
            {
                if (waiting(client))
                {
                    return false;
                }
                continue;
            }
            BufferedImage image = icon(config);
            if (image != null)
            {
                SPRITES.put(type, image);
            }
        }
        return true;
    }
}

package com.hdmapreforged;

import java.awt.*;
import java.util.*;
import net.runelite.api.coords.*;

/** One's grave while it stands, drawn over the other icons; clicked, its card offers a route there. Swing thread. */
final class GraveMarker implements MapView.Overlay, MapView.HitLayer
{
    final MapView view;
    WorldPoint at;
    Poi grave;

    GraveMarker(MapView view)
    {
        this.view = view;
        view.addOverlay(this);
        view.hitLayers.add(this);
    }

    /** Null when no grave stands. */
    void set(WorldPoint at)
    {
        if (Objects.equals(at, this.at))
        {
            return;
        }
        if (grave != null && view.selected() == grave)
        {
            view.select(null);
        }
        this.at = at;
        grave = null;
        view.repaint();
    }

    /** Made once the map list knows the grave's map (it may stand before the map's data came), again for a new list. */
    Poi grave()
    {
        var on = at == null ? null : view.mapOf(at);
        if (grave == null || grave.map != on)
        {
            grave = on == null ? null : new Poi(PoiType.GRAVE, "Your grave", at, on, null, Needs.NONE, "Grave", null, null);
        }
        return grave;
    }

    public void paint(Graphics2D g, Projection p)
    {
        Point center = center(p);
        if (center != null)
        {
            boolean selected = view.selected() == grave;
            double size = view.iconSize(p.zoom()) * (selected ? 1.25 : 1.1);
            PoiIcons.paintCached(g, PoiType.GRAVE, center.x, center.y, size, selected, false);
        }
    }

    public Poi hit(Point point, Projection p)
    {
        Point center = center(p);
        return center != null && center.distance(point) <= view.iconSize(p.zoom()) * 0.6 ? grave : null;
    }

    Point center(Projection p)
    {
        var shown = grave();
        if (shown == null || !shown.isOn(p.map()))
        {
            return null;
        }
        var at = p.shown(shown.location);
        return new Point((int) p.screenX(at.getX() + 0.5), (int) p.screenY(at.getY() + 0.5));
    }
}

package com.hdmapreforged;

import lombok.*;
import net.runelite.client.party.messages.*;

/** A valuable drop a party member just got, sent once to the party. Values from other clients are checked. */
@AllArgsConstructor
public class HdMapPartyDrop extends PartyMemberMessage
{
    /** Item id, quantity, and worth in coins as the sender priced it. */
    private final int i;
    private final int q;
    private final long v;

    /** -1 when not believable. */
    int item()
    {
        return i >= 0 && i < HdMapPartyGear.MAX_ITEM ? i : -1;
    }

    int quantity()
    {
        return Math.max(1, q);
    }

    long value()
    {
        return Math.max(0, Math.min(Integer.MAX_VALUE * 100L, v));
    }
}

package com.hdmapreforged;

import static java.lang.Math.*;

import java.util.*;
import java.util.function.*;
import net.runelite.client.party.messages.*;

/**
 * What a party member carries, wears and can do, sent when it changes. Short field names keep the message small;
 * values from other clients are checked before use.
 */
public class HdMapPartyGear extends PartyMemberMessage
{
    static final int INVENTORY = 28;
    static final int EQUIPMENT = 14;
    static final int SKILLS = 24;
    /** Item ids above this are not believed. */
    static final int MAX_ITEM = 100_000;

    /** Inventory ids (-1 empty) and quantities. */
    private final int[] i;
    private final int[] q;
    /** Worn item ids by slot, -1 for none. */
    private final int[] e;
    /** Real and current skill levels, in RuneLite's Skill order. */
    private final int[] s;
    private final int[] b;
    /** Experience per skill; null from older versions. */
    private final int[] x;
    /** Run and special attack energy, 0 to 100; null from older versions. */
    private final Integer r;
    private final Integer p;

    HdMapPartyGear(int[] inventory, int[] quantities, int[] equipment, int[] levels, int[] boosted, int[] experience,
        int run, int special)
    {
        i = inventory;
        q = quantities;
        e = equipment;
        s = levels;
        b = boosted;
        x = experience;
        r = run < 0 ? null : run;
        p = special < 0 ? null : special;
    }

    /** Null when not shared. */
    int[] experience()
    {
        return x == null ? null : copy(x, SKILLS, 0, v -> max(0, min(200_000_000, v)));
    }

    /** 0 to 100, or -1 when not shared. */
    int runEnergy()
    {
        return r == null ? -1 : max(0, min(100, r));
    }

    /** 0 to 100, or -1 when not shared. */
    int specialAttack()
    {
        return p == null ? -1 : max(0, min(100, p));
    }

    int[] inventory()
    {
        return items(i, INVENTORY);
    }

    int[] quantities()
    {
        return copy(q, INVENTORY, 0, v -> max(0, v));
    }

    int[] equipment()
    {
        return items(e, EQUIPMENT);
    }

    int[] levels()
    {
        return levels(s);
    }

    int[] boosted()
    {
        return levels(b);
    }

    private static int[] items(int[] ids, int size)
    {
        return copy(ids, size, -1, id -> id >= 0 && id < MAX_ITEM ? id : -1);
    }

    private static int[] levels(int[] values)
    {
        return copy(values, SKILLS, 0, v -> max(0, min(255, v)));
    }

    /** The first {@code size} values checked, {@code empty} where none came. */
    private static int[] copy(int[] values, int size, int empty, IntUnaryOperator check)
    {
        int[] out = new int[size];
        Arrays.fill(out, empty);
        for (int k = 0; values != null && k < min(values.length, size); k++)
        {
            out[k] = check.applyAsInt(values[k]);
        }
        return out;
    }
}

package com.hdmapreforged;

import net.runelite.api.coords.*;
import net.runelite.client.party.messages.*;
import net.runelite.client.util.*;

/** Where a party member is. The class name is the message type on the party server; short field names keep it small. */
public class HdMapPartyLocation extends PartyMemberMessage
{
    static final int MAX_COORDINATE = 16383;
    static final int MAX_NAME = 12;
    static final int MAX_RAW_NAME = 64;

    private final int x;
    private final int y;
    private final int p;
    /** World, 0 when unknown. */
    private final int w;
    private final String n;
    /** In a house (the point is its portal); else left out, as null. */
    private final Boolean h;

    HdMapPartyLocation(WorldPoint point, int world, String name, boolean house)
    {
        h = house ? true : null;
        x = point == null ? -1 : point.getX();
        y = point == null ? -1 : point.getY();
        p = point == null ? 0 : point.getPlane();
        w = world;
        n = name;
    }

    static HdMapPartyLocation offline(String name)
    {
        return new HdMapPartyLocation(null, 0, name, false);
    }

    WorldPoint point()
    {
        return plausible(x, y, p) ? new WorldPoint(x, y, p) : null;
    }

    static boolean plausible(WorldPoint point)
    {
        return point != null && plausible(point.getX(), point.getY(), point.getPlane());
    }

    private static boolean plausible(int x, int y, int plane)
    {
        return x >= 0 && y >= 0 && x <= MAX_COORDINATE && y <= MAX_COORDINATE && plane >= 0 && plane <= 3;
    }

    boolean house()
    {
        return Boolean.TRUE.equals(h);
    }

    int world()
    {
        return w > 0 && w < 1000 ? w : 0;
    }

    String name()
    {
        return cleaned(n, false);
    }

    /**
     * Tags stripped (and, for a name from RuneLite's own party data, any stray {@code <} as well, so none of it is
     * ever taken as HTML in a Swing label); non-breaking spaces made plain, trimmed. Null if empty, too long raw, or
     * too long after.
     */
    static String cleaned(String raw, boolean stripBrackets)
    {
        if (raw == null || raw.length() > MAX_RAW_NAME)
        {
            return null;
        }
        String name = Text.removeTags(raw);
        if (stripBrackets)
        {
            name = name.replace('<', ' ');
        }
        name = name.replace('\u00a0', ' ').trim();
        return name.isEmpty() || name.length() > MAX_NAME ? null : name;
    }
}

