/** Details of the selected icon (requirements, destinations, links), or the teleports nearest a chosen point. */
final class InfoCard extends Fitted
{
    static final int MAX_LINKS = 60;
    static final Color MET = new Color(110, 200, 110);
    static final Color MISSING = new Color(230, 110, 100);

    final MapView map;
    final Supplier<WorldData> world;
    final ItemNames itemNames;
    final HdMapReforgedConfig config;
    Poi poi;
    WorldPoint nearestTo;
    List<Poi> nearest = new ArrayList<>();
    int textWidth = 160;
    IntFunction<JComponent> route;
    /** The route's steps take milliseconds to build: while the card is hidden they wait, built once it shows. */
    boolean routeStale;
    @Setter
    Runnable onRebuilt = () -> { };

    InfoCard(MapView map, Supplier<WorldData> world, ItemNames itemNames, HdMapReforgedConfig config)
    {
        // As JPanel(); a page down keeps 16 pixels of the page before.
        super(new FlowLayout(), 16);
        this.map = map;
        this.world = world;
        this.itemNames = itemNames;
        this.config = config;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARKER_GRAY_COLOR);
        setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
        // Shown again (the map opened, the card unfolded): the route's steps that waited are built now.
        addHierarchyListener(e -> {
            if (routeStale && route != null && isShowing())
            {
                routeStale = false;
                refill(routeHolder, route);
            }
        });
        refresh();
    }

    void setTextWidth(int width)
    {
        textWidth = width;
        refresh();
    }

    List<ItemSources.Ware> wares;
    /** The shop a shop icon stands for, for its shopkeeper's picture. */
    WorldData.Shop shop;
    @Setter
    Consumer<String> itemSearch;
    @Setter
    NpcPictures npcPictures = new NpcPictures((id, done) -> done.accept(null));

    Consumer<Tour.Stop> stopAdder;

    void setStopAdder(Consumer<Tour.Stop> stopAdder)
    {
        this.stopAdder = stopAdder;
        refresh();
    }

    Consumer<WorldPoint> router;

    void setRouter(Consumer<WorldPoint> router)
    {
        this.router = router;
        refresh();
    }

    void show(Poi poi)
    {
        this.poi = poi;
        nearestTo = null;
        shop = poi != null && poi.type == PoiType.SHOP ? world.get().shop(poi.location) : null;
        wares = shop == null ? null : world.get().wares(poi.location);
        if (poi != null)
        {
            var ids = new ArrayList<Integer>();
            poi.members().forEach(member -> ids.addAll(Requirements.itemIds(member.needs.items)));
            poi.links().forEach(link -> ids.addAll(Requirements.itemIds(link.needs.items)));
            // The wares' prices.
            if (wares != null)
            {
                wares.forEach(ware -> ids.add(ware.itemId));
            }
            if (!ids.isEmpty())
            {
                itemNames.resolve(ids, () -> {
                    if (this.poi == poi)
                    {
                        refresh();
                    }
                });
            }
        }
        refresh();
    }

    /** A route step passed rebuilds only the route: not the search list beside it, nor details that hide it. */
    void setRoute(IntFunction<JComponent> route, boolean show)
    {
        boolean had = this.route != null;
        this.route = route;
        if (show && route != null)
        {
            poi = null;
            nearestTo = null;
        }
        else if (poi != null || nearestTo != null)
        {
            return;
        }
        else if (had && route != null && routeHolder.getParent() == this && !isShowing())
        {
            // Built once the card shows.
            routeStale = true;
            return;
        }
        else if (had && route != null && refill(routeHolder, route))
        {
            return;
        }
        refresh();
    }

    /** The route again in place of a place or extra shown since (the map opened while one is walked). */
    void showRoute()
    {
        if (route != null)
        {
            setRoute(route, true);
        }
    }

    void setExtra(IntFunction<JComponent> extra)
    {
        this.extra = extra;
        if (extra != null)
        {
            poi = null;
            nearestTo = null;
        }
        refresh();
    }

    /**
     * A background update of {@code old}: taken only while it is still the card's extra, re-rendered only while shown
     * (no place's details open over it), never closing anything.
     */
    boolean updateExtra(IntFunction<JComponent> old, IntFunction<JComponent> now)
    {
        if (extra == null || extra != old)
        {
            return false;
        }
        extra = now;
        if (poi == null && nearestTo == null && !refill(extraHolder, now))
        {
            refresh();
        }
        return true;
    }

    IntFunction<JComponent> extra;
    /** The extra and the route shown each in a holder of its own, so one can change without the other. */
    final JPanel extraHolder = column();
    final JPanel routeHolder = column();

    /** {@code holder} holding {@code section} alone, at the card's text width. */
    JPanel fill(JPanel holder, IntFunction<JComponent> section)
    {
        holder.removeAll();
        holder.add(section.apply(textWidth));
        return holder;
    }

    /** Only {@code holder} built again, while the card shows it; false when the card must be built whole. */
    boolean refill(JPanel holder, IntFunction<JComponent> section)
    {
        if (holder.getParent() != this || waiting != null)
        {
            return false;
        }
        fill(holder, section);
        revalidate();
        repaint();
        onRebuilt.run();
        return true;
    }

    void showNearest(WorldPoint point, List<Poi> found)
    {
        map.select(null);
        poi = null;
        nearestTo = point;
        nearest = new ArrayList<>(found);
        refresh();
    }

    /** Not while the map animates: building a card with many rows made the map's flight stutter. */
    void refresh()
    {
        if (!map.animator.isRunning())
        {
            if (waiting != null)
            {
                waiting.stop();
                waiting = null;
            }
            rebuildNow();
        }
        else if (waiting == null)
        {
            // Until then only the name, so the old selection's buttons cannot be used.
            removeAll();
            if (poi != null)
            {
                JLabel title = bold(plain(poi.name));
                title.setForeground(Color.WHITE);
                title.setAlignmentX(Component.LEFT_ALIGNMENT);
                add(title);
            }
            revalidate();
            repaint();
            waiting = new Timer(40, e -> {
                if (!map.animator.isRunning())
                {
                    refresh();
                }
            });
            waiting.start();
        }
    }

    Timer waiting;

    void rebuildNow()
    {
        removeAll();
        if (nearestTo != null)
        {
            buildNearest();
        }
        else if (poi == null && (extra != null || route != null))
        {
            if (extra != null)
            {
                add(fill(extraHolder, extra));
            }
            if (extra != null && route != null)
            {
                add(Box.createVerticalStrut(8));
                var line = new JSeparator();
                line.setAlignmentX(Component.LEFT_ALIGNMENT);
                add(line);
                add(Box.createVerticalStrut(4));
            }
            if (route != null)
            {
                routeStale = !isShowing();
                add(routeStale ? routeHolder : fill(routeHolder, route));
            }
        }
        else if (poi == null)
        {
            add(grey("Click an icon for details. Scroll to zoom, drag to move, double-click to zoom in. "
                + "Right-click for the nearest teleports to a spot."));
        }
        else
        {
            buildDetails();
        }
        revalidate();
        repaint();
        onRebuilt.run();
    }

    void buildNearest()
    {
        add(text("Nearest teleports to this spot", Color.WHITE, true));
        add(grey("As the crow flies, from where each one lands. Walking routes may differ."));
        if (nearest.isEmpty())
        {
            add(grey("None on this map."));
        }
        for (var found : nearest)
        {
            JLabel entry = link(found.name + "  (" + found.location.distanceTo2D(nearestTo) + " tiles)", () -> map.focus(found));
            entry.setIcon(new ImageIcon(PoiIcons.image(found.type, 12)));
            add(entry);
        }
    }

    void buildDetails()
    {
        JLabel title = text(poi.name, Color.WHITE, true);
        title.setIcon(new ImageIcon(PoiIcons.image(poi.type, 16)));
        title.setIconTextGap(6);
        add(title);
        String where = poi.type.displayName + (poi.map != null ? " · " + poi.map.name : "")
            + (poi.location.getPlane() > 0 ? " · floor " + poi.location.getPlane() : "");
        var dot = poi.type == QUEST_START && map.unlocks != null ? map.unlocks.questColor(poi.name) : null;
        where += dot == null ? "" : dot == Color.GREEN ? " · Finished" : dot == Color.YELLOW ? " · Started"
            : " · Not started";
        add(grey(where));

        var buttons = new ArrayList<JButton>();
        var inside = MapView.mapBelow(poi);
        if (inside != null)
        {
            buttons.add(button(inside.map.id == BaseMap.SURFACE ? "Go out" : "Go in", () -> map.goIn(inside)));
        }
        var target = poi;
        if (router != null)
        {
            buttons.add(tip(button("Route", () -> router.accept(target.location)),
                "A route from where you are to here"));
        }
        if (stopAdder != null)
        {
            buttons.add(tip(button("+ Stop", () -> stopAdder.accept(Tour.Stop.place(
                target.name, target.location))), "Add to your custom route (right-click the map, Custom routes...)"));
        }
        buttons.add(button("Wiki", () -> LinkBrowser.browse(
            Wiki.searchUrl(poi.wikiQuery != null ? poi.wikiQuery : poi.name))));
        // Slimmer than usual, so more share a row.
        buttons.forEach(button -> button.setMargin(new Insets(2, 6, 2, 6)));
        add(Box.createVerticalStrut(6));
        add(wrapLabels(buttons, 4, textWidth + 70));
        if (extra != null)
        {
            add(Box.createVerticalStrut(4));
            add(link("← Back to the search results", () -> map.select(null)));
        }

        if (poi.note != null)
        {
            add(Box.createVerticalStrut(6));
            add(text(poi.note, new Color(255, 200, 120), false));
        }

        if (!poi.nearby().isEmpty())
        {
            boolean teleports = poi.nearby().stream().allMatch(p -> p.type == TELEPORT);
            heading(teleports ? "Teleports that land here" : "Also here");
            for (var other : poi.nearby())
            {
                for (var member : other.members())
                {
                    addMember(member, member.type == TELEPORT || teleports ? ""
                        : "  (" + member.type.displayName + ")");
                }
            }
        }

        if (poi.type == PoiType.SHOP)
        {
            buildWares();
        }

        var members = poi.members();
        if (members.size() > 1)
        {
            heading("Ways to get here (" + members.size() + ")");
            for (var member : members)
            {
                addMember(member, "");
            }
        }
        var own = Requirements.describe(poi.needs, itemNames);
        if (members.size() <= 1 && !own.isEmpty())
        {
            heading("Requirements");
            addRequirements(own, "");
        }

        var links = poi.links();
        var ownLines = new HashSet<String>();
        own.forEach(line -> ownLines.add(line.text));
        if (!links.isEmpty())
        {
            heading(poi.type.isRandomDestination() ? "Can send you to (" + links.size() + ")"
                : PoiType.NETWORKS.contains(poi.type) ? "Travel to (" + links.size() + ")" : "Leads to");
            var lines = new JCheckBox("Show lines on the map", map.linesShown(poi.type));
            lines.setOpaque(false);
            lines.setFocusable(false);
            lines.setFont(FontManager.getRunescapeSmallFont());
            lines.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            lines.setAlignmentX(Component.LEFT_ALIGNMENT);
            String type = poi.type.displayName.toLowerCase(Locale.ROOT);
            lines.setToolTipText("Draw lines from this " + type + " to where it leads; remembered for every " + type);
            lines.addActionListener(e -> map.setLinesShown(target.type, lines.isSelected()));
            add(lines);
            for (int i = 0; i < links.size() && i < MAX_LINKS; i++)
            {
                var link = links.get(i);
                boolean usable = usable(link.needs);
                if (!usable && config.onlyUsable())
                {
                    continue;
                }
                String label = link.label + (link.map != null && link.map != poi.map && !link.label.contains(link.map.name)
                    ? "  (" + link.map.name + ")" : "");
                JLabel entry = link((usable ? "" : "✗ ") + label, () -> goTo(link));
                if (!usable)
                {
                    entry.setToolTipText("You do not meet a requirement for this trip");
                }
                add(entry);
                // Only what this trip needs beyond the stop's own requirements, listed above.
                var tripNeeds = Requirements.describe(link.needs, itemNames);
                tripNeeds.removeIf(line -> ownLines.contains(line.text));
                addRequirements(tripNeeds, "    ");
            }
        }

        var group = groupOf(poi);
        if (!group.isEmpty())
        {
            String kind = poi.group.toLowerCase(Locale.ROOT).endsWith("teleports") ? poi.group : poi.group + " teleports";
            heading("Other " + kind + " (" + group.size() + ")");
            for (int i = 0; i < group.size() && i < MAX_LINKS; i++)
            {
                var other = group.get(i);
                add(link(shortName(other), () -> map.focus(other)));
            }
        }
    }

    boolean usable(Needs needs)
    {
        return map.unlocks() == null || map.unlocks().usable(needs);
    }

    void addMember(Poi member, String kind)
    {
        boolean usable = usable(member.needs);
        if (!usable && config.onlyUsable())
        {
            return;
        }
        add(text((usable ? "" : "✗ ") + member.name + kind, usable ? Color.WHITE : MISSING, false));
        addRequirements(Requirements.describe(member.needs, itemNames), "    ");
    }

    void buildWares()
    {
        if (wares == null || wares.isEmpty())
        {
            return;
        }
        if (shop != null && shop.npc >= 0)
        {
            JLabel keeper = pictureIcon(NpcPictures.LARGE);
            npcPictures.show(shop.npc, keeper);
            add(pictureRow(keeper, grey(shop.name)));
        }
        heading("Sells (" + wares.size() + ")");
        add(choice(new String[][]{{"shop", "Shop order"}, {"stock", "Stock"}, {"name", "Name"},
            {"price", "Price"}}, wareSort, sort -> {
                wareSort = sort;
                refresh();
            }, textWidth));
        var sorted = new ArrayList<ItemSources.Ware>(wares);
        sorted.sort(ItemSources.wareOrder(wareSort, itemNames::price));
        for (var ware : sorted)
        {
            JLabel icon = pictureIcon(PICTURE);
            itemNames.picture(ware.itemId, icon);
            // The name, like a drop's in the search panel, looks the item up in the plugin: where else it comes from.
            Runnable wiki = () -> LinkBrowser.browse(Wiki.pageUrl(ware.item));
            Runnable open = itemSearch != null ? () -> itemSearch.accept(ware.item) : wiki;
            String onWiki = "Open " + ware.item + " on the wiki";
            JComponent name = tip(bold(link(ware.item, open)),
                itemSearch != null ? "Where else to get " + ware.item : onWiki);
            int price = itemNames.price(ware.itemId);
            JPanel line = panel(new FlowLayout(FlowLayout.LEFT, 0, 0));
            line.add(tip(grey(dotted(ItemSources.stockText(ware.stock),
                price >= 0 ? "GE " + gp(price) : null) + " · "),
                "How many the shop keeps when no one has bought any, and the Grand Exchange price"));
            line.add(tip(link("Wiki", wiki), onWiki));
            add(Box.createVerticalStrut(3));
            add(clickableRow(pictureRow(icon, name, line), open));
        }
    }

    /** How a shop's wares are ordered; kept from one shop to the next. */
    String wareSort = "shop";

    void addRequirements(List<Requirements.Line> lines, String indent)
    {
        var unlocks = map.unlocks();
        for (var line : lines)
        {
            Boolean met = unlocks == null ? null : unlocks.met(line);
            String mark = met == null ? "• " : met ? "✓ " : "✗ ";
            Color color = met == null ? Color.WHITE : met ? MET : MISSING;
            add(text(indent + mark + line.text, color, false));
        }
    }

    List<Poi> groupOf(Poi poi)
    {
        var group = new ArrayList<Poi>();
        if (poi.type != TELEPORT || poi.group == null)
        {
            return group;
        }
        for (var other : map.pois())
        {
            var member = other.memberOf(poi.group);
            if (other != poi && other.type == TELEPORT && member != null && map.usable(member.needs))
            {
                group.add(other);
            }
        }
        return group;
    }

    String shortName(Poi poi)
    {
        var member = poi.memberOf(this.poi.group);
        String name = member != null ? member.name : poi.name;
        int colon = name.indexOf(':');
        return colon > 0 ? name.substring(colon + 1).trim() : name;
    }

    void goTo(Poi.Link link)
    {
        for (var other : map.pois())
        {
            if (other != poi && other.type == poi.type && other.location.getPlane() == link.point.getPlane()
                && other.location.distanceTo2D(link.point) <= 12)
            {
                map.focus(other);
                return;
            }
        }
        map.focus(link.point);
    }

    /** A heading as the search panel's. */
    void heading(String text)
    {
        add(Box.createVerticalStrut(8));
        add(SearchResults.heading(text, textWidth));
        add(Box.createVerticalStrut(2));
    }

    /** Names as they are (places, party members): a leading {@code <html>} must not render as HTML (remote images). */
    static JLabel plain(String text)
    {
        JLabel label = new JLabel();
        label.putClientProperty("html.disable", Boolean.TRUE);
        label.setText(text);
        return label;
    }

    JLabel grey(String text)
    {
        return text(text, SOFT, false);
    }

    /** As the search panel's, without the space between lines of a list. */
    JLabel text(String text, Color color, boolean bold)
    {
        return SearchResults.text(text, color, bold ? Font.BOLD : Font.PLAIN, bold ? 1 : 0, textWidth);
    }

    JLabel link(String text, Runnable action)
    {
        return clickable(text(text, LINK, false), action, true);
    }

    static String escape(String text)
    {
        return RouteFeature.RouteText.escape(text).replace("\n", "<br>");
    }
}

package com.hdmapreforged;

import com.hdmapreforged.route.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import javax.swing.*;
import lombok.*;
import net.runelite.client.callback.*;
import net.runelite.client.game.*;
import net.runelite.client.util.*;

/**
 * Item names for requirement lists, and the Grand Exchange prices the client knows; looked up on the client thread,
 * read from Swing.
 */
@RequiredArgsConstructor
final class ItemNames implements IntFunction<String>, SearchResults.Prices
{
    final ClientThread clientThread;
    final ItemManager itemManager;
    final Map<Integer, String> names = new ConcurrentHashMap<>();
    /** Id to last lookup time; retried later, as the game's item data may not have been ready. */
    final Map<Integer, Long> unnamed = new ConcurrentHashMap<>();
    static final long RETRY_MS = 30_000;
    final Map<Integer, Integer> prices = new ConcurrentHashMap<>();
    /** Id to when its price was looked up; prices move, so they are looked up again after a while. */
    final Map<Integer, Long> priced = new ConcurrentHashMap<>();
    /** More than a big shop sells; the game's own image cache keeps only 128 for every plugin. */
    static final int IMAGES = 512;
    /** The pictures of the items shown last, so a list built again never asks the game again. Swing thread. */
    final Map<Integer, AsyncBufferedImage> images = new LruMap<>(16, IMAGES);

    public int price(int id)
    {
        Integer price = prices.get(id);
        return price == null ? -1 : price;
    }

    /** Shows the game's picture of an item in {@code label}, once loaded. */
    void picture(int id, JLabel label)
    {
        images.computeIfAbsent(id, itemManager::getImage).addTo(label);
    }

    public String apply(int id)
    {
        String name = names.get(id);
        return name != null || !unnamed.containsKey(id) ? name : "Item " + id;
    }

    /** Client thread. */
    String lookUp(int id)
    {
        try
        {
            var item = itemManager.getItemComposition(id);
            String name = item == null ? null : item.getName();
            return name == null || name.isEmpty() || "null".equals(name) ? null : name;
        }
        catch (RuntimeException e)
        {
            return null;
        }
    }

    boolean wanted(int id, long now)
    {
        if (!names.containsKey(id))
        {
            Long tried = unnamed.get(id);
            if (tried == null || now - tried >= RETRY_MS)
            {
                return true;
            }
        }
        Long priced = this.priced.get(id);
        // Prices are looked up again after 10 minutes.
        return priced == null || now - priced >= 10 * 60_000;
    }

    /** Client thread. */
    int lookUpPrice(int id)
    {
        try
        {
            return (int) Math.min(Integer.MAX_VALUE, Math.max(0, itemManager.getItemPrice(id)));
        }
        catch (RuntimeException e)
        {
            return 0;
        }
    }

    public void resolve(Collection<Integer> ids, Runnable done)
    {
        // Previews run without a client.
        long now = System.currentTimeMillis();
        if (clientThread == null || ids.stream().noneMatch(id -> wanted(id, now)))
        {
            return;
        }
        clientThread.invoke(() -> {
            long at = System.currentTimeMillis();
            for (int id : ids)
            {
                if (!wanted(id, at))
                {
                    continue;
                }
                if (!names.containsKey(id))
                {
                    String name = lookUp(id);
                    if (name != null)
                    {
                        names.put(id, name);
                        unnamed.remove(id);
                    }
                    else
                    {
                        unnamed.put(id, at);
                    }
                }
                prices.put(id, lookUpPrice(id));
                priced.put(id, at);
            }
            SwingUtilities.invokeLater(done);
        });
    }
}

package com.hdmapreforged;

import java.util.*;
import java.util.function.IntUnaryOperator;
import lombok.*;
import net.runelite.api.coords.*;

/**
 * Where an item comes from ({@link WorldData#item}): the shops that sell it, where it lies on the ground and the
 * monsters that drop it; also a shop's wares, each with the stock it keeps.
 */
@RequiredArgsConstructor
final class ItemSources
{
    @RequiredArgsConstructor
    static final class Store
    {
        final String shop;
        final WorldPoint point;
        final int stock;
    }

    @RequiredArgsConstructor
    static final class Ware
    {
        final String item;
        /** The game's item id, for its picture. */
        final int itemId;
        final int stock;
    }

    /** A spot where the item lies on the ground, with how many lie there. */
    @RequiredArgsConstructor
    static final class Ground
    {
        final WorldPoint point;
        final int count;
    }

    /** A monster that drops the item, and how rarely ("Always", "3/128"). */
    @RequiredArgsConstructor
    static final class Dropper
    {
        final int npc;
        final String name;
        final String rarity;
        /** The monster's version that drops it when not the standard one ("Wilderness Slayer Cave"); else "". */
        final String version;
        /** "5-10", "7"; empty for one. */
        final String quantity;
        /** In how many places monsters of the name stand; those standing nowhere known are left out. */
        final int places;
        /** The first of its page's drop tables that drops the item ("" unnamed): the monster's Drops tab shows it. */
        final String table;
    }

    /** The item's name. */
    final String page;
    /** The game's id of the item, for its picture and price. */
    final int item;
    final List<Store> stores;
    final List<Ground> grounds;
    final List<Dropper> droppers;

    /** "Stock 10", "Stock ∞": how many a shop keeps while no one trades. */
    static String stockText(int stock)
    {
        return "Stock " + (stock == WorldData.ENDLESS ? "∞" : Integer.toString(stock));
    }

    /** Fuller stocks first, an endless one before all. */
    static int byStock(int a, int b)
    {
        return Integer.compare(b == WorldData.ENDLESS ? Integer.MAX_VALUE : b, a == WorldData.ENDLESS ? Integer.MAX_VALUE : a);
    }

    /**
     * A shop's wares in the order chosen: "shop" as the shop lists them, "stock" fullest first, "name", "price" dearest
     * first by the Grand Exchange ({@code price} gives an item's, -1 when not known: those last).
     */
    static Comparator<Ware> wareOrder(String sort, IntUnaryOperator price)
    {
        switch (sort)
        {
            case "stock":
                return (a, b) -> byStock(a.stock, b.stock) != 0 ? byStock(a.stock, b.stock) : a.item.compareToIgnoreCase(b.item);
            case "name":
                return (a, b) -> a.item.compareToIgnoreCase(b.item);
            case "price":
                return Comparator.comparingLong((Ware w) -> price.applyAsInt(w.itemId) < 0 ? Long.MAX_VALUE
                    : -(long) price.applyAsInt(w.itemId)).thenComparing(w -> w.item, String.CASE_INSENSITIVE_ORDER);
            default:
                return (a, b) -> 0;
        }
    }
}

package com.hdmapreforged;

import java.util.*;
import lombok.*;
import net.runelite.api.coords.*;

/**
 * Every place of one kind (herb patches, shark fishing spots, banks) from our icons, game icons and skill spots, as a
 * map version's places.json lists them (made by the test sources' KindIndexBuilder).
 */
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
final class KindIndex
{
    @RequiredArgsConstructor
    static final class Entry
    {
        final String name;
        final WorldPoint point;
        final String detail;
        /** Null for a listed skilling spot. */
        final Poi poi;
    }

    @RequiredArgsConstructor
    static final class Kind
    {
        final String label;
        /** Null for skilling spots. */
        final PoiType type;
        final String page;
        final List<Entry> entries = new ArrayList<>();
    }

    final List<Kind> kinds;

    List<Kind> all()
    {
        return Collections.unmodifiableList(kinds);
    }
}

package com.hdmapreforged;

import java.io.*;
import java.nio.charset.*;
import lombok.extern.slf4j.*;
import net.runelite.client.util.*;

/** The map server's map version as last seen, kept on disk so the next start shows it before the server answers. */
@Slf4j
final class KnownVersion
{
    static final String FILE = "server-map-version.txt";

    /** Null when missing or unusable. Its first line; older plugins wrote when they asked on the second. */
    static String read(Filepath file)
    {
        if (!file.isFile())
        {
            return null;
        }
        try
        {
            String version = new String(TileCache.read(file), StandardCharsets.UTF_8).split("\n")[0].trim();
            return MapServer.isSafeVersion(version) ? version : null;
        }
        catch (IOException e)
        {
            log.debug("Ignoring unreadable {}", file, e);
            return null;
        }
    }

    static void write(Filepath file, String version)
    {
        try
        {
            TileCache.writeAtomically(file, (version + "\n").getBytes(StandardCharsets.UTF_8));
        }
        catch (IOException e)
        {
            log.debug("Could not save the map version", e);
        }
    }
}

package com.hdmapreforged;

import java.util.function.*;
import lombok.*;

/** Icon groups toggled together, in order of precedence when icons overlap. */
@RequiredArgsConstructor
enum Layer
{
    DUNGEONS(-0.5, HdMapReforgedConfig::showDungeons),
    TRANSPORTS(Double.NEGATIVE_INFINITY, HdMapReforgedConfig::showTransports),
    TELEPORTS(-2.5, HdMapReforgedConfig::showTeleports),
    SAILING(-1.5, HdMapReforgedConfig::showSailing),
    SKILLING(1.5, HdMapReforgedConfig::showSkilling),
    ACTIVITIES(-1, HdMapReforgedConfig::showActivities),
    SERVICES(1, HdMapReforgedConfig::showServices),
    GAME_ICONS(Double.NEGATIVE_INFINITY, config -> true);

    /** Hidden below this zoom, so the zoomed-out map stays readable. */
    final double minZoom;
    final Predicate<HdMapReforgedConfig> setting;
}

package com.hdmapreforged;

import com.google.gson.*;
import lombok.*;
import java.io.*;
import java.util.*;
import java.util.stream.*;
import net.runelite.api.coords.*;

/**
 * Everything the map shows and the planner uses for a map version, read from the map server's places.json, which the
 * test sources' MapDataBuilder makes: the game's world map icons and map links are the one source for places and ways
 * in; ours only where the game has none. Our entrances and passages are the planner's only.
 */
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
final class MapData
{
    /**
     * Of places.json. An incompatible change raises it, and a new map version built with the new builder carries it:
     * a published version's files never change, and the plugin refuses another format.
     */
    static final int FORMAT = 2;

    @RequiredArgsConstructor
    static final class Place
    {
        final WorldPoint point;
        final String name;
        /**
         * How the game's map labels it: "region", "ocean", "settlement", "sea", "floor" or "place" (see
         * the map server's MapLabels); null for places only used for naming.
         */
        final String kind;
    }

    /** One of the game's own map icons (drawn by {@link MapIconLayer} from the game's sprites) with what it stands for. */
    static final class Icon
    {
        final WorldPoint location;
        /** Differs from {@link #location} where the map draws a place elsewhere (the Keldagrim tunnel). */
        final WorldPoint drawn;
        final BaseMap map;
        /** Our own place at the same spot ({@link #own}), else its own. */
        final Poi poi;
        final boolean own;
        /** The game's map element, or -1. */
        final int element;
        /** On a floor above the ground, which the map draws flat on the ground floor as the game's map does (Keldagrim). */
        final boolean flat;
        /** The name of its key on the game's world map ("Shipwright"), or null. */
        final String kind;

        Icon(WorldPoint location, BaseMap map, Poi poi, boolean own, int element, String kind)
        {
            this.location = location;
            drawn = MapView.shownOn(map, location);
            this.map = map;
            this.poi = poi;
            this.own = own;
            this.element = element;
            flat = map != null && drawn != null && drawn.getPlane() > 0
                && drawn.getPlane() < WorldMapMoves.floorsDrawnFlat(map.id, drawn.getX(), drawn.getY());
            this.kind = kind;
        }
    }

    /** In order of layers, with the planner's passages among them. */
    final List<Poi> pois;
    /** Of {@link #pois}, those not drawn. */
    final Set<Poi> hidden;
    final List<Place> labels;
    final List<Icon> icons;
    /** The game's icons with no icon of ours on them, which the search finds too. */
    final List<Poi> gameIcons;
    /** Every place of a kind, for the search and for custom routes' "nearest of a kind". */
    final KindIndex kinds;
    final SearchIndex search;

    /**
     * Of {@code places} of {@code kind} (null: any), the one nearest {@code point} within {@code radius}, another floor
     * counting {@code floorCost} tiles more (negative: none on another floor); the first of equals.
     */
    static Place nearest(Collection<Place> places, WorldPoint point, String kind, int radius, int floorCost)
    {
        Place best = null;
        long bestDistance = radius + 1L;
        for (Place place : places)
        {
            int floor = place.point.getPlane() == point.getPlane() ? 0 : floorCost;
            int d = place.point.distanceTo2D(point) + floor;
            // The kind last: comparing words is slower, and only needed for a nearer place.
            if (floor >= 0 && d < bestDistance && (kind == null || kind.equals(place.kind)))
            {
                best = place;
                bestDistance = d;
            }
        }
        return best;
    }

    static final int TOWN_RADIUS = 120;

    /**
     * The nearest town. Its own loop, not {@link #nearest}: the search index names thousands of places with it, and a
     * loop shared with other kinds of lists ran about twice as slow (the JIT no longer inlines the iteration).
     */
    static String settlement(List<Place> places, WorldPoint at)
    {
        String best = null;
        int bestDistance = TOWN_RADIUS + 1;
        for (Place place : places)
        {
            int d = place.point.distanceTo2D(at);
            if (d < bestDistance && "settlement".equals(place.kind))
            {
                best = place.name;
                bestDistance = d;
            }
        }
        return best;
    }

    /**
     * A map version's places.json, with the same version's map list and region table: what the plugin shows and plans
     * with. Unknown keys are ignored; a place of an unknown type or malformed is left out, and an icon or a kind's
     * entry standing for it. Data thread.
     *
     * @throws IOException not readable, or not this version's places in this format
     */
    static MapData read(Gson gson, Reader json, BaseMaps maps, String version) throws IOException
    {
        PlacesFile file;
        try
        {
            file = gson.fromJson(json, PlacesFile.class);
        }
        catch (RuntimeException e)
        {
            throw new IOException("Unreadable places of map version " + version, e);
        }
        if (file == null || file.format != FORMAT || !version.equals(file.version))
        {
            throw new IOException("Not the places of map version " + version + " in format " + FORMAT);
        }
        Reading reading = new Reading(maps);
        // As listed, null where left out: an icon of ours gives its place's index in it.
        var listed = new ArrayList<Poi>();
        var pois = new ArrayList<Poi>();
        Set<Poi> hidden = Collections.newSetFromMap(new IdentityHashMap<>());
        for (var place : list(file.pois))
        {
            var poi = reading.poi(place, 0);
            listed.add(poi);
            if (poi != null)
            {
                pois.add(poi);
                if (Boolean.TRUE.equals(place.hidden))
                {
                    hidden.add(poi);
                }
            }
        }
        Map<Integer, String> keys = file.keys == null ? Collections.emptyMap() : file.keys;
        var icons = new ArrayList<Icon>();
        for (var icon : list(file.icons))
        {
            var at = point(icon.at);
            var poi = icon.own == null ? reading.poi(icon.poi, 0) : item(listed, icon.own);
            if (at != null && poi != null)
            {
                icons.add(new Icon(at, reading.map(icon.map), poi, icon.own != null, icon.element,
                    keys.get(icon.element)));
            }
        }
        // Labels and kinds as listed too, null where left out: a search hit gives its target's index.
        var listedLabels = new ArrayList<Place>();
        for (var label : list(file.labels))
        {
            var at = point(label.at);
            listedLabels.add(at == null || label.name == null ? null : new Place(at, label.name, label.kind));
        }
        // The kinds' places as numbered: the places read, each with what it stands for, then the spots.
        var places = new ArrayList<KindIndex.Entry>();
        for (var poi : reading.numbered)
        {
            places.add(poi == null ? null : new KindIndex.Entry(poi.name, poi.location, poi.note, poi));
        }
        for (var spot : list(file.spots))
        {
            var at = point(spot.at);
            places.add(at == null || spot.name == null ? null : new KindIndex.Entry(spot.name, at, spot.detail, null));
        }
        var listedKinds = new ArrayList<KindIndex.Kind>();
        for (var written : list(file.kinds))
        {
            var kind = new KindIndex.Kind(written.label, value(PoiType.class, written.type), written.page);
            for (int i : written.places == null ? new int[0] : written.places)
            {
                var place = item(places, i);
                if (place != null)
                {
                    kind.entries.add(place);
                }
            }
            listedKinds.add(written.label == null || kind.entries.isEmpty() ? null : kind);
        }
        var hits = new ArrayList<SearchIndex.Hit>();
        for (var hit : list(file.hits))
        {
            var type = value(SearchIndex.Type.class, hit.type);
            Object target = type == null ? null : type == SearchIndex.Type.MAP ? maps.byId(hit.target)
                : item(type == SearchIndex.Type.PLACE ? listedLabels : type == SearchIndex.Type.KIND
                || type == SearchIndex.Type.KIND_PLACE ? listedKinds : reading.numbered, hit.target);
            if (target != null && hit.label != null)
            {
                var made = new SearchIndex.Hit(type, hit.label, hit.words == null ? hit.label : hit.words,
                    hit.place, target, point(hit.at), value(PoiType.class, hit.icon));
                made.later = hit.later == null ? 0 : hit.later;
                hits.add(made);
            }
        }
        var gameIcons = icons.stream().filter(icon -> !icon.own).map(icon -> icon.poi).distinct()
            .collect(Collectors.toList());
        return new MapData(pois, hidden, nonNull(listedLabels), icons, gameIcons, new KindIndex(nonNull(listedKinds)),
            new SearchIndex(hits));
    }

    /** Reading one file: its version's maps, and one Needs for equal requirements (a few hundred in thousands). */
    @RequiredArgsConstructor
    static final class Reading
    {
        final BaseMaps maps;
        final Map<Needs, Needs> needs = new HashMap<>();
        /** Listed places and those nearby, then the game's icons' own, in the file's order: null where left out. */
        final List<Poi> numbered = new ArrayList<>();

        /** A map id the list lacks reads as none. */
        BaseMap map(Integer id)
        {
            return id == null ? null : maps.byId(id);
        }

        /** Null when malformed. */
        Needs needs(String[] raw)
        {
            if (raw == null)
            {
                return Needs.NONE;
            }
            if (raw.length != 4)
            {
                return null;
            }
            Needs read = new Needs(text(raw[0]), text(raw[1]), text(raw[2]), text(raw[3]));
            return read.isEmpty() ? Needs.NONE : needs.computeIfAbsent(read, n -> n);
        }

        /** {@code depth}: 0 for a listed place (which may stand for places nearby), 1 nearby, 2 a stacked member. */
        Poi poi(PoiJson place, int depth)
        {
            var type = place == null ? null : value(PoiType.class, place.type);
            var at = type == null ? null : point(place.at);
            Needs needs = at == null ? null : needs(place.needs);
            // Older map versions name the Seers option of Camelot Teleport "Bank": read as a bank step.
            String name = "Camelot Teleport: Bank".equals(place.name) ? "Camelot Teleport: Seers" : place.name;
            var poi = needs == null || name == null ? null : new Poi(type, name, at, map(place.map),
                place.group, needs, place.wiki, map(place.target), place.note);
            if (depth < 2)
            {
                numbered.add(poi);
            }
            var drawn = poi == null || place.drawn == null ? null : point(place.drawn);
            if (drawn != null)
            {
                poi.drawnAt = drawn;
            }
            if (poi == null)
            {
                // The places nearby are left out with it, keeping their numbers.
                numbered.addAll(Collections.nCopies(depth == 0 && place != null ? list(place.nearby).size() : 0, null));
                return null;
            }
            for (var link : list(place.links))
            {
                var to = point(link.at);
                Needs linkNeeds = needs(link.needs);
                if (to != null && linkNeeds != null && link.name != null)
                {
                    poi.links.add(new Poi.Link(link.name, to, map(link.map), linkNeeds));
                }
            }
            for (var member : depth < 2 ? list(place.members) : Collections.<PoiJson>emptyList())
            {
                var read = poi(member, 2);
                if (read != null)
                {
                    poi.members.add(read);
                }
            }
            for (var near : depth == 0 ? list(place.nearby) : Collections.<PoiJson>emptyList())
            {
                var read = poi(near, 1);
                if (read != null)
                {
                    poi.nearby.add(read);
                }
            }
            return poi;
        }
    }

    static <E extends Enum<E>> E value(Class<E> type, String name)
    {
        try
        {
            return name == null ? null : Enum.valueOf(type, name);
        }
        catch (IllegalArgumentException unknown)
        {
            return null;
        }
    }

    static <T> T item(List<? extends T> list, int i)
    {
        return i >= 0 && i < list.size() ? list.get(i) : null;
    }

    static <T> List<T> nonNull(List<T> list)
    {
        return list.stream().filter(Objects::nonNull).collect(Collectors.toUnmodifiableList());
    }

    static WorldPoint point(int[] at)
    {
        return at != null && at.length == 3 ? new WorldPoint(at[0], at[1], at[2]) : null;
    }

    static String text(String raw)
    {
        return raw == null ? "" : raw;
    }

    static <T> List<T> list(List<T> list)
    {
        return list == null ? Collections.emptyList() : list;
    }

    /**
     * A map version's places.json (format 2) as {@link #read} binds it and the builder (test sources) writes it, one
     * class for both. Points are [x, y, plane]; map ids those of the version's maps.json. Absent: null, false or none.
     */
    static final class PlacesFile
    {
        int format;
        String version;
        List<String> credits;
        /** In drawing order, the planner's passages among them. */
        List<PoiJson> pois;
        List<IconJson> icons;
        List<LabelJson> labels;
        /** Map element id to the name of its key on the game's world map. */
        Map<Integer, String> keys;
        /** RuneLite's skilling spots that are places of a kind. */
        List<SpotJson> spots;
        List<KindJson> kinds;
        List<HitJson> hits;
    }

    static final class PoiJson
    {
        String type;
        String name;
        int[] at;
        /** Where the map draws it, when not at {@code at} (an upper floor's teleport drawn on the ground floor). */
        int[] drawn;
        Integer map;
        String group;
        /** Skills, items, quests, varbits, raw as the travel tables write them. */
        String[] needs;
        String wiki;
        Integer target;
        String note;
        /** Not drawn (top-level places only). */
        Boolean hidden;
        List<LinkJson> links;
        /** Stacked teleports. */
        List<PoiJson> members;
        /** Only on a top-level place. */
        List<PoiJson> nearby;
    }

    static final class LinkJson
    {
        String name;
        int[] at;
        Integer map;
        String[] needs;
    }

    static final class IconJson
    {
        int[] at;
        Integer map;
        int element = -1;
        /** The index in pois of the place the icon stands for; else {@link #poi}, its own place. */
        Integer own;
        PoiJson poi;
    }

    static final class LabelJson
    {
        int[] at;
        String name;
        String kind;
    }

    static final class SpotJson
    {
        int[] at;
        String name;
        String detail;
    }

    /** Every place of one kind ({@link KindIndex}). */
    static final class KindJson
    {
        String label;
        String type;
        String page;
        /**
         * Its places in order, numbered as read: each of {@link PlacesFile#pois} followed by its places nearby, then
         * the places of the icons that are not ours, then the spots.
         */
        int[] places;
    }

    /** One of the place search's hits ({@link SearchIndex.Hit}). */
    static final class HitJson
    {
        String type;
        String label;
        /** The words it is found by, when not its label's. */
        String words;
        /** The words of where it is, if any. */
        String place;
        /**
         * The map id of a MAP, else an index: in {@link PlacesFile#labels} for a PLACE, {@link PlacesFile#kinds} for a
         * KIND or KIND_PLACE, the places as {@link KindJson#places} numbers them for an ICON or GAME_ICON.
         */
        int target;
        int[] at;
        String icon;
        Double later;
    }
}

package com.hdmapreforged;

import static com.hdmapreforged.PoiType.*;
import static java.lang.Math.*;

import lombok.*;
import java.awt.*;
import java.awt.geom.*;
import java.awt.image.*;
import java.util.*;
import java.util.List;
import java.util.function.*;
import net.runelite.api.coords.*;
import com.hdmapreforged.MapData.Icon;

/**
 * Draws the game's own map icons (their sprites, {@link GameIconSprites}) where places.json puts them, hoverable and
 * clickable; only the hovered or selected one gets a ring. Where one stands on an icon of ours for the same thing,
 * ours is not drawn ({@link #covers}); one for a way in stands for the planner's passage there too, ringed when that is
 * selected. They are at least 15 px, more where the map enlarges its most detailed tiles, centred 1.5 of the tiles'
 * pixels left of and above their spot's south-west corner, from tile level 0 in; the ground floor shows every floor's
 * above ground and where the game's map draws a place's floors flat (Keldagrim), upper floors only their own.
 */
@RequiredArgsConstructor
final class MapIconLayer implements MapView.Overlay, MapView.HitLayer
{
    static final double ICON_PIXELS = 15;
    static final Color RING = new Color(255, 255, 255, 230);
    static final Color RING_SHADOW = new Color(0, 0, 0, 150);

    final MapView view;
    final BooleanSupplier enabled;
    /** By 64×64 region, so a frame or mouse move only looks near the view. */
    Map<Integer, List<Icon>> byRegion = new HashMap<>();
    /** One icon per spot with a game sprite, by region. */
    Map<Integer, List<Icon>> drawnByRegion = new HashMap<>();
    Map<Poi, List<Icon>> byPoi = new IdentityHashMap<>();
    /**
     * Game sprites scaled once per element and size, as zooming goes back and forth between a few sizes: made again at
     * each change of size, the first frame of each drew some 400 new images (60 ms on an accelerated pipeline).
     */
    final Map<Long, BufferedImage> scaled = new HashMap<>();
    /** Past about 4 MB of sprites (1 << 20 pixels) the sizes kept start again. */
    int scaledPixels;
    /** Made this frame: at a new size the rest are drawn at a size made before, and follow in the next frames. */
    int madeNow;
    boolean later;
    static final int MADE_PER_FRAME = 48;
    static final BasicStroke RING_SHADOW_STROKE = new BasicStroke(4f);
    static final BasicStroke RING_SELECTED = new BasicStroke(2.2f);
    static final BasicStroke RING_HOVERED = new BasicStroke(1.6f);
    /** Our icons standing on a game icon of the same thing, and our passages on the game's icon for that way in. */
    Map<Poi, Icon> covering = new IdentityHashMap<>();
    /** Icons made for the game's icons (not ours), for their labels. */
    Map<Poi, Icon> created = new IdentityHashMap<>();

    /** The size our icons are drawn at; the game's are drawn as large. */
    final IntSupplier size;

    /**
     * As large as ours at a zoom, never smaller than {@link #ICON_PIXELS} times the tiles' scale (above 1 where the map
     * enlarges its most detailed tiles), in whole times the game's 15 pixels: the nearest, at least once. Pixel art
     * stays even: at 20 a 15-pixel icon had every third pixel doubled, and made smaller it was smoothed.
     */
    double drawnSize(Projection projection)
    {
        double wanted = max(ICON_PIXELS * scale(projection.zoom()),
            size.getAsInt() * MapView.iconScale(projection.zoom()));
        return ICON_PIXELS * max(1, round(wanted / ICON_PIXELS));
    }

    static int region(int x, int y)
    {
        return (x >> 6) << 16 | (y >> 6) & 0xffff;
    }

    List<List<Icon>> near(Map<Integer, List<Icon>> grid, Projection p,
        double left, double top, double right, double bottom)
    {
        double scale = p.screenX(1) - p.screenX(0);
        double x0 = p.screenX(0);
        double y0 = p.screenY(0);
        int minX = (int) floor((left - x0) / scale) - 1;
        int maxX = (int) ceil((right - x0) / scale) + 1;
        int maxY = (int) ceil((y0 - top) / scale) + 1;
        int minY = (int) floor((y0 - bottom) / scale) - 1;
        var found = new ArrayList<List<Icon>>();
        if ((long) (maxX - minX) * (maxY - minY) > 4_000_000_000L)
        {
            found.addAll(grid.values());
            return found;
        }
        for (int rx = minX >> 6; rx <= maxX >> 6; rx++)
        {
            for (int ry = minY >> 6; ry <= maxY >> 6; ry++)
            {
                var list = grid.get(rx << 16 | ry & 0xffff);
                if (list != null)
                {
                    found.add(list);
                }
            }
        }
        return found;
    }

    /** Swing thread only. {@code hidden}: our places the map does not draw, the planner's passages among them. */
    void setIcons(List<Icon> icons, Collection<Poi> hidden)
    {
        var made = new IdentityHashMap<Poi, Icon>();
        var cover = new IdentityHashMap<Poi, Icon>();
        var grid = new HashMap<Integer, List<Icon>>();
        var drawnGrid = new HashMap<Integer, List<Icon>>();
        var poiIcons = new IdentityHashMap<Poi, List<Icon>>();
        var spots = new HashSet<Long>();
        for (var icon : icons)
        {
            // Ours standing on the game's icon for it: the game's is drawn instead, once its sprite is there.
            (icon.own ? cover : made).put(icon.poi, icon);
            int key = region(icon.drawn.getX(), icon.drawn.getY());
            grid.computeIfAbsent(key, k -> new ArrayList<>()).add(icon);
            poiIcons.computeIfAbsent(icon.poi, k -> new ArrayList<>(1)).add(icon);
            long spot = (long) icon.drawn.getX() << 32 | (long) icon.drawn.getY() << 2 | icon.drawn.getPlane();
            if (icon.element >= 0 && spots.add(spot))
            {
                drawnGrid.computeIfAbsent(key, k -> new ArrayList<>()).add(icon);
            }
        }
        // A passage of ours chosen (in the search, among a kind's places) rings the game's icon for that way in rather
        // than being drawn over it ("Mining Guild basement" drew the game's dungeon icon, an exclamation mark, on the
        // map link). A click on the game's icon still selects the game's own place, which knows where its link leads.
        waysIn(icons, hidden).forEach((passage, icon) -> {
            if (cover.putIfAbsent(passage, icon) == null)
            {
                poiIcons.computeIfAbsent(passage, k -> new ArrayList<>(1)).add(icon);
            }
        });
        covering = cover;
        created = made;
        byRegion = grid;
        drawnByRegion = drawnGrid;
        byPoi = poiIcons;
        scaled.clear();
        scaledPixels = 0;
        view.searchExtras = new ArrayList<>(made.keySet());
        view.repaint();
    }

    /** How far from our passage the game's icon for that way in may stand: its dungeon icons stand a tile off. */
    static final int WAY_IN_REACH = 1;

    /**
     * Of our passages the map does not draw (they serve routes and the search), those the game shows a way in or out
     * for, each with that icon of the game's: on the passage's tile, else on one beside it.
     */
    static Map<Poi, Icon> waysIn(List<Icon> icons, Collection<Poi> hidden)
    {
        var byTile = new HashMap<WorldPoint, Icon>();
        for (var icon : icons)
        {
            if (wayIn(icon))
            {
                byTile.putIfAbsent(icon.location, icon);
            }
        }
        var found = new IdentityHashMap<Poi, Icon>();
        for (var poi : hidden)
        {
            if (poi.type != DUNGEON_ENTRANCE && poi.type != MAP_EXIT)
            {
                continue;
            }
            var icon = byTile.get(poi.location);
            for (int dx = -WAY_IN_REACH; icon == null && dx <= WAY_IN_REACH; dx++)
            {
                for (int dy = -WAY_IN_REACH; icon == null && dy <= WAY_IN_REACH; dy++)
                {
                    icon = byTile.get(poi.location.dx(dx).dy(dy));
                }
            }
            if (icon != null)
            {
                found.put(poi, icon);
            }
        }
        return found;
    }

    /** One of the game's own icons for a way in or out: a map link or dungeon icon, also one that knows no target. */
    static boolean wayIn(Icon icon)
    {
        var type = icon.poi.type;
        return !icon.own && (type == MAP_LINK || type == DUNGEON_ENTRANCE
            || "Dungeon".equalsIgnoreCase(icon.kind) || "Map link".equalsIgnoreCase(icon.kind));
    }

    void paintLarger(Graphics2D g, Projection projection)
    {
        if (!showsAny(projection))
        {
            return;
        }
        double drawn = drawnSize(projection);
        int px = (int) round(drawn);
        if (px <= 0)
        {
            return;
        }
        double r = drawn / 2 + 1;
        var toggled = toggles();
        madeNow = 0;
        later = false;
        for (var list : near(drawnByRegion, projection, -r, -r, projection.width() + r,
            projection.height() + r))
        {
            for (var icon : list)
            {
                double sx = projection.screenX(icon.drawn.getX());
                double sy = projection.screenY(icon.drawn.getY());
                if (sx < -r - 2 || sy < -r - 2 || sx > projection.width() + r + 2 || sy > projection.height() + r + 2
                    || !toggled[layer(icon).ordinal()] || !onView(icon, projection) || hidden(icon))
                {
                    continue;
                }
                BufferedImage sprite = sized(icon.element, px, view.locked(icon.poi));
                if (sprite == null)
                {
                    continue;
                }
                var c = center(icon, projection);
                g.drawImage(sprite, (int) round(c.getX() - sprite.getWidth() / 2.0),
                    (int) round(c.getY() - sprite.getHeight() / 2.0), null);
                Color dot = view.config.questStatus() ? quest(icon) : null;
                if (dot != null)
                {
                    var spot = PlayerMarker.circle(c.getX() + drawn * 0.35, c.getY() + drawn * 0.35,
                        max(3, drawn * 0.18));
                    g.setColor(dot);
                    g.fill(spot);
                    g.setColor(Color.BLACK);
                    g.draw(spot);
                }
            }
        }
        if (later)
        {
            view.repaint();
        }
    }

    /**
     * A game sprite at {@code px}: itself at its own size, else enlarged by whole times, once per size. Past a frame's
     * share, one already made at the next size down or up stands in: at a change of size making all at once drew some
     * 400 new images in one frame (55 ms on an accelerated pipeline, which uploads each).
     */
    BufferedImage sized(int element, int px, boolean locked)
    {
        BufferedImage sprite = GameIconSprites.element(element);
        if (sprite == null)
        {
            return null;
        }
        if (locked)
        {
            // Its own sizes, apart from the sprite's.
            sprite = PoiIcons.locked(sprite);
            element = ~element;
        }
        int own = max(sprite.getWidth(), sprite.getHeight());
        int times = max(1, round((float) px / own));
        if (times == 1)
        {
            return sprite;
        }
        BufferedImage cached = scaled.get(key(element, times));
        if (cached != null)
        {
            return cached;
        }
        if (madeNow >= MADE_PER_FRAME)
        {
            BufferedImage near = scaled.getOrDefault(key(element, times - 1), scaled.get(key(element, times + 1)));
            if (near != null || times == 2)
            {
                later = true;
                return near != null ? near : sprite;
            }
        }
        madeNow++;
        int w = sprite.getWidth() * times;
        int h = sprite.getHeight() * times;
        BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
        var g = out.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
        g.drawImage(sprite, 0, 0, w, h, null);
        g.dispose();
        scaledPixels += w * h;
        if (scaledPixels > 1 << 20)
        {
            scaled.clear();
            scaledPixels = w * h;
        }
        scaled.put(key(element, times), out);
        return out;
    }

    static long key(int element, int times)
    {
        return (long) times << 32 | element & 0xffffffffL;
    }

    static int tileLevel(double zoom)
    {
        return (int) max(TileCache.MIN_ZOOM, min(TileCache.MAX_ZOOM, ceil(zoom - 1e-6)));
    }

    /**
     * Of the zoom's own tile level, not the coarser one a large window draws past the memory cap: our tiles hold no
     * icons for the sprites to cover, and following that level drew them up to twice as large, unevenly.
     */
    static double scale(double zoom)
    {
        return pow(2, zoom - tileLevel(zoom));
    }

    boolean shows(Icon icon, Projection projection)
    {
        return showsAny(projection) && view.toggled(layer(icon)) && onView(icon, projection) && !hidden(icon);
    }

    /** A quest start icon's dot (see {@link Unlocks#questColor}), else null. */
    Color quest(Icon icon)
    {
        var unlocks = view.unlocks;
        return icon.poi.type != QUEST_START || unlocks == null ? null : unlocks.questColor(icon.poi.name);
    }

    boolean hidden(Icon icon)
    {
        return quest(icon) == Color.GREEN && view.config.hideCompletedQuests();
    }

    /** The setting a game icon follows besides its own: a bank's that of the banks; a map link the dungeon entrances. */
    static Layer layer(Icon icon)
    {
        return icon.poi.type == MAP_LINK ? Layer.DUNGEONS : icon.poi.type.layer;
    }

    /** Each layer's setting, read once per frame rather than per icon. */
    boolean[] toggles()
    {
        var toggled = new boolean[Layer.values().length];
        for (Layer layer : Layer.values())
        {
            toggled[layer.ordinal()] = view.toggled(layer);
        }
        return toggled;
    }

    boolean showsAny(Projection projection)
    {
        // From tile level 0 on.
        return projection.map() != null && tileLevel(projection.zoom()) >= 0 && enabled.getAsBoolean();
    }

    /** On the map in view and its floor, or on the ground floor's view a floor drawn flat on it. */
    static boolean onView(Icon icon, Projection projection)
    {
        var map = projection.map();
        return (map.id == BaseMap.FULL || icon.map == map)
            && (icon.drawn.getPlane() == projection.plane()
                // Ground floor tiles show the floors above; underground only where the game's map draws a place's
                // floors flat (Keldagrim's houses), floors on one spot being other places elsewhere.
                || projection.plane() == 0 && (icon.drawn.getY() < MapView.UNDERGROUND_Y || icon.flat));
    }

    /** {@link #covers} for a frame, the settings read once. */
    Predicate<Poi> covers(Projection projection)
    {
        if (!showsAny(projection))
        {
            return poi -> false;
        }
        var toggled = toggles();
        return poi -> {
            var icon = covering.get(poi);
            return icon != null && toggled[layer(icon).ordinal()] && GameIconSprites.element(icon.element) != null
                && onView(icon, projection);
        };
    }

    static Point2D center(Icon icon, Projection projection)
    {
        // -1.5 pixels at the tile level's own size.
        double offset = -1.5 * scale(projection.zoom());
        return new Point2D.Double(projection.screenX(icon.drawn.getX()) + offset,
            projection.screenY(icon.drawn.getY()) + offset);
    }

    public Poi hit(Point point, Projection projection)
    {
        var icon = iconAt(point, projection);
        return icon == null ? null : icon.poi;
    }

    /** The game icon under a point, nearest middle wins; null if none. */
    Icon iconAt(Point point, Projection projection)
    {
        if (!showsAny(projection))
        {
            return null;
        }
        double reach = drawnSize(projection) / 2 + 1;
        Icon best = null;
        double bestDistance = reach;
        var toggled = toggles();
        for (var list : near(byRegion, projection, point.x - reach - 8, point.y - reach - 8,
            point.x + reach + 8, point.y + reach + 8))
        {
            for (var icon : list)
            {
                double sx = projection.screenX(icon.drawn.getX());
                double sy = projection.screenY(icon.drawn.getY());
                if (abs(sx - point.x) > reach + 4 || abs(sy - point.y) > reach + 4
                    || !toggled[layer(icon).ordinal()] || !onView(icon, projection) || hidden(icon))
                {
                    continue;
                }
                var c = center(icon, projection);
                double d = c.distance(point);
                if (d <= bestDistance)
                {
                    best = icon;
                    bestDistance = d;
                }
            }
        }
        return best;
    }

    public Point2D labelAnchor(Poi poi, Projection projection)
    {
        var c = iconCenter(poi, projection);
        return c == null ? null : new Point2D.Double(c.getX(), c.getY() + drawnSize(projection) / 2 + 5);
    }

    public Point2D iconCenter(Poi poi, Projection projection)
    {
        var icon = created.get(poi);
        if (icon == null && covers(projection).test(poi))
        {
            icon = covering.get(poi);
        }
        return icon == null ? null : center(icon, projection);
    }

    /** Draws the game's sprites once read from the client; then rings the hovered and selected. */
    public void paint(Graphics2D g, Projection projection)
    {
        if (GameIconSprites.hasElements() && enabled.getAsBoolean())
        {
            paintLarger(g, projection);
        }
        var hovered = view.hovered();
        var selected = view.selected();
        if (hovered == null && selected == null)
        {
            return;
        }
        double r = drawnSize(projection) / 2 + 2.5;
        var ofSelected = byPoi.getOrDefault(selected, Collections.emptyList());
        var ringed = new ArrayList<Icon>(byPoi.getOrDefault(hovered, Collections.emptyList()));
        // The selected's last, on top. A passage's is the game's icon for it, which may be the one hovered.
        ringed.removeAll(ofSelected);
        ringed.addAll(ofSelected);
        for (var icon : ringed)
        {
            if (!shows(icon, projection))
            {
                continue;
            }
            var c = center(icon, projection);
            if (c.getX() < -r || c.getY() < -r || c.getX() > projection.width() + r || c.getY() > projection.height() + r)
            {
                continue;
            }
            var ring = PlayerMarker.circle(c.getX(), c.getY(), r);
            g.setStroke(RING_SHADOW_STROKE);
            g.setColor(RING_SHADOW);
            g.draw(ring);
            boolean chosen = ofSelected.contains(icon);
            g.setStroke(chosen ? RING_SELECTED : RING_HOVERED);
            g.setColor(chosen ? PlayerMarker.YELLOW : RING);
            g.draw(ring);
        }
    }
}

package com.hdmapreforged;

import static com.hdmapreforged.FriendsWidget.*;
import static com.hdmapreforged.SearchResults.*;
import static net.runelite.client.ui.ColorScheme.*;

import java.awt.*;
import java.awt.event.*;
import java.awt.image.*;
import java.util.*;
import java.util.List;
import java.util.function.*;
import javax.swing.*;
import javax.swing.Timer;
import net.runelite.api.*;
import net.runelite.api.coords.*;
import net.runelite.client.ui.*;

/** The sidebar: buttons to open the map, the route's steps, custom routes and the party. Swing thread. */
final class MapPanel extends PluginPanel
{
    interface Friends
    {
        boolean inGroup();

        List<Row> rows();

        /** The world the player is on, or 0. */
        int world();

        /** What a member last shared, or null. */
        PartyMapMembers.Gear gear(long id);

        Images images();

        boolean canRejoin();

        /** Rejoins the last party. */
        void join(Component from);

        /** Has the maps follow a member. */
        void follow(long id);
    }

    /** Text width inside the sidebar's padding. */
    static final int TEXT_WIDTH = PANEL_WIDTH - 52;

    final Consumer<WorldPoint> showOnMap;
    final Friends friends;
    final Function<WorldPoint, String> placeName;
    final JPanel routeHolder = column();
    /** Shown only with no route; a route's steps have their own title. */
    final JLabel routeHeading = heading("Route");
    /** A route's steps not built yet: it changed while the sidebar was hidden. */
    IntFunction<JComponent> waitingRoute;
    final JPanel friendsHolder = column();
    final JPanel toursHolder = column();
    TourPanel.Actions tours;
    /** The custom route open for editing, or null for the list. */
    IntFunction<JComponent> editorSection;
    TourPanel editor;
    long openFriend = -1;
    int friendPage;
    final Timer friendsTimer;
    String friendsShown;

    MapPanel(Runnable openMap, Runnable openWindow, Consumer<WorldPoint> showOnMap, Friends friends,
        Function<WorldPoint, String> placeName)
    {
        super(false);
        this.showOnMap = showOnMap;
        this.friends = friends;
        this.placeName = placeName;
        setLayout(new BorderLayout());
        setBackground(DARK_GRAY_COLOR);

        JPanel content = column();
        content.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
        JPanel buttons = new JPanel(new GridLayout(1, 2, 6, 0));
        buttons.add(tip(button("Open map", openMap), "The map over the game (also with the map key)"));
        buttons.add(tip(button("In a window", openWindow), "The map in a window of its own"));
        content.add(fitted(buttons));
        content.add(Box.createVerticalStrut(10));
        content.add(card(routeHeading, routeHolder));
        content.add(Box.createVerticalStrut(8));
        content.add(card(heading("Custom routes"), toursHolder));
        content.add(Box.createVerticalStrut(8));
        content.add(card(heading("Party"), friendsHolder));

        // Never wider than the sidebar: what does not fit wraps.
        JPanel top = new Fitted(new BorderLayout(), 0);
        top.setBackground(DARK_GRAY_COLOR);
        top.add(content, BorderLayout.NORTH);
        add(MapScreen.scroll(top), BorderLayout.CENTER);

        // Shown (its tab picked, the sidebar opened): a route that waited is built now, and the party as it is (joined
        // in RuneLite's Party panel meanwhile), not as it was when hidden.
        addHierarchyListener(e -> {
            if (waitingRoute != null && isShowing())
            {
                showRoute(waitingRoute);
            }
            if (isShowing())
            {
                refreshFriends();
            }
        });
        showRoute(null);
        // Every 2 seconds.
        friendsTimer = new Timer(2000, e -> refreshFriends());
        friendsTimer.start();
        refreshFriends();
    }

    /** The route's steps ({@code section} builds them for a width), or null for none. */
    void showRoute(IntFunction<JComponent> section)
    {
        // The steps take milliseconds to build: while the sidebar is hidden they wait, built once it shows.
        waitingRoute = section != null && !isShowing() ? section : null;
        if (waitingRoute != null)
        {
            return;
        }
        routeHolder.removeAll();
        routeHeading.setVisible(section == null);
        if (section == null)
        {
            routeHolder.add(text("No route. Right-click a place on the map, Path to here."));
        }
        else
        {
            var steps = section.apply(TEXT_WIDTH);
            steps.setAlignmentX(Component.LEFT_ALIGNMENT);
            routeHolder.add(steps);
        }
        refresh(routeHolder);
    }

    void setTours(TourPanel.Actions actions)
    {
        tours = actions;
        editor = new TourPanel(actions, section -> {
            editorSection = section;
            showTours();
        }, showOnMap, "\u2039 All routes");
        refreshTours();
    }

    void refreshTours()
    {
        if (editor != null && editor.isOpen())
        {
            editor.refresh();
            return;
        }
        showTours();
    }

    void edit(Tour tour)
    {
        tours.save(tours.tours(), tour.name);
        if (!editor.isOpen())
        {
            editor.toggle();
        }
        else
        {
            editor.refresh();
        }
    }

    void showTours()
    {
        toursHolder.removeAll();

        if (editorSection != null)
        {
            // HTML widths come out wider than asked in RuneLite's font: some room to spare.
            var section = editorSection.apply(TEXT_WIDTH - 40);
            section.setAlignmentX(Component.LEFT_ALIGNMENT);
            toursHolder.add(section);
            refresh(toursHolder);
            return;
        }
        List<Tour> saved = tours == null ? Collections.emptyList() : tours.tours();
        String running = tours == null ? null : tours.runningTour();
        if (saved.isEmpty())
        {
            toursHolder.add(text("None yet. Right-click the map, Add to custom route."));
            JButton make = tip(button("New route", () -> edit(new Tour(Tour.unique(saved, "My route"),
                Collections.emptyList()))), "Make a route; add its stops from the map");
            make.setAlignmentX(Component.LEFT_ALIGNMENT);
            toursHolder.add(make);
        }
        for (Tour tour : saved)
        {
            boolean runs = tour.name.equals(running);
            String what = plural(tour.stops.size(), "stop");
            toursHolder.add(entry(tour.name, runs ? "Running, " + what : what, runs ? new Color(120, 220, 140) : null,
                "Open this route: its stops, their order, Run", () -> edit(tour)));
        }
        refresh(toursHolder);
    }

    void stop()
    {
        friendsTimer.stop();
    }

    /** Rebuilt only when something shown changed. */
    void refreshFriends()
    {
        if (!isShowing() && friendsShown != null)
        {
            return;
        }
        boolean in = friends.inGroup();
        List<Row> rows = in ? friends.rows() : Collections.emptyList();
        boolean rejoin = !in && friends.canRejoin();
        StringBuilder key = new StringBuilder(in ? "in" : rejoin ? "out, rejoin" : "out");
        var places = new String[rows.size()];
        for (int i = 0; i < rows.size(); i++)
        {
            Row row = rows.get(i);
            places[i] = row.point == null ? null : placeName.apply(row.point);
            key.append('|').append(row.name).append(',').append(row.world).append(',').append(places[i]);
            if (row.id == openFriend)
            {
                var shared = friends.gear(row.id);
                key.append(",open,").append(friendPage).append(',').append(shared == null ? 0 : shared.at);
            }
        }
        if (key.toString().equals(friendsShown))
        {
            return;
        }
        friendsShown = key.toString();
        friendsHolder.removeAll();
        if (!in)
        {
            if (rejoin)
            {
                JButton join = tip(button("Rejoin party", () -> friends.join(this)), "Join your last party again");
                join.setAlignmentX(Component.LEFT_ALIGNMENT);
                friendsHolder.add(capped(join));
                friendsHolder.add(Box.createVerticalStrut(4));
            }
            friendsHolder.add(text("Not in a party. In one (RuneLite's Party panel), its members show here: where "
                + "they are and what they carry."));
        }
        else if (rows.isEmpty())
        {
            friendsHolder.add(text("No one else in your party yet."));
        }
        int me = friends.world();
        for (int i = 0; i < rows.size(); i++)
        {
            Row row = rows.get(i);
            String where = row.point == null ? "Not sharing where they are"
                : (row.world > 0 && row.world != me ? "World " + row.world + ", " : "")
                    + (places[i] != null ? places[i] : "on the map");
            friendsHolder.add(friend(row, where));
            if (row.id == openFriend)
            {
                friendsHolder.add(details(row, me));
            }
        }
        refresh(friendsHolder);
    }

    static void refresh(JComponent c)
    {
        c.revalidate();
        c.repaint();
    }

    void rebuildFriends()
    {
        friendsShown = null;
        refreshFriends();
    }

    JComponent friend(Row row, String where)
    {
        return entry(row.name, where, row.color != null ? row.color : MEDIUM_GRAY_COLOR,
            row.id == openFriend ? "Close" : "What " + row.name + " carries, wears and can do", () -> {
                openFriend = openFriend == row.id ? -1 : row.id;
                rebuildFriends();
            });
    }

    /** A member's details: an on-map button and their world, their orbs and one page of what they share. */
    JComponent details(Row row, int me)
    {
        JPanel box = column();
        box.setBorder(BorderFactory.createEmptyBorder(0, 6, 8, 0));
        JPanel actions = new JPanel(new GridLayout(1, 2, 4, 0));
        JButton show = tip(button("On map", () -> {
            showOnMap.accept(row.point);
            friends.follow(row.id);
        }), "Open the map where they are");
        show.setEnabled(row.point != null);
        actions.add(show);
        if (row.world > 0 && me > 0 && row.world != me)
        {
            JLabel world = new JLabel("World " + row.world, JLabel.CENTER);
            world.setToolTipText("On another world: hop there with the game's world switcher");
            actions.add(world);
        }
        box.add(fitted(actions));
        box.add(Box.createVerticalStrut(6));
        var shared = friends.gear(row.id);
        if (shared == null)
        {
            box.add(text("Nothing shared yet. They share it with this plugin's setting."));
            return box;
        }
        var images = friends.images();
        JPanel status = new JPanel(new GridLayout(2, 2, 4, 4));
        int[][] orbs = orbs(shared);
        for (int k = 0; k < 4; k++)
        {
            status.add(orb(Orbs.Kind.values()[k], orbs[k][0], orbs[k][1], images));
        }
        box.add(fitted(status));
        box.add(Box.createVerticalStrut(6));
        JPanel pages = new JPanel(new GridLayout(1, 3, 4, 0));
        for (int k = 0; k < PAGES.length; k++)
        {
            int page = k;
            JButton tab = tip(button(PAGES[k], () -> {
                friendPage = page;
                rebuildFriends();
            }), PAGES[k]);
            tab.setEnabled(k != friendPage);
            tab.setMargin(new Insets(2, 1, 2, 1));
            pages.add(tab);
        }
        box.add(fitted(pages));
        box.add(Box.createVerticalStrut(6));
        JPanel grid;
        if (friendPage == 0)
        {
            grid = new JPanel(new GridLayout(7, 4, 2, 2));
            for (int k = 0; k < HdMapPartyGear.INVENTORY; k++)
            {
                grid.add(item(images, shared.inventory[k], shared.quantities[k]));
            }
        }
        else if (friendPage == 1)
        {
            grid = new JPanel(new GridLayout(5, 3, 2, 2));
            var cells = new JComponent[15];
            for (int k = 0; k < WORN.length; k++)
            {
                var at = WORN[k];
                if (at != null)
                {
                    cells[at[1] * 3 + at[0]] = item(images, shared.equipment[k], 1);
                }
            }
            for (var cell : cells)
            {
                grid.add(cell != null ? cell : new JLabel());
            }
        }
        else
        {
            grid = new JPanel(new GridLayout(8, 3, 2, 2));
            for (int k = 0; k < Math.min(HdMapPartyGear.SKILLS, Skill.values().length); k++)
            {
                BufferedImage icon = images.skill(k);
                JLabel skill = new JLabel(level(shared.boosted[k], shared.levels[k]),
                    icon == null ? null : new ImageIcon(icon), JLabel.LEFT);
                skill.setForeground(levelColor(shared.boosted[k], shared.levels[k]));
                skill.setToolTipText(Skill.values()[k].getName());
                grid.add(skill);
            }
        }
        box.add(fitted(grid));
        return box;
    }

    static JComponent item(Images images, int id, int quantity)
    {
        BufferedImage picture = id < 0 ? null : images.item(id, Math.max(1, quantity));
        JLabel label = new JLabel(picture == null ? null : new ImageIcon(picture));
        label.setHorizontalAlignment(JLabel.CENTER);
        label.setPreferredSize(new Dimension(36, 32));
        return label;
    }

    static JComponent orb(Orbs.Kind kind, int value, int max, Images pictures)
    {
        JComponent orb = new JComponent()
        {
            protected void paintComponent(Graphics g)
            {
                var g2 = (Graphics2D) g.create();
                Orbs.paint(g2, (getWidth() - Orbs.WIDTH) / 2, 0, kind, value, max, pictures::sprite);
                g2.dispose();
            }
        };
        orb.setPreferredSize(new Dimension(Orbs.WIDTH, Orbs.HEIGHT));
        return orb;
    }

    /** A name over a smaller line; with {@code action}, clickable. */
    static JComponent entry(String title, String under, Color dot, String tip, Runnable action)
    {
        JPanel line = new JPanel(new BorderLayout(6, 0));
        line.setBackground(DARK_GRAY_COLOR);
        line.setBorder(BorderFactory.createEmptyBorder(5, 6, 5, 6));
        line.setAlignmentX(Component.LEFT_ALIGNMENT);
        if (dot != null)
        {
            JLabel mark = new JLabel("\u25CF");
            mark.setForeground(dot);
            line.add(mark, BorderLayout.WEST);
        }
        JPanel texts = new JPanel(new GridLayout(2, 1));
        texts.setOpaque(false);
        JLabel name = InfoCard.plain(title);
        name.setForeground(action != null ? Color.WHITE : LIGHT_GRAY_COLOR);
        name.setFont(FontManager.getRunescapeBoldFont());
        texts.add(name);
        JLabel small = InfoCard.plain(under);
        small.setForeground(LIGHT_GRAY_COLOR);
        small.setFont(FontManager.getRunescapeSmallFont());
        texts.add(small);
        line.add(texts, BorderLayout.CENTER);
        if (action != null)
        {
            clickableRow(line, action).setToolTipText(tip);
            line.addMouseListener(new MouseAdapter()
            {
                public void mouseEntered(MouseEvent e)
                {
                    line.setBackground(DARK_GRAY_HOVER_COLOR);
                }

                public void mouseExited(MouseEvent e)
                {
                    line.setBackground(DARK_GRAY_COLOR);
                }
            });
        }
        return RoutePanels.wrapped(line, 4);
    }

    static JComponent card(JComponent heading, JComponent body)
    {
        JPanel card = column();
        card.setOpaque(true);
        card.setBackground(DARKER_GRAY_COLOR);
        card.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
        card.add(heading);
        card.add(body);
        return card;
    }

    /** Transparent, left-aligned, no taller than it needs. */
    static JComponent fitted(JComponent c)
    {
        c.setOpaque(false);
        c.setAlignmentX(Component.LEFT_ALIGNMENT);
        return capped(c);
    }

    static JLabel heading(String text)
    {
        JLabel label = new JLabel(text);
        label.setForeground(Color.WHITE);
        label.setFont(FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD));
        label.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
        label.setAlignmentX(Component.LEFT_ALIGNMENT);
        return label;
    }

    static JLabel text(String text)
    {
        return SearchResults.text(text, LIGHT_GRAY_COLOR, Font.PLAIN, 0, TEXT_WIDTH);
    }
}

package com.hdmapreforged;

