    void clearSearch()
    {
        npcs.clear();
    }

    void showSection(IntFunction<JComponent> section)
    {
        if (layout == Layout.FULL)
        {
            showFloating(npcPanel, npcFloat, section, PALETTE_LAYER);
            return;
        }
        card.setExtra(section);
