package com.hdmapreforged;

import com.hdmapreforged.route.*;
import java.awt.*;
import java.awt.image.*;
import java.util.*;
import java.util.List;
import java.util.function.*;
import javax.swing.*;
import lombok.*;

/**
 * NPC pictures from our map server, for the search panels and cards of both maps: scaled once to the two sizes shown
 * and kept. A label waiting for a picture gets it when it comes, so no list is built again for it. A label asks only
 * once it is painted, so the rows of a long list cost nothing until scrolled to, and a few are asked for at a time:
 * a row scrolled past before its turn waits until it is painted again. Swing thread.
 */
@RequiredArgsConstructor
final class NpcPictures
{
    /** A row's picture; headers and shopkeepers show {@link #LARGE}. */
    static final int SMALL = SearchResults.PICTURE;
    static final int LARGE = 2 * SMALL;
    /** The rows of a few screens of both maps' lists, so a list built again has those in view at once. */
    static final int KEPT = 160;
    /** Asked for at once at most: scrolling through hundreds of rows never sends hundreds of requests. */
    static final int AT_ONCE = 4;
    /** A picture the server did not send is asked for again after this long. */
    static final long RETRY_MS = 60_000;

    /** Where a picture comes from, called back on any thread, with null when there is none. */
    final BiConsumer<Integer, Consumer<BufferedImage>> source;
    /** Each NPC's picture at {@link #SMALL} and {@link #LARGE}, those shown last kept. */
    final Map<Integer, Icon[]> icons = new LruMap<>(16, KEPT);
    /** Asked for and not answered yet, or waiting their turn, with the labels waiting for each. */
    final Map<Integer, List<JLabel>> waiting = new HashMap<>();
    /** Waiting their turn, the last painted first: a list paints its rows from the last up, so its top row is first. */
    final Deque<Integer> queued = new ArrayDeque<>();
    int asking;
    /** Whether {@link #next} runs once all the labels painted together have asked. */
    boolean nextLater;
    /** When a picture the server did not send was asked for. */
    final Map<Integer, Long> missing = new HashMap<>();

    /**
     * The NPC's picture in {@code label}, at the label's preferred width: now when kept, else an empty square that asks
     * for it once painted.
     */
    void show(int npc, JLabel label)
    {
        var known = icons.get(npc);
        if (known != null)
        {
            put(known, label);
            return;
        }
        label.setIcon(new Pending(npc, label.getPreferredSize().width));
    }

    /** A label painted: its picture waits its turn; not when the server had none just now. */
    void want(int npc, JLabel label)
    {
        var known = icons.get(npc);
        if (known != null)
        {
            put(known, label);
            return;
        }
        Long failed = missing.get(npc);
        if (failed != null && System.currentTimeMillis() - failed < RETRY_MS)
        {
            return;
        }
        var labels = waiting.get(npc);
        if (labels == null)
        {
            waiting.put(npc, labels = new ArrayList<>());
            queued.push(npc);
        }
        labels.add(label);
        if (!nextLater)
        {
            nextLater = true;
            SwingUtilities.invokeLater(this::next);
        }
    }

    /** Asks for the next while fewer than {@link #AT_ONCE} are; those out of view now ask again once painted again. */
    void next()
    {
        nextLater = false;
        while (asking < AT_ONCE && !queued.isEmpty())
        {
            int npc = queued.pop();
            var labels = waiting.get(npc);
            if (labels.stream().anyMatch(label -> label.isShowing() && !label.getVisibleRect().isEmpty()))
            {
                asking++;
                source.accept(npc, image -> SwingUtilities.invokeLater(() -> arrived(npc, image)));
                continue;
            }
            waiting.remove(npc);
            labels.forEach(label -> {
                if (label.getIcon() instanceof Pending)
                {
                    ((Pending) label.getIcon()).asked = false;
                }
            });
        }
    }

    void arrived(int npc, BufferedImage image)
    {
        asking--;
        var labels = waiting.remove(npc);
        if (image == null)
        {
            missing.put(npc, System.currentTimeMillis());
        }
        else
        {
            missing.remove(npc);
            // Drawn smoothly: far quicker than Image.SCALE_SMOOTH, and halving is exact.
            BufferedImage large = ScaledTiles.scale(image, LARGE, LARGE);
            Icon[] both = {new ImageIcon(ScaledTiles.scale(large, SMALL, SMALL)), new ImageIcon(large)};
            icons.put(npc, both);
            labels.forEach(label -> put(both, label));
        }
        next();
    }

    static void put(Icon[] both, JLabel label)
    {
        label.setIcon(both[label.getPreferredSize().width == LARGE ? 1 : 0]);
    }

    /** An empty square of the picture's size, so the picture comes without a new layout; asks for it once painted. */
    @RequiredArgsConstructor
    final class Pending implements Icon
    {
        final int npc;
        final int size;
        boolean asked;

        public void paintIcon(Component c, Graphics g, int x, int y)
        {
            if (!asked && c instanceof JLabel)
            {
                asked = true;
                // Not while painting: the picture may be put on the label at once.
                SwingUtilities.invokeLater(() -> want(npc, (JLabel) c));
            }
        }

        public int getIconWidth()
        {
            return size;
        }

        public int getIconHeight()
        {
            return size;
        }
    }
}

package com.hdmapreforged;

import java.awt.Color;
import java.util.*;
import lombok.*;
import net.runelite.api.coords.*;

/** Where a monster or NPC is, as places of close spawns, and what it drops ({@link WorldData#spawns}); also a kind's places. */
final class NpcSpawns
{
    @RequiredArgsConstructor
    static final class Group
    {
        final String name;
        final String location;
        final List<WorldPoint> points;
        final String category;
        /** What the list says of it ("7 here", "4 spots"); empty or null for nothing. */
        final String note;
        final Color color;
        Poi poi;
        /** How many stand here (see {@link WorldData#spawns}); 0 when not counted. */
        int seen;
        /** The way in to a boss fought in an instance, not where it stands. */
        boolean entrance;
        /** A shop's stock of the item searched ({@link WorldData#ENDLESS} for endless); 0 for other places. */
        int stock;

        Group(String name, String location, List<WorldPoint> points)
        {
            this(name, location, points, null, null, null);
        }

        Group withNote(String note)
        {
            return copy(location, note);
        }

        /** The same place under a place name ("Waterfall Dungeon"). */
        Group at(String place)
        {
            return copy(place, note);
        }

        Group copy(String place, String text)
        {
            Group group = new Group(name, place, points, category, text, color);
            group.poi = poi;
            group.seen = seen;
            group.entrance = entrance;
            group.stock = stock;
            return group;
        }

        WorldPoint center()
        {
            return NpcSpawns.center(points);
        }
    }

    /** The point nearest the middle of them all, so a mark sits on a real tile; null for none. */
    static WorldPoint center(List<WorldPoint> points)
    {
        double x = points.stream().mapToInt(WorldPoint::getX).average().orElse(0);
        double y = points.stream().mapToInt(WorldPoint::getY).average().orElse(0);
        return points.stream().min(Comparator.comparingDouble(p -> (p.getX() - x) * (p.getX() - x)
            + (p.getY() - y) * (p.getY() - y))).orElse(null);
    }

    final String page;
    final List<Group> groups;
    /** The kind of the name most seen, whose picture stands for them all; -1 for none. */
    final int npc;
    /** The page's drop tables, the standard one first, the items named; empty when its drops are not known. */
    final List<WorldData.Table> tables;
    /** The standard table's drops. */
    final List<WorldData.Drop> drops;

    NpcSpawns(String page, List<Group> groups, int npc, List<WorldData.Table> tables)
    {
        this.page = page;
        this.groups = Collections.unmodifiableList(groups);
        this.npc = npc;
        this.tables = Collections.unmodifiableList(tables);
        this.drops = tables.isEmpty() ? Collections.emptyList() : Collections.unmodifiableList(tables.get(0).drops);
    }
}

package com.hdmapreforged;

import java.awt.*;
import java.awt.image.*;
import java.util.function.*;
import lombok.*;
import net.runelite.api.gameval.*;
import net.runelite.client.ui.*;
import net.runelite.api.gameval.SpriteID.OrbFiller;
import net.runelite.api.gameval.SpriteID.OrbIcon;

/** The game's minimap orbs drawn from its own sprites: frame, fill to what is left, icon and coloured number. */
final class Orbs
{
    /** The frame: number box on the left, orb on the right. */
    static final int WIDTH = 57;
    static final int HEIGHT = 34;
    static final int ORB_X = 27;
    static final int ORB_Y = 4;
    static final int ORB = 26;

    @RequiredArgsConstructor
    enum Kind
    {
        HITPOINTS(OrbFiller.HITPOINTS, OrbIcon.HITPOINTS, new Color(170, 40, 40)),
        PRAYER(OrbFiller.PRAYER, OrbIcon.PRAYER, new Color(40, 140, 170)),
        RUN(OrbFiller.RUN, OrbIcon.RUN, new Color(180, 150, 40)),
        SPECIAL(OrbFiller.SPECIAL, OrbIcon.SPECIAL, new Color(60, 150, 70));

        final int filler;
        final int icon;
        /** Used before the game's sprites load. */
        final Color plain;
    }

    static final int[] SPRITES = {SpriteID.OrbFrame.FRAME, OrbFiller.EMPTY, OrbFiller.HITPOINTS,
        OrbFiller.PRAYER, OrbFiller.RUN, OrbFiller.SPECIAL, OrbIcon.HITPOINTS,
        OrbIcon.PRAYER, OrbIcon.RUN, OrbIcon.SPECIAL};

    /** A negative {@code value} is unknown (empty, a dash); {@code sprites} returns null while loading. */
    static void paint(Graphics2D g, int x, int y, Kind kind, int value, int max, IntFunction<BufferedImage> sprites)
    {
        double left = value < 0 || max <= 0 ? 0 : Math.max(0, Math.min(1, value / (double) max));
        BufferedImage frame = sprites.apply(SpriteID.OrbFrame.FRAME);
        BufferedImage icon = sprites.apply(kind.icon);
        if (frame != null)
        {
            g.drawImage(frame, x, y, null);
        }
        else
        {
            g.setColor(new Color(40, 36, 30));
            g.fillRoundRect(x, y + 6, WIDTH - 4, HEIGHT - 12, 10, 10);
            g.fillOval(x + ORB_X - 3, y + ORB_Y - 3, ORB + 6, ORB + 6);
        }
        int ox = x + ORB_X;
        int oy = y + ORB_Y;
        orb(g, sprites.apply(OrbFiller.EMPTY), ox, oy, new Color(20, 20, 20));
        int filled = (int) Math.round(ORB * left);
        Shape clip = g.getClip();
        g.clipRect(ox, oy + ORB - filled, ORB, filled);
        orb(g, sprites.apply(kind.filler), ox, oy, kind.plain);
        g.setClip(clip);
        if (icon != null)
        {
            g.drawImage(icon, ox + (ORB - icon.getWidth()) / 2, oy + (ORB - icon.getHeight()) / 2, null);
        }
        String text = value < 0 ? "–" : String.valueOf(value);
        g.setFont(FontManager.getRunescapeSmallFont());
        var metrics = g.getFontMetrics();
        int tx = x + 15 - metrics.stringWidth(text) / 2;
        int ty = y + 26;
        g.setColor(Color.BLACK);
        g.drawString(text, tx + 1, ty + 1);
        g.setColor(value < 0 ? Color.LIGHT_GRAY : color(left));
        g.drawString(text, tx, ty);
    }

    /** The sprite, or a plain circle while it loads. */
    static void orb(Graphics2D g, BufferedImage sprite, int x, int y, Color plain)
    {
        if (sprite != null)
        {
            g.drawImage(sprite, x, y, ORB, ORB, null);
        }
        else
        {
            g.setColor(plain);
            g.fillOval(x, y, ORB, ORB);
        }
    }

    /** Green when full, through yellow, to red when empty. */
    static Color color(double left)
    {
        double f = Math.max(0, Math.min(1, left));
        int red = f > 0.5 ? (int) Math.round(255 * (1 - f) * 2) : 255;
        int green = f > 0.5 ? 255 : (int) Math.round(255 * f * 2);
        return new Color(red, green, 0);
    }
}

package com.hdmapreforged;

import static com.hdmapreforged.HdMapReforgedConfig.*;
import static com.hdmapreforged.HdMapPartyGear.*;

import java.awt.*;
import java.awt.Point;
import java.awt.event.*;
import java.awt.image.*;
import java.util.*;
import java.util.List;
import java.util.concurrent.*;
import java.util.function.*;
import javax.inject.*;
import javax.swing.*;
import javax.swing.Timer;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import net.runelite.api.coords.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.*;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.*;
import net.runelite.client.config.*;
import net.runelite.client.eventbus.*;
import net.runelite.client.events.*;
import net.runelite.client.game.*;
import net.runelite.client.party.*;
import net.runelite.client.party.events.*;
import net.runelite.client.party.messages.*;
import net.runelite.client.plugins.party.messages.*;
import net.runelite.client.util.*;

/**
 * Party members on the map through RuneLite's party service. Nothing is sent outside a party, and a party is never
 * joined without a user click: "Rejoin party" rejoins the remembered last one.
 */
@Slf4j
@RequiredArgsConstructor(onConstructor_ = @Inject)
public final class PartyMap implements MapPanel.Friends, FriendsWidget.Images
{
    static final String LAST_KEY = "partyLast";
    static final List<Class<? extends WebsocketMessage>> MESSAGES =
        List.of(HdMapPartyLocation.class, HdMapPartyGear.class, HdMapPartyDrop.class);

    // The constructor takes these in this order.
    final Client client;
    final PartyService party;
    final WSClient wsClient;
    final EventBus eventBus;
    final ConfigManager configManager;
    final HdMapReforgedConfig config;
    final ItemManager itemManager;
    final SkillIconManager skillIcons;
    final ClientThread clientThread;
    final SpriteManager spriteManager;

    final PartyMapMembers members = new PartyMapMembers();
    final PartyMapRules.Throttle throttle = new PartyMapRules.Throttle();
    // Initializers may read later or constructor-set fields only through "this" or "PartyMap.this".
    final PartyMapOverlay overlay = new PartyMapOverlay(this::markers, () -> this.myWorld);

    {
        overlay.selected = id -> this.widgets.values().stream().anyMatch(w -> w.selected() == id);
        overlay.hovered = id -> id == this.hoveredMember;
        overlay.loot = id -> members.loot(id, System.currentTimeMillis());
        overlay.itemImage = this::item;
        overlay.ticker = new PartyMapOverlay.Ticker(this::repaint);
    }

    /** Swing thread only; each view's value undoes what {@link #start} added to it. */
    final Map<MapView, Runnable> views = new LinkedHashMap<>();
    final Map<MapView, FriendsWidget> widgets = new LinkedHashMap<>();
    volatile int myWorld;
    /** The party this plugin joined for the user, or null. */
    volatile String joinedCode;
    volatile long lastChange = Long.MIN_VALUE / 2;
    Timer idleCheck;
    volatile boolean sentOnline;
    volatile Long loggedOutSince;

    volatile boolean gearChanged = true;
    int gearSentTick = Integer.MIN_VALUE / 2;
    /** The members as last read without a clash with the websocket thread. */
    volatile List<FriendsWidget.Member> lastGroup = Collections.emptyList();
    final Map<Long, BufferedImage> itemImages = new ConcurrentHashMap<>();

    void start(MapView... maps)
    {
        MESSAGES.forEach(wsClient::registerMessage);
        eventBus.register(this);
        for (int id : Orbs.SPRITES)
        {
            spriteManager.getSpriteAsync(id, 0, image -> {
                sprites.put(id, image);
                repaint();
            });
        }
        loggedOutSince = client.getGameState() == GameState.LOGGED_IN ? null : System.currentTimeMillis();
        SwingUtilities.invokeLater(() -> {
            for (var view : maps)
            {
                MapView.MenuContributor menu = (popup, point) -> contribute(popup, view);
                view.addOverlay(overlay);
                view.menuContributors.add(menu);
                FriendsWidget widget = new FriendsWidget(this::markers, this::groupMembers, party::isInParty,
                    () -> myWorld, config::partyFriendsTab, row -> follow(view, row.id), view::repaint,
                    new PartyMapOverlay.Ticker(view::repaint));
                widget.drops = id -> members.drops(id, System.currentTimeMillis());
                widget.canJoin = () -> !party.isInParty() && lastParty() != null;
                widget.join = () -> join(view);
                MapView.ClickCatcher catcher = (at, projection) -> clickedMember(view, widget, at, projection);
                view.clickCatchers.add(catcher);
                var pointing = new MouseAdapter()
                {
                    public void mouseMoved(MouseEvent e)
                    {
                        long now = memberAt(e.getPoint(), view.projection());
                        if (now != hoveredMember)
                        {
                            hoveredMember = now;
                            view.repaint();
                        }
                    }

                    public void mouseExited(MouseEvent e)
                    {
                        if (hoveredMember >= 0)
                        {
                            hoveredMember = -1;
                            view.repaint();
                        }
                    }
                };
                view.addMouseMotionListener(pointing);
                view.addMouseListener(pointing);
                widget.gear = members::gear;
                widget.images = this;
                widgets.put(view, widget);
                view.addWidget(widget);
                views.put(view, () -> {
                    view.removeOverlay(overlay);
                    view.menuContributors.remove(menu);
                    view.clickCatchers.remove(catcher);
                    view.removeMouseMotionListener(pointing);
                    view.removeMouseListener(pointing);
                    view.removeWidget(widget);
                    widget.ticker.stop();
                });
            }
            idleCheck = new Timer(30_000, e -> checkIdle());
            idleCheck.start();
        });
    }

    void stop()
    {
        sendOffline();
        eventBus.unregister(this);
        MESSAGES.forEach(wsClient::unregisterMessage);
        members.clear();
        throttle.reset();
        itemImages.clear();
        sprites.clear();
        SwingUtilities.invokeLater(() -> {
            if (idleCheck != null)
            {
                idleCheck.stop();
                idleCheck = null;
            }
            views.values().forEach(Runnable::run);
            views.clear();
            widgets.clear();
            overlay.ticker.stop();
            if (PartyMapRules.leaveOnShutdown(joinedCode, party.getPartyPassphrase()))
            {
                party.changeParty(null);
            }
            joinedCode = null;
        });
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        myWorld = client.getWorld();
    }

    volatile long hoveredMember = -1;

    boolean clickedMember(MapView view, FriendsWidget widget, Point at, Projection projection)
    {
        long best = memberAt(at, projection);
        if (best < 0)
        {
            return false;
        }
        widget.show(best);
        follow(view, best);
        repaint();
        return true;
    }

    long memberAt(Point at, Projection projection)
    {
        long best = -1;
        double bestDistance = 14;
        for (var marker : markers())
        {
            // Where the map draws them, which can differ from the game.
            var shown = projection.shown(marker.point);
            if (!projection.shows(marker.point))
            {
                continue;
            }
            double d = at.distance(projection.screenX(shown.getX() + 0.5), projection.screenY(shown.getY() + 0.5));
            if (d < bestDistance)
            {
                bestDistance = d;
                best = marker.id;
            }
        }
        return best;
    }

    final Map<Integer, BufferedImage> sprites = new ConcurrentHashMap<>();
    /** The sidebar's and the map's pictures of what members share. */
    public BufferedImage skill(int ordinal)
    {
        var skills = Skill.values();
        return ordinal < 0 || ordinal >= Math.min(SKILLS, skills.length) ? null
            : skillIcons.getSkillImage(skills[ordinal], true);
    }

    public BufferedImage sprite(int id)
    {
        return sprites.get(id);
    }

    /** The sidebar's party list. */
    public boolean inGroup()
    {
        return party.isInParty();
    }

    public List<FriendsWidget.Row> rows()
    {
        return FriendsWidget.rows(markers(), groupMembers());
    }

    public int world()
    {
        return myWorld;
    }

    public PartyMapMembers.Gear gear(long id)
    {
        return members.gear(id);
    }

    public FriendsWidget.Images images()
    {
        return this;
    }

    public boolean canRejoin()
    {
        return lastParty() != null;
    }

    public void follow(long id)
    {
        views.keySet().forEach(view -> follow(view, id));
    }

    /** Follows a member clicked: the map keeps them in view as they move. Swing thread. */
    void follow(MapView view, long id)
    {
        Supplier<WorldPoint> at = () -> markers().stream().filter(m -> m.id == id).map(m -> m.point).findFirst()
            .orElse(null);
        if (at.get() != null)
        {
            view.follow(at);
        }
    }

    List<FriendsWidget.Member> groupMembers()
    {
        var list = new ArrayList<FriendsWidget.Member>();
        if (!party.isInParty())
        {
            return list;
        }
        List<PartyMember> all;
        try
        {
            // The websocket thread changes this list while we read it on the Swing thread.
            all = new ArrayList<>(party.getMembers());
        }
        catch (ConcurrentModificationException | ArrayIndexOutOfBoundsException e)
        {
            return new ArrayList<>(lastGroup);
        }
        for (var member : all)
        {
            if (member != null && !isLocal(member.getMemberId()))
            {
                // RuneLite names a member "<unknown>" until they log in and send their name.
                String name = member.getDisplayName();
                list.add(new FriendsWidget.Member(member.getMemberId(),
                    name == null || name.startsWith("<") ? null : PartyMapMembers.clean(name)));
            }
        }
        lastGroup = List.copyOf(list);
        return list;
    }

    List<PartyMapMembers.Marker> markers()
    {
        return config.partyShowMembers() ? members.markers(System.currentTimeMillis()) : Collections.emptyList();
    }

    void tick(WorldPoint location, boolean house, int tick)
    {
        if (!members.isEmpty() && tick % 5 == 0)
        {
            // Markers fade over minutes: every few seconds is enough (animations have their own ticker).
            repaint();
        }
        // Run and special attack energy alone are no reason to send.
        if (gearChanged && party.isInParty() && config.partyShareGear()
            && tick - gearSentTick >= PartyMapRules.GEAR_TICKS)
        {
            gearChanged = false;
            gearSentTick = tick;
            party.send(gear());
        }
        if (party.isInParty() && config.partyShareLocation() && throttle.shouldSend(location, tick))
        {
            party.send(new HdMapPartyLocation(location, client.getWorld(), localName(), house));
            sentOnline = true;
        }
    }

    String localName()
    {
        Player player = client.getLocalPlayer();
        return player == null || player.getName() == null ? null : Text.removeTags(player.getName());
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        GameState state = event.getGameState();
        if (state == GameState.LOGGED_IN)
        {
            loggedOutSince = null;
        }
        else if (state == GameState.LOGIN_SCREEN)
        {
            if (loggedOutSince == null)
            {
                loggedOutSince = System.currentTimeMillis();
            }
            sendOffline();
            throttle.reset();
            myWorld = 0;
        }
        else if (state == GameState.HOPPING)
        {
            // The same tile on another world: sent at once, not only with the next heartbeat.
            throttle.force();
        }
    }

    void sendOffline()
    {
        if (sentOnline && party.isInParty())
        {
            party.send(HdMapPartyLocation.offline(null));
        }
        sentOnline = false;
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!GROUP.equals(event.getGroup()) || !event.getKey().startsWith("party"))
        {
            return;
        }
        if ("partyShareLocation".equals(event.getKey()) && !config.partyShareLocation() && party.isInParty()
            && client.getGameState() == GameState.LOGGED_IN)
        {
            party.send(HdMapPartyLocation.offline(null));
            sentOnline = false;
        }
        throttle.force();
        repaint();
    }

    // Party events arrive on the websocket thread.

    @Subscribe
    public void onHdMapPartyLocation(HdMapPartyLocation message)
    {
        if (isLocal(message.getMemberId()))
        {
            return;
        }
        members.update(message.getMemberId(), message.point(), message.world(), message.name(),
            message.house(), System.currentTimeMillis());
        memberDetails(message.getMemberId());
        repaint();
    }

    /** RuneLite's Party plugin's messages, for members without this plugin. */
    @Subscribe
    public void onLocationUpdate(LocationUpdate message)
    {
        if (isLocal(message.getMemberId()))
        {
            return;
        }
        var point = message.getWorldPoint();
        if (!HdMapPartyLocation.plausible(point))
        {
            return;
        }
        if (members.updateFromCore(message.getMemberId(), point, System.currentTimeMillis()))
        {
            memberDetails(message.getMemberId());
            repaint();
        }
    }

    @Subscribe
    public void onUserJoin(UserJoin event)
    {
        throttle.force();
        gearChanged = true;
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        int id = event.getContainerId();
        if (id == InventoryID.INV || id == InventoryID.WORN)
        {
            gearChanged = true;
        }
    }

    @Subscribe
    public void onStatChanged(StatChanged event)
    {
        gearChanged = true;
    }

    @Subscribe
    public void onHdMapPartyGear(HdMapPartyGear message)
    {
        if (isLocal(message.getMemberId()))
        {
            return;
        }
        members.gear(message.getMemberId(), new PartyMapMembers.Gear(message, System.currentTimeMillis()));
        repaint();
    }

    @Subscribe
    public void onNpcLootReceived(NpcLootReceived event)
    {
        shareDrops(event.getItems());
    }

    @Subscribe
    public void onPlayerLootReceived(PlayerLootReceived event)
    {
        shareDrops(event.getItems());
    }

    void shareDrops(Collection<ItemStack> items)
    {
        // Untradeables go only with drop sharing on: turned off, nothing is shared.
        boolean untradeables = config.partyShareUntradeables();
        if (!party.isInParty() || !config.partyShareDrops())
        {
            return;
        }
        var valuable = new ArrayList<HdMapPartyDrop>();
        for (ItemStack stack : items)
        {
            long value = itemManager.getItemPriceWithSource(stack.getId(), false) * stack.getQuantity();
            // A lower value saved before the setting had its minimum still reads back as it was.
            if (value >= Math.max(MIN_DROP_VALUE, config.partyDropValue())
                || untradeables && !tradeable(stack.getId()))
            {
                valuable.add(new HdMapPartyDrop(stack.getId(), stack.getQuantity(), value));
            }
        }
        // Only the most valuable few; the map shows no more.
        valuable.sort(Comparator.comparingLong((HdMapPartyDrop d) -> -d.value()));
        for (var drop : valuable.subList(0, Math.min(valuable.size(), PartyMapRules.MAX_DROPS_PER_LOOT)))
        {
            party.send(drop);
        }
    }

    boolean tradeable(int item)
    {
        return itemManager.getItemComposition(itemManager.canonicalize(item)).isTradeable();
    }

    @Subscribe
    public void onHdMapPartyDrop(HdMapPartyDrop message)
    {
        int item = message.item();
        if (isLocal(message.getMemberId()) || item < 0)
        {
            return;
        }
        // Only items the game has, valued by our own prices.
        clientThread.invoke(() -> {
            if (item < client.getItemCount())
            {
                long value = itemManager.getItemPriceWithSource(item, false) * message.quantity();
                // An untradeable one shows by name, as it has no price.
                String name = tradeable(item) ? null : itemManager.getItemComposition(item).getName();
                members.loot(message.getMemberId(), new PartyMapMembers.Loot(item, message.quantity(), value,
                    System.currentTimeMillis(), name));
                repaint();
            }
        });
    }

    HdMapPartyGear gear()
    {
        int[] quantities = new int[INVENTORY];
        int[] inventory = items(InventoryID.INV, quantities);
        int[] equipment = items(InventoryID.WORN, new int[EQUIPMENT]);
        int[] levels = new int[SKILLS];
        int[] boosted = new int[SKILLS];
        int[] experience = new int[SKILLS];
        var skills = Skill.values();
        for (int k = 0; k < Math.min(skills.length, levels.length); k++)
        {
            levels[k] = client.getRealSkillLevel(skills[k]);
            boosted[k] = client.getBoostedSkillLevel(skills[k]);
            experience[k] = client.getSkillExperience(skills[k]);
        }
        return new HdMapPartyGear(inventory, quantities, equipment, levels, boosted, experience,
            client.getEnergy() / 100, client.getVarpValue(VarPlayerID.SA_ENERGY) / 10);
    }

    /** Item ids (-1 where empty) and quantities of a container, as many as {@code quantities} holds. */
    int[] items(int container, int[] quantities)
    {
        int[] ids = new int[quantities.length];
        Arrays.fill(ids, -1);
        var items = client.getItemContainer(container);
        Item[] all = items == null ? new Item[0] : items.getItems();
        for (int k = 0; k < Math.min(all.length, ids.length); k++)
        {
            ids[k] = all[k].getId();
            quantities[k] = all[k].getQuantity();
        }
        return ids;
    }

    public BufferedImage item(int id, int quantity)
    {
        long key = (long) id << 32 | quantity;
        if (itemImages.size() > 512 && !itemImages.containsKey(key))
        {
            itemImages.clear();
        }
        return itemImages.computeIfAbsent(key, k -> {
            var image = itemManager.getImage(id, quantity, quantity > 1);
            image.onLoaded(this::repaint);
            return image;
        });
    }

    @Subscribe
    public void onUserSync(UserSync event)
    {
        throttle.force();
    }

    @Subscribe
    public void onUserPart(UserPart event)
    {
        members.remove(event.getMemberId());
        repaint();
    }

    @Subscribe
    public void onPartyChanged(PartyChanged event)
    {
        if (event.getPartyId() != null && event.getPassphrase() != null && !event.getPassphrase().isEmpty())
        {
            // Whoever joined it (this plugin or RuneLite's Party panel).
            configManager.setConfiguration(GROUP, LAST_KEY, event.getPassphrase());
        }
        String ours = joinedCode;
        if (ours != null && !ours.equals(event.getPassphrase()))
        {
            // A party joined by hand is the user's own and never left for them.
            joinedCode = null;
        }
        members.clear();
        throttle.reset();
        throttle.force();
        repaint();
    }

    @Subscribe
    public void onPartyMemberAvatar(PartyMemberAvatar event)
    {
        members.avatar(event.getMemberId(), event.getImage());
        repaint();
    }

    boolean isLocal(long memberId)
    {
        var local = party.getLocalMember();
        return local != null && local.getMemberId() == memberId;
    }

    void memberDetails(long memberId)
    {
        try
        {
            var member = party.getMemberById(memberId);
            if (member != null)
            {
                members.name(memberId, member.getDisplayName());
                BufferedImage avatar = member.getAvatar();
                if (avatar != null)
                {
                    members.avatar(memberId, avatar);
                }
            }
        }
        catch (ConcurrentModificationException e)
        {
            // The next message fills this in.
        }
    }

    void repaint()
    {
        SwingUtilities.invokeLater(() -> {
            for (var view : views.keySet())
            {
                view.followMember();
                view.repaint();
            }
        });
    }

    void contribute(JPopupMenu popup, MapView view)
    {
        var friends = new JMenu("Party");
        String current = party.getPartyPassphrase();
        for (var marker : markers())
        {
            String name = marker.name != null ? marker.name : "party member";
            friends.add("Show " + name + (marker.stale() ? " (" + PartyMapOverlay.ago(marker.ageMillis) + ")" : ""))
                .addActionListener(a -> view.focus(marker.point));
        }
        if (friends.getMenuComponentCount() > 0)
        {
            friends.addSeparator();
        }
        if (current != null)
        {
            friends.add("Leave party").addActionListener(a -> leave());
        }
        else if (lastParty() != null)
        {
            friends.add("Rejoin party").addActionListener(a -> join(view));
        }
        if (friends.getMenuComponentCount() == 0)
        {
            friends.add("Join a party in RuneLite's Party panel").setEnabled(false);
        }
        popup.addSeparator();
        popup.add(friends);
    }

    String lastParty()
    {
        String last = configManager.getConfiguration(GROUP, LAST_KEY);
        return last == null || last.trim().isEmpty() ? null : last.trim();
    }

    public void join(Component view)
    {
        String code = lastParty();
        if (code == null)
        {
            return;
        }
        long now = System.currentTimeMillis();
        String current = party.getPartyPassphrase();
        switch (PartyMapRules.join(code, client.getGameState() == GameState.LOGGED_IN, current, lastChange, now))
        {
            case ALREADY_IN:
            case INVALID_CODE:
                return;
            case NOT_LOGGED_IN:
                tell(view, "Log in to the game first, then rejoin the party.");
                return;
            case TOO_SOON:
                tell(view, "You just changed party. Try again in a few seconds.");
                return;
            case CONFIRM_LEAVE_OTHER:
                if (JOptionPane.showConfirmDialog(view, "You are in another party. Leave it and rejoin your last party?",
                    "Reimagined World Map", JOptionPane.YES_NO_OPTION) != JOptionPane.YES_OPTION)
                {
                    return;
                }
                break;
            default:
                break;
        }
        lastChange = now;
        joinedCode = code;
        party.changeParty(code);
    }

    static void tell(Component to, String message)
    {
        JOptionPane.showMessageDialog(to, message, "Reimagined World Map", JOptionPane.INFORMATION_MESSAGE);
    }

    void leave()
    {
        lastChange = System.currentTimeMillis();
        joinedCode = null;
        party.changeParty(null);
    }

    /** Leaves a party we rejoined after long logged out, as RuneLite's Party plugin does. */
    void checkIdle()
    {
        if (PartyMapRules.leaveIdle(joinedCode, party.getPartyPassphrase(), loggedOutSince, System.currentTimeMillis()))
        {
            log.debug("Leaving the party we rejoined after a long time logged out");
            leave();
        }
    }
}

package com.hdmapreforged;

import com.hdmapreforged.route.*;
import java.awt.image.*;
import java.util.*;
import java.util.function.*;
import lombok.*;
import net.runelite.api.coords.*;

/** Last known location of each party member: written from network threads, read on Swing, so all synchronized. */
final class PartyMapMembers
{
    /** Heartbeats come every 30 s; after this without news the marker fades. */
    static final long FRESH_MILLIS = 75_000;
    static final long FADE_MILLIS = 5 * 60_000;
    /** After this without news the member is left off the map (probably crashed). */
    static final long GONE_MILLIS = 30 * 60_000;
    static final float MIN_ALPHA = 0.4f;
    /** The core Party plugin's location messages are coarser; ours win while they keep coming. */
    static final long OWN_MESSAGE_PRIORITY_MILLIS = 60_000;

    @RequiredArgsConstructor
    static final class Marker
    {
        final long id;
        final String name;
        final WorldPoint point;
        final int world;
        final BufferedImage avatar;
        final long ageMillis;
        final float alpha;
        /** In a house, at its portal. */
        final boolean house;

        boolean stale()
        {
            return ageMillis > FRESH_MILLIS;
        }
    }

    static final class Member
    {
        String name;
        WorldPoint point;
        boolean house;
        int world;
        BufferedImage avatar;
        long updated;
        long ownUpdated = Long.MIN_VALUE / 2;
    }

    final Map<Long, Member> members = new HashMap<>();
    final Map<Long, Gear> gear = new HashMap<>();

    static final class Gear
    {
        final int[] inventory;
        final int[] quantities;
        final int[] equipment;
        final int[] levels;
        final int[] boosted;
        /** Null when not shared (an older version). */
        final int[] experience;
        /** 0 to 100, or -1 when not shared. */
        final int run;
        final int special;
        final long at;

        Gear(HdMapPartyGear message, long at)
        {
            inventory = message.inventory();
            quantities = message.quantities();
            equipment = message.equipment();
            levels = message.levels();
            boosted = message.boosted();
            experience = message.experience();
            run = message.runEnergy();
            special = message.specialAttack();
            this.at = at;
        }
    }

    @RequiredArgsConstructor
    static final class Drop
    {
        final int skill;
        final int amount;
        final long at;
    }

    static final long DROP_MS = 2200;
    static final int MAX_DROPS = 16;
    final Map<Long, List<Drop>> drops = new HashMap<>();

    synchronized void gear(long id, Gear shared)
    {
        Gear before = gear.put(id, shared);
        if (before != null && before.experience != null && shared.experience != null)
        {
            var list = drops.computeIfAbsent(id, k -> new ArrayList<>());
            for (int k = 0; k < shared.experience.length; k++)
            {
                int gained = shared.experience[k] - before.experience[k];
                if (gained > 0 && gained < 5_000_000)
                {
                    list.add(new Drop(k, gained, shared.at));
                }
            }
            // Only read while details are open: keep it short either way.
            list.removeIf(d -> shared.at - d.at > DROP_MS);
            if (list.size() > MAX_DROPS)
            {
                list.subList(0, list.size() - MAX_DROPS).clear();
            }
        }
    }

    @RequiredArgsConstructor
    static final class Loot
    {
        final int item;
        final int quantity;
        final long value;
        final long at;
        /** An untradeable drop's name, else null. */
        final String name;
    }

    static final long LOOT_MS = 3500;
    final Map<Long, List<Loot>> loot = new HashMap<>();

    synchronized void loot(long id, Loot drop)
    {
        var list = loot.computeIfAbsent(id, k -> new ArrayList<>());
        list.removeIf(l -> drop.at - l.at > LOOT_MS);
        list.add(drop);
        // A big pile shows its most valuable few.
        if (list.size() > 4)
        {
            list.sort(Comparator.comparingLong((Loot l) -> -l.value));
            list.subList(4, list.size()).clear();
        }
    }

    synchronized List<Loot> loot(long id, long now)
    {
        return recent(loot.get(id), l -> now - l.at > LOOT_MS);
    }

    /** A copy without the old ones, which go. */
    static <T> List<T> recent(List<T> list, Predicate<T> old)
    {
        if (list == null)
        {
            return Collections.emptyList();
        }
        list.removeIf(old);
        return new ArrayList<>(list);
    }

    synchronized List<Drop> drops(long id, long now)
    {
        return recent(drops.get(id), d -> now - d.at > DROP_MS);
    }

    synchronized Gear gear(long id)
    {
        return gear.get(id);
    }

    /** A location from our own message; a null point means they left the game. */
    synchronized void update(long id, WorldPoint point, int world, String name, boolean house, long now)
    {
        Member member = members.computeIfAbsent(id, k -> new Member());
        // From a version that sent the house's room template (far off any map): its last spot outside, in a house.
        boolean template = point != null && HouseTracker.isTemplate(point.getX(), point.getY());
        member.point = template ? member.point : point;
        member.house = house || template;
        member.world = world;
        if (name != null)
        {
            member.name = name;
        }
        member.updated = now;
        member.ownUpdated = now;
    }

    /** A location from RuneLite's Party plugin, used only while no recent message of ours came. */
    synchronized boolean updateFromCore(long id, WorldPoint point, long now)
    {
        Member member = members.computeIfAbsent(id, k -> new Member());
        if (now - member.ownUpdated < OWN_MESSAGE_PRIORITY_MILLIS)
        {
            return false;
        }
        member.point = point;
        member.house = false;
        member.updated = now;
        return true;
    }

    /** From RuneLite's party data, when the member's own messages carry none. */
    synchronized void name(long id, String name)
    {
        Member member = members.get(id);
        name = clean(name);
        if (member != null && member.name == null && name != null)
        {
            member.name = name;
        }
    }

    /** Never HTML in a Swing label; null when nothing is left. */
    static String clean(String name)
    {
        return HdMapPartyLocation.cleaned(name, true);
    }

    synchronized void avatar(long id, BufferedImage avatar)
    {
        Member member = members.get(id);
        if (member != null)
        {
            member.avatar = avatar;
        }
    }

    synchronized void remove(long id)
    {
        List.of(members, gear, drops, loot).forEach(m -> m.remove(id));
    }

    synchronized void clear()
    {
        List.of(members, gear, drops, loot).forEach(Map::clear);
    }

    synchronized boolean isEmpty()
    {
        return members.isEmpty();
    }

    /** Oldest news first so the freshest end up on top. */
    synchronized List<Marker> markers(long now)
    {
        var markers = new ArrayList<Marker>();
        for (var entry : members.entrySet())
        {
            Member member = entry.getValue();
            long age = Math.max(0, now - member.updated);
            if (member.point == null || age > GONE_MILLIS)
            {
                continue;
            }
            markers.add(new Marker(entry.getKey(), member.name, member.point, member.world, member.avatar, age, alpha(age),
                member.house));
        }
        markers.sort((a, b) -> Long.compare(b.ageMillis, a.ageMillis));
        return Collections.unmodifiableList(markers);
    }

    /** Full until FRESH_MILLIS, then fading linearly to MIN_ALPHA over FADE_MILLIS. */
    static float alpha(long ageMillis)
    {
        if (ageMillis <= FRESH_MILLIS)
        {
            return 1f;
        }
        double t = Math.min(1, (ageMillis - FRESH_MILLIS) / (double) FADE_MILLIS);
        return (float) (1 - t * (1 - MIN_ALPHA));
    }
}

package com.hdmapreforged;

import static java.lang.Math.*;
import static com.hdmapreforged.PlayerMarker.circle;
import static com.hdmapreforged.MapView.text;

import java.awt.*;
import java.awt.geom.*;
import java.awt.image.*;
import java.util.*;
import java.util.List;
import java.util.function.*;
import javax.swing.Timer;
import lombok.*;
import net.runelite.api.coords.*;
import com.hdmapreforged.PartyMapMembers.Marker;

/** Party members on the map: a disc (or avatar) with their initial; name and world when pointed at or clicked. */
@RequiredArgsConstructor
final class PartyMapOverlay implements MapView.Overlay
{
    /** Distinct from the player's yellow and the icon colours. */
    static final Color[] COLORS = {
        new Color(64, 200, 255),
        new Color(255, 105, 180),
        new Color(90, 230, 120),
        new Color(255, 140, 60),
        new Color(170, 130, 255),
        new Color(60, 230, 210),
        new Color(255, 90, 90),
        new Color(200, 230, 80),
    };
    static final Color LABEL_BACKGROUND = new Color(20, 20, 24, 200);
    static final Font NAME_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 11);
    static final Font SMALL_FONT = new Font(Font.SANS_SERIF, Font.PLAIN, 10);

    final Supplier<List<Marker>> markers;
    final IntSupplier myWorld;
    /** Only the clicked member and the one under the mouse show a name. */
    LongPredicate selected = id -> false;
    LongPredicate hovered = id -> false;

    LongFunction<List<PartyMapMembers.Loot>> loot = id -> Collections.emptyList();
    BiFunction<Integer, Integer, BufferedImage> itemImage = (id, q) -> null;
    /** Replaced by the party map with one that repaints its views. */
    Ticker ticker = new Ticker(() -> { });

    /**
     * Repaints ~30 times a second while something moves, instead of asking for a frame from inside paint (which never
     * lets the map rest); stops by itself once nothing moved for a moment. Swing thread only.
     */
    static final class Ticker
    {
        static final int FRAME_MS = 33;
        static final long LINGER_MS = 200;
        final Timer timer;
        long lastMoving;

        Ticker(Runnable repaint)
        {
            timer = new Timer(FRAME_MS, e -> {
                if (System.currentTimeMillis() - lastMoving > LINGER_MS)
                {
                    ((Timer) e.getSource()).stop();
                    return;
                }
                repaint.run();
            });
        }

        void painted(boolean moving)
        {
            if (moving)
            {
                lastMoving = System.currentTimeMillis();
                timer.start(); // no-op while running
            }
        }

        void stop()
        {
            timer.stop();
        }
    }

    static Color color(long id)
    {
        long mixed = id * 0x9E3779B97F4A7C15L;
        return COLORS[(int) ((mixed >>> 33) % COLORS.length)];
    }

    /** Lower case, with spaces, underscores and hyphens the same, as the game treats names. */
    static String nameKey(String name)
    {
        return name == null ? "" : name.replace(' ', ' ').replace('_', ' ').replace('-', ' ').trim()
            .toLowerCase(Locale.ROOT);
    }

    public void paint(Graphics2D g, Projection projection)
    {
        var all = markers.get();
        if (all.isEmpty())
        {
            ticker.painted(false);
            return;
        }
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        boolean rising = false;
        for (var marker : all)
        {
            if (!projection.shows(marker.point))
            {
                continue;
            }
            var at = projection.shown(marker.point);
            double x = projection.screenX(at.getX() + 0.5);
            double y = projection.screenY(at.getY() + 0.5);
            paintMarker(g, projection, marker, at, x, y, myWorld.getAsInt(), selected.test(marker.id),
                hovered.test(marker.id));
            rising |= paintLoot(g, projection, marker, x, y);
        }
        ticker.painted(rising);
    }

    static final Color UNTRADEABLE = new Color(240, 210, 120);

    /** Ground Items' colours for a value: medium, high, insane. */
    static Color lootColor(long value)
    {
        return value >= 10_000_000 ? new Color(255, 102, 178) : value >= 1_000_000 ? new Color(153, 255, 153)
            : new Color(102, 178, 255);
    }

    /** "1.2M", "450K", as Ground Items writes values. */
    static String shortValue(long value)
    {
        if (value >= 10_000_000)
        {
            return value / 1_000_000 + "M";
        }
        if (value >= 1_000_000)
        {
            return String.format(Locale.ROOT, "%.1fM", value / 1_000_000.0);
        }
        return value / 1000 + "K";
    }

    /** Drops rising above the marker, newest lowest; true while any shows. */
    boolean paintLoot(Graphics2D g, Projection projection, Marker marker, double x, double y)
    {
        var showing = loot.apply(marker.id);
        if (showing.isEmpty())
        {
            return false;
        }
        // Off screen: nothing to keep the map drawing for.
        if (x < -120 || x > projection.width() + 120 || y < -40 || y > projection.height() + 40 + 22 * showing.size() + 60)
        {
            return false;
        }
        long now = System.currentTimeMillis();
        var layer = (Graphics2D) g.create();
        try
        {
            layer.setFont(NAME_FONT);
            var metrics = layer.getFontMetrics();
            for (int k = 0; k < showing.size(); k++)
            {
                var drop = showing.get(k);
                double t = min(1, (now - drop.at) / (double) PartyMapMembers.LOOT_MS);
                double rise = 1 - pow(1 - t, 3);
                float alpha = (float) (t < 0.75 ? 1 : 1 - (t - 0.75) / 0.25);
                layer.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, max(0, alpha)));
                double top = y - 22 - (showing.size() - 1 - k) * 22 - rise * 50;
                String text = drop.name != null ? drop.name : shortValue(drop.value);
                BufferedImage icon = itemImage.apply(drop.item, drop.quantity);
                int iconW = icon == null ? 0 : 26;
                double width = iconW + metrics.stringWidth(text) + 10;
                double left = x - width / 2;
                layer.setColor(new Color(20, 20, 24, 190));
                layer.fill(new RoundRectangle2D.Double(left, top - 12, width, 22, 10, 10));
                if (icon != null)
                {
                    layer.drawImage(icon, (int) left + 2, (int) top - 12, 26, 22, null);
                }
                layer.setColor(Color.BLACK);
                layer.drawString(text, (float) (left + iconW + 6), (float) top + 4);
                layer.setColor(drop.name != null ? UNTRADEABLE : lootColor(drop.value));
                layer.drawString(text, (float) (left + iconW + 5), (float) top + 3);
            }
        }
        finally
        {
            layer.dispose();
        }
        return true;
    }

    static void paintMarker(Graphics2D g, Projection projection, Marker marker, WorldPoint at, double x,
        double y, int myWorld, boolean chosen, boolean hover)
    {
        if (x < -40 || y < -40 || x > projection.width() + 40 || y > projection.height() + 40)
        {
            return;
        }
        float alpha = marker.alpha;
        boolean otherFloor = at.getPlane() != projection.plane();
        if (otherFloor)
        {
            alpha *= 0.6f;
        }
        var layer = (Graphics2D) g.create();
        try
        {
            layer.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
            Color color = color(marker.id);
            double r = 7.5;
            var disc = circle(x, y, r);
            if (marker.house)
            {
                PlayerMarker.box(layer, x, y, r, color);
                layer.setFont(NAME_FONT);
                text(layer, "House", x - layer.getFontMetrics().stringWidth("House") / 2.0, y - r - 12);
            }
            layer.setColor(RouteFeature.alpha(color, 60));
            layer.fill(circle(x, y, r + 5));
            if (marker.avatar != null)
            {
                Shape clip = layer.getClip();
                layer.clip(disc);
                layer.drawImage(marker.avatar, (int) round(x - r), (int) round(y - r),
                    (int) round(r * 2), (int) round(r * 2), null);
                layer.setClip(clip);
            }
            else
            {
                layer.setColor(color);
                layer.fill(disc);
                String initial = marker.name == null || marker.name.isEmpty() ? "?"
                    : marker.name.substring(0, 1).toUpperCase(Locale.ROOT);
                layer.setFont(NAME_FONT);
                var metrics = layer.getFontMetrics();
                layer.setColor(new Color(15, 15, 20));
                text(layer, initial, x - metrics.stringWidth(initial) / 2.0, y + metrics.getAscent() / 2.0 - 1.5);
            }
            // White: gold would read as the local player's yellow marker.
            ring(layer, disc, 2f, Color.WHITE);
            ring(layer, circle(x, y, r + 2), 1f, color);
            if (chosen)
            {
                ring(layer, circle(x, y, r + 5), 3f, Color.WHITE);
                ring(layer, circle(x, y, r + 8), 2f, color);
            }
            if (chosen || hover)
            {
                paintLabel(layer, marker, x, y + r + 4, color, otherFloor, otherWorld(marker, myWorld));
            }
        }
        finally
        {
            layer.dispose();
        }
    }

    static void ring(Graphics2D g, Shape shape, float width, Color color)
    {
        g.setStroke(new BasicStroke(width));
        g.setColor(color);
        g.draw(shape);
    }

    static void paintLabel(Graphics2D g, Marker marker, double x, double top, Color color,
        boolean otherFloor, boolean otherWorld)
    {
        String name = marker.name != null ? marker.name : "Party member";
        String detail = detail(marker, otherFloor, otherWorld);
        g.setFont(NAME_FONT);
        var nameMetrics = g.getFontMetrics();
        int nameWidth = nameMetrics.stringWidth(name);
        var smallMetrics = g.getFontMetrics(SMALL_FONT);
        int detailWidth = detail == null ? 0 : smallMetrics.stringWidth(detail);
        int width = max(nameWidth, detailWidth) + 10;
        int height = nameMetrics.getHeight() + (detail == null ? 0 : smallMetrics.getHeight()) + 2;
        double left = x - width / 2.0;
        var box = new RoundRectangle2D.Double(left, top, width, height, 8, 8);
        g.setColor(LABEL_BACKGROUND);
        g.fill(box);
        ring(g, box, 1f, color);
        double textLeft = x - nameWidth / 2.0;
        float baseline = (float) (top + 1 + nameMetrics.getAscent());
        g.setColor(Color.WHITE);
        text(g, name, textLeft, baseline);
        if (detail != null)
        {
            g.setFont(SMALL_FONT);
            g.setColor(otherWorld ? FriendsWidget.OTHER_WORLD : Floating.LIGHT);
            text(g, detail, x - detailWidth / 2.0, top + 1 + nameMetrics.getHeight() + smallMetrics.getAscent());
        }
    }

    static boolean otherWorld(Marker marker, int myWorld)
    {
        return marker.world > 0 && myWorld > 0 && marker.world != myWorld;
    }

    /** "World 330 · floor 1 · 3 min ago", leaving out what is not worth saying. */
    static String detail(Marker marker, boolean otherFloor, boolean otherWorld)
    {
        var text = new StringJoiner(" · ");
        if (otherWorld)
        {
            text.add("World " + marker.world);
        }
        if (otherFloor)
        {
            text.add("floor " + marker.point.getPlane());
        }
        if (marker.stale())
        {
            text.add(ago(marker.ageMillis));
        }
        return text.length() == 0 ? null : text.toString();
    }

    static String ago(long millis)
    {
        long minutes = millis / 60_000;
        return minutes < 1 ? (millis / 1000) + " s ago" : minutes + " min ago";
    }
}

package com.hdmapreforged;

import java.util.*;
import net.runelite.api.coords.*;

/**
 * Party decisions, free of RuneLite services for testing. Joining is always the user's own action: RuneLite rejects
 * auto-joined parties.
 */
final class PartyMapRules
{
    /** Party Hotkeys waits this long between party changes; so do we. */
    static final long CHANGE_COOLDOWN_MILLIS = 5_000;
    /** RuneLite's Party plugin leaves after 30 minutes logged out; we do the same for a party we rejoined. */
    static final long IDLE_LEAVE_MILLIS = 30 * 60_000;
    /** Every tick something changed, as RuneLite's own Party plugin sends its status. */
    static final int MIN_SEND_TICKS = 1;
    static final int GEAR_TICKS = 1;
    static final int MAX_DROPS_PER_LOOT = 4;
    /** Sent at least this often while standing still, so newcomers and fading work. */
    static final int HEARTBEAT_TICKS = 50;

    enum Join
    {
        JOIN,
        ALREADY_IN,
        CONFIRM_LEAVE_OTHER,
        NOT_LOGGED_IN,
        INVALID_CODE,
        TOO_SOON,
    }

    static Join join(String code, boolean loggedIn, String currentPassphrase, long lastChange, long now)
    {
        return code == null ? Join.INVALID_CODE : code.equals(currentPassphrase) ? Join.ALREADY_IN
            : !loggedIn ? Join.NOT_LOGGED_IN : now - lastChange < CHANGE_COOLDOWN_MILLIS ? Join.TOO_SOON
            : currentPassphrase != null ? Join.CONFIRM_LEAVE_OTHER : Join.JOIN;
    }

    /** Only a party this plugin joined; parties the user joined elsewhere are never left. */
    static boolean leaveIdle(String joinedCode, String currentPassphrase, Long loggedOutSince, long now)
    {
        return leaveOnShutdown(joinedCode, currentPassphrase) && loggedOutSince != null
            && now - loggedOutSince >= IDLE_LEAVE_MILLIS;
    }

    static boolean leaveOnShutdown(String joinedCode, String currentPassphrase)
    {
        return joinedCode != null && joinedCode.equals(currentPassphrase);
    }

    /** {@link #shouldSend} runs on the client thread; party events reset and force it from other threads. */
    static final class Throttle
    {
        WorldPoint lastSent;
        int lastTick = Integer.MIN_VALUE / 2;
        volatile boolean forced;

        void force()
        {
            forced = true;
        }

        synchronized void reset()
        {
            lastSent = null;
            lastTick = Integer.MIN_VALUE / 2;
            forced = false;
        }

        synchronized boolean shouldSend(WorldPoint point, int tick)
        {
            if (point == null)
            {
                return false;
            }
            int since = tick - lastTick;
            boolean moved = !Objects.equals(point, lastSent);
            boolean due = forced || since >= HEARTBEAT_TICKS || moved;
            if (!due || since < MIN_SEND_TICKS)
            {
                return false;
            }
            lastSent = point;
            lastTick = tick;
            forced = false;
            return true;
        }
    }
}

package com.hdmapreforged;

import java.util.*;
import java.util.function.*;
import com.hdmapreforged.route.*;

/**
 * The spirit trees one plants (Port Sarim, Etceteria, Brimhaven, Hosidius, the Farming Guild) that stand grown for this
 * account. The game says so only near the patch: its farming varbit, read where RuneLite's Time Tracking reads it
 * (FarmingWorld: the patch's regions and varbit), is 20 for a grown tree one travels by ("Spirit Tree[Travel,...]",
 * PatchImplementation.SPIRIT_TREE); any other value (growing, diseased, dead, to check, weeds) is none. Kept per account
 * (RS profile key {@link #KEY}); a patch not visited since is not known, so not used.
 */
final class PlantedSpiritTrees
{
    static final String KEY = "plantedSpiritTrees";
    /** The patch state of a grown spirit tree one can travel by. */
    static final int GROWN = 20;
    /** As the travel table's stops are named: the patch's varbit, then its regions (list "spirit tree patches"). */
    static final RouteFiles.Table<Map<String, int[]>> PATCHES = new RouteFiles.Table<>(() -> Pathfinder.pairs(
        "spirit tree patches", Pathfinder::ints));

    volatile Set<String> grown = Collections.emptySet();

    /** A stop of the travel table that needs a tree planted ("Only after planting a spirit tree here"). */
    static boolean planted(Poi stop)
    {
        return stop.type == PoiType.SPIRIT_TREE && stop.note != null && stop.note.startsWith("Only after planting");
    }

    Set<String> grown()
    {
        return grown;
    }

    void load(String saved)
    {
        grown = saved == null || saved.isBlank() ? Collections.emptySet()
            : Collections.unmodifiableSet(new TreeSet<>(Arrays.asList(saved.split(","))));
    }

    String text()
    {
        return String.join(",", grown);
    }

    /** In {@code region}: reads its patch, if it has one. Whether what is known changed. Client thread. */
    boolean update(int region, IntUnaryOperator varbit)
    {
        for (var patch : PATCHES.get().entrySet())
        {
            int[] read = patch.getValue();
            for (int i = 1; i < read.length; i++)
            {
                if (read[i] == region)
                {
                    String name = patch.getKey();
                    boolean stands = varbit.applyAsInt(read[0]) == GROWN;
                    if (stands == grown.contains(name))
                    {
                        return false;
                    }
                    var next = new TreeSet<String>(grown);
                    if (stands)
                    {
                        next.add(name);
                    }
                    else
                    {
                        next.remove(name);
                    }
                    grown = Collections.unmodifiableSet(next);
                    return true;
                }
            }
        }
        return false;
    }
}

package com.hdmapreforged;

import static java.awt.BasicStroke.*;
import static java.lang.Math.*;

import java.awt.*;
import java.awt.geom.*;

/** The local player on the map as a yellow target, or an arrow at the view's edge when out of sight. */
final class PlayerMarker
{
    static final Color YELLOW = new Color(255, 214, 64);
    static final Color SHADOW = new Color(0, 0, 0, 170);
    static final Font FONT = new Font(Font.SANS_SERIF, Font.BOLD, 11);

    /** {@code otherFloor}: drawn fainter and dashed; {@code home}: in a box saying so, where the house stands. */
    static void paint(Graphics2D g, TextSprites text, double x, double y, double zoom, boolean otherFloor, boolean home)
    {
        double ring = 12 + max(0, min(3, zoom)) * 1.5;
        if (home)
        {
            box(g, x, y, ring, YELLOW);
            label(g, text, "Home", x, y - ring - 16);
        }
        var dash = otherFloor ? new float[]{4f, 3f} : null;
        // A glow, so it reads on bright and dark areas alike.
        g.setColor(new Color(255, 214, 64, otherFloor ? 30 : 60));
        g.fill(circle(x, y, ring + 5));
        for (int pass = 0; pass < 2; pass++)
        {
            g.setColor(pass == 0 ? SHADOW : YELLOW);
            g.setStroke(new BasicStroke(pass == 0 ? 5f : 2.6f, CAP_BUTT, JOIN_ROUND, 10f, dash, 0f));
            g.draw(circle(x, y, ring));
        }
        double in = ring - 5;
        double out = ring + 5;
        for (int pass = 0; pass < 2; pass++)
        {
            g.setStroke(new BasicStroke(pass == 0 ? 2.4f : 1.4f, CAP_ROUND, JOIN_ROUND));
            g.setColor(pass == 0 ? SHADOW : YELLOW);
            for (int i = 0; i < 4; i++)
            {
                double a = PI / 2 * i;
                g.draw(new Line2D.Double(x + cos(a) * in, y + sin(a) * in, x + cos(a) * out,
                    y + sin(a) * out));
            }
        }
        g.setColor(otherFloor ? new Color(255, 214, 64, 150) : YELLOW);
        g.fill(circle(x, y, 5.5));
        g.setColor(Color.BLACK);
        g.setStroke(new BasicStroke(2f));
        g.draw(circle(x, y, 5.5));
        label(g, text, otherFloor ? "You (other floor)" : "You", x, y + ring + 8);
    }

    /** The box round a marker in a house, at its portal: room above for its label. */
    static void box(Graphics2D g, double x, double y, double ring, Color color)
    {
        var box = new RoundRectangle2D.Double(x - ring - 12, y - ring - 26, ring * 2 + 24, ring * 2 + 44, 10, 10);
        g.setColor(SHADOW);
        g.fill(box);
        g.setColor(color);
        g.setStroke(new BasicStroke(1.5f));
        g.draw(box);
    }

    /** Radius {@code r} round {@code (x, y)}; the party's markers and the route's ends draw with it too. */
    static Ellipse2D circle(double x, double y, double r)
    {
        return new Ellipse2D.Double(x - r, y - r, r * 2, r * 2);
    }

    /** An arrow at {@code (x, y)} pointing at {@code angle} (radians, screen coordinates). */
    static void pointer(Graphics2D g, TextSprites text, double x, double y, double angle)
    {
        var arrow = new Path2D.Double();
        arrow.moveTo(12, 0);
        arrow.lineTo(-8, -9);
        arrow.lineTo(-4, 0);
        arrow.lineTo(-8, 9);
        arrow.closePath();
        var at = AffineTransform.getTranslateInstance(x, y);
        at.rotate(angle);
        Shape shape = at.createTransformedShape(arrow);
        g.setColor(SHADOW);
        g.setStroke(new BasicStroke(4f, CAP_ROUND, JOIN_ROUND));
        g.draw(shape);
        g.setColor(YELLOW);
        g.fill(shape);
        g.setColor(Color.BLACK);
        g.setStroke(new BasicStroke(1.2f));
        g.draw(shape);
        label(g, text, "You", x - cos(angle) * 22, y - sin(angle) * 22 + 4);
    }

    static void label(Graphics2D g, TextSprites text, String label, double cx, double top)
    {
        g.setFont(FONT);
        var metrics = g.getFontMetrics();
        text.draw(g, label, FONT, (float) (cx - metrics.stringWidth(label) / 2.0), (float) (top + metrics.getAscent() / 2.0),
            YELLOW);
    }
}

package com.hdmapreforged;

import lombok.*;
import java.util.*;
import net.runelite.api.coords.*;

/** An icon on the map. */
@RequiredArgsConstructor
final class Poi
{
    @RequiredArgsConstructor
    static final class Link
    {
        final String label;
        final WorldPoint point;
        /** Null when no map draws it. */
        final BaseMap map;
        final Needs needs;
    }

    final PoiType type;
    final String name;
    final WorldPoint location;
    final BaseMap map;
    /** Highlighted together (such as all Ardougne cloak teleports); may be null. */
    final String group;
    final Needs needs;
    final String wikiQuery;
    /** Where an entrance or passage leads, or null. */
    final BaseMap target;
    final String note;
    final List<Link> links = new ArrayList<>();
    /**
     * Where the map draws it when not at {@link #location}: a teleport or transport on an upper floor of a building on
     * the surface is drawn on the ground floor (where its map icon stands), so it is seen on the map; routes go to its
     * location. Null: drawn at its location.
     */
    WorldPoint drawnAt;

    /** Where the map draws it. */
    WorldPoint drawn()
    {
        return drawnAt != null ? drawnAt : location;
    }

    /** Teleports stacked on this icon; empty for a single one. */
    final List<Poi> members = new ArrayList<>();
    /** Other things at the same place this icon stands for. */
    final List<Poi> nearby = new ArrayList<>();

    List<Link> links()
    {
        return Collections.unmodifiableList(links);
    }

    List<Poi> members()
    {
        return members.isEmpty() ? Collections.singletonList(this) : Collections.unmodifiableList(members);
    }

    List<Poi> nearby()
    {
        return Collections.unmodifiableList(nearby);
    }

    /** Icons with the things they stand for. */
    static List<Poi> flatten(List<Poi> pois)
    {
        var all = new ArrayList<Poi>(pois.size() + 16);
        for (var poi : pois)
        {
            all.add(poi);
            all.addAll(poi.nearby);
        }
        return all;
    }

    /** A spot of the game on the water (a Barracuda Trial's start, salvage): sailed to, not walked to its shore. */
    boolean atSea()
    {
        return type == PoiType.SALVAGE || name.startsWith("Barracuda Trial");
    }

    boolean hasGroup(String group)
    {
        return memberOf(group) != null;
    }

    Poi memberOf(String group)
    {
        if (group == null)
        {
            return null;
        }
        for (var member : members())
        {
            if (group.equals(member.group))
            {
                return member;
            }
        }
        for (var other : nearby)
        {
            var member = other.memberOf(group);
            if (member != null)
            {
                return member;
            }
        }
        return null;
    }

    boolean isOn(BaseMap view)
    {
        return view != null && map != null && (view.id == BaseMap.FULL || map == view);
    }

    public String toString()
    {
        return name;
    }
}

package com.hdmapreforged;

import static java.awt.RenderingHints.*;
import static java.lang.Math.*;

import java.awt.*;
import java.awt.geom.*;
import java.awt.image.*;
import java.io.*;
import java.nio.charset.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.*;

/** Vector map icons, so they stay sharp at every zoom level and interface scale. */
final class PoiIcons
{
    static final Color OUTLINE = new Color(20, 18, 16);
    static final Color GLYPH = new Color(255, 255, 255, 240);

    /** Rendered badges by type, size and screen scale. */
    static final Map<Long, BufferedImage> SPRITES = new ConcurrentHashMap<>();
    /** The pixels they hold together: zooming makes a size per quarter pixel, and 4000 large ones were tens of MB. */
    static final AtomicLong SPRITE_PIXELS = new AtomicLong();

    /** {@link #paint} from a cached image: painting hundreds of badges shape by shape was most of a frame's cost. */
    static void paintCached(Graphics2D g, PoiType type, double cx, double cy, double size, boolean emphasised,
        boolean locked)
    {
        var transform = g.getTransform();
        double device = device(transform);
        // Quarter pixels of badge size, so zooming changes the image in small steps.
        int quarter = (int) round(size * 4);
        long key = (long) type.ordinal() << 40 | (locked ? 1L << 39 : 0) | (long) quarter << 16 | round(device * 10) << 1
            | (emphasised ? 1 : 0);
        double drawnSize = quarter / 4.0;
        // Room around the badge for the shadow and the emphasis ring.
        double extent = drawnSize + (ceil(drawnSize * 0.35) + 2) * 2;
        BufferedImage sprite = SPRITES.get(key);
        if (sprite == null)
        {
            // At most 4000 sprites and 4 million pixels.
            if (SPRITES.size() > 4000 || SPRITE_PIXELS.get() > 4_000_000)
            {
                SPRITES.clear();
                SPRITE_PIXELS.set(0);
            }
            sprite = sprite(extent, extent, device, sg -> {
                sg.setRenderingHint(KEY_STROKE_CONTROL, VALUE_STROKE_PURE);
                paint(sg, type, extent / 2, extent / 2, drawnSize, emphasised, locked);
            });
            SPRITES.put(key, sprite);
            SPRITE_PIXELS.addAndGet((long) sprite.getWidth() * sprite.getHeight());
        }
        blit(g, transform, sprite, cx - extent / 2, cy - extent / 2);
    }

    /** Draws a screen-resolution sprite on whole screen pixels: at fractions Java2D resamples it each draw (slow). */
    static void blit(Graphics2D g, BufferedImage sprite, double x, double y)
    {
        blit(g, g.getTransform(), sprite, x, y);
    }

    /** {@code transform}: the graphics' own. */
    static void blit(Graphics2D g, AffineTransform transform, BufferedImage sprite, double x, double y)
    {
        double tx = transform.getTranslateX();
        double ty = transform.getTranslateY();
        if (transform.getType() <= AffineTransform.TYPE_TRANSLATION && tx == rint(tx) && ty == rint(ty))
        {
            // Screen scale 1 on whole pixels: drawn in place, without swapping the transform (costly).
            g.drawImage(sprite, (int) round(x), (int) round(y), null);
            return;
        }
        if ((transform.getType() & (AffineTransform.TYPE_GENERAL_ROTATION | AffineTransform.TYPE_QUADRANT_ROTATION
            | AffineTransform.TYPE_GENERAL_TRANSFORM | AffineTransform.TYPE_FLIP)) != 0)
        {
            double device = device(transform);
            var place = new AffineTransform(transform);
            place.translate(x, y);
            place.scale(1 / device, 1 / device);
            g.drawImage(sprite, place, null);
            return;
        }
        long sx = round(transform.getScaleX() * x + tx);
        long sy = round(transform.getScaleY() * y + ty);
        g.setTransform(AffineTransform.getTranslateInstance(sx, sy));
        g.drawImage(sprite, 0, 0, null);
        g.setTransform(transform);
    }

    /** A white dot with a coloured rim, marking where a line ends; from a cached image. */
    static void paintDot(Graphics2D g, double cx, double cy, Color rim)
    {
        double device = device(g.getTransform());
        long key = (1L << 62) | ((long) (rim.getRGB() & 0xffffffffL) << 8) | (int) round(device * 10);
        double extent = 13;
        blit(g, SPRITES.computeIfAbsent(key, k -> sprite(extent, extent, device, sg -> {
            var dot = new Ellipse2D.Double(extent / 2 - 4.5, extent / 2 - 4.5, 9, 9);
            sg.setColor(Color.WHITE);
            sg.fill(dot);
            sg.setColor(rim);
            sg.setStroke(new BasicStroke(2f));
            sg.draw(dot);
        })), cx - extent / 2, cy - extent / 2);
    }

    /**
     * A game sprite with the game's sign for what one cannot use yet, in its own pixels as the game draws it: red on the
     * pixels just inside its outline, all round, and a band three pixels wide from top right to bottom left. Once per
     * sprite.
     */
    static BufferedImage locked(BufferedImage icon)
    {
        return LOCKED_SPRITES.computeIfAbsent(icon, k -> {
            int w = icon.getWidth();
            int h = icon.getHeight();
            var out = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
            for (int y = 0; y < h; y++)
            {
                for (int x = 0; x < w; x++)
                {
                    int rgb = icon.getRGB(x, y);
                    boolean red = drawn(icon, x, y) && !edge(icon, x, y) && (abs(x + y - (w + h - 2) / 2.0) <= 1
                        || edge(icon, x + 1, y) || edge(icon, x - 1, y) || edge(icon, x, y + 1) || edge(icon, x, y - 1));
                    out.setRGB(x, y, red ? LOCKED.getRGB() : rgb);
                }
            }
            return out;
        });
    }

    /** Whether the pixel is on the sprite's outline: drawn, beside one that is not. */
    static boolean edge(BufferedImage icon, int x, int y)
    {
        return drawn(icon, x, y)
            && !(drawn(icon, x + 1, y) && drawn(icon, x - 1, y) && drawn(icon, x, y + 1) && drawn(icon, x, y - 1));
    }

    static boolean drawn(BufferedImage icon, int x, int y)
    {
        return x >= 0 && y >= 0 && x < icon.getWidth() && y < icon.getHeight() && icon.getRGB(x, y) >>> 24 != 0;
    }

    static final Map<BufferedImage, BufferedImage> LOCKED_SPRITES = Collections.synchronizedMap(new WeakHashMap<>());
    static final Color LOCKED = new Color(230, 20, 20);

    /** Screen pixels per unit, clamped to a sane range; shared with {@link TextSprites}. */
    static double device(AffineTransform transform)
    {
        return max(1, min(4, abs(transform.getScaleX())));
    }

    /** A picture of {@code width} by {@code height} units, {@code device} pixels a unit (rounded up), drawn antialiased. */
    static BufferedImage sprite(double width, double height, double device, Consumer<Graphics2D> draw)
    {
        BufferedImage sprite = new BufferedImage((int) ceil(width * device), (int) ceil(height * device),
            BufferedImage.TYPE_INT_ARGB);
        var sg = sprite.createGraphics();
        sg.setRenderingHint(KEY_ANTIALIASING, VALUE_ANTIALIAS_ON);
        sg.scale(device, device);
        draw.accept(sg);
        sg.dispose();
        return sprite;
    }

    static void clearCache()
    {
        SPRITES.clear();
    }

    /** The game's own map icon for the type if it has one, else a round badge in the type's color with a glyph. */
    static void paint(Graphics2D g, PoiType type, double cx, double cy, double size, boolean emphasised, boolean locked)
    {
        BufferedImage game = GameIconSprites.get(type);
        if (game != null)
        {
            paintGameIcon(g, locked ? locked(game) : game, cx, cy, size, emphasised);
            return;
        }
        double r = size / 2;
        var badge = PlayerMarker.circle(cx, cy, r);
        if (emphasised)
        {
            g.setColor(new Color(255, 255, 255, 200));
            g.setStroke(new BasicStroke((float) (size * 0.16)));
            g.draw(new Ellipse2D.Double(cx - r - size * 0.14, cy - r - size * 0.14, size * 1.28, size * 1.28));
        }
        g.setColor(new Color(0, 0, 0, 90));
        g.fill(new Ellipse2D.Double(cx - r + size * 0.06, cy - r + size * 0.1, size, size));
        g.setColor(type.color);
        g.fill(badge);
        g.setColor(OUTLINE);
        g.setStroke(new BasicStroke((float) max(1, size * 0.08)));
        g.draw(badge);
        g.setColor(GLYPH);
        g.setStroke(new BasicStroke((float) max(1, size * 0.09), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        draw(g, GLYPHS.getOrDefault(type.name(), "O -0.4 -0.4 0.8 0.8"), cx, cy, r * 0.62);
    }

    static void paintGameIcon(Graphics2D g, BufferedImage icon, double cx, double cy, double size, boolean emphasised)
    {
        // Pixel art in whole pixels: enlarged by whole times (the nearest, at least once), made smaller smoothly.
        double fit = size / max(icon.getWidth(), icon.getHeight());
        double scale = fit >= 1 ? max(1, round(fit)) : fit;
        double w = icon.getWidth() * scale;
        double h = icon.getHeight() * scale;
        if (emphasised)
        {
            double r = max(w, h) / 2 + size * 0.18;
            g.setColor(new Color(255, 255, 255, 210));
            g.setStroke(new BasicStroke((float) max(1.5, size * 0.12)));
            g.draw(PlayerMarker.circle(cx, cy, r));
        }
        var copy = (Graphics2D) g.create();
        copy.setRenderingHint(KEY_INTERPOLATION, scale >= 1
            ? VALUE_INTERPOLATION_NEAREST_NEIGHBOR : VALUE_INTERPOLATION_BILINEAR);
        copy.drawImage(icon, new AffineTransform(scale, 0, 0, scale, round(cx - w / 2), round(cy - h / 2)),
            null);
        copy.dispose();
    }

    /** Draws a glyph from {@code poi_glyphs.txt} in units of {@code s} around {@code (x, y)}; the file lists the ops. */
    static void draw(Graphics2D g, String ops, double x0, double y0, double s0)
    {
        // The origin and unit; U moves them until the path is painted.
        double x = x0;
        double y = y0;
        double s = s0;
        Path2D pen = new Path2D.Double();
        for (String op : ops.split(";"))
        {
            var t = op.trim().split(" ");
            var a = new double[8];
            for (int i = 1; i < t.length; i++)
            {
                a[i] = Double.parseDouble(t[i]);
            }
            double px = x + s * a[1];
            double py = y + s * a[2];
            double w = s * a[3];
            double h = s * a[4];
            boolean fill = Character.isUpperCase(t[0].charAt(0));
            switch (t[0])
            {
                case "g":
                    pen = new GeneralPath();
                    break;
                case "m":
                    pen.moveTo(px, py);
                    break;
                case "l":
                    pen.lineTo(px, py);
                    break;
                case "q":
                    pen.quadTo(px, py, x + w, y + h);
                    break;
                case "b":
                    pen.curveTo(px, py, x + w, y + h, x + s * a[5], y + s * a[6]);
                    break;
                case "z":
                    pen.closePath();
                    break;
                case "P":
                case "p":
                    shape(g, pen, fill);
                    pen = new Path2D.Double();
                    x = x0;
                    y = y0;
                    s = s0;
                    break;
                case "U":
                    x = px;
                    y = py;
                    s = w;
                    break;
                case "R":
                    g.fill(new Rectangle2D.Double(px, py, w, h));
                    break;
                case "O":
                case "o":
                    shape(g, new Ellipse2D.Double(px, py, w, h), fill);
                    break;
                case "L":
                    g.draw(new Line2D.Double(px, py, x + w, y + h));
                    break;
                case "A":
                case "a":
                    shape(g, new Arc2D.Double(px, py, w, h, a[5], a[6], (int) a[7]), fill);
                    break;
                case "W":
                    g.fill(new RoundRectangle2D.Double(px, py, w, h, s * a[5], s * a[5]));
                    break;
                case "c":
                    g.fill(PlayerMarker.circle(px, py, w));
                    break;
                case "C":
                    g.setColor(OUTLINE);
                    break;
                case "K":
                    g.setColor(new Color((int) a[1], (int) a[2], (int) a[3]));
                    break;
                case "w":
                    g.setStroke(a[2] == 1 ? new BasicStroke((float) a[1], BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND)
                        : new BasicStroke((float) a[1]));
                    break;
                default:
                    throw new IllegalArgumentException(op);
            }
        }
    }

    /** Upper-case ops fill, lower-case ones outline. */
    static void shape(Graphics2D g, Shape shape, boolean fill)
    {
        if (fill)
        {
            g.fill(shape);
        }
        else
        {
            g.draw(shape);
        }
    }

    static final Map<String, String> GLYPHS = new HashMap<>();

    static
    {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(
            PoiIcons.class.getResourceAsStream("poi_glyphs.txt"), StandardCharsets.UTF_8)))
        {
            // A blank line or one without its tab is skipped, not a class that fails to load.
            reader.lines().map(line -> line.split("\t", 2))
                .filter(cells -> cells.length == 2 && !cells[0].startsWith("#"))
                .forEach(cells -> GLYPHS.put(cells[0], cells[1]));
        }
        catch (IOException e)
        {
            throw new UncheckedIOException(e);
        }
    }

    /** A small image of an icon, for buttons and lists. */
    static BufferedImage image(PoiType type, int size)
    {
        return sprite(size + 2, size + 2, 1, g -> {
            g.setRenderingHint(KEY_STROKE_CONTROL, VALUE_STROKE_PURE);
            paint(g, type, (size + 2) / 2.0 - 0.5, (size + 2) / 2.0 - 1, size - 1, false, false);
        });
    }

    static BufferedImage icon(int size, String name)
    {
        return sprite(size, size, 1, g -> draw(g, GLYPHS.get(name), 0, 0, 1));
    }

    /** The sidebar button: a folded map. */
    static BufferedImage navigationIcon()
    {
        return icon(16, "NAVIGATION");
    }
}

package com.hdmapreforged;

import java.awt.*;
import java.io.*;
import java.nio.charset.*;
import java.util.*;

enum PoiType
{
    TELEPORT, FAIRY_RING, SPIRIT_TREE, GNOME_GLIDER, BALLOON, QUETZAL, MUSHTREE, OBELISK, BOAT, CHARTER, CANOE, CARPET,
    MINECART, PORTAL, LEVER, TRANSPORT, DUNGEON_ENTRANCE, MAP_EXIT, MOORING, SALVAGE, RUNECRAFT_ALTAR, AGILITY_COURSE,
    AGILITY_SHORTCUT, FARMING_PATCH, MINIGAME, BANK, ALTAR, ANVIL,
    // The game's own icons: drawn by MapIconLayer from the game's sprites, not as our badges.
    SHOP, QUEST_START, MAP_LINK, GAME_ICON,
    /** A search result without an icon of its own: only selected, never drawn. */
    FOUND,
    /** One's grave while it stands: drawn by {@link GraveMarker}. */
    GRAVE;

    final String displayName;
    final Layer layer;
    final Color color;
    /** The game map element whose icon stands for this type (GameIconSprites); -1 none. */
    final int element;

    PoiType()
    {
        String[] cells = Rows.BY_TYPE.get(name());
        displayName = cells[1];
        layer = Layer.valueOf(cells[2]);
        color = new Color(Integer.parseInt(cells[3], 16));
        element = cells.length > 4 ? Integer.parseInt(cells[4]) : -1;
    }

    /** The types' names, layers, colours and game icons, bundled (data/poi_types.tsv). */
    private static final class Rows
    {
        static final Map<String, String[]> BY_TYPE = new HashMap<>();

        static
        {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(
                PoiType.class.getResourceAsStream("data/poi_types.tsv"), StandardCharsets.UTF_8)))
            {
                reader.lines().filter(line -> !line.startsWith("#")).map(line -> line.split("\t"))
                    .forEach(cells -> BY_TYPE.put(cells[0], cells));
            }
            catch (IOException e)
            {
                throw new UncheckedIOException(e);
            }
        }
    }

    /** Obelisks send you to a random other obelisk unless you can choose. */
    boolean isRandomDestination()
    {
        return this == OBELISK;
    }

    /** Fairy rings to obelisks, in the order above; every stop of one reaches every other. */
    static final Set<PoiType> NETWORKS = EnumSet.range(FAIRY_RING, OBELISK);
}

package com.hdmapreforged;

import net.runelite.api.coords.*;

/** Where world points appear in the frame being painted; add 0.5 to a tile for its middle. */
interface Projection
{
    double screenX(double worldX);

    double screenY(double worldY);

    /** Log2 of screen pixels per game tile. */
    double zoom();

    BaseMap map();

    int plane();

    int width();

    int height();

    boolean shows(WorldPoint point);

    /** Where a game point is drawn on the map in view (the Kalphite Lair is drawn beside the desert caves). */
    default WorldPoint shown(WorldPoint point)
    {
        return point;
    }
}

package com.hdmapreforged;

import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;

/**
 * Which maps really show a 64×64 region where map bounds overlap (empty: checked, none), and where several share a
 * region, which draws each 8×8 zone: a map version's regions.tsv from the map server (built from its tiles by the test
 * sources' RegionResolver).
 */
class RegionTable
{
    static final int[] NONE = new int[0];

    static final int ZONES = 8;
    static final int ZONE = 8;
    /** A zone's owners as a bit mask over the region's owner list, one character (up to 6 owners). */
    static final String MASKS = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_-";

    final Map<Integer, int[]> owners = new ConcurrentHashMap<>();
    /** 64 mask characters, zone (x, y) at index x * 8 + y. */
    final Map<Integer, String> zones = new ConcurrentHashMap<>();
    /**
     * Per region, by zone and floor ({@code (zone * 4 + floor)}): the map and floor drawing that floor's ground where the
     * zone's own map does not, packed as {@code (map id + 2) << 2 | floor}; 0 where the zone's map draws it.
     */
    final Map<Integer, int[]> floors = new ConcurrentHashMap<>();
    /**
     * By tile and floor ({@link #tileKey}): the map and floor drawing that floor's ground at that one tile where the map
     * shown there (after the zone's floor line) draws nothing, packed as the zones' ({@code (map id + 2) << 2 | floor});
     * for strips narrower than a zone (along Cam Torum's walls).
     */
    final Map<Integer, Integer> tileFloors = new ConcurrentHashMap<>();

    static int regionId(int x, int y)
    {
        return ((x >> 6) << 8) | (y >> 6);
    }

    /** Owner map ids, empty when none, or null when the table does not list the region. */
    int[] owners(int region)
    {
        return owners.get(region);
    }

    void put(int region, int[] ids)
    {
        owners.put(region, ids);
    }

    /**
     * The owners drawing a tile's zone, or when none does, the zones around it (an entrance just beside a drawing);
     * null when zones are not known; empty when none draws anything near.
     */
    int[] zoneOwners(int x, int y)
    {
        int region = regionId(x, y);
        String text = zones.get(region);
        var ids = owners.get(region);
        if (text == null || ids == null)
        {
            return null;
        }
        int zx = (x & 63) / ZONE;
        int zy = (y & 63) / ZONE;
        int mask = MASKS.indexOf(text.charAt(zx * ZONES + zy));
        if (mask == 0)
        {
            for (int dx = -1; dx <= 1; dx++)
            {
                for (int dy = -1; dy <= 1; dy++)
                {
                    int nx = zx + dx;
                    int ny = zy + dy;
                    if (nx >= 0 && ny >= 0 && nx < ZONES && ny < ZONES)
                    {
                        mask |= MASKS.indexOf(text.charAt(nx * ZONES + ny));
                    }
                }
            }
        }
        int count = Integer.bitCount(mask & ((1 << Math.min(6, ids.length)) - 1));
        var found = new int[count];
        int n = 0;
        for (int i = 0; i < ids.length && i < 6; i++)
        {
            if ((mask & 1 << i) != 0)
            {
                found[n++] = ids[i];
            }
        }
        return found;
    }

    /**
     * Where the ground a floor walks in this spot's zone is drawn when the zone's own map does not draw it on that floor
     * (an upper floor the game draws a floor lower, as the Brimhaven Dungeon's raised paths; a floor walked under the one
     * the game's map shows, as in Cam Torum): {map id, floor drawn}; null where the zone's map draws it.
     */
    int[] floorOverride(int x, int y, int floor)
    {
        if (floor < 0 || floor > 3)
        {
            return null;
        }
        Integer tile = tileFloors.isEmpty() ? null : tileFloors.get(tileKey(x, y, floor));
        if (tile != null)
        {
            return new int[]{(tile >> 2) - 2, tile & 3};
        }
        var packed = floors.get(regionId(x, y));
        int v = packed == null ? 0 : packed[((x & 63) / ZONE * ZONES + (y & 63) / ZONE) * 4 + floor];
        return v == 0 ? null : new int[]{(v >> 2) - 2, v & 3};
    }

    /** A tile and floor as one number (as the route data packs them). */
    static int tileKey(int x, int y, int floor)
    {
        return floor << 28 | x << 14 | y;
    }

    void putTileFloor(int x, int y, int floor, int mapId, int drawnFloor)
    {
        tileFloors.put(tileKey(x, y, floor), (mapId + 2) << 2 | drawnFloor);
    }

    void putFloor(int region, int zone, int floor, int mapId, int drawnFloor)
    {
        floors.computeIfAbsent(region, r -> new int[ZONES * ZONES * 4])[zone * 4 + floor] = (mapId + 2) << 2 | drawnFloor;
    }

    /**
     * Lines of region id, tab, comma-separated map ids, optionally tab and zones; floor lines ({@code F}, tab, region,
     * tab, {@code zone.floor=map/floor} comma-separated) and tile floor lines ({@code T}, tab, region, tab,
     * {@code x.y.floor=map/floor} comma-separated, x and y within the region), which tables before them did not have (a
     * reader that cannot read a line skips it); bad lines are skipped.
     */
    RegionTable read(Reader tsv) throws IOException
    {
        BufferedReader reader = new BufferedReader(tsv);
        String line;
        while ((line = reader.readLine()) != null)
        {
            if (line.startsWith("#") || line.trim().isEmpty())
            {
                continue;
            }
            try
            {
                if (line.startsWith(FLOOR_LINE))
                {
                    readFloors(line);
                    continue;
                }
                if (line.startsWith(TILE_FLOOR_LINE))
                {
                    readTileFloors(line);
                    continue;
                }
                readLine(line);
            }
            catch (RuntimeException e)
            {
                // Skipped: the maps' bounds decide there.
            }
        }
        return this;
    }

    void readLine(String line)
    {
        var cells = line.split("\t", -1);
        var ids = NONE;
        if (cells.length > 1 && !cells[1].trim().isEmpty())
        {
            ids = Arrays.stream(cells[1].split(",")).mapToInt(s -> Integer.parseInt(s.trim())).toArray();
        }
        int region = Integer.parseInt(cells[0].trim());
        if (region < 0 || region > 0xFFFF)
        {
            return;
        }
        String zoned = cells.length > 2 ? cells[2].trim() : "";
        if (zoned.length() == ZONES * ZONES && ids.length > 0 && zoned.chars().allMatch(c -> MASKS.indexOf(c) >= 0))
        {
            zones.put(region, zoned);
        }
        else if (!Arrays.equals(owners.get(region), ids))
        {
            // A later table with other owners: its zones are not known.
            zones.remove(region);
        }
        put(region, ids);
    }

    static boolean valid(int floor, int map, int drawn)
    {
        return floor >= 0 && floor < 4 && map >= BaseMap.FULL && map < 1 << 20 && drawn >= 0 && drawn < 4;
    }

    static final String FLOOR_LINE = "F\t";
    static final String TILE_FLOOR_LINE = "T\t";

    /** {@code T <tab> region <tab> x.y.floor=map/floor,...} (x, y within the region); entries out of range are skipped. */
    void readTileFloors(String line)
    {
        readEntries(line, 5, (region, p) -> {
            int x = p[0], y = p[1], floor = p[2], map = p[3], drawn = p[4];
            if (x >= 0 && x < 64 && y >= 0 && y < 64 && valid(floor, map, drawn))
            {
                putTileFloor(((region >> 8) << 6) + x, ((region & 255) << 6) + y, floor, map, drawn);
            }
        });
    }

    /** {@code F <tab> region <tab> zone.floor=map/floor,...}; entries out of range are skipped. */
    void readFloors(String line)
    {
        readEntries(line, 4, (region, p) -> {
            int zone = p[0], floor = p[1], map = p[2], drawn = p[3];
            if (zone >= 0 && zone < ZONES * ZONES && valid(floor, map, drawn))
            {
                putFloor(region, zone, floor, map, drawn);
            }
        });
    }

    /**
     * A {@code T} or {@code F} line's entries: {@code <tab> region <tab> a.b...=c/d,...}, each entry {@code fields}
     * numbers, passed with the region to {@code use}. The whole line is skipped where the region is unreadable or
     * {@code cells} too short; one bad or short entry skips only itself.
     */
    void readEntries(String line, int fields, BiConsumer<Integer, int[]> use)
    {
        var cells = line.split("\t");
        int region = Integer.parseInt(cells[1].trim());
        if (region < 0 || region > 0xFFFF || cells.length < 3)
        {
            return;
        }
        for (String entry : cells[2].split(","))
        {
            var parts = entry.trim().split("[.=/]");
            if (parts.length != fields)
            {
                continue;
            }
            try
            {
                var p = new int[fields];
                for (int i = 0; i < fields; i++)
                {
                    p[i] = Integer.parseInt(parts[i]);
                }
                use.accept(region, p);
            }
            catch (RuntimeException e)
            {
                // That entry only.
            }
        }
    }
}

package com.hdmapreforged;

import com.hdmapreforged.route.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import java.util.regex.*;
import java.util.stream.*;
import lombok.*;

/** Turns requirement columns ({@link Needs}) into readable lines. */
final class Requirements
{
    static final int MAX_ALTERNATIVES = 3;
    static final Pattern SPACES = Pattern.compile("\\s+");
    /** {@link #skillsAndQuests} per requirement: a route request asks for thousands, of a few hundred kinds. */
    static final Map<Needs, List<Line>> CHECKABLE = new ConcurrentHashMap<>();

    @RequiredArgsConstructor
    static final class Line
    {
        final String text;
        final String skill;
        final int level;
        final String quest;
    }

    /** Lines such as {@code "25 Magic"}, {@code "3 × Air rune"} and {@code "Quest: Sea Slug"}. */
    static List<Line> describe(Needs needs, IntFunction<String> itemNames)
    {
        var lines = new ArrayList<Line>();
        for (String skill : needs.skills.split(";"))
        {
            var parts = SPACES.split(skill.trim(), 2);
            if (parts.length == 2 && isNumber(parts[0]))
            {
                String name = parts[1].trim();
                String shown = name.equals("Quest") ? " quest points"
                    : name.contains("+") ? " " + name.replace("+", " and ") + " together" : " " + name;
                lines.add(new Line(parts[0] + shown, name, Integer.parseInt(parts[0]), null));
            }
            else if (!skill.trim().isEmpty())
            {
                lines.add(new Line(skill.trim(), null, 0, null));
            }
        }
        for (String item : items(needs.items, itemNames))
        {
            lines.add(new Line(item, null, 0, null));
        }
        for (String quest : needs.quests.split(";"))
        {
            if (!quest.trim().isEmpty())
            {
                lines.add(new Line("Quest: " + quest.trim(), null, 0, quest.trim()));
            }
        }
        return lines;
    }

    /** The lines {@link Unlocks} can tick off: skill levels and quests. */
    static List<Line> skillsAndQuests(Needs needs)
    {
        var lines = CHECKABLE.get(needs);
        if (lines == null)
        {
            lines = Collections.unmodifiableList(describe(new Needs(needs.skills, "", needs.quests, ""), id -> null));
            if (CHECKABLE.size() < Unlocks.CACHED)
            {
                CHECKABLE.put(needs, lines);
            }
        }
        return lines;
    }

    /** {@code "556=3&&554=1"}: all needed; {@code "1706=1||1708=1"}: alternatives. {@code itemNames} may return null. */
    static List<String> items(String column, IntFunction<String> itemNames)
    {
        // A blank column has no alternatives: no lines.
        var lines = new ArrayList<String>();
        for (String all : ItemSnapshot.ALL.split(column))
        {
            var alternatives = new LinkedHashSet<String>();
            int quantity = 1;
            for (String alternative : ItemSnapshot.ANY.split(all))
            {
                var parts = alternative.trim().split("=");
                if (parts[0].isEmpty())
                {
                    continue;
                }
                if (parts.length > 1)
                {
                    try
                    {
                        quantity = Integer.parseInt(parts[1].trim());
                    }
                    catch (NumberFormatException ignored)
                    {
                    }
                }
                alternatives.add(itemName(parts[0].trim(), itemNames));
            }
            if (alternatives.isEmpty())
            {
                continue;
            }
            var names = new ArrayList<String>(alternatives);
            String text = String.join(" or ", names.subList(0, Math.min(MAX_ALTERNATIVES, names.size())));
            if (names.size() > MAX_ALTERNATIVES)
            {
                text += " or others";
            }
            lines.add(quantity > 1 ? quantity + " × " + text : text);
        }
        return lines;
    }

    static String itemName(String token, IntFunction<String> itemNames)
    {
        String name = isNumber(token) ? itemNames.apply(Integer.parseInt(token)) : null;
        // Charged variants such as "Amulet of glory(4)" collapse into one entry.
        return name == null ? "Item " + token : name.replaceFirst("\\s*\\(\\d+\\)$", "");
    }

    static List<Integer> itemIds(String column)
    {
        return Arrays.stream(column.split("&&|\\|\\|")).map(token -> token.split("=")[0].trim())
            .filter(Requirements::isNumber).map(Integer::parseInt).collect(Collectors.toList());
    }

    static boolean isNumber(String text)
    {
        return !text.isEmpty() && text.length() <= 9 && text.chars().allMatch(Character::isDigit);
    }
}

