    String placeName(WorldPoint point)
    {
        if (screens.length > 0)
        {
            for (var poi : screens[0].view.pois())
            {
                if (poi.location.getPlane() == point.getPlane() && poi.location.distanceTo2D(point) <= 2)
                {
                    return poi.name;
                }
            }
            String place = screens[0].placeName(point);
            if (place != null)
            {
                return "Near " + place;
            }
        }
        return "A spot on the map";
    }

