/**
 * One's own house for routes, kept per account: looked through once per visit (its portals, nexus and such, and its
 * plan), its picture drawn at the surface map's edge, and its panel. Threads as {@link RouteFeature}'s.
 */
@Slf4j
@RequiredArgsConstructor
public final class RouteHouse
{
    final RouteFeature routes;
    final HouseTracker house;

    /**
     * Where a route tile is in the scene: the plan of one's house lies at {@link HousePlan#X}/{@link HousePlan#Y}
     * plus the house's own place, moved to where it is loaded now; null outside the scene, past its edge only as far as
     * an expanded scene loads.
     */
    LocalPoint local(WorldView view, int point)
    {
        int x = Tiles.x(point);
        int y = Tiles.y(point);
        // In an instance copying a place (the Watchtower's top floor): its tiles are the template's, wherever the
        // instance put them in the scene.
        var template = view.isInstance() ? InstanceCopies.template(x, y, Tiles.z(point)) : null;
        if (template != null)
        {
            for (var at : WorldPoint.toLocalInstance(view, new WorldPoint(template[0], template[1], template[2])))
            {
                var local = LocalPoint.fromWorld(view, at);
                if (local != null)
                {
                    return local;
                }
            }
            return null;
        }
        if (contains(x, y))
        {
            return house.own() ? LocalPoint.fromScene(x - HousePlan.X + houseX, y - HousePlan.Y + houseY, view) : null;
        }
        var local = LocalPoint.fromWorld(view, x, y);
        if (local == null)
        {
            // Past the scene's edge, where an expanded scene (the GPU plugins' setting) draws the ground on: the
            // route goes on there too, as far as the game loaded.
            int beyond = routes.expandedTiles();
            int sx = x - view.getBaseX();
            int sy = y - view.getBaseY();
            if (beyond > 0 && sx >= -beyond && sy >= -beyond && sx < view.getSizeX() + beyond
                && sy < view.getSizeY() + beyond)
            {
                local = LocalPoint.fromScene(sx, sy, view);
            }
        }
        return local;
    }

    /**
     * Tiles from the plan to the scene as loaded now. The game centres the scene on where one stood as it loaded (a
     * teleport in, building mode), so the house lies elsewhere in it each time; the plan keeps its south-west room at
     * chunk 2. Client thread writes.
     */
    volatile int houseX;

    volatile int houseY;

    void placeHouse(WorldView view)
    {
        var chunks = view == null ? null : view.getInstanceTemplateChunks();
        int west = 13;
        int south = 13;
        for (var plane : chunks == null ? new int[0][][] : chunks)
        {
            for (int x = 0; x < plane.length; x++)
            {
                for (int y = 0; y < plane[x].length; y++)
                {
                    // A room of the house: copied from the game's house templates.
                    int data = plane[x][y];
                    if (data != -1 && HouseTracker.isTemplate((data >> 14 & 0x3ff) * 8, (data >> 3 & 0x7ff) * 8))
                    {
                        west = min(west, x);
                        south = min(south, y);
                    }
                }
            }
        }
        houseX = west < 13 ? (west - 2) * 8 : 0;
        houseY = south < 13 ? (south - 2) * 8 : 0;
        placed = west < 13;
    }

    /** Whether the house's rooms are placed on the plan: not on the first tick after coming in, as its scene loads. */
    boolean placed;

    /** The player's tile on the plan of their own house once seen; else -1 (the route starts from its ways out). */
    int inHouse()
    {
        Player player = routes.client.getLocalPlayer();
        var local = player == null ? null : player.getLocalLocation();
        var view = routes.client.getTopLevelWorldView();
        var seen = plan;
        int at = seen == null || !house.own() || local == null || view == null ? -1
            : planNode(local, view.getPlane());
        // Just in, one stands where the portal put one (its arrival), but the tile read from the scene on the first
        // ticks is off (the scene still loading): the arrival is the tile until the reading changes (it settles, or
        // one walks).
        boolean settling = seen != null && enteredAt >= 0 && routes.ticks - enteredAt < SETTLE_TICKS;
        if (!settling)
        {
            return at;
        }
        if (firstReading == NONE)
        {
            firstReading = at;
        }
        if (at == firstReading || at < 0)
        {
            return seen.arrival;
        }
        enteredAt = -1;
        return at;
    }

    /** Ticks after coming in during which the arrival is the tile while the scene's reading has not changed. */
    static final int SETTLE_TICKS = 10;
    static final int NONE = Integer.MIN_VALUE;
    /** The tick one came into the house; -1 when not in it. */
    int enteredAt = -1;
    /** The scene's first reading of one's tile since coming in. */
    int firstReading = NONE;

    void entered(int tick)
    {
        enteredAt = tick;
        firstReading = NONE;
    }

    /** A scene tile of one's house on its plan. */
    int planNode(LocalPoint local, int plane)
    {
        return node(local.getSceneX() - houseX, local.getSceneY() - houseY, plane);
    }

    @Subscribe
    public void onGameObjectSpawned(GameObjectSpawned event)
    {
        // Not while a scene loads: the scan sees those, and going into building mode its spaces load before it shows.
        if (house.own() && routes.client.getGameState() == GameState.LOGGED_IN)
        {
            house.seen(name(event.getGameObject().getId()));
        }
    }

    String name(int id)
    {
        var object = routes.client.getObjectDefinition(id);
        if (object != null && object.getImpostorIds() != null)
        {
            object = object.getImpostor();
        }
        return object == null || "null".equals(object.getName()) ? null : object.getName();
    }

    /** The game's list of portal nexus teleports (an enum of structs), and the param naming each. */
    static final int NEXUS_TELEPORTS = 1377;

    static final int NEXUS_NAME = 660;

    static final Pattern STAIRS = Pattern.compile(".*(tair|adder|rapdoor).*");

    /**
     * One's own house, looked through once per visit (its objects spawn while it loads, before a tick finds the player
     * inside): its portals, nexus and such for routes, and its plan, drawn at the surface map's edge. Kept per account.
     */
    void scanHouse()
    {
        var view = routes.client.getTopLevelWorldView();
        Player player = routes.client.getLocalPlayer();
        var me = player == null ? null : player.getLocalLocation();
        if (view == null || me == null)
        {
            house.scanAgain();
            return;
        }
        int dx = houseX;
        int dy = houseY;
        var scene = view.getScene().getTiles();
        var collision = view.getCollisionMaps();
        // Moved to the house's own place (houseX/houseY): the scene is centred on where one stood as it loaded.
        byte[][] placed = new byte[4][SIZE * SIZE];
        var things = new LinkedHashMap<Integer, String>();
        var names = new ArrayList<String>();
        for (int z = 0; z < 4; z++)
        {
            var flags = collision == null || collision[z] == null ? new int[0][] : collision[z].getFlags();
            for (int x = max(0, dx); x < min(SIZE, SIZE + dx); x++)
            {
                for (int y = max(0, dy); y < min(SIZE, SIZE + dy); y++)
                {
                    Tile tile = scene[z][x][y];
                    // No ground (the void round the house) is no floor, though the game sets no flag there.
                    int f = tile == null || tile.getSceneTilePaint() == null && tile.getSceneTileModel() == null
                        || x >= flags.length || y >= flags[x].length ? CollisionDataFlag.BLOCK_MOVEMENT_FULL : flags[x][y];
                    int node = node(x - dx, y - dy, z);
                    placed[z][(x - dx) * SIZE + y - dy] = (byte) (((f & CollisionDataFlag.BLOCK_MOVEMENT_FULL) == 0 ? 1 : 0)
                        | ((f & CollisionDataFlag.BLOCK_MOVEMENT_NORTH) != 0 ? 2 : 0)
                        | ((f & CollisionDataFlag.BLOCK_MOVEMENT_EAST) != 0 ? 4 : 0));
                    var standing = tile == null ? new GameObject[0] : tile.getGameObjects();
                    for (int k = 0; tile != null && k < standing.length + 2; k++)
                    {
                        // A mounted glory hangs on a wall.
                        var object = k < standing.length ? standing[k]
                            : k == standing.length ? tile.getWallObject() : tile.getDecorativeObject();
                        // Once per object, at its south-west tile.
                        Point base = object instanceof GameObject ? ((GameObject) object).getSceneMinLocation() : null;
                        // Its tiles east (32) and north (64) of its first: routes use it from beside any.
                        placed[z][(x - dx) * SIZE + y - dy] |= base == null ? 0 : base.getX() < x && base.getY() == y ? 32
                            : base.getY() < y && base.getX() == x ? 64 : 0;
                        String name = object == null || base != null && (base.getX() != x || base.getY() != y) ? null
                            : name(object.getId());
                        if (name == null)
                        {
                            continue;
                        }
                        String lower = name.toLowerCase(Locale.ROOT);
                        if (lower.endsWith(" space"))
                        {
                            // Building mode's empty spaces (its varbit can come before the normal house loads).
                            house.scanAgain();
                            return;
                        }
                        names.add(name);
                        if (object instanceof WallObject && lower.contains("door"))
                        {
                            door(placed[z], x - dx, y - dy, ((WallObject) object).getOrientationA());
                        }
                        else if (lower.contains("nexus") || name.equals("Portal") || HouseTracker.feature(name) != null
                            || STAIRS.matcher(name).matches())
                        {
                            things.put(node, lower.contains("nexus") ? RouteSource.NEXUS : name);
                        }
                    }
                }
            }
        }
        house.replaceFeatures(Set.of());
        names.forEach(house::seen);
        things.replaceAll((node, name) -> name.equals(RouteSource.NEXUS) ? nexus() : name);
        int arrival = node(me.getSceneX() - dx, me.getSceneY() - dy, view.getPlane());
        var from = new ArrayList<Integer>(List.of(arrival));
        things.forEach((node, name) -> {
            for (int d = 0; STAIRS.matcher(name).matches() && d < 9; d++)
            {
                // From where the player stands; stairs lead to the floors above and below.
                from.add(Tiles.pack(Tiles.x(node) + d / 3 - 1, Tiles.y(node) + d % 3 - 1, Tiles.z(node)));
            }
        });
        keepReachable(placed, from);
        String exit = "Portal";
        for (var thing : things.entrySet())
        {
            for (int d = 1; exit.equals(thing.getValue()) && d <= 3; d++)
            {
                int north = thing.getKey() + d;
                int y = Tiles.y(north) - HousePlan.Y;
                if (y < SIZE && (placed[Tiles.z(north)][(Tiles.x(north) - HousePlan.X) * SIZE + y] & 1) != 0)
                {
                    arrival = north;
                    exit = "";
                }
            }
        }
        // A house may have several superior gardens: a spirit tree in one and a fairy ring in another count as both.
        var gardens = things.values().stream().filter(RouteHouse::garden).map(HouseTracker::feature)
            .collect(Collectors.toSet());
        if (!gardens.isEmpty())
        {
            boolean both = gardens.size() > 1 || gardens.contains(BOTH);
            var kept = new LinkedHashSet<String>(house.features());
            kept.removeIf(Arrays.asList(GARDENS)::contains);
            kept.add(both ? BOTH : gardens.iterator().next());
            house.replaceFeatures(kept);
        }
        var seen = new HousePlan(placed, things, arrival);
        // The game's own minimap of each floor (only floors the house has: each picture is drawn for the whole scene).
        var drawn = new BufferedImage[4];
        for (int z = 0; z < 4; z++)
        {
            var floor = placed[z];
            var minimap = IntStream.range(0, floor.length).anyMatch(i -> (floor[i] & 1) != 0)
                ? routes.client.drawInstanceMap(z) : null;
            drawn[z] = minimap == null ? null : minimap.toBufferedImage();
        }
        keepLook(drawn, placed, dx, dy);
        String text = seen.encode();
        if (text != null)
        {
            routes.configManager.setRSProfileConfiguration(GROUP, PLAN_KEY, text);
        }
        setPlan(seen);
        writeHouse(house.features());
    }

    static boolean garden(String thing)
    {
        String feature = HouseTracker.feature(thing);
        return feature != null && Arrays.asList(GARDENS).contains(feature);
    }

    /** A door counts as open (orientation 1 west, 2 north, 4 east, 8 south): its wall's bit becomes a door's. */
    static void door(byte[] tiles, int x, int y, int orientation)
    {
        int wall = orientation == 2 || orientation == 8 ? 2 : orientation == 1 || orientation == 4 ? 4 : 0;
        int tx = orientation == 1 ? x - 1 : x;
        int ty = orientation == 8 ? y - 1 : y;
        int i = tx * SIZE + ty;
        if (wall != 0 && tx >= 0 && ty >= 0)
        {
            tiles[i] = (byte) (tiles[i] & ~wall | wall * 4);
        }
    }

    /** The varbits of the nexus' 45 slots: runs one after another, each its first and length (list "nexus slots"). */
    static final RouteFiles.Table<int[]> NEXUS_SLOTS = new RouteFiles.Table<>(() -> Pathfinder.list("nexus slots",
        item -> Arrays.copyOf(Pathfinder.ints(item), 2)).stream().flatMapToInt(run -> IntStream.range(run[0],
        run[0] + run[1])).filter(varbit -> varbit >= 0).limit(45).toArray());

    /** "Portal Nexus: Varrock, Falador": its places from the game's varbits (slot, teleport, its name). */
    String nexus()
    {
        var places = new ArrayList<String>();
        var teleports = routes.client.getEnum(NEXUS_TELEPORTS);
        for (int varbit : teleports == null ? new int[0] : NEXUS_SLOTS.get())
        {
            int id = routes.client.getVarbitValue(varbit);
            int struct = id <= 0 ? -1 : teleports.getIntValue(id);
            var teleport = struct < 0 ? null : routes.client.getStructComposition(struct);
            String name = teleport == null ? null : teleport.getStringValue(NEXUS_NAME);
            String place = name == null ? null : Text.removeTags(name);
            if (place != null && !place.isEmpty())
            {
                places.add(place);
                house.seen(RouteSource.NEXUS + ": " + place);
            }
        }
        return RouteSource.NEXUS + (places.isEmpty() ? "" : ": " + String.join(", ", places));
    }

    /** Which house a house portal leads to, as the player chose it there. */
    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        Widget widget = event.getWidget();
        String what = (event.getMenuOption() + " " + Text.removeTags(event.getMenuTarget()) + " " + (widget == null
            || widget.getText() == null ? "" : Text.removeTags(widget.getText()))).toLowerCase(Locale.ROOT);
        // Also a tablet, the spell or a cape into it (not their Outside): at a portal that would look like a friend's.
        if (what.startsWith("home ") || what.startsWith("build mode ") || what.contains("your house")
            || what.startsWith("tele to poh") || what.matches("(break|inside|cast) teleport to house.*"))
        {
            house.chose(true);
        }
        else if (what.contains("friend's house"))
        {
            house.chose(false);
        }
    }

    /**
     * The house per floor as the game's minimap draws it, 4 pixels a tile over the scene's 104, north up; null where
     * not seen. Kept per account as one picture in the plugin's folder, the floors one under another.
     */
    final AtomicReference<BufferedImage[]> houseLook = new AtomicReference<>(new BufferedImage[4]);

    static final int LOOK = SIZE * 4;

    /** Set by the plugin when it starts. */
    volatile Filepath houseFolder;

    volatile Executor houseIo;

    Filepath lookFile(long account)
    {
        var folder = houseFolder;
        return folder == null || houseIo == null ? null : folder.joinSegment(Long.toHexString(account) + ".png");
    }

    /**
     * The house in a minimap picture that may cover an expanded scene, moved as the plan is ({@code dx}, {@code dy}
     * tiles from the plan to the scene): of the margins a chunk apart, the one where the plan's walls are the
     * picture's white lines (else its floor is painted); null when none fits. Black (no ground) becomes clear.
     */
    static BufferedImage sceneOf(BufferedImage all, byte[] floor, int dx, int dy)
    {
        BufferedImage best = null;
        int most = 0;
        for (int margin = 0; margin + LOOK <= min(all.getWidth(), all.getHeight()); margin += 32)
        {
            int painted = 0;
            for (int i = 0; i < floor.length; i++)
            {
                int x = (i / SIZE + dx) * 4;
                int y = (SIZE - 1 - i % SIZE - dy) * 4;
                boolean in = x >= 0 && y >= 0 && x + 4 <= LOOK && y + 4 <= LOOK;
                int rgb = in ? all.getRGB(margin + x + 2, margin + y + 2) : 0;
                painted += (floor[i] & 1) != 0 && rgb >>> 24 != 0 && (rgb & 0xffffff) != 0 ? 1 : 0;
                // A wall on the tile's north or east edge: white there.
                painted += in && (floor[i] & 2) != 0 && white(all.getRGB(margin + x + 1, margin + y)) ? 16 : 0;
                painted += in && (floor[i] & 4) != 0 && white(all.getRGB(margin + x + 3, margin + y + 1)) ? 16 : 0;
            }
            if (painted > most)
            {
                // A copy: the rest of the picture (four times its size) is not kept with it.
                most = painted;
                int[] pixels = new int[LOOK * LOOK];
                for (int i = 0; i < pixels.length; i++)
                {
                    int x = i % LOOK + dx * 4;
                    int y = i / LOOK - dy * 4;
                    int rgb = x < 0 || y < 0 || x >= LOOK || y >= LOOK ? 0 : all.getRGB(margin + x, margin + y);
                    pixels[i] = (rgb & 0xffffff) == 0 ? 0 : rgb;
                }
                best = new BufferedImage(LOOK, LOOK, BufferedImage.TYPE_INT_ARGB);
                best.setRGB(0, 0, LOOK, LOOK, pixels, 0, LOOK);
            }
        }
        return best;
    }

    static boolean white(int rgb)
    {
        return (rgb >> 16 & 255) > 180 && (rgb >> 8 & 255) > 180 && (rgb & 255) > 180;
    }

    /**
     * Fitted to the plan ({@link #sceneOf}: up to 7 ms a floor, 200 ms the first time), shown and written on the file
     * thread: not on the client thread.
     */
    void keepLook(BufferedImage[] drawn, byte[][] floors, int dx, int dy)
    {
        // A look read from the file meanwhile does not replace this one.
        var pending = new BufferedImage[4];
        houseLook.set(pending);
        var file = lookFile(houseOf);
        Executor io = houseIo;
        Runnable fit = () -> {
            var look = new BufferedImage[4];
            for (int z = 0; z < 4; z++)
            {
                look[z] = drawn[z] == null ? null : sceneOf(drawn[z], floors[z], dx, dy);
            }
            // Not over a newer scan, nor for another account.
            if (houseLook.compareAndSet(pending, look))
            {
                SwingUtilities.invokeLater(routes::repaint);
                write(look, file);
            }
        };
        if (io == null)
        {
            fit.run();
        }
        else
        {
            later(io, fit);
        }
    }

    /** The plugin's io threads stop with it: work handed over after that is dropped. */
    static void later(Executor io, Runnable work)
    {
        if (!TileCache.execute(io, work))
        {
            log.debug("Plugin stopped; house file work dropped");
        }
    }

    static void write(BufferedImage[] look, Filepath file)
    {
        if (file != null)
        {
            BufferedImage all = new BufferedImage(LOOK, LOOK * 4, BufferedImage.TYPE_INT_ARGB);
            var g = all.createGraphics();
            for (int z = 0; z < 4; z++)
            {
                g.drawImage(look[z], 0, z * LOOK, null);
            }
            g.dispose();
            // In memory: ImageIO would cache through a temporary file of its own.
            ByteArrayOutputStream bytes = new ByteArrayOutputStream();
            try
            {
                try (ImageOutputStream out = new MemoryCacheImageOutputStream(bytes))
                {
                    ImageIO.write(all, "png", out);
                }
                TileCache.writeAtomically(file, bytes.toByteArray());
            }
            catch (IOException | RuntimeException e)
            {
                log.debug("Could not keep the house's look", e);
            }
        }
    }

    /** The account's kept look, read on the file thread; our own drawing of the plan until then. */
    void readLook(long account)
    {
        var none = new BufferedImage[4];
        houseLook.set(none);
        var file = lookFile(account);
        if (file == null)
        {
            return;
        }
        later(houseIo, () -> {
            var look = new BufferedImage[4];
            try (ImageInputStream in = file.isFile() ? new MemoryCacheImageInputStream(new ByteArrayInputStream(
                TileCache.read(file))) : null)
            {
                BufferedImage all = in == null ? null : ImageIO.read(in);
                for (int z = 0; all != null && all.getWidth() == LOOK && all.getHeight() == LOOK * 4 && z < 4; z++)
                {
                    look[z] = all.getSubimage(0, z * LOOK, LOOK, LOOK);
                }
            }
            catch (IOException | RuntimeException e)
            {
                log.debug("Could not read the house's look", e);
            }
            // Not over a scan made meanwhile, nor for another account.
            if (houseOf == account && houseLook.compareAndSet(none, look))
            {
                SwingUtilities.invokeLater(routes::repaint);
            }
        });
    }

    /** The account whose house is loaded (client thread); none after a log out. */
    volatile long houseOf = Long.MIN_VALUE;

    /** For Swing: the features as last written. */
    volatile Set<String> houseFeatures = Set.of();

    volatile HousePlan plan;

    volatile CollisionMap collision;

    /** The plan and the route data (loaded meanwhile) are joined under this lock. */
    synchronized void setPlan(HousePlan seen)
    {
        plan = seen;
        if (collision != null)
        {
            collision.setHouse(seen);
        }
        houseChanged();
    }

    /** This account's house; not before RuneLite knows the account's profile: that may come just after the login. */
    void loadHouse()
    {
        if (routes.configManager.getRSProfileKey() == null)
        {
            return;
        }
        houseOf = routes.client.getAccountHash();
        routes.loadBank();
        routes.planted.load(routes.configManager.getRSProfileConfiguration(GROUP,
            PlantedSpiritTrees.KEY));
        String saved = routes.configManager.getRSProfileConfiguration(GROUP, HOUSE_KEY);
        var features = new LinkedHashSet<String>(Arrays.asList(saved == null ? new String[0] : saved.split(",")));
        features.remove("");
        house.reset();
        house.restore(features);
        readLook(houseOf);
        writeHouse(house.features());
        String text = routes.configManager.getRSProfileConfiguration(GROUP, PLAN_KEY);
        setPlan(text == null ? null : decode(text));
    }

    void writeHouse(Set<String> features)
    {
        houseFeatures = Set.copyOf(features);
        routes.configManager.setRSProfileConfiguration(GROUP, HOUSE_KEY, String.join(",", features));
        houseChanged();
    }

    @Subscribe
    public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
    {
        routes.clientThread.invokeLater(() -> {
            if (routes.client.getGameState() == GameState.LOGGED_IN)
            {
                loadHouse();
            }
        });
    }

    /** One's house at the surface map's edge: its picture per floor, and what stands where. */
    void paintHouse(Graphics2D g, Projection p)
    {
        var seen = plan;
        g.setFont(FontManager.getRunescapeSmallFont());
        if (seen == null)
        {
            return;
        }
        // One picture a floor, the game's minimap of it: not thousands of shapes a frame.
        BufferedImage look = houseLook.get()[max(0, min(3, p.plane()))];
        // At the surface map's edge, where the map draws the house.
        int left = (int) round(p.screenX(DRAWN_X));
        int top = (int) round(p.screenY(DRAWN_Y + SIZE));
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
        g.drawImage(look, left, top, (int) round(p.screenX(DRAWN_X
            + SIZE)) - left, (int) round(p.screenY(DRAWN_Y)) - top, null);
        seen.things.forEach((node, name) -> {
            String label = name.split(":")[0];
            float x = (float) RouteText.x(p, node) - g.getFontMetrics().stringWidth(label) / 2f;
            float y = (float) RouteText.y(p, node);
            if (Tiles.z(node) == p.plane())
            {
                g.setColor(Color.BLACK);
                g.drawString(label, x + 1, y + 1);
                g.setColor(Color.WHITE);
                g.drawString(label, x, y);
            }
        });
    }

    /** "Your house" for this account: what it has for routes, set here, and its plan. Swing thread. */
    JComponent housePanel(int width)
    {
        JPanel panel = column();
        panel.setBorder(BorderFactory.createEmptyBorder(4, 0, 4, 0));
        panel.add(label("Your house", width, Font.BOLD, Color.WHITE));
        var seen = plan;
        var now = houseFeatures;
        if (collision == null || houseOf == Long.MIN_VALUE)
        {
            panel.add(label("Log in to see and set this account's house.", width, NOTE));
            return panel;
        }
        Color gray = ColorScheme.LIGHT_GRAY_COLOR;
        panel.add(label(seen == null ? "Teleport into it once: its rooms, portals, nexus and jewellery box are read "
            + "then. Or set them here." : "As seen last time you were in it, for this account. Routes walk through it; "
            + "right-click in it for a route there.", width, gray));
        var box = new JComboBox<String>(new String[]{"No jewellery box", "Basic jewellery box",
            "Fancy jewellery box", "Ornate jewellery box"});
        box.setSelectedIndex(Arrays.asList(BOXES).indexOf(HouseSettings.box(now)));
        String[] amulets = {"Mounted amulet of glory", "Mounted Xeric's talisman", "Mounted digsite pendant"};
        var mounted = IntStream.range(0, amulets.length).mapToObj(i -> new JCheckBox(amulets[i],
            now.contains(MOUNTED[i]))).toArray(JCheckBox[]::new);
        // A superior garden has one of these.
        var garden = new JComboBox<String>(new String[]{"No fairy ring or spirit tree", "Fairy ring",
            "Spirit tree", "Both (a spiritual fairy tree, or two gardens)"});
        garden.setSelectedIndex(HouseSettings.garden(now));
        var obelisk = new JCheckBox("Obelisk to the Wilderness", now.contains("obelisk"));
        obelisk.setToolTipText("Routes use it with the Hard Wilderness Diary, which lets you choose the obelisk it "
            + "leads to");
        JTextField portals = new JTextField(HouseSettings.places(now, PORTAL));
        JTextField nexus = new JTextField(HouseSettings.places(now, NEXUS));
        long account = houseOf;
        ActionListener save = e ->
        {
            var amulet = IntStream.range(0, amulets.length).filter(i -> mounted[i].isSelected())
                .mapToObj(i -> MOUNTED[i]).collect(Collectors.toSet());
            editHouse(account, HouseSettings.features(BOXES[box.getSelectedIndex()], amulet,
                garden.getSelectedIndex(), obelisk.isSelected(), portals.getText(), nexus.getText()));
        };
        box.addActionListener(save);
        for (var amulet : mounted)
        {
            amulet.addActionListener(save);
        }
        garden.addActionListener(save);
        obelisk.addActionListener(save);
        for (JTextField places : new JTextField[]{portals, nexus})
        {
            places.setToolTipText("Where they lead, as the spellbooks name them, with commas; Enter saves");
            FullMapWindow.typable(places);
            places.addActionListener(save);
        }
        var parts = new ArrayList<JComponent>(List.of(box));
        parts.addAll(List.of(mounted));
        parts.addAll(List.of(garden, obelisk, label("Portals:", width, gray), portals,
            label("Portal nexus:", width, gray), nexus));
        for (var part : parts)
        {
            part.setAlignmentX(Component.LEFT_ALIGNMENT);
            part.setOpaque(part instanceof JTextField);
            part.setMaximumSize(new Dimension(width, part.getPreferredSize().height));
            panel.add(part);
        }
        if (seen != null)
        {
            add(panel, 6, button("Show its plan",
                () -> routes.forScreens(screen -> screen.view.focus(worldPoint(seen.arrival)))));
        }
        return panel;
    }

    /** Dropped when another account (or none) is logged in than the panel was made for. */
    void editHouse(long account, Set<String> features)
    {
        routes.clientThread.invokeLater(() -> {
            if (houseOf != account)
            {
                return;
            }
            house.replaceFeatures(features);
            writeHouse(features);
            routes.state = routes.capture();
            SwingUtilities.invokeLater(routes::settingsChanged);
        });
    }

    final IntFunction<JComponent> houseSection = this::housePanel;

    void openHouse()
    {
        routes.forScreens(screen -> screen.showHouse(houseSection));
    }

    /** The maps painted again, and an open house panel built again with what is known now (a scan, the other map). */
    void houseChanged()
    {
        SwingUtilities.invokeLater(() -> {
            routes.repaint();
            routes.forScreens(screen -> screen.updateHouse(houseSection));
        });
    }

    /** The route data, loaded meanwhile, joined with the plan under the plan's lock; null when stopped. */
    synchronized void setCollision(CollisionMap map)
    {
        collision = map;
        if (map != null)
        {
            map.setHouse(plan);
        }
    }

    /** No account's house (logged out, or stopped). Client thread. */
    void forget()
    {
        house.reset();
        houseOf = Long.MIN_VALUE;
        houseLook.set(new BufferedImage[4]);
        setPlan(null);
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN && routes.client.getAccountHash() != houseOf)
        {
            loadHouse();
        }
        else if (event.getGameState() == GameState.LOADING)
        {
            house.reloaded();
        }
        else if (event.getGameState() == GameState.LOGIN_SCREEN)
        {
            forget();
        }
    }
}

package com.hdmapreforged;

import static com.hdmapreforged.RouteFeature.*;
import static com.hdmapreforged.RouteFeature.RouteText.*;
import static com.hdmapreforged.SearchResults.*;
import static net.runelite.client.ui.ColorScheme.*;

import com.hdmapreforged.route.*;
import com.hdmapreforged.route.Route.*;
import com.hdmapreforged.route.Route.Step.*;
import java.awt.*;
import java.util.List;
import java.util.function.*;
import javax.swing.*;
import net.runelite.api.coords.*;

/** The route's panels for the sidebar and the map's card: the step list, the "Now" box, and the pieces they are made of. */
final class RoutePanels
{

    static final Color SEA = new Color(64, 200, 255);
    static final Color NOTE = new Color(255, 190, 120);

    static JComponent nowBox(Route left, int width, Color walk, Color jump)
    {
        JPanel box = edgeBox(walk);
        // The text's width inside the border, with room to spare as label leaves it.
        int inner = Math.max(80, width - 47);
        box.add(text("Now", LIGHT_GRAY_COLOR, Font.PLAIN, 0, inner));
        Step now = left.steps.get(0);
        JLabel doing = text(saying(left, now, false), color(now, walk, jump), Font.BOLD, 3, inner);
        box.add(doing);
        if (now.detail != null && !unsure(now.detail))
        {
            box.add(text(now.detail, LIGHT_GRAY_COLOR, Font.PLAIN, 0, inner));
        }
        for (int i = 1; i < Math.min(3, left.steps.size()); i++)
        {
            Step then = left.steps.get(i);
            add(box, 4, text((i == 1 ? "Then: " : "After that: ") + saying(left, then, false), color(then, walk, jump),
                Font.PLAIN, 0, inner));
        }
        JLabel remaining = text(duration(left) + " left", LIGHT_GRAY_COLOR, Font.PLAIN, 0, inner);
        add(box, 4, remaining);
        var wrapped = wrapped(box, 8);
        // What changes as the player walks (updateNow).
        wrapped.putClientProperty("doing", doing);
        wrapped.putClientProperty("left", remaining);
        wrapped.putClientProperty("width", inner);
        return wrapped;
    }

    /**
     * What to bring for a quicker way, as a box like {@link #nowBox} with an orange edge: each thing in bold with what it
     * is for under it, then how much sooner.
     */
    static JComponent tipBox(List<String[]> bring, String sooner, int width)
    {
        JPanel box = edgeBox(NOTE);
        int inner = Math.max(80, width - 47);
        box.add(text("Quicker if you bring", NOTE, Font.PLAIN, 0, inner));
        for (var thing : bring)
        {
            add(box, 4, text(thing[0], Color.WHITE, Font.BOLD, 0, inner));
            box.add(text("for " + thing[1], LIGHT_GRAY_COLOR, Font.PLAIN, 0, inner));
        }
        add(box, 4, text(sooner, NOTE, Font.PLAIN, 0, inner));
        return wrapped(box, 8);
    }

    /** A box like {@link #nowBox}/{@link #tipBox}: dark background, a coloured left edge. */
    static JPanel edgeBox(Color edge)
    {
        JPanel box = column();
        box.setOpaque(true);
        box.setBackground(DARK_GRAY_COLOR);
        box.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createMatteBorder(0, 3, 0, 0, edge),
            BorderFactory.createEmptyBorder(6, 8, 6, 6)));
        return box;
    }

    /** {@code box} sized to its content, with the gap the route panels put after a box like this. */
    static JComponent wrapped(JComponent box, int gap)
    {
        JPanel spaced = column();
        spaced.add(capped(box));
        spaced.add(Box.createVerticalStrut(gap));
        return spaced;
    }

    /** A tick of walking: only the two texts of {@link #nowBox} that change are set again. */
    static void updateNow(JComponent box, Route left)
    {
        int inner = (Integer) box.getClientProperty("width");
        setText((JLabel) box.getClientProperty("doing"), saying(left, left.steps.get(0), false), inner);
        setText((JLabel) box.getClientProperty("left"), duration(left) + " left", inner);
    }

    /** The step list: title, notes, steps (click to see on the map) and "Clear path". */
    static JComponent panel(Route route, int target, String status, int width, Consumer<WorldPoint> focus,
        Runnable clear, RouteFeature actions, Color walk, Color jump, int done)
    {
        JPanel panel = column();
        panel.setBorder(BorderFactory.createEmptyBorder(4, 0, 4, 0));
        panel.add(label("Route" + (Tiles.z(target) > 0 ? " (floor " + Tiles.z(target) + ")" : ""), width,
            Font.BOLD, Color.WHITE));
        if (route == null)
        {
            panel.add(label(status != null ? status : "Searching…", width, LIGHT_GRAY_COLOR));
        }
        else
        {
            for (String note : notes(route))
            {
                panel.add(label(note, width, NOTE));
            }
            boolean unreachable = actions != null && actions.unreachable();
            int blocked = unreachable ? blockedFrom(route) : -1;
            if (unreachable)
            {
                panel.add(label(cannotYet(route), width, Font.BOLD, CANNOT));
            }
            var blockers = actions == null || route.outcome != Outcome.NEAREST ? null
                : actions.blockers();
            if (blockers != null)
            {
                panel.add(label(blockers.isEmpty() ? "Needs something the map can't name (a quest step, a key)."
                    : blockers.contains(NO_WAY) ? NO_WAY : "Needs: " + String.join(", ", blockers), width, NOTE));
            }
            if (!route.steps.isEmpty())
            {
                panel.add(label(duration(route) + (route.outcome == Outcome.NEAREST
                    ? " to where the route ends" : ""), width, LIGHT_GRAY_COLOR));
            }
            String bring = RouteText.bring(route);
            if (bring != null)
            {
                // Vines, jungle and webs do not stop the route: what to take along.
                panel.add(label("Bring: " + bring, width, new Color(150, 220, 150)));
            }
            int number = 1;
            boolean unsure = false;
            for (Step step : route.steps)
            {
                boolean lacking = unreachable && lacks(step);
                boolean cannot = blocked >= 0 && number - 1 >= blocked;
                String detail = lacking ? "Needs " + lack(step) : step.detail;
                if (!lacking && unsure(detail))
                {
                    unsure = true; // said once under the steps
                    detail = null;
                }
                // A passage, stairs or transport shows where it leads (the other map).
                boolean leads = step.isJump() && !Tiles.isSea(step.last()) && step.first() != step.last();
                int point = leads ? step.last() : step.first();
                JButton row = flat("<html><body style='width:" + Math.max(80, width - 40) + "px'>" + number++ + ". "
                    + escape(saying(route, step, false))
                    + (detail != null ? "<br><span style='color:" + (cannot ? "#ff7070" : "#a0a0a0") + "'>"
                        + escape(detail) + "</span>" : "")
                    + "</body></html>", leads ? "Show where this leads on the map" : "Show on the map",
                    () -> focus.accept(worldPoint(point)));
                row.setForeground(number - 2 < done ? MEDIUM_GRAY_COLOR : cannot ? CANNOT
                    : color(step, walk, jump));
                row.setMargin(new Insets(1, 0, 1, 0));
                boolean choice = step.name != null && (step.kind == Kind.TELEPORT
                    || step.kind == Kind.TRANSPORT || step.kind == Kind.SHIP
                    || (step.kind == Kind.ENTRANCE || step.kind == Kind.HOUSE) && step.category != null);
                if (actions == null || !choice)
                {
                    panel.add(row);
                    continue;
                }
                JPanel line = SearchResults.panel(new BorderLayout());
                line.add(row, BorderLayout.CENTER);
                JButton more = new JButton("⋯");
                more.setFocusable(false);
                more.setMargin(new Insets(0, 4, 0, 4));
                more.setToolTipText("Leave this out of the route");
                String name = BankDetour.plain(step.name);
                String category = step.category;
                more.addActionListener(a -> {
                    var menu = new JPopupMenu();
                    String running = actions.runningTour();
                    // With a custom route running: saved with it, left out whenever it runs.
                    Consumer<String> leave = running != null ? actions::avoidInRoute : actions::avoid;
                    String verb = running != null ? "Leave" : "Avoid";
                    String scope = running != null ? " out of \"" + running + "\"" : " for this route";
                    item(menu, verb + scope, () -> leave.accept(name));
                    if (category != null)
                    {
                        item(menu, verb + " every " + category + scope, () -> leave.accept(RouteSource.TYPE + category));
                    }
                    menu.addSeparator();
                    item(menu, "Never use \"" + name + "\"", () -> actions.never(name));
                    if (category != null)
                    {
                        item(menu, "Never use any " + category, () -> actions.never(RouteSource.TYPE + category));
                    }
                    menu.show(more, 0, more.getHeight());
                });
                line.add(more, BorderLayout.EAST);
                panel.add(capped(line));
            }
            if (unsure)
            {
                add(panel, 4, label("Some steps may need a quest, level or item the map does not know about.", width,
                    MEDIUM_GRAY_COLOR));
            }
        }
        if (actions != null && !actions.neverUsed().isEmpty())
        {
            add(panel, 6, label("Never used:", width, Font.BOLD, LIGHT_GRAY_COLOR));
            for (String never : actions.neverUsed())
            {
                JButton allow = flat("✕  " + Tour.describe(never), "Use it again", () -> actions.allow(never));
                allow.setForeground(LIGHT_GRAY_COLOR);
                panel.add(allow);
            }
        }
        JButton clearButton = button("Clear path", clear);
        clearButton.setAlignmentX(0);
        clearButton.setToolTipText("Remove the route from the map");
        add(panel, 4, clearButton);
        return panel;
    }

    /** The route panels' text: bold at the usual size, wrapped with room to spare (HTML comes out wider than asked). */
    static JLabel label(String text, int width, int style, Color color)
    {
        return text(text, color, style, 0, Math.max(80, width - 30));
    }

    /** {@link #label(String, int, int, Color)} in plain type. */
    static JLabel label(String text, int width, Color color)
    {
        return label(text, width, Font.PLAIN, color);
    }

    static Color color(Step step, Color walk, Color jump)
    {
        switch (step.kind)
        {
            case WALK:
                return walk;
            case SAIL:
            case BOARD:
            case DISEMBARK:
                return SEA;
            default:
                return jump;
        }
    }
}

package com.hdmapreforged;

import static com.hdmapreforged.route.Tiles.*;
import static java.util.Locale.ROOT;
import static com.hdmapreforged.PoiType.*;
import static com.hdmapreforged.RouteFeature.pack;

import com.hdmapreforged.route.*;
import com.hdmapreforged.route.Edge.Kind;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import java.util.regex.*;
import java.util.stream.*;
import lombok.*;
import net.runelite.api.coords.*;

/** The jumps a route may take for this player. Thread-safe: requests come from Swing and the extras thread. */
@RequiredArgsConstructor
final class RouteSource
{
    static final int SNAP = 5;
    static final int DOCK_REACH = 18;
    static final int PORT_RADIUS = 24;
    /** How far from its dock a port's boat lies, at most (Port Piscarilius: 34 tiles). */
    static final int BOAT_REACH = 40;
    static final Pattern SAILING = Pattern.compile("(\\d+)\\s+Sailing", Pattern.CASE_INSENSITIVE);

    @RequiredArgsConstructor
    static final class Options
    {
        final boolean teleports;
        @With
        final boolean sailing;
        /** Where shipwrights stand (not changed once given). */
        final int[] shipwrights;
        final boolean ignoreLevels;
        final boolean ignoreItems;
        final Set<String> avoid;
        final Saving saving;
        /** The way anyone could go, shown when the player's way does not arrive (not the "ignore" settings). */
        final boolean fallback;
        /** Stay out of the Wilderness unless the route starts or ends there. */
        final boolean avoidWilderness;
        /** Sail also to places on land that can be walked to; else only from or to the sea, or where walking does not get. */
        @With
        final boolean sailToLand;
    }

    /** Tiles a kind of trip must save to be taken (a teleport for a few tiles wastes runes); search weight only. */
    @RequiredArgsConstructor
    static final class Saving
    {
        static final Saving NONE = new Saving(0, 0, 0, 0, 0, 0);

        final int teleport;
        final int shortcut;
        final int transport;
        final int canoe;
        final int carpet;
        final int ship;

        int tiles(PoiType type)
        {
            switch (type)
            {
                case AGILITY_SHORTCUT:
                    return shortcut;
                case CANOE:
                    return canoe;
                case CARPET:
                    return carpet;
                case BOAT:
                case CHARTER:
                    return ship;
                case PORTAL:
                case LEVER:
                    return 0;
                default:
                    return transport;
            }
        }
    }

    /** How near a dock a shipwright, or a port where one's boat may lie, must be to count as there. */
    static final int SHIPWRIGHT_REACH = 40;

    final CollisionMap map;
    final SeaMap sea;
    /** The planner's passages that are Agility shortcuts ({@link Pathfinder#shortcutPassages()}). */
    final List<ShortcutPassage> shortcuts;
    /**
     * {@link Pathfinder#pocket}: a jump's end snaps to open ground, not a shut-in tile beside it, from which no route goes
     * on (Tal Teklan's quetzal, several fairy rings).
     */
    final IntPredicate pocket;
    /** The game's item names, for what a step lacks ("3200 × Coins"); null: "items you do not have". */
    volatile IntFunction<String> itemNames;

    /** Snapped ends by spot (and the spot to keep away from): the map does not change, and requests snap thousands. */
    final Map<Long, Integer> snaps = new ConcurrentHashMap<>();

    RouteRequest request(int start, int target, List<Poi> pois, Unlocks unlocks, PlayerState state, Options options,
        int nodeLimit)
    {
        if (options.sailing && !options.sailToLand && !isSea(target) && !(start >= 0 && isSea(start)))
        {
            // A place on land: walk; the boat only when walking does not get there.
            var walking = request(start, target, pois, unlocks, state, options.withSailing(false), nodeLimit);
            var sailing = request(start, target, pois, unlocks, state, options.withSailToLand(true), nodeLimit);
            return walking == null || sailing == null ? sailing : walking.withBoat(sailing);
        }
        if (start >= 0 && HousePlan.contains(start))
        {
            // On the plan of one's house: in it, also before the player's state (read every few ticks) says so.
            state = state.inOwnHouse(true);
        }
        return new Call(options, unlocks, state).request(start, target, pois, nodeLimit);
    }

    /** Half ticks (tiles run) a spell or item in the house must be quicker than its own ways. */
    static final int HOUSE_FIRST = 10;

    final class Call
    {
        final Set<String> avoiding;
        final Saving saving;
        final Unlocks realUnlocks;
        final Unlocks missingLevels;
        final ItemSnapshot missingItems;
        /** With the bank's items too: what is carried without them (to say what to take out); else null. */
        final ItemSnapshot carried;
        /** What may be used: carried, and with the bank's items too. */
        final ItemSnapshot items;
        final int realSailing;
        final boolean fallback;
        final long minute = System.currentTimeMillis() / 60_000;

        final IntFunction<String> itemNames;
        /** The stops of planted spirit trees not grown for this player: not travelled to. */
        Set<WorldPoint> notGrown = Collections.emptySet();

        final Options options;
        /** As the options make them: no unlocks when levels are ignored, every item when items are. */
        final Unlocks unlocks;
        final PlayerState state;

        Call(Options options, Unlocks unlocks, PlayerState state)
        {
            this.options = options;
            itemNames = RouteSource.this.itemNames;
            avoiding = options.avoid;
            saving = options.saving;
            realUnlocks = unlocks;
            missingLevels = options.ignoreLevels ? unlocks : null;
            missingItems = options.ignoreItems ? state.items : null;
            carried = state.carried;
            items = state.items;
            realSailing = !options.ignoreLevels ? 99 : state.sailing ? state.sailingLevel : 0;
            fallback = options.fallback;
            this.unlocks = options.ignoreLevels ? null : unlocks;
            state = options.ignoreLevels ? state.with(state.items, 99, true) : state;
            this.state = options.ignoreItems ? state.with(ItemSnapshot.EVERYTHING, state.sailingLevel, state.sailing) : state;
        }

        /** Whether the route leaves out a way by its name or by its kind; either may be null. */
        boolean avoids(String name, String category)
        {
            return name != null && avoiding.contains(name.toLowerCase(ROOT))
                || category != null && avoiding.contains(typeKey(category));
        }

        RouteRequest request(int start, int target, List<Poi> pois, int nodeLimit)
        {
            var startEdges = new ArrayList<Edge>();
            var edges = new ArrayList<Edge>();
            var teleportsByName = new HashMap<String, Poi>();
            var all = Poi.flatten(pois);
            notGrown = all.stream().filter(RouteSource.this::notPlanted).map(poi -> poi.location).collect(Collectors.toSet());
            for (var poi : all)
            {
                if (poi.type == TELEPORT)
                {
                    for (var member : poi.members())
                    {
                        teleportsByName.putIfAbsent(member.name.toLowerCase(ROOT), member);
                        if (options.teleports)
                        {
                            teleport(member, startEdges, edges);
                        }
                    }
                }
                else if (poi.type == MOORING)
                {
                    if (options.sailing)
                    {
                        mooring(poi, start >= 0 && isSea(start), edges);
                    }
                }
                else if (isTransport(poi.type))
                {
                    transport(poi, edges);
                }
            }
            gates(edges);
            shortcuts(edges);
            if (options.sailing && state.sailing)
            {
                seaPassages(edges);
            }
            // In an area whose way out leads back to where one came from (the Rune essence mine, the Shipyard): its exits,
            // there, when the player was seen coming in.
            var back = start >= 0 ? ReturnAreas.at(start) : null;
            if (back != null && state.returnExit >= 0)
            {
                for (int exit : back.exits)
                {
                    int from = snap(RouteFeature.worldPoint(exit));
                    if (from >= 0)
                    {
                        edges.add(new Edge(from, state.returnExit, Kind.ENTRANCE, back.exitName, null, 6));
                    }
                }
            }
            if (options.sailing && options.teleports)
            {
                teleportToBoat(startEdges);
            }
            if (state.inHouse || options.teleports)
            {
                house(pois, teleportsByName, startEdges, edges);
            }
            if (!avoiding.isEmpty())
            {
                // Also the house's ways (its jewellery box, portals), by name or kind as the route's steps show them.
                Predicate<Edge> avoided = e -> avoids(e.name, e.category);
                startEdges.removeIf(avoided);
                edges.removeIf(avoided);
            }
            if (state.inHouse)
            {
                // In the house its own portal, box or amulet goes before a spell or item, unless that is over 10 tiles quicker.
                startEdges.replaceAll(e -> e.kind == Kind.TELEPORT ? e.weighed(HOUSE_FIRST) : e);
            }
            if (start < 0 && startEdges.isEmpty())
            {
                return null;
            }
            int level = options.sailing && state.sailing ? state.sailingLevel : -1;
            if (start >= 0 && isSea(start) && level < 0)
            {
                // On a boat without the Sailing data: still let the route sail home.
                level = Math.max(1, state.sailingLevel);
            }
            return new RouteRequest(start, target, startEdges, edges, level, state.running, nodeLimit, options.avoidWilderness);
        }

        void gates(List<Edge> into)
        {
            for (Gate gate : GATES.get())
            {
                // Its quests and levels, and the items it takes (a key, a skavid map and a light) carried or worn.
                if (!usable(gate.needs) || !state.items.has(gate.needs.items))
                {
                    continue;
                }
                int a = snap(gate.from, gate.to);
                int b = snap(gate.to, gate.from);
                if (a >= 0 && b >= 0 && a != b)
                {
                    // A row named by its action ("Climb-down Ladder (Mining Guild)") as it is; a door or gate opened.
                    String name = ACTION.get().matcher(gate.name).lookingAt() ? gate.name : "Open " + gate.name;
                    into.add(new Edge(a, b, Kind.ENTRANCE, name, detail(null, gate.needs), 4));
                }
            }
        }

        /** The sea caves and the like (sea_passages.tsv) between blocks of sea the player's boat can sail. */
        void seaPassages(List<Edge> into)
        {
            for (var passage : SEA_PASSAGES.get())
            {
                int from = seaAt(passage.fromX, passage.fromY);
                int to = seaAt(passage.toX, passage.toY);
                if (usable(passage.needs) && sea.sailable(cellX(from), cellY(from), state.sailingLevel)
                    && sea.sailable(cellX(to), cellY(to), state.sailingLevel))
                {
                    // What it needs, and what the step should say besides (the boat's kind).
                    String needs = detail(null, passage.needs);
                    String detail = needs == null ? passage.note : passage.note.isEmpty() ? needs : needs + ". " + passage.note;
                    into.add(new Edge(from, to, Kind.ENTRANCE, passage.name, detail.isEmpty() ? null : detail, 10));
                }
            }
        }

        void shortcuts(List<Edge> into)
        {
            for (var passage : shortcuts)
            {
                // Any of its ways the player meets: with a grapple, or bare-handed at a higher level.
                for (var way : passage.ways)
                {
                    Needs needs = new Needs(way[0], way[1], way[2], way[3]);
                    if (usable(needs) && state.items.has(needs.items))
                    {
                        Edge e = passage.edge;
                        into.add(new Edge(e.from, e.to, e.kind, e.name, detail(null, needs), e.cost));
                        break;
                    }
                }
            }
        }

        boolean usable(Needs needs)
        {
            return unlocks == null || unlocks.usable(needs);
        }

        /**
         * A teleport from anywhere ({@code into}); in a house a minigame teleport only from outside its portal
         * ({@code edges}): the game does not let one cast it in a player-owned house.
         */
        void teleport(Poi member, List<Edge> into, List<Edge> edges)
        {
            if (HouseTracker.isTemplate(member.location.getX(), member.location.getY())
                || !usable(member.needs) || !state.items.has(member.needs.items)
                || unlocks != null && unlocks.waiting(member.name, member.group, minute))
            {
                return;
            }
            int lacking = lacking(member.needs);
            int to = snap(member.location);
            // Outside one's own house only (a friend's house tells nothing of it).
            if (to < 0 || member.name.contains("(Outside)") && (state.houseExit < 0 || state.inHouse && !state.ownHouse
                || distance(to, state.houseExit) > PORT_RADIUS))
            {
                return;
            }
            String name = member.name.toLowerCase(ROOT);
            String category = member.group != null && !member.group.isEmpty() ? member.group : "Teleports";
            boolean once = onceOnly(name, member.group);
            if (avoids(name, category) || once && avoiding.contains(ONCE_ONLY))
            {
                return;
            }
            boolean outside = state.inHouse && "Minigame teleports".equals(member.group);
            int from = outside && state.houseExit >= 0 ? snap(RouteFeature.worldPoint(state.houseExit)) : Edge.ANYWHERE;
            if (outside && from < 0)
            {
                return;
            }
            (outside ? edges : into).add(new Edge(from, to, Kind.TELEPORT, member.name,
                detail(TELEPORT, member.needs),
                // Half ticks: 4 ticks (a teleport spell, a tablet); a home or minigame teleport takes 24 ticks to cast.
                once ? 48 : 8, category)
                .weighed(saving.teleport + lacking + (charged(member.group, state) ? 1 : 0)));
        }

        void transport(Poi poi, List<Edge> into)
        {
            if (notPlanted(poi))
            {
                return;
            }
            // Only what is carried: a route never fetches an item (a fare's coins, a fairy ring's staff) from the bank.
            // (The bank only as a way past it first: BankDetour, a setting.)
            boolean exactEnds = poi.type == AGILITY_SHORTCUT && walkable(poi.location);
            if (!usable(poi.needs) || !carried(poi.type, poi.needs)
                || !exactEnds && snap(poi.location) < 0)
            {
                return;
            }
            var kind = kind(poi.type);
            for (var link : poi.links())
            {
                if (!usable(link.needs) || !carried(poi.type, link.needs)
                    || poi.type == SPIRIT_TREE && notGrown.contains(link.point))
                {
                    continue;
                }
                // Each end on its own side: stepping stones stand on lava or water, with pockets between them.
                boolean sameFloor = link.point.getPlane() == poi.location.getPlane();
                // A shortcut's ends are its two sides as given: kept where walkable, also inside ground shut in but for
                // shortcuts and gates (Gu'Tanoth behind its crumbling wall), which a snap would leave for open ground.
                int from = exactEnds ? pack(poi.location) : snap(poi.location, sameFloor ? link.point : poi.location);
                int to = poi.type == AGILITY_SHORTCUT && walkable(link.point) ? pack(link.point)
                    : snap(link.point, sameFloor ? poi.location : link.point);
                if (to < 0 || to == from)
                {
                    continue;
                }
                String name = describe(poi, link);
                // A shortcut left out before 0.3.2 was saved with its other side ("… → other side").
                if (avoids(name, poi.type.displayName) || poi.type == AGILITY_SHORTCUT && link.label != null
                    && avoiding.contains((name + " → " + link.label).toLowerCase(ROOT)))
                {
                    continue;
                }
                var fee = Fees.at(poi.location.getX(), poi.location.getY(), poi.location.getPlane());
                String needs = detail(poi.type, link.needs);
                if (fee != null)
                {
                    // The fee apart: it cannot be checked, so it is not something the player lacks.
                    needs = needs == null ? "Needs: " + fee.text : needs + ". Also needs: " + fee.text;
                }
                into.add(new Edge(from, to, kind, name, needs, cost(poi.type) * dials(poi.type, link.label)
                    + (fee == null ? 0 : fee.cost),
                    poi.type.displayName).weighed(saving.tiles(poi.type)));
            }
        }

        /**
         * A dock: leaving the boat needs its Sailing level; boarding needs the boat there, a shipwright to bring it, or a
         * port when no boat's port is known. {@code onBoat}: the route starts at sea on the boat, so it lies at no dock.
         */
        void mooring(Poi poi, boolean onBoat, List<Edge> into)
        {
            if (!state.sailing || state.sailingLevel < level(poi.needs) || !usable(poi.needs))
            {
                return;
            }
            int x = poi.location.getX();
            int y = poi.location.getY();
            int land = map.nearestWalkable(x, y, 0, 8);
            int water = sea.nearestBlock(x, y, DOCK_REACH, state.sailingLevel);
            if (land < 0 || water < 0)
            {
                return;
            }
            into.add(new Edge(water, land, Kind.DISEMBARK, "Dock at " + poi.name + dockLevel(poi), null, 10));
            int needed = Math.max(1, level(poi.needs));
            String lacking = realSailing < needed
                ? "You lack: " + (realSailing <= 0 ? "Sailing" : needed + " Sailing")
                : null;
            String name = "Board your boat at " + poi.name;
            String hint = null;
            int cost = 10;
            String summon = Arrays.stream(state.boatFocus).anyMatch(focus -> focus >= 1)
                ? boatSpell("summon boat") : null;
            if (Arrays.stream(state.boats).anyMatch(boat -> distance(boat, land) <= BOAT_REACH))
            {
                name += dockLevel(poi);
            }
            else if (summon != null)
            {
                name = "Summon your boat and board it at " + poi.name;
                hint = summon;
                cost = 16;
            }
            else if (Arrays.stream(options.shipwrights).anyMatch(s -> distance(s, land) <= SHIPWRIGHT_REACH))
            {
                hint = "Ask the shipwright here to bring your boat (fee)";
                cost = 60;
            }
            else if (state.boats.length == 0 && !onBoat
                && Arrays.stream(PORTS.get()).anyMatch(port -> distance(port, land) <= SHIPWRIGHT_REACH))
            {
                // Where the boat lies is not known yet (not logged in): a port, where it may lie; not any dock.
                hint = "If your boat is moored here (a shipwright can bring it)";
            }
            else
            {
                return;
            }
            into.add(new Edge(land, water, Kind.BOARD, name, lacking != null ? lacking : hint, cost));
        }

        /** How the player casts a boat spell now: its tablet, the spell itself, or null when neither. */
        String boatSpell(String kind)
        {
            var spell = own(kind).stream().findFirst().orElse(null);
            return spell == null ? null : state.items.has(spell[7]) ? spell[1]
                : usable(needs(spell)) && state.items.has(needs(spell).items) ? "Spell (standard spellbook)" : null;
        }

        /** To each boat with the greater teleport focus: by the Sailing cape, a tablet or the spell, when the player can. */
        void teleportToBoat(List<Edge> into)
        {
            String means = !state.sailing ? null : own("sailing cape").stream().filter(c -> state.items.has(c[3]))
                .map(c -> c[1]).findFirst().orElseGet(() -> boatSpell("boat teleport"));
            for (int i = 0; means != null && i < state.boats.length; i++)
            {
                int land = i >= state.boatFocus.length || state.boatFocus[i] < 2 ? -1
                    : map.nearestWalkable(x(state.boats[i]), y(state.boats[i]), 0, 12);
                if (land >= 0)
                {
                    into.add(new Edge(Edge.ANYWHERE, land, Kind.TELEPORT, "Teleport to Boat", means, 10));
                }
            }
        }

        /**
         * Whether what a step needs is carried. A fairy ring's staff (Dramen or Lunar) is not needed once the Lumbridge &
         * Draynor Elite Diary is done.
         */
        boolean carried(PoiType type, Needs needs)
        {
            return state.items.has(needs.items) || type == FAIRY_RING && unlocks != null && unlocks.lumbridgeElite();
        }

        /** The fallback takes a teleport whose item the player lacks only as a last resort (else all of it would be red). */
        int lacking(Needs needs)
        {
            return fallback && missingItems != null && !needs.items.isEmpty()
                && !missingItems.has(needs.items) ? LACKING_ITEM : 0;
        }

        /**
         * The house's ways out. With its plan seen (own house) they stand where they are on it, routes walk to them and
         * teleport in to its arrival; else, in the house, the route starts with them, and from outside a teleport in or
         * its portal leads to them at once.
         */
        void house(List<Poi> pois, Map<String, Poi> teleports,
            List<Edge> starts, List<Edge> edges)
        {
            var plan = state.inHouse && !state.ownHouse ? null : map.house();
            var into = new ArrayList<Edge>();
            var portal = state.houseExit < 0 ? null
                : new WorldPoint(x(state.houseExit), y(state.houseExit), 0);
            if (state.inHouse && portal != null && (plan == null || !plan.things.containsValue("Portal")))
            {
                addHouse(into, portal, "Leave the house by its portal", 6, null);
            }
            var placed = new HashSet<String>();
            if (plan != null)
            {
                plan.things.forEach((node, name) -> {
                    // Each side: the route takes the one the game walks to as it is clicked (Pathfinder.steps).
                    int[] at = plan.approach(node);
                    var out = new ArrayList<Edge>();
                    List<String> features = name.startsWith(NEXUS + ": ") ? Arrays.stream(name.substring(NEXUS.length() + 2)
                        .split(", ")).map(place -> "nexus:" + place).collect(Collectors.toList())
                        : name.startsWith(NEXUS) ? List.of() : Collections.singletonList(HouseTracker.feature(name));
                    // A spiritual fairy tree is both: of it what the settings have (only its ring, say).
                    if (features.contains(HouseSettings.BOTH) && !state.houseFeatures.contains(HouseSettings.BOTH))
                    {
                        features = List.of(HouseSettings.GARDENS[1], HouseSettings.GARDENS[2]);
                    }
                    // As set for the account (the panel may have taken one off); one not reachable is used from the arrival.
                    // Each of several alike (two spirit trees) from where it stands: the route takes the nearest.
                    for (String feature : features)
                    {
                        if (feature != null && at.length > 0 && HouseSettings.has(state.houseFeatures, feature))
                        {
                            placed.add(feature);
                            ways(feature, pois, teleports, out);
                        }
                    }
                    if (name.equals("Portal") && portal != null)
                    {
                        addHouse(out, portal, "Leave the house by its portal", 6, null);
                    }
                    for (int dz = -1; stairs(name) && dz <= 1; dz += 2)
                    {
                        int other = z(node) + dz;
                        // Only to a floor with stairs where these stand: they go up or down, seldom both.
                        if (plan.things.entrySet().stream().anyMatch(t -> z(t.getKey()) == other
                            && distance(t.getKey(), node) <= 3 && stairs(t.getValue())))
                        {
                            out.add(new Edge(Edge.ANYWHERE, map.nearestWalkable(x(node), y(node), other, 3),
                                Kind.STAIRS, name, null, 5));
                        }
                    }
                    for (Edge e : out)
                    {
                        for (int side : e.to >= 0 ? at : new int[0])
                        {
                            edges.add(e.withFrom(side));
                        }
                    }
                });
            }
            // Not seen on the plan (typed in by hand), or no plan: usable at once in the house.
            for (String feature : state.inHouse && !state.ownHouse ? Set.<String>of() : state.houseFeatures)
            {
                // "Both" is a ring and a tree, maybe in two gardens: only a part not on the plan is used at once.
                boolean both = feature.equals(HouseSettings.BOTH) && !placed.contains(feature);
                for (String part : both ? List.of(HouseSettings.GARDENS[1], HouseSettings.GARDENS[2]) : List.of(feature))
                {
                    if (!HouseSettings.has(placed, part))
                    {
                        ways(part, pois, teleports, into);
                    }
                }
            }
            if (plan != null)
            {
                into.forEach(e -> edges.add(e.withFrom(plan.arrival)));
                into.clear();
            }
            if (state.inHouse)
            {
                starts.addAll(into);
                return;
            }
            String[] best = null;
            int lacking = 0;
            for (var way : own("house"))
            {
                Needs needs = needs(way);
                int lack = lacking(needs);
                // Set to land outside, the capes do so; the spell and the tablet keep an option to land inside.
                if ((state.landsInside || !way[7].equals("outside")) && usable(needs) && state.items.has(needs.items)
                    && (best == null || lack < lacking)
                    && !avoids(way[1] + (state.landsInside ? "" : " (inside)"), "Teleports"))
                {
                    best = way;
                    lacking = lack;
                }
            }
            int door = portal == null ? -1 : snap(portal);
            String teleport = best == null ? null : best[1] + (state.landsInside ? "" : " (Inside)");
            if (plan != null)
            {
                if (best != null)
                {
                    starts.add(new Edge(Edge.ANYWHERE, plan.arrival, Kind.TELEPORT, teleport,
                        detail(TELEPORT, needs(best)), 10, "Teleports")
                        .weighed(saving.teleport + lacking));
                }
                if (door >= 0)
                {
                    edges.add(new Edge(door, plan.arrival, Kind.ENTRANCE, "Enter your house", null, 6));
                }
                return;
            }
            for (Edge e : into)
            {
                if (best != null)
                {
                    starts.add(new Edge(Edge.ANYWHERE, e.to, Kind.HOUSE, teleport + " → " + e.name,
                        both(detail(TELEPORT, needs(best)), e.detail), 10 + e.cost)
                        .weighed(saving.teleport + lacking));
                }
                if (door >= 0)
                {
                    edges.add(new Edge(door, e.to, Kind.HOUSE, "Enter your house → " + e.name, e.detail,
                        6 + e.cost));
                }
            }
        }

        /** Where a feature of the house ("portal:Varrock", "box:ornate", "glory", "xeric", "fairy ring") leads, from anywhere. */
        void ways(String feature, List<Poi> pois, Map<String, Poi> teleports, List<Edge> into)
        {
            int mounted = Arrays.asList(HouseSettings.MOUNTED).indexOf(feature);
            if (feature.startsWith("portal:") || feature.startsWith("nexus:"))
            {
                String place = feature.substring(feature.indexOf(':') + 1);
                var teleport = portalTeleport(place, teleports);
                if (teleport != null)
                {
                    // Named as the portal is ("Troll Stronghold"), not as the teleport that says where it leads.
                    addHouse(into, teleport.location, (feature.startsWith("nexus:") ? "Portal nexus: " : "House portal: ")
                        + place, 6, null);
                }
            }
            else if (feature.startsWith("box:") || mounted >= 0)
            {
                var groups = mounted >= 0 ? List.of(HouseSettings.MOUNTED_GROUPS[mounted])
                    : Pathfinder.list("jewellery box teleports").stream().limit(feature.equals("box:basic") ? 2
                    : feature.equals("box:ornate") ? 6 : 4).collect(Collectors.toList());
                for (var teleport : teleports.values())
                {
                    if (teleport.group != null && groups.contains(teleport.group) && usable(teleport.needs))
                    {
                        addHouse(into, teleport.location, (mounted >= 0 ? MOUNTED_NAMES[mounted] : "Jewellery box: ")
                            + teleport.name, 8, null);
                    }
                }
            }
            if (feature.equals("obelisk"))
            {
                // As those in the Wilderness: to the obelisk one chooses, with the Hard Wilderness Diary.
                for (var poi : pois)
                {
                    if (poi.type == OBELISK && usable(poi.needs))
                    {
                        addHouse(into, poi.location, "House obelisk: " + poi.name, cost(OBELISK), null);
                    }
                }
            }
            if (feature.contains("fairy ring") || feature.contains("spirit tree"))
            {
                for (var poi : pois)
                {
                    boolean ring = poi.type == FAIRY_RING && feature.contains("fairy ring");
                    boolean tree = poi.type == SPIRIT_TREE && feature.contains("spirit tree");
                    // The house's ring needs the staff as any ring does.
                    if ((ring || tree) && usable(poi.needs) && carried(poi.type, poi.needs)
                        && !notPlanted(poi))
                    {
                        addHouse(into, poi.location, "House " + poi.type.displayName.toLowerCase(ROOT) + ": "
                            + code(poi.type, poi.name), 10 * dials(poi.type, poi.name), bankNeeds(poi.type,
                            poi.needs));
                    }
                }
            }
        }

        void addHouse(List<Edge> into, WorldPoint point, String name, int cost, String detail)
        {
            int to = snap(point);
            if (to >= 0)
            {
                // One kind (as minigame teleports are), to leave all out at once; the way out of the house is none.
                into.add(new Edge(Edge.ANYWHERE, to, Kind.HOUSE, name, detail, cost, name.contains(": ")
                    ? "House teleports" : null));
            }
        }

        String needsText(Needs needs)
        {
            if (needs.isEmpty())
            {
                return null;
            }
            if (missingLevels == null && missingItems == null)
            {
                return uncheckedText(realUnlocks, needs);
            }
            var parts = new ArrayList<String>();
            if (missingLevels != null)
            {
                parts.addAll(unmetLines(missingLevels, needs));
            }
            if (missingItems != null && !missingItems.has(needs.items))
            {
                parts.add(missingItems(missingItems, needs.items, itemNames));
            }
            return parts.isEmpty() ? null : "You lack: " + String.join(", ", parts);
        }

        /** A step's detail: what it needs from the bank ({@link #bankNeeds}), else {@link #needsText}. */
        String detail(PoiType type, Needs needs)
        {
            String bank = bankNeeds(type, needs);
            return bank != null ? bank : needsText(needs);
        }

        /**
         * What a step needs from the bank, when the bank is counted and what is carried is not enough; else null. A fairy
         * ring needs no staff after the Lumbridge & Draynor Elite Diary.
         */
        String bankNeeds(PoiType type, Needs needs)
        {
            boolean enough = carried == null || carried.has(needs.items)
                || type == FAIRY_RING && unlocks != null && unlocks.lumbridgeElite();
            return enough ? null : BankDetour.FROM_BANK + fromBank(needs.items);
        }

        /**
         * What of {@code column} only the bank has, by name: of each part not carried, the alternatives the bank holds
         * ("Dramen staff", "Law rune, Air rune ×3").
         */
        String fromBank(String column)
        {
            return itemLines(Arrays.stream(ItemSnapshot.ALL.split(column)).filter(all -> !carried.has(all))
                .map(all -> Arrays.stream(ItemSnapshot.ANY.split(all)).filter(items::has).findFirst().map(String::trim)
                    .orElse(all)).collect(Collectors.toList()), itemNames, "items");
        }
    }

    @RequiredArgsConstructor
    static final class Gate
    {
        final WorldPoint from;
        final WorldPoint to;
        final String name;
        final Needs needs;
    }

    /** A way between two seas that sailing alone does not join (sea_passages.tsv): a sea cave. */
    @RequiredArgsConstructor
    static final class SeaPassage
    {
        final int fromX;
        final int fromY;
        final int toX;
        final int toY;
        final String name;
        final Needs needs;
        final String note;
    }

    /** Read once per route.zip, so the unlocks' per-requirement cache hits. */
    static final RouteFiles.Table<List<Gate>> GATES = new RouteFiles.Table<>(RouteSource::readGates);
    static final RouteFiles.Table<List<SeaPassage>> SEA_PASSAGES =
        new RouteFiles.Table<>(RouteSource::readSeaPassages);
    /**
     * The needs of the bundled gates, shortcuts and own ways (a house tablet), whose quests and varbits the requirements
     * read must watch too, and whose items are named and kept of the bank.
     */
    static List<Needs> fixedNeeds()
    {
        var needs = new ArrayList<Needs>();
        GATES.get().forEach(gate -> needs.add(gate.needs));
        OWN.get().forEach(way -> needs.add(needs(way)));
        SEA_PASSAGES.get().forEach(passage -> needs.add(passage.needs));
        for (var way : ShortcutPassage.allWays())
        {
            needs.add(new Needs(way[0], way[1], way[2], way[3]));
        }
        return needs;
    }

    /** Where to stand at each bank (banks.tsv): by its icon's tile, the tiles beside its booths, nearest the icon first. */
    static final RouteFiles.Table<Map<Integer, int[]>> BANKS = new RouteFiles.Table<>(() -> Pathfinder.table(
        RouteFiles.DIR + "banks.tsv", cells -> new int[]{parse(cells[0]), parse(cells[1])}).stream()
        .filter(row -> row[0] >= 0 && row[1] >= 0).collect(Collectors.groupingBy(row -> row[0],
            Collectors.collectingAndThen(Collectors.toList(), rows -> rows.stream().mapToInt(row -> row[1]).toArray()))));

    /** The booth or chest each stand of banks.tsv uses (its fifth column), by the stand. */
    static final RouteFiles.Table<Map<Integer, Integer>> BOOTHS = new RouteFiles.Table<>(() -> Pathfinder.table(
        RouteFiles.DIR + "banks.tsv", cells -> new int[]{parse(cells[1]), parse(cells[4])}).stream()
        .filter(row -> row[0] >= 0 && row[1] >= 0).collect(Collectors.toMap(row -> row[0], row -> row[1], (a, b) -> a)));

    /** Where a bank step is named: on the booth or chest used from {@code stand}, else the stand. */
    static int booth(int stand)
    {
        return BOOTHS.get().getOrDefault(stand, stand);
    }

    /** Where to stand to use the bank whose icon is at {@code icon}: by each of its booths, else the icon itself. */
    static int[] bankStands(int icon)
    {
        var stands = BANKS.get().get(icon);
        return stands != null ? stands : new int[]{icon};
    }

    /** Where a boat can lie: the game's ports. */
    static final RouteFiles.Table<int[]> PORTS = new RouteFiles.Table<>(RouteSource::readPorts);

    static int[] readPorts()
    {
        try
        {
            return Ports.load().values().stream().mapToInt(Integer::intValue).toArray();
        }
        catch (IOException e)
        {
            return new int[0];
        }
    }

    /** gates.tsv by column: Name, Origin, Destination, Skills, Items, Quests, Varbits; {@code #} lines are comments. */
    static List<Gate> readGates()
    {
        return Pathfinder.table(RouteFiles.DIR + "gates.tsv", cells -> {
            var from = point(cell(cells, 1));
            var to = point(cell(cells, 2));
            return from == null || to == null ? null : new Gate(from, to, cell(cells, 0), new Needs(cell(cells, 3),
                cell(cells, 4), cell(cells, 5), cell(cells, 6)));
        });
    }

    /** sea_passages.tsv by column: from x y, to x y, Name, Quests, Note; {@code #} lines are comments. */
    static List<SeaPassage> readSeaPassages()
    {
        return Pathfinder.table(RouteFiles.DIR + "sea_passages.tsv", cells -> {
            var from = Pathfinder.ints(cell(cells, 0));
            var to = Pathfinder.ints(cell(cells, 1));
            return new SeaPassage(from[0], from[1], to[0], to[1], cell(cells, 2), new Needs("", "", cell(cells, 3), ""),
                cell(cells, 4));
        });
    }

    static String cell(String[] cells, int column)
    {
        return column < cells.length ? cells[column].trim() : "";
    }

    /** {@code "x y plane"}, or null. */
    static WorldPoint point(String cell)
    {
        var parts = cell.split("\\s+");
        try
        {
            return parts.length != 3 ? null
                : new WorldPoint(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]), Integer.parseInt(parts[2]));
        }
        catch (NumberFormatException e)
        {
            return null;
        }
    }

    /** How a gate named by its action starts (list "actions"); (?!) matches nothing: without the list all are opened. */
    static final RouteFiles.Table<Pattern> ACTION = new RouteFiles.Table<>(() -> Pattern.compile("((?!)"
        + Pathfinder.list("actions").stream().map(a -> "|" + Pattern.quote(a)).collect(Collectors.joining()) + ")\\b"));

    // Obelisks only with the Hard Wilderness Diary, which their stops need (it lets one choose where they lead; without
    // it they lead to a random other obelisk). Not entrances (map links, in Pathfinder, not our icons).
    static final Set<PoiType> TRANSPORTS = EnumSet.of(FAIRY_RING, SPIRIT_TREE,
        GNOME_GLIDER, BALLOON, QUETZAL, MUSHTREE, OBELISK, BOAT,
        CHARTER, CANOE, CARPET, MINECART, PORTAL, LEVER,
        TRANSPORT, AGILITY_SHORTCUT);

    static boolean isTransport(PoiType type)
    {
        return TRANSPORTS.contains(type);
    }

    boolean walkable(WorldPoint point)
    {
        return map.walkable(point.getX(), point.getY(), point.getPlane());
    }

    int snap(WorldPoint point)
    {
        return snap(point, point);
    }

    int snap(WorldPoint point, WorldPoint other)
    {
        long key = (long) pack(point) << 32 | pack(other) & 0xffffffffL;
        // A spot one can stand on is where the game puts one, also in ground shut in but for the jump itself (the fairy
        // ring BIS in the zoo's unicorn pen): only a spot on an object or a wall moves to the nearest open ground.
        return snaps.computeIfAbsent(key, k -> walkable(point) ? pack(point) : map.nearestWalkable(point.getX(),
            point.getY(), point.getPlane(), SNAP, other.getX(), other.getY(), pocket));
    }

    static final RouteFiles.Table<Map<String, String>> UNLIMITED = new RouteFiles.Table<>(() -> Pathfinder.pairs(
        "unlimited", v -> v));

    /**
     * Jewellery and such with charges (list "charged"): at a tie a spell's runes or a teleport without limit (list
     * "unlimited": the amulet of eternal glory, the eternal slayer ring) go first.
     */
    static boolean charged(String group, PlayerState state)
    {
        if (group == null || !Pathfinder.list("charged").contains(group))
        {
            return false;
        }
        String unlimited = UNLIMITED.get().get(group);
        return unlimited == null || !state.items.has(unlimited);
    }

    /** The planted spirit trees that stand grown for this account (see {@link PlantedSpiritTrees}). */
    volatile Set<String> plantedTrees = Collections.emptySet();

    /** A planted spirit tree's stop the player has no grown tree at: not travelled from or to. */
    boolean notPlanted(Poi poi)
    {
        return PlantedSpiritTrees.planted(poi) && !plantedTrees.contains(poi.name);
    }

    static final String TYPE = "type:";

    static String typeKey(String category)
    {
        return TYPE + category.toLowerCase(ROOT);
    }

    static String describe(Poi poi, Poi.Link link)
    {
        String label = link.label == null || link.label.isEmpty() ? null : link.label;
        switch (poi.type)
        {
            // The obstacle is enough: its other side ("Other side", "Go over") says nothing.
            case AGILITY_SHORTCUT:
                return poi.name;
            case LEVER:
            case PORTAL:
                return poi.name + (label != null && !poi.name.contains(label) ? " → " + label : "");
            default:
                return poi.type.displayName + ": " + code(poi.type, label != null ? label : poi.name);
        }
    }

    /**
     * A fairy ring by the code one dials ("BIP"), not its whole title; codes dialled one after another ("AIR-DLR-DJQ-AJS",
     * the Fairy Resistance Hideout) as "AIR, DLR, DJQ, then AJS".
     */
    static String code(PoiType type, String name)
    {
        int dash = type == FAIRY_RING ? name.indexOf(" – ") : -1;
        String code = dash < 0 ? name : name.substring(0, dash);
        var codes = code.split("-");
        return dials(type, code) == 1 ? code
            : String.join(", ", Arrays.copyOf(codes, codes.length - 1)) + ", then " + codes[codes.length - 1];
    }

    /** How many rings one goes through to a stop: the codes of a sequence ("AIR-DLR-DJQ-AJS"), else one. */
    static int dials(PoiType type, String name)
    {
        if (type != FAIRY_RING || name == null)
        {
            return 1;
        }
        int dash = name.indexOf(" – ");
        String code = dash < 0 ? name : name.substring(0, dash);
        return code.matches("[A-Z]{3}(-[A-Z]{3})+") ? code.split("-").length : 1;
    }

    static Kind kind(PoiType type)
    {
        switch (type)
        {
            case BOAT:
            case CHARTER:
                return Kind.SHIP;
            case AGILITY_SHORTCUT:
            case PORTAL:
            case LEVER:
                return Kind.ENTRANCE;
            default:
                return Kind.TRANSPORT;
        }
    }

    /** In the avoid set: no home or minigame teleport at all (an order's trips without the one cast they get). */
    static final String ONCE_ONLY = TYPE + "home and minigame teleports";

    /** A home or minigame teleport: cast once, then its cooldown (30 and 20 minutes). {@code name} lower case. */
    static boolean onceOnly(String name, String group)
    {
        return name.contains("home teleport") || "Minigame teleports".equals(group);
    }

    /** Whether a route's step is such a teleport. */
    static boolean onceOnly(Route.Step step)
    {
        return step.kind == Route.Step.Kind.TELEPORT && step.name != null
            && onceOnly(step.name.toLowerCase(ROOT), step.category);
    }

    static int cost(PoiType type)
    {
        switch (type)
        {
            case FAIRY_RING:
            case SPIRIT_TREE:
            case MUSHTREE:
                return 10;
            case LEVER:
            case AGILITY_SHORTCUT:
            case OBELISK:
                return 8;
            case PORTAL:
                return 6;
            // A ship's trip is a few seconds of its map interlude, a boat's with its talk more.
            case MINECART:
            case GNOME_GLIDER:
            case QUETZAL:
                return 12;
            case CHARTER:
            case BALLOON:
                return 14;
            case CANOE:
                return 60;
            case CARPET:
                return 100;
            default:
                return 20;
        }
    }

    static String dockLevel(Poi poi)
    {
        int level = level(poi.needs);
        return level > 1 ? " (" + level + " Sailing)" : "";
    }

    static int level(Needs needs)
    {
        Matcher m = SAILING.matcher(needs.skills);
        return m.find() ? Integer.parseInt(m.group(1)) : 1;
    }

    static boolean stairs(String thing)
    {
        return HouseTracker.feature(thing) == null && !thing.equals("Portal") && !thing.startsWith(NEXUS);
    }

    /**
     * The player's own ways the planner adds itself (the map version's own_ways.tsv) by kind: into one's own house best
     * first, the boat spells (Summon Boat brings a boat with a teleport focus to the dock one stands at, Teleport to
     * Boat takes one to a boat with the greater focus), the Sailing cape. Each: kind, name, needs (skills, items,
     * quests, varbits), short name, then a tablet's item id or whether it lands outside the house.
     */
    static final RouteFiles.Table<List<String[]>> OWN = new RouteFiles.Table<>(() -> Pathfinder.table(
        RouteFiles.DIR + "own_ways.tsv", c -> c.length < 8 ? null : c));

    static List<String[]> own(String kind)
    {
        return OWN.get().stream().filter(c -> c[0].equals(kind)).collect(Collectors.toList());
    }

    static Needs needs(String[] way)
    {
        return new Needs(way[2], way[3], way[4], way[5]);
    }

    /** Two details of one step (the way into the house and what is used there): what the bank gives as one line. */
    static String both(String a, String b)
    {
        String bank = BankDetour.FROM_BANK;
        if (a == null || b == null)
        {
            return a == null ? b : a;
        }
        return a.startsWith(bank) && b.startsWith(bank) ? a + ", " + b.substring(bank.length()) : a + ". " + b;
    }

    static final String NEXUS = "Portal Nexus";
    /** How a mounted amulet's house step starts, in {@link HouseSettings#MOUNTED}'s order. */
    static final String[] MOUNTED_NAMES = {"Mounted glory: ", "Mounted talisman: ", "Mounted pendant: "};

    /** Portal and nexus places the spellbooks name otherwise (list "portal names"). */
    static final RouteFiles.Table<Map<String, String>> PORTAL_NAMES = new RouteFiles.Table<>(() -> Pathfinder.pairs(
        "portal names", v -> v));

    /** A spell starting with the place's name first, else a teleport to it by name ("Stony basalt: Troll Stronghold"). */
    static Poi portalTeleport(String place, Map<String, Poi> teleports)
    {
        String given = place.trim().toLowerCase(ROOT);
        String wanted = PORTAL_NAMES.get().getOrDefault(given, given);
        int bestRank = 0;
        String bestName = null;
        Poi best = null;
        for (var entry : teleports.entrySet())
        {
            String name = entry.getKey();
            var teleport = entry.getValue();
            boolean spell = name.startsWith(wanted) && teleport.group != null && teleport.group.contains("Spellbook");
            if (!spell && !name.contains(": " + wanted))
            {
                continue;
            }
            if (name.equals(wanted) || name.equals(wanted + " teleport"))
            {
                return teleport;
            }
            // Spells first, then the shortest name, then the first alphabetically.
            int rank = (spell ? 0 : 1 << 16) + name.length();
            if (best == null || rank < bestRank || rank == bestRank && name.compareTo(bestName) < 0)
            {
                bestRank = rank;
                bestName = name;
                best = teleport;
            }
        }
        return best;
    }

    static final int LACKING_ITEM = 2000;

    /** The skill/quest lines of {@code needs} that {@code unlocks} says are not met, by their text. */
    static List<String> unmetLines(Unlocks unlocks, Needs needs)
    {
        return Requirements.skillsAndQuests(needs).stream().filter(line -> Boolean.FALSE.equals(unlocks.met(line)))
            .map(line -> line.text).collect(Collectors.toList());
    }

    /** The groups of a column like {@code "563=1&&556=3"} that are not carried, by name: "1 × Law rune". */
    static String missingItems(ItemSnapshot carried, String column, IntFunction<String> names)
    {
        var missing = Arrays.stream(ItemSnapshot.ALL.split(column)).filter(all -> !carried.has(all))
            .collect(Collectors.toList());
        return itemLines(missing, names, "items you do not have");
    }

    static String itemLines(List<String> all, IntFunction<String> names, String none)
    {
        var lines = names == null ? List.<String>of() : Requirements.items(String.join("&&", all), names);
        return lines.isEmpty() ? none : String.join(", ", lines);
    }

    /** A step's requirements when not all could be checked (logged out, unknown quest or item); else null. */
    static String uncheckedText(Unlocks realUnlocks, Needs needs)
    {
        var lines = Requirements.skillsAndQuests(needs);
        if (lines.stream().allMatch(line -> realUnlocks != null && realUnlocks.met(line) != null))
        {
            return null;
        }
        var parts = lines.stream().map(line -> line.text).collect(Collectors.toList());
        if (!needs.items.trim().isEmpty() && realUnlocks == null)
        {
            parts.add("items");
        }
        return parts.isEmpty() ? null : "Needs: " + String.join(", ", parts);
    }
}

package com.hdmapreforged;

import static com.hdmapreforged.MapView.*;

import lombok.*;
import java.awt.*;
import java.awt.geom.*;
import java.util.function.*;

/** The custom routes button above the floor buttons: toggles the custom routes panel. Swing thread only. */
@RequiredArgsConstructor
final class RoutesButton implements Widget
{
    static final int LEFT = 12;
    static final Color OPEN = new Color(60, 66, 44, 235);

    final Runnable toggle;
    final BooleanSupplier open;
    final BooleanSupplier shown;

    public void paint(Graphics2D g, int width, int height, int bottom, Clicks clicks)
    {
        if (!shown.getAsBoolean())
        {
            return;
        }
        g.setFont(CONTROL_FONT);
        var metrics = g.getFontMetrics();
        int w = floorGroupWidth(metrics);
        var button = new RoundRectangle2D.Double(LEFT, bottom - CONTROL, w, CONTROL, 10, 10);
        box(g, button, open.getAsBoolean() ? OPEN : clicks.hovered(button) ? CONTROL_HOVER : CONTROL_FILL, CONTROL_EDGE);
        // Three stops joined by a dashed line, then the word.
        int textWidth = metrics.stringWidth("Routes");
        double x = LEFT + (w - textWidth - 20) / 2.0;
        double y = bottom - CONTROL / 2.0;
        var path = new Path2D.Double();
        path.moveTo(x, y + 5);
        path.lineTo(x + 6, y - 5);
        path.lineTo(x + 12, y + 3);
        g.setColor(PlayerMarker.YELLOW);
        g.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND, 1f, new float[]{2.5f, 2f}, 0));
        g.draw(path);
        g.setColor(Color.WHITE);
        for (var p : new double[][]{{x, y + 5}, {x + 6, y - 5}, {x + 12, y + 3}})
        {
            g.fill(new Ellipse2D.Double(p[0] - 2, p[1] - 2, 4, 4));
        }
        text(g, "Routes", x + 20, middle(y, metrics));
        clicks.add(button, toggle, "Custom routes: your own routes with several stops, to order, save and run");
    }
}

package com.hdmapreforged;

import static java.awt.RenderingHints.*;

import java.awt.*;
import java.awt.geom.*;
import java.awt.image.*;
import java.lang.ref.*;
import java.util.*;
import java.util.List;
import lombok.*;

/**
 * Tiles pre-scaled to their drawn size: smooth scaling every frame was the most expensive part of painting. Swing
 * thread only.
 */
final class ScaledTiles
{
    static final long MAX_BYTES = 64L * 1024 * 1024;
    /** Copies made per frame, in pixels (about 3 ms of smooth scaling): after a zoom, all at once took 16-30 ms. */
    static final int FRAME_PIXELS = 1 << 19;

    static final class Entry
    {
        /** Weak, so a tile the cache dropped is not kept alive here. */
        final WeakReference<BufferedImage> source;
        /** Soft: the JVM drops copies before it runs out of memory; the tile is then drawn from its source, as sharp. */
        final SoftReference<BufferedImage[]> scaled;
        final int width;
        final int height;
        /** The frame that last drew it; never dropped for another copy that frame, or each would be made again. */
        int frame;

        Entry(BufferedImage source, int width, int height)
        {
            this.source = new WeakReference<>(source);
            this.width = width;
            this.height = height;
            // A copy is kept in strips of at most 360 × 360 pixels: larger ones would pass half of a 1 MB heap region,
            // which Java's G1 keeps "humongous" in whole regions of the old generation; at zoom 3.5 to 4 they filled a
            // 768 MB heap and made the map stutter.
            int rows = Math.max(1, 360 * 360 / width);
            var strips = new BufferedImage[(height + rows - 1) / rows];
            for (int i = 0; i < strips.length; i++)
            {
                strips[i] = scale(source, width, height, i * rows, Math.min(rows, height - i * rows));
            }
            scaled = new SoftReference<>(strips);
        }

        long bytes()
        {
            return 4L * width * height;
        }
    }

    @RequiredArgsConstructor
    static final class Wanted
    {
        final TileCache.Key key;
        final BufferedImage source;
        final int width;
        final int height;
    }

    final LinkedHashMap<TileCache.Key, Entry> cache = new LinkedHashMap<>(64, 0.75f, true);
    int limit = 64;
    long bytes;
    int frame;
    /** Tiles this frame drew the fast way for want of a copy, farthest from the middle first. */
    final List<Wanted> wanted = new ArrayList<>();

    /** Before a frame's tiles: keeps at most {@code tiles} copies. */
    void beginFrame(int tiles)
    {
        limit = Math.max(16, tiles);
        frame++;
        wanted.clear();
        trim();
    }

    /**
     * Makes the copies this frame lacked, the middle first, a frame's share; true when more wait for the next frame.
     * With no room left (a view too large for {@link #MAX_BYTES}) the rest stay drawn the fast way.
     */
    boolean endFrame()
    {
        int pixels = FRAME_PIXELS;
        for (int i = wanted.size() - 1; i >= 0 && !full(4L * wanted.get(i).width * wanted.get(i).height); i--)
        {
            if (pixels <= 0)
            {
                wanted.clear();
                return true;
            }
            Wanted want = wanted.get(i);
            pixels -= want.width * want.height;
            Entry entry = new Entry(want.source, want.width, want.height);
            entry.frame = frame;
            Entry old = cache.put(want.key, entry);
            bytes += entry.bytes() - (old == null ? 0 : old.bytes());
            trim();
        }
        wanted.clear();
        return false;
    }

    /** No room for {@code more} bytes without dropping a copy this frame drew. */
    boolean full(long more)
    {
        return (cache.size() >= limit || bytes + more > MAX_BYTES) && !cache.isEmpty()
            && cache.values().iterator().next().frame == frame;
    }

    void clear()
    {
        cache.clear();
        bytes = 0;
    }

    /** A new copy is only made when {@code settled} (the zoom is not animating), at {@link #endFrame}. */
    void draw(Graphics2D g, TileCache.Key key, BufferedImage source, int x, int y, int width, int height,
        boolean settled, boolean smooth)
    {
        var transform = g.getTransform();
        double device = Math.abs(transform.getScaleX());
        int dw = (int) Math.round(width * device);
        int dh = (int) Math.round(height * device);
        if (dw <= 0 || dh <= 0)
        {
            return;
        }
        // Crisp squares past the most detailed tiles (nearest neighbour): drawn from the source, the same pixels.
        // Larger than 512 × 512 would take a lot of memory and scales cheaply anyway.
        if (!smooth || dw == source.getWidth() && dh == source.getHeight() || (long) dw * dh > 512 * 512
            || transform.getShearX() != 0 || transform.getShearY() != 0)
        {
            g.drawImage(source, x, y, width, height, null);
            return;
        }
        Entry entry = cache.get(key);
        var shown = entry == null || entry.source.get() != source ? null : entry.scaled.get();
        if (shown == null && entry != null)
        {
            // Dropped by the JVM, or of an older tile: no longer counted against the limit.
            cache.remove(key);
            bytes -= entry.bytes();
        }
        if (shown == null || entry.width != dw || entry.height != dh)
        {
            if (settled)
            {
                wanted.add(new Wanted(key, source, dw, dh));
            }
            // Meanwhile scaled the fast way, as while moving.
            Object hint = g.getRenderingHint(KEY_INTERPOLATION);
            g.setRenderingHint(KEY_INTERPOLATION, VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
            g.drawImage(source, x, y, width, height, null);
            if (hint != null)
            {
                g.setRenderingHint(KEY_INTERPOLATION, hint);
            }
            return;
        }
        entry.frame = frame;
        var copy = device == 1 ? g : (Graphics2D) g.create();
        int left = x;
        int top = y;
        if (device != 1)
        {
            var place = new AffineTransform(transform);
            place.translate(x, y);
            place.scale(width / (double) dw, height / (double) dh);
            copy.setTransform(place);
            left = 0;
            top = 0;
        }
        for (var strip : shown)
        {
            copy.drawImage(strip, left, top, null);
            top += strip.getHeight();
        }
        if (copy != g)
        {
            copy.dispose();
        }
    }

    static BufferedImage scale(BufferedImage source, int width, int height)
    {
        return scale(source, width, height, 0, height);
    }

    /** Rows {@code top} on of the source scaled to {@code width} x {@code height}: strips give the same pixels as one copy. */
    static BufferedImage scale(BufferedImage source, int width, int height, int top, int rows)
    {
        BufferedImage scaled = new BufferedImage(width, rows, source.getColorModel().hasAlpha()
            ? BufferedImage.TYPE_INT_ARGB_PRE : BufferedImage.TYPE_INT_RGB);
        var g = scaled.createGraphics();
        g.setRenderingHint(KEY_INTERPOLATION, VALUE_INTERPOLATION_BILINEAR);
        g.setRenderingHint(KEY_RENDERING, VALUE_RENDER_QUALITY);
        g.drawImage(source, 0, -top, width, height, null);
        g.dispose();
        return scaled;
    }

    void trim()
    {
        var it = cache.values().iterator();
        while ((cache.size() > limit || bytes > MAX_BYTES) && it.hasNext())
        {
            Entry eldest = it.next();
            if (eldest.frame == frame)
            {
                return;
            }
            bytes -= eldest.bytes();
            it.remove();
        }
    }
}

package com.hdmapreforged;

import lombok.*;
import java.util.*;
import java.util.function.*;
import java.util.regex.*;
import net.runelite.api.coords.*;

/**
 * The place search: every typed word must fit the name or its place, in any order, a small typo forgiven. Its hits come
 * in a map version's places.json (made by the test sources' SearchIndexBuilder).
 */
@RequiredArgsConstructor
final class SearchIndex
{
    @RequiredArgsConstructor
    enum Type
    {
        PLACE(0),
        MAP(1),
        /** "Shark fishing spots". */
        KIND(1),
        ICON(2),
        /** "Shark fishing spots – Catherby". */
        KIND_PLACE(2),
        GAME_ICON(3);

        final int rank;
    }

    static final class Hit
    {
        final Type type;
        final String label;
        final String[] words;
        final String joined;
        final String[] placeWords;
        /** A {@link MapData.Place}, {@link BaseMap}, {@link Poi} or {@link KindIndex.Kind}. */
        final Object target;
        final WorldPoint point;
        final PoiType icon;
        /** Kingdoms, seas and small places come after towns of the same name (the builder's {@code later}). */
        double later;

        Hit(Type type, String label, String words, String place, Object target, WorldPoint point, PoiType icon)
        {
            this.type = type;
            this.label = label;
            this.words = words(words);
            this.joined = String.join(" ", this.words);
            this.placeWords = place == null ? new String[0] : words(place);
            this.target = target;
            this.point = point;
            this.icon = icon;
        }
    }

    final List<Hit> hits;

    /**
     * A game label or a map named after monsters ("Abyssal demons", the map "Nex"): found as the monsters, whose places
     * say where to go, not as a place or map of their own.
     */
    static boolean namesMonsters(Hit hit, WorldData world)
    {
        switch (hit.type)
        {
            case PLACE:
                var place = (MapData.Place) hit.target;
                return "place".equals(place.kind) && world.monsterName(place.name);
            case MAP:
                return world.monsterName(((BaseMap) hit.target).name);
            default:
                return false;
        }
    }

    List<Hit> find(String query, int limit, Predicate<Hit> allowed)
    {
        var typed = words(query);
        if (typed.length == 0)
        {
            return Collections.emptyList();
        }
        String whole = String.join(" ", typed);
        var scores = new HashMap<Hit, Double>();
        var found = new ArrayList<Hit>();
        for (Hit hit : hits)
        {
            double score = score(hit, typed, whole);
            if (!Double.isNaN(score) && allowed.test(hit))
            {
                scores.put(hit, score);
                found.add(hit);
            }
        }
        // Stable: equally good hits keep the index's order.
        found.sort(Comparator.comparingDouble(scores::get));
        var best = new ArrayList<Hit>();
        var labels = new HashSet<String>();
        for (Hit hit : found)
        {
            if (labels.add(hit.type == Type.MAP ? hit.label : hit.label.toLowerCase(Locale.ROOT)) && best.size() < limit)
            {
                best.add(hit);
            }
        }
        return best;
    }

    /**
     * Lower is better, NaN when a word fits nowhere. A kind at a place needs words fitting both ("shark catherby"), so a
     * town's name alone does not list everything in it.
     */
    static double score(Hit hit, String[] typed, String whole)
    {
        double score = 0;
        boolean ownWord = false;
        boolean placeWord = false;
        for (String word : typed)
        {
            int own = best(word, hit.words);
            int place = best(word, hit.placeWords);
            if (own < 0 && place < 0)
            {
                return Double.NaN;
            }
            if (own >= 0 && (place < 0 || own <= place))
            {
                ownWord = true;
                score += own;
            }
            else
            {
                placeWord = true;
                score += place + 0.5;
            }
        }
        if (!ownWord || hit.type == Type.KIND_PLACE && !placeWord)
        {
            return Double.NaN;
        }
        String name = hit.joined;
        if (name.equals(whole))
        {
            score -= 3;
        }
        else if (name.startsWith(whole))
        {
            score -= 2;
        }
        // Fewer words of its own and of its place first: "Catherby" before "Catherby Bay" for "catherby".
        return score + hit.type.rank * 0.6 + (hit.words.length + hit.placeWords.length) * 0.05 + hit.later;
    }

    /** 0 same word, 1 start of one, 2 inside one (3+ letters), 3 one letter off (5+ letters), -1 none. */
    static int best(String typed, String[] words)
    {
        int best = -1;
        for (String word : words)
        {
            int fit = word.equals(typed) ? 0 : word.startsWith(typed) ? 1
                : typed.length() >= 3 && word.contains(typed) ? 2
                : typed.length() >= 5 && nearlyStarts(word, typed) ? 3 : -1;
            if (fit >= 0 && (best < 0 || fit < best))
            {
                best = fit;
            }
        }
        return best;
    }

    static boolean nearlyStarts(String word, String typed)
    {
        for (int length = typed.length() - 1; length <= typed.length() + 1; length++)
        {
            if (length <= word.length() && oneEdit(word, length, typed))
            {
                return true;
            }
        }
        return false;
    }

    /**
     * Whether the first {@code length} letters of {@code word} are at most one letter changed, added or left out from
     * {@code typed}: checked letter by letter, with nothing made, as it runs for every word at every keystroke.
     */
    static boolean oneEdit(String word, int length, String typed)
    {
        int t = typed.length();
        int i = 0;
        while (i < length && i < t && word.charAt(i) == typed.charAt(i))
        {
            i++;
        }
        if (i == length || i == t)
        {
            return Math.abs(length - t) <= 1;
        }
        return length == t ? word.regionMatches(i + 1, typed, i + 1, t - i - 1)
            : length == t + 1 ? word.regionMatches(i + 1, typed, i, t - i)
            : length == t - 1 && word.regionMatches(i, typed, i + 1, length - i);
    }

    static final Pattern NOT_WORD = Pattern.compile("[^a-z0-9]+");

    /** Lower-case words without punctuation: "Phosani's Nightmare" is "phosanis nightmare". */
    static String[] words(String text)
    {
        String clean = NOT_WORD.matcher(text.toLowerCase(Locale.ROOT).replace("'", "")).replaceAll(" ").trim();
        return clean.isEmpty() ? new String[0] : clean.split(" ");
    }
}

package com.hdmapreforged;

import static java.lang.Math.*;

import java.util.concurrent.*;
import java.awt.*;
import java.awt.event.*;
import java.awt.geom.*;
import java.awt.image.*;
import java.util.*;
import java.util.List;
import java.util.function.*;
import java.util.regex.*;
import java.util.stream.*;
import javax.swing.*;
import net.runelite.api.coords.*;
import net.runelite.client.ui.*;
import lombok.*;
import net.runelite.client.util.*;
import com.hdmapreforged.NpcSpawns.Group;
import com.hdmapreforged.WorldData.Drop;

/** What a search found (a monster, an item's sources, a kind of place), marked on the map and listed. Swing thread. */
final class SearchResults implements MapView.Overlay, MapView.HitLayer
{
    interface Card
    {
        void show(IntFunction<JComponent> section);

        /** A background answer (a tile check): re-render only while this search is what is shown. */
        default void update(IntFunction<JComponent> section)
        {
            show(section);
        }
    }

    static final class Result
    {
        final String title;
        final String page;
        final String summary;
        final List<Group> groups;
        final String credit;
        String kind;
        /** The NPC whose picture heads it; -1 for none. */
        int picture = -1;
        /** The item it is about, for its picture and price; -1 for none. */
        int item = -1;
        /** A monster's drops: its standard table's. */
        List<Drop> drops = Collections.emptyList();
        /** All its page's drop tables, the standard one first. */
        List<WorldData.Table> tables = Collections.emptyList();
        /** An item's droppers. */
        List<ItemSources.Dropper> droppers = Collections.emptyList();

        Result(String title, String page, String summary, List<Group> groups, String credit)
        {
            this.title = title;
            this.page = page;
            this.summary = summary;
            this.groups = Collections.unmodifiableList(groups);
            this.credit = credit;
        }
    }

    static final String SHOPS = "Shops";
    static final String GROUND = "On the ground";
    static final Pattern FRACTION = Pattern.compile("(\\d+(?:\\.\\d+)?)\\s*/\\s*(\\d+(?:\\.\\d+)?)");

    static final Color DOT = new Color(70, 220, 90);
    static final Color SHOP = new Color(255, 196, 60);
    static final Color GROUND_COLOR = new Color(120, 200, 255);
    static final Color DOT_EDGE = new Color(0, 50, 10, 230);
    static final Color LABEL_BACKGROUND = new Color(16, 16, 20, 215);
    static final Font LABEL_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 11);
    static final Color LINK = ColorScheme.GRAND_EXCHANGE_LIMIT;

    final MapView view;
    final Supplier<WorldData> world;
    final Card card;
    @Setter
    Function<WorldPoint, MapData.Place> places = point -> null;
    Result result;
    String failed;
    /** What the search failed to find, for its Wiki button. */
    String failedName;
    /** The results clicked through from (a drop, a dropper), for Back. */
    /** The results clicked through from, newest last, at most 20; Back takes the newest. */
    final Deque<Visit> history = new ArrayDeque<>();
    /** The tab shown of the current result (a kind of place, "drops", "droppers"); null for the first. */
    String tab;
    /** Which of a monster's drop tables the Drops tab shows. */
    int table;
    /** How the Shops tab is ordered ("nearest", "stock", "name"); null for nearest while the player is known, else stock. */
    String shopSort;
    /** How a drops table is ordered within its parts ("page", "rarity", "value"); kept from one search to the next. */
    String dropSort = "page";
    @Setter
    Prices prices = Prices.NONE;

    /** The Grand Exchange prices the game client knows ({@link ItemNames}). */
    interface Prices
    {
        Prices NONE = id -> -1;

        /** -1 while not known. */
        int price(int id);

        /** Looks up what is not known yet, then runs {@code done} on the Swing thread. */
        default void resolve(Collection<Integer> ids, Runnable done)
        {
        }
    }

    /** A result left by clicking through (a drop, a dropper), with the tab and drop table it showed. */
    @RequiredArgsConstructor
    static final class Visit
    {
        final Result result;
        final String tab;
        final int table;
    }

    SearchResults(MapView view, Supplier<WorldData> world, Card card)
    {
        this.view = view;
        this.world = world;
        this.card = card;
        view.addOverlay(this);
        view.hitLayers.add(this);
        filter.setAlignmentX(Component.LEFT_ALIGNMENT);
        filter.setToolTipText("Only the monsters whose names hold the words typed");
        FullMapWindow.typable(filter);
        // Escape empties it; once empty, the key is the window's (closing the map over the game).
        HintField.bind(filter, KeyEvent.VK_ESCAPE, "empty", () -> filter.setText(""), () -> !filter.getText().isEmpty());
        HintField.onEdit(filter, this::filtered);
    }

    /**
     * Filters the Dropped by list by name as one types: one field however often the panel is built, so the typing goes
     * on when a late answer builds it again ({@link #rebuild}).
     */
    final JTextField filter = new HintField(() -> "Filter by name");
    /** The Dropped by list as last built: the line saying none matches, then each row after the space above it. */
    JPanel listed = column();
    /** A Dropped by row's monster, kept on the row for the filter. */
    static final String NAMED = "monster";

    /** Typed in the filter: the rows that match show from the top; nothing else is built again. */
    void filtered()
    {
        filterRows();
        listed.scrollRectToVisible(new Rectangle(0, 0, 1, 1));
    }

    /** Shows the rows whose monster's name holds the words typed, each with the space above it, else that none does. */
    void filterRows()
    {
        var parts = listed.getComponents();
        boolean any = false;
        for (int i = 2; i < parts.length; i += 2)
        {
            boolean shown = matches((String) ((JComponent) parts[i]).getClientProperty(NAMED), filter.getText());
            parts[i - 1].setVisible(shown);
            parts[i].setVisible(shown);
            any |= shown;
        }
        if (parts.length > 0)
        {
            parts[0].setVisible(!any);
        }
    }

    /** Whether {@code name} holds every word typed, in any letters and order: "gi fire" finds "Fire giant". Pure. */
    static boolean matches(String name, String typed)
    {
        String lower = name.toLowerCase(Locale.ROOT);
        return Arrays.stream(typed.toLowerCase(Locale.ROOT).trim().split("\\s+")).allMatch(lower::contains);
    }

    /**
     * Runs {@code action} (building a panel again, opening a menu) so that it never takes focus from the game: a
     * {@code field} being typed in keeps the keys, also where it is shown again.
     */
    static void keepFocus(JComponent field, Runnable action)
    {
        boolean typing = field.isFocusOwner();
        action.run();
        if (typing)
        {
            field.requestFocusInWindow();
        }
    }

    @Setter
    Consumer<Tour.Stop> stopAdder;
    @Setter
    NpcPictures npcPictures = new NpcPictures((id, done) -> done.accept(null));
    @Setter
    BiConsumer<Integer, JLabel> itemPictures = (id, label) -> { };

    @Setter
    Consumer<List<WorldPoint>> fastest;

    /**
     * What to call a place of the search: the map it is shown on ({@link #mapOf}) when that is a dungeon's, so the name
     * and the map agree (the Brimhaven Dungeon, not the Ardent Ocean Underground around it); else the map's naming.
     */
    MapData.Place placeOf(WorldPoint point)
    {
        var maps = view.maps();
        var map = maps == null ? null : world.get().drawnBy(maps).get(point);
        return map != null && map.id != BaseMap.SURFACE && map.id != BaseMap.FULL ? MapScreen.mapPlace(map, point)
            : places.apply(point);
    }

    void findMonster(String name)
    {
        findMonster(name, null);
    }

    /** The monster, its Drops tab on the table named {@code table} (a dropper's: the version dropping the item). */
    void findMonster(String name, String table)
    {
        var found = world.get().spawns(name);
        Result shown = found == null ? null : monsterResult(found, this::placeOf, view.near());
        answer(shown, "No places of \"" + name + "\" are known.", name,
            shown == null ? 0 : tableNamed(shown.tables, table));
    }

    /** Which of a monster's drop tables has this name; the first when none has, or for null. Pure. */
    static int tableNamed(List<WorldData.Table> tables, String name)
    {
        for (int i = 0; i < tables.size(); i++)
        {
            if (tables.get(i).name.equals(name))
            {
                return i;
            }
        }
        return 0;
    }

    /** What a search for {@code name} found, on its drop table {@code table}, else {@code none}: why nothing shows. */
    void answer(Result found, String none, String name, int table)
    {
        if (found != null)
        {
            if (result != null && result != found)
            {
                history.addLast(new Visit(result, tab, this.table));
                if (history.size() > 20)
                {
                    history.removeFirst();
                }
            }
            show(found, null, table);
            return;
        }
        result = null;
        tab = null;
        failed = none;
        failedName = name;
        refresh();
    }

    /** A monster's places by name, nearest first, each with how many stand there at once. Pure. */
    static Result monsterResult(NpcSpawns found, Function<WorldPoint, MapData.Place> places, WorldPoint player)
    {
        var groups = named(found.groups, places, "Elsewhere");
        Result shown = new Result(found.page, found.page, "In " + places(groups.size()) + ", marked with green arrows"
            + (player != null ? ", nearest first" : "") + ". Click a place to see it; its card has the way there.",
            nearestFirst(groups, player), null);
        shown.picture = found.npc;
        shown.drops = found.drops;
        shown.tables = found.tables;
        return shown;
    }

    /**
     * The groups under the names of their places ({@code unnamed} where no place is known; "" keeps the group's own
     * words): places of one name say which side of it they are, an upper floor says so, else the same side is
     * numbered. Pure.
     */
    static List<Group> named(List<Group> found, Function<WorldPoint, MapData.Place> places,
        String unnamed)
    {
        var known = new ArrayList<MapData.Place>();
        var uses = new HashMap<String, Integer>();
        for (var group : found)
        {
            var place = places.apply(group.center());
            known.add(place);
            if (place != null)
            {
                uses.merge(place.name, 1, Integer::sum);
            }
        }
        var groups = new ArrayList<Group>();
        var numbered = new HashMap<String, Integer>();
        for (int i = 0; i < found.size(); i++)
        {
            var group = found.get(i);
            var place = known.get(i);
            String name = place == null ? unnamed : place.name;
            if (name.isEmpty())
            {
                groups.add(group);
                continue;
            }
            if (place != null && uses.get(place.name) > 1 && !place.point.equals(group.center()))
            {
                name += ", " + MapScreen.compass(place.point, group.center());
            }
            int floor = group.center().getPlane();
            int n = numbered.merge(name + ":" + floor, 1, Integer::sum);
            groups.add(group.at(floor > 0 && numbered.containsKey(name + ":0") ? name + ", upstairs"
                : n > 1 ? name + " (" + n + ")" : name));
        }
        return groups;
    }

    void findItem(String name)
    {
        var found = world.get().item(name);
        answer(found == null ? null : itemResult(found, this::placeOf, view.near()),
            "Nothing known about \"" + name + "\": no shop, ground spawn or drop.", name, 0);
    }

    void showKind(KindIndex.Kind kind, Function<WorldPoint, String> placeName)
    {
        var groups = kindGroups(kind, placeName, view.near());
        Result shown = new Result(kind.label, kind.page, places(groups.size()) + ", marked with green arrows" + (view.near() != null ? ", nearest first" : "") + ". Click one to go there.",
            groups, kind.type == null ? "Skilling spots: RuneLite (BSD 2-Clause)" : null);
        shown.kind = kind.label;
        show(shown);
    }

    /** A kind's places, those close together in one town merged ("Catherby, 4 spots"). */
    static List<Group> kindGroups(KindIndex.Kind kind, Function<WorldPoint, String> placeName, WorldPoint player)
    {
        var groups = new ArrayList<Group>();
        entries:
        for (var entry : kind.entries)
        {
            String place = Objects.requireNonNullElse(placeName.apply(entry.point), "");
            String name = kind.type == null && !place.isEmpty() ? place : entry.name;
            for (var group : groups)
            {
                var first = group.points.get(0);
                if (!place.isEmpty() && group.location.equals(place) && group.name.equals(name)
                    // Spots 48 tiles apart or closer on one floor, one after another, are one place.
                    && first.distanceTo(entry.point) <= 48)
                {
                    group.points.add(entry.point);
                    continue entries;
                }
            }
            var group = new Group(name, place,
                new ArrayList<>(Collections.singletonList(entry.point)), null, entry.detail == null ? "" : entry.detail,
                null);
            group.poi = entry.poi;
            groups.add(group);
        }
        groups.replaceAll(g -> {
            int n = g.points.size();
            return n > 1 ? g.withNote(n + " spots" + (g.note.isEmpty() ? "" : " · " + g.note)) : g;
        });
        return nearestFirst(groups, player);
    }

    /**
     * Where an item comes from: the shops (gold arrows) and the spots on the ground (blue), each under the name of its
     * place, nearest first. Pure.
     */
    static Result itemResult(ItemSources found, Function<WorldPoint, MapData.Place> places, WorldPoint player)
    {
        var shops = new ArrayList<Group>();
        for (var store : found.stores)
        {
            var shop = new Group(store.shop, "", Collections.singletonList(store.point), SHOPS,
                ItemSources.stockText(store.stock), SHOP);
            shop.stock = store.stock;
            shops.add(shop);
        }
        var grounds = new ArrayList<Group>();
        for (var ground : found.grounds)
        {
            var group = new Group(found.page, "", Collections.singletonList(ground.point), GROUND,
                ground.count + " here", GROUND_COLOR);
            group.seen = ground.count;
            grounds.add(group);
        }
        var parts = new ArrayList<String>();
        if (!shops.isEmpty())
        {
            parts.add("sold in " + plural(shops.size(), "shop"));
        }
        if (!grounds.isEmpty())
        {
            parts.add("lying in " + places(grounds.size()));
        }
        if (!found.droppers.isEmpty())
        {
            parts.add("dropped by " + plural(found.droppers.size(), "monster"));
        }
        String summary = Character.toUpperCase(parts.get(0).charAt(0)) + String.join(", ", parts).substring(1)
            + (shops.isEmpty() && grounds.isEmpty() ? "." : ": marked on the map" + (player != null ? ", nearest first"
            : "") + ". Click a place to see it.");
        var groups = new ArrayList<Group>(nearestFirst(named(shops, places, ""), player));
        groups.addAll(nearestFirst(named(grounds, places, ""), player));
        Result shown = new Result(found.page, found.page, summary, groups, null);
        shown.item = found.item;
        var droppers = new ArrayList<ItemSources.Dropper>(found.droppers);
        droppers.sort(Comparator.comparingDouble((ItemSources.Dropper d) -> rarity(d.rarity)).thenComparing(d -> d.name));
        shown.droppers = droppers;
        return shown;
    }

    /** How often a drop comes, as a number to sort by: always first, then by chance, then by its words. */
    static double rarity(String words)
    {
        String w = words.toLowerCase(Locale.ROOT);
        Matcher fraction = FRACTION.matcher(w);
        if (fraction.find())
        {
            double chance = Double.parseDouble(fraction.group(1)) / Double.parseDouble(fraction.group(2));
            return chance > 0 ? -chance : 0;
        }
        if (w.startsWith("always"))
        {
            return -1;
        }
        // The words, as the chances they stand for, roughly.
        String[] kinds = {"very common", "common", "uncommon", "very rare", "rare"};
        double[] chances = {1 / 4.0, 1 / 10.0, 1 / 50.0, 1 / 5000.0, 1 / 500.0};
        for (int i = 0; i < kinds.length; i++)
        {
            if (w.startsWith(kinds[i]))
            {
                return -chances[i];
            }
        }
        return 1;
    }

    static List<Group> nearestFirst(List<Group> groups, WorldPoint player)
    {
        var sorted = new ArrayList<Group>(groups);
        if (player != null)
        {
            sorted.sort(Comparator.comparingLong(g -> distance(g.center(), player)));
        }
        return sorted;
    }

    static String places(int n)
    {
        return plural(n, "place");
    }

    static String plural(int n, String thing)
    {
        return n + " " + thing + (n == 1 ? "" : "s");
    }

    static long distance(WorldPoint a, WorldPoint b)
    {
        long dx = a.getX() - b.getX();
        long dy = a.getY() - b.getY();
        return dx * dx + dy * dy;
    }

    void refresh()
    {
        keepFocus(filter, () -> card.show(this::section));
        view.repaint();
    }

    void show(Result found)
    {
        show(found, null, 0);
    }

    /** Shows a result on {@code tab} (null: its first) and, for a monster, on its drop table {@code table}. */
    void show(Result found, String tab, int table)
    {
        filter.setText("");
        resetFound();
        foundPois.clear();
        result = found;
        this.tab = tab;
        this.table = table;
        // The place clicked before is no longer what is shown. The map stays: a place is gone to by a click.
        view.select(null);
        refresh();
        askPrices(found);
    }

    /** Asks the game for the prices of what the result shows, and shows them when they come. */
    void askPrices(Result found)
    {
        var ids = new HashSet<Integer>();
        if (found.item >= 0)
        {
            ids.add(found.item);
        }
        found.drops.forEach(drop -> ids.add(drop.item));
        found.tables.forEach(table -> table.drops.forEach(drop -> ids.add(drop.item)));
        if (!ids.isEmpty())
        {
            prices.resolve(ids, () -> {
                if (result == found)
                {
                    keepFocus(filter, () -> card.update(this::section));
                }
            });
        }
    }

    void clear()
    {
        result = null;
        resetFound();
        history.clear();
        card.show(null);
        view.repaint();
    }

    /** Forgets the caches a shown result fills (tags, centers, per-group lookups) and any failure message. */
    void resetFound()
    {
        failed = null;
        failedName = null;
        tags.clear();
        centers.clear();
        groupBounds.clear();
        groupMaps.clear();
    }

    /** Whether no map draws this place: going there would show only black. */
    boolean undrawn(Group group)
    {
        return mapOf(group) == null;
    }

    void look(Group group)
    {
        var map = mapOf(group);
        if (map == null)
        {
            return;
        }
        view.setFollowing(false);
        view.rememberForBack(map);
        // Where the map draws it: a place drawn elsewhere (Dagannoth Kings' lair) would otherwise land in a corner.
        view.showMap(map, MapView.shownOn(map, standing(group.center(), view.ground())), max(view.targetZoom(), 2));
        view.select(iconOf(group, map));
    }

    Poi iconOf(Group group, BaseMap map)
    {
        if (group.poi != null)
        {
            return group.poi;
        }
        var c = standing(group.center(), view.ground());
        boolean shop = SHOPS.equals(group.category);
        return view.searchExtras().stream().filter(poi -> shop && poi.type == PoiType.SHOP
            && poi.location.distanceTo(c) <= WorldData.SHOP_RADIUS)
            .min(Comparator.comparingInt(poi -> poi.location.distanceTo2D(c))).orElseGet(() -> foundPois.computeIfAbsent(group, g -> {
            String title = result == null ? g.name : result.title;
            String name = placeName(g, title);
            String note = dotted(g.note);
            String page = shop ? g.name : result != null && result.page != null ? result.page : g.name;
            return new Poi(shop ? PoiType.SHOP : PoiType.FOUND, name.equals(title) || shop ? name : title + ": " + name,
                c, map, null, Needs.NONE, page, null, note.isEmpty() ? null : note);
        }));
    }

    /** One per place of the result shown, so a click and a hover pick the same. */
    final Map<Group, Poi> foundPois = new IdentityHashMap<>();

    /** A place's arrows on the map: clicked, the place is selected, and the map shows the way there. */
    public Poi hit(Point point, Projection projection)
    {
        Result shown = result;
        var viewMap = projection.map();
        if (shown == null || viewMap == null)
        {
            return null;
        }
        double r = arrowRadius(projection.zoom());
        for (var group : shown.groups)
        {
            var map = mapOf(group);
            if (map == null || viewMap.id != BaseMap.FULL && map != viewMap)
            {
                continue;
            }
            var first = group.points.get(0);
            var moved = projection.shown(first);
            for (var p : group.points)
            {
                double x = projection.screenX(p.getX() + moved.getX() - first.getX() + 0.5);
                double y = projection.screenY(p.getY() + moved.getY() - first.getY() + 0.5) - r;
                if (hypot(point.x - x, point.y - y) <= r * 2)
                {
                    return iconOf(group, map);
                }
            }
        }
        return null;
    }

    /** Arrows grow a little when zoomed in, so a spawn tile stays easy to spot. */
    static double arrowRadius(double zoom)
    {
        return zoom < -1 ? 3 : zoom < 2 ? 4.5 : 4.5 + min(4, (zoom - 2) * 1.5);
    }

    void lookAtPoint(WorldPoint at)
    {
        if (result != null && at != null)
        {
            result.groups.stream().filter(group -> group.points.contains(at)).findFirst().ifPresent(this::look);
        }
    }

    /** Each place's map, worked out once per result and maps, not in every frame. */
    final Map<Group, Optional<BaseMap>> groupMaps = new IdentityHashMap<>();
    Map<WorldPoint, BaseMap> groupMapsFor;
    BaseMaps groupMapsFrom;

    /** The map that draws a place: where maps overlap as our map server worked it out ({@link WorldData#drawnBy}). */
    BaseMap mapOf(Group group)
    {
        var maps = view.maps();
        var placeMaps = world.get().drawnBy(maps);
        if (groupMapsFor != placeMaps || groupMapsFrom != maps)
        {
            groupMaps.clear();
            groupMapsFor = placeMaps;
            groupMapsFrom = maps;
        }
        return groupMaps.computeIfAbsent(group, g -> Optional.ofNullable(mapOf(g, maps, placeMaps, view.ground())))
            .orElse(null);
    }

    final Map<Group, int[]> groupBounds = new IdentityHashMap<>();

    int[] bounds(Group group)
    {
        return groupBounds.computeIfAbsent(group, g -> {
            int[] b = {Integer.MAX_VALUE, Integer.MAX_VALUE, Integer.MIN_VALUE, Integer.MIN_VALUE};
            for (var p : g.points)
            {
                b[0] = min(b[0], p.getX());
                b[1] = min(b[1], p.getY());
                b[2] = max(b[2], p.getX());
                b[3] = max(b[3], p.getY());
            }
            return b;
        });
    }

    /**
     * The map a place is shown on: the map server's answer for its spot, or where one stands there on another floor
     * ({@link #standing}) the map showing a player standing there.
     */
    static BaseMap mapOf(Group group, BaseMaps maps, Map<WorldPoint, BaseMap> placeMaps,
        Predicate<WorldPoint> ground)
    {
        if (maps == null)
        {
            return null;
        }
        var c = group.center();
        var at = standing(c, ground);
        return at.equals(c) && placeMaps.containsKey(c) ? placeMaps.get(c) : maps.find(at);
    }

    /**
     * Where one stands at a place: its spot, or beside it on its floor (a counter, a tree), else the nearest floor there
     * that is ground. A place's floor is given as its map draws it: the Brimhaven Dungeon's raised paths on floor
     * 1, walked on floor 2.
     */
    static WorldPoint standing(WorldPoint p, Predicate<WorldPoint> ground)
    {
        if (ground == null || groundNear(p, ground))
        {
            return p;
        }
        for (int d = 1; d < 4; d++)
        {
            for (int floor : new int[]{p.getPlane() + d, p.getPlane() - d})
            {
                var other = new WorldPoint(p.getX(), p.getY(), floor);
                if (floor >= 0 && floor < 4 && groundNear(other, ground))
                {
                    return other;
                }
            }
        }
        return p;
    }

    /** Ground at the spot or within two tiles of it, on its floor. */
    static boolean groundNear(WorldPoint p, Predicate<WorldPoint> ground)
    {
        for (int dx = -2; dx <= 2; dx++)
        {
            for (int dy = -2; dy <= 2; dy++)
            {
                if (ground.test(new WorldPoint(p.getX() + dx, p.getY() + dy, p.getPlane())))
                {
                    return true;
                }
            }
        }
        return false;
    }

    /** The corners after the tip, in radii: right, up. */
    static final double[][] ARROW = {{-1.2, 1.4}, {-0.45, 1.4}, {-0.45, 2.6}, {0.45, 2.6}, {0.45, 1.4},
        {1.2, 1.4}};

    static Path2D arrow(double x, double y, double r)
    {
        var arrow = new Path2D.Double();
        arrow.moveTo(x, y);
        for (var corner : ARROW)
        {
            arrow.lineTo(x + r * corner[0], y - r * corner[1]);
        }
        arrow.closePath();
        return arrow;
    }

    static BufferedImage dotIcon()
    {
        return PoiIcons.sprite(14, 14, 1, g -> paintArrow(g, arrow(7, 13, 4.4), DOT, new BasicStroke()));
    }

    /** A magnifying glass: searching everything. */
    static BufferedImage allIcon()
    {
        return PoiIcons.sprite(14, 14, 1, g -> {
            g.setColor(new Color(230, 230, 230));
            g.setStroke(new BasicStroke(1.8f));
            g.drawOval(1, 1, 8, 8);
            g.drawLine(8, 8, 12, 12);
        });
    }

    static BufferedImage itemIcon()
    {
        return PoiIcons.sprite(14, 14, 1, g -> {
            g.setColor(SHOP);
            g.fill(new Ellipse2D.Double(1.5, 4.5, 11, 9));
            g.fill(new Rectangle2D.Double(5, 2, 4, 4));
            g.setColor(new Color(90, 60, 10));
            g.setStroke(new BasicStroke(1f));
            g.draw(new Ellipse2D.Double(1.5, 4.5, 11, 9));
            g.draw(new Line2D.Double(4.5, 5, 9.5, 5));
        });
    }

    static void paintArrow(Graphics2D g, Path2D arrow, Color fill, BasicStroke edge)
    {
        g.setColor(fill);
        g.fill(arrow);
        g.setColor(DOT_EDGE);
        g.setStroke(edge);
        g.draw(arrow);
    }

    /** A result's panel: the header (title, summary, buttons, tabs, sort) kept in view, the list below it scrolling. */
    JComponent section(int width)
    {
        JPanel header = column();
        if (result == null)
        {
            header.add(grey(failed != null ? failed : "Nothing found.", width));
            // Buttons may reach past the text's width: HTML text comes out wider than asked.
            add(header, 6, wrapLabels(buttons(failedName), 4, width + 70));
            return header;
        }
        if (!history.isEmpty())
        {
            Visit back = history.peekLast();
            add(header, 0, link("← Back to " + back.result.title, () -> {
                history.pollLast();
                show(back.result, back.tab, back.table);
            }, width));
            header.add(Box.createVerticalStrut(4));
        }
        var title = heading(result.title, width - 70);
        if (result.picture >= 0)
        {
            header.add(pictureRow(pictureLabel(result.picture, NpcPictures.LARGE), title));
        }
        else if (result.item >= 0)
        {
            JLabel icon = pictureIcon(PICTURE);
            itemPictures.accept(result.item, icon);
            header.add(pictureRow(icon, title));
        }
        else
        {
            header.add(title);
        }
        header.add(grey(result.summary, width));
        int price = result.item >= 0 ? prices.price(result.item) : -1;
        if (price >= 0)
        {
            header.add(grey("Grand Exchange " + gp(price), width));
        }
        add(header, 6, wrapLabels(buttons(result.page), 4, width + 70));
        var tabs = tabs();
        if (tabs.isEmpty())
        {
            return header;
        }
        String shown = tabs.stream().map(t -> t[0]).filter(key -> key.equals(tab)).findFirst().orElse(tabs.get(0)[0]);
        var labels = new ArrayList<JComponent>();
        for (var t : tabs)
        {
            boolean active = t[0].equals(shown);
            JLabel label = optionLabel(t[1], active);
            label.setBorder(BorderFactory.createMatteBorder(0, 0, 2, 0, active ? Color.WHITE : new Color(0, 0, 0, 0)));
            labels.add(clickable(label, () -> {
                tab = t[0];
                refresh();
            }, !active));
        }
        add(header, 8, wrapLabels(labels, 12, width));
        JPanel body = column();
        if (shown.equals("drops"))
        {
            dropsTab(header, body, width);
        }
        else if (shown.equals("droppers"))
        {
            droppersTab(header, body, width);
        }
        else
        {
            placesTab(shown, header, body, width);
        }
        if (result.credit != null)
        {
            add(body, 10, grey(result.credit, width));
        }
        return new Sections(header, body);
    }

    /** The tabs of the result shown, {key, label}: places by kind (a monster's all as "Locations"), drops, droppers. */
    List<String[]> tabs()
    {
        var counts = new LinkedHashMap<String, Integer>();
        result.groups.forEach(g -> counts.merge(category(g), 1, Integer::sum));
        var tabs = new ArrayList<String[]>();
        counts.forEach((category, n) -> tabs.add(new String[]{category, category + " (" + n + ")"}));
        var drops = shownDrops();
        if (!drops.isEmpty())
        {
            tabs.add(new String[]{"drops", "Drops (" + drops.size() + ")"});
        }
        if (!result.droppers.isEmpty())
        {
            tabs.add(new String[]{"droppers", "Dropped by (" + result.droppers.size() + ")"});
        }
        return tabs;
    }

    static String category(Group group)
    {
        return group.category == null ? "Locations" : group.category;
    }

    /** Which of the page's drop tables is chosen. */
    int chosenTable()
    {
        return min(table, max(0, result.tables.size() - 1));
    }

    List<Drop> shownDrops()
    {
        return result.tables.isEmpty() ? result.drops : result.tables.get(chosenTable()).drops;
    }

    /** The Drops tab: the table chosen, its order, then the drops under the parts of the page. */
    void dropsTab(JPanel header, JPanel body, int width)
    {
        if (result.tables.size() > 1)
        {
            add(header, 6, versions(result.tables, chosenTable(), width));
        }
        add(header, 6, choice(new String[][]{{"page", "Page order"}, {"rarity", "Rarity"}, {"value", "Value"}},
            dropSort, sort -> {
                dropSort = sort;
                refresh();
            }, width));
        var drops = dropOrder(shownDrops(), dropSort, prices::price);
        // 100%, the main table, the rare drop table, tertiary.
        String[][] parts = {{"a", "100%"}, {"", "Main drops"}, {"r", "Rare drop table"}, {"t", "Tertiary"}};
        for (var part : parts)
        {
            boolean first = true;
            for (var drop : drops)
            {
                if (!drop.part.equals(part[0]))
                {
                    continue;
                }
                if (first)
                {
                    add(body, 8, heading(part[1], width));
                    first = false;
                }
                JLabel icon = pictureIcon(PICTURE);
                itemPictures.accept(drop.item, icon);
                long value = value(prices.price(drop.item), drop.quantity);
                Runnable open = () -> findItem(drop.name);
                add(body, 3, clickableRow(pictureRow(icon, bold(link(drop.name, open, width - PICTURE - 8)),
                    grey(dotted(drop.rarity, drop.quantity, value >= 0 ? "GE " + gp(value) : null, drop.version),
                        width - PICTURE - 8)), open));
            }
        }
    }

    /** A list of more droppers than this gets a filter by name. */
    static final int FILTERED = 10;

    /**
     * The Dropped by tab: each monster with its picture, how often and many, and in how many places it stands; a long
     * list with a filter by name above it.
     */
    void droppersTab(JPanel header, JPanel body, int width)
    {
        if (result.droppers.size() > FILTERED)
        {
            filter.setPreferredSize(new Dimension(width, filter.getPreferredSize().height));
            filter.setMaximumSize(filter.getPreferredSize());
            add(header, 6, filter);
        }
        listed = column();
        listed.add(grey("No monster of that name drops it.", width));
        int shown = 0;
        for (var dropper : result.droppers)
        {
            // The first 1000 droppers get their picture, each asked of the map server once its row is in view, then
            // kept on disk.
            JLabel icon = shown++ < 1000 ? pictureLabel(dropper.npc, PICTURE) : pictureIcon(PICTURE);
            Runnable open = () -> findMonster(dropper.name, dropper.table);
            int w = width - PICTURE - 8;
            JPanel row = pictureRow(icon, bold(link(dropper.name, open, w)), grey(dotted(dropper.rarity,
                dropper.quantity, places(dropper.places), dropper.version), w));
            row.putClientProperty(NAMED, dropper.name);
            add(listed, 3, clickableRow(row, open));
        }
        body.add(listed);
        filterRows();
    }

    /** A tab of places: shops in the order chosen, the rest as the result lists them. */
    void placesTab(String shown, JPanel header, JPanel body, int width)
    {
        var groups = result.groups.stream().filter(g -> shown.equals(category(g)))
            .collect(Collectors.toList());
        if (shown.equals(SHOPS))
        {
            String sort = shopSort != null ? shopSort : view.near() != null ? "nearest" : "stock";
            add(header, 6, choice(new String[][]{{"nearest", "Nearest"}, {"stock", "Stock"}, {"name", "Name"}}, sort,
                pick -> {
                    shopSort = pick;
                    refresh();
                }, width));
            groups.sort(shopOrder(sort, view.near(), result.title));
        }
        for (int i = 0; i < groups.size(); i++)
        {
            add(body, i == 0 ? 4 : 3, place(groups.get(i), width));
        }
    }

    /**
     * Shops in the order chosen: "nearest" the player (as listed, without one), "stock" fullest first, "name" by the
     * shop's, as the list names it.
     */
    static Comparator<Group> shopOrder(String sort, WorldPoint player, String title)
    {
        var byName = Comparator.comparing((Group g) -> placeName(g, title),
            String.CASE_INSENSITIVE_ORDER);
        switch (sort)
        {
            case "stock":
                return (a, b) -> {
                    int byStock = ItemSources.byStock(a.stock, b.stock);
                    return byStock != 0 ? byStock : byName.compare(a, b);
                };
            case "name":
                return byName;
            default:
                return player == null ? (a, b) -> 0 : Comparator.comparingLong(g -> distance(g.center(), player));
        }
    }

    /** Drops in the order chosen: "page" as listed, "rarity" surest first, "value" dearest first. */
    static List<Drop> dropOrder(List<Drop> drops, String sort, IntUnaryOperator price)
    {
        var sorted = new ArrayList<Drop>(drops);
        var byName = Comparator.comparing((Drop d) -> d.name, String.CASE_INSENSITIVE_ORDER);
        if (sort.equals("rarity"))
        {
            sorted.sort(Comparator.comparingDouble((Drop d) -> rarity(d.rarity)).thenComparing(byName));
        }
        else if (sort.equals("value"))
        {
            sorted.sort(Comparator.comparingLong((Drop d) -> {
                long value = value(price.applyAsInt(d.item), d.quantity);
                return value < 0 ? Long.MAX_VALUE : -value;
            }).thenComparing(byName));
        }
        return sorted;
    }

    static final Pattern NUMBER = Pattern.compile("\\d{1,9}");

    /**
     * What a drop is worth at the Grand Exchange: the price times the least that drops ("5-10": five); -1 while the
     * price is not known.
     */
    static long value(int price, String quantity)
    {
        if (price < 0)
        {
            return -1;
        }
        Matcher number = NUMBER.matcher(quantity);
        return price * (number.find() ? Long.parseLong(number.group()) : 1);
    }

    /** "1,234 gp". */
    static String gp(long amount)
    {
        return String.format(Locale.ROOT, "%,d gp", amount);
    }

    /** The choice of a monster's drop table: its versions (the Wilderness Slayer Cave), loot that is not a drop. */
    JComboBox<String> versions(List<WorldData.Table> tables, int chosen, int width)
