    /** The second line of a row, the summary: lighter than the names, still easy to read. */
    static final Color SOFT = new Color(205, 205, 210);

    static JLabel grey(String text, int width)
    {
        return text(text, SOFT, false, width);
    }

    /** A list's heading. */
    static JLabel heading(String text, int width)
    {
        return text(text, Color.WHITE, true, width);
    }

    /** A list's line: {@code bold} one point larger, a pixel of space above and below. */
    static JLabel text(String text, Color color, boolean bold, int width)
    {
        JLabel label = text(text, color, bold ? Font.BOLD : Font.PLAIN, bold ? 1 : 0, width);
        label.setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 0));
        return label;
    }

    /** Text in {@code style} ({@link Font#BOLD} or plain), {@code larger} points above the usual size. */
    static JLabel text(String text, Color color, int style, float larger, int width)
    {
        JLabel label = new JLabel();
        // Font and colour before the text: changing either makes an HTML label parse its text again.
        if (style != Font.PLAIN || larger != 0)
        {
            label.setFont(label.getFont().deriveFont(style, label.getFont().getSize2D() + larger));
        }
        label.setForeground(color);
        label.setAlignmentX(Component.LEFT_ALIGNMENT);
        return setText(label, text, width);
    }

    /**
     * HTML labels wrap, but are slow to build: plain wherever the text fits on one line, else wrapped at {@code width}.
     * Plain text is never read as HTML (a name may start with {@code <html>}); a label set again may switch between them.
     */
    static JLabel setText(JLabel label, String text, int width)
    {
        boolean plain = text.indexOf('\n') < 0 && label.getFontMetrics(label.getFont()).stringWidth(text) <= width;
        label.putClientProperty("html.disable", plain ? Boolean.TRUE : null);
        label.setText(plain ? text : "<html><div style='width:" + width + "px'>" + InfoCard.escape(text) + "</div></html>");
        return label;
    }

    static JLabel link(String text, Runnable action, int width)
    {
        return clickable(text(text, LINK, false, width), action, true);
    }

    /** A label that runs {@code action} when clicked; {@code hover}: a link that turns white under the mouse. */
    static JLabel clickable(JLabel label, Runnable action, boolean hover)
    {
        clickableRow(label, action);
        if (hover)
        {
            label.addMouseListener(new MouseAdapter()
            {
                public void mouseEntered(MouseEvent e)
                {
                    label.setForeground(Color.WHITE);
                }

                public void mouseExited(MouseEvent e)
                {
                    label.setForeground(LINK);
                }
            });
        }
        return label;
    }

    static final BasicStroke EDGE = new BasicStroke(1.2f);
    final Map<Group, WorldPoint> centers = new IdentityHashMap<>();

    /**
     * Arrows and each place's label as pictures made once: drawing hundreds of shapes and texts every frame was slow.
     * Labels for {@link #tagsDevice}; a label's colour follows from its place.
     */
    final Map<Group, BufferedImage> tags = new IdentityHashMap<>();
    double tagsDevice;
    final Map<Long, BufferedImage> arrows = new HashMap<>();

    static void cap(Map<?, ?> cache, int max)
    {
        if (cache.size() > max)
        {
            cache.clear();
        }
    }

    BufferedImage arrowSprite(Color fill, double r, double device)
    {
        long key = (long) fill.getRGB() << 32 | (round(r * 4) & 0xffffL) << 16 | round(device * 10) & 0xffffL;
        cap(arrows, 500);
        return arrows.computeIfAbsent(key, k -> {
            double w = r * 2.4 + 4;
            double h = r * 2.6 + 4;
            return PoiIcons.sprite(w, h, device, g -> paintArrow(g, arrow(w / 2, h - 2, r), fill, EDGE));
        });
    }

    static BufferedImage labelSprite(String label, Color color, FontMetrics metrics, double device)
    {
        int width = metrics.stringWidth(label) + 10;
        int height = metrics.getHeight() + 2;
        return PoiIcons.sprite(width + 2, height + 2, device, g -> {
            g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            g.setFont(LABEL_FONT);
            var box = new RoundRectangle2D.Double(1, 1, width, height, 8, 8);
            g.setColor(LABEL_BACKGROUND);
            g.fill(box);
            g.setColor(color);
            g.draw(box);
            g.setColor(Color.WHITE);
            MapView.text(g, label, 6, 1 + metrics.getHeight() - metrics.getDescent());
        });
    }

    static final Map<Color, Color> FADED = new ConcurrentHashMap<>();

    public void paint(Graphics2D g, Projection projection)
    {
        Result shown = result;
        var viewMap = projection.map();
        if (shown == null || viewMap == null)
        {
            return;
        }
        double zoom = projection.zoom();
        double r = arrowRadius(zoom);
        g.setFont(LABEL_FONT);
        var metrics = g.getFontMetrics();
        double device = max(1, min(4, abs(g.getTransform().getScaleX())));
        cap(groupBounds, 5000);
        cap(tags, device != tagsDevice ? -1 : 5000);
        tagsDevice = device;
        for (var group : shown.groups)
        {
            var b = bounds(group);
            // A place the map draws elsewhere (the Kalphite Lair, the Brimhaven Dungeon's raised paths) moves as its first
            // point does, on the floor one stands on there.
            var first = standing(group.points.get(0), view.ground());
            var moved = projection.shown(first);
            int dx = moved.getX() - first.getX();
            int dy = moved.getY() - first.getY();
            double left = projection.screenX(b[0] + dx);
            double right = projection.screenX(b[2] + 1 + dx);
            double top = projection.screenY(b[3] + 1 + dy);
            double bottom = projection.screenY(b[1] + dy);
            if (right < -150 || left > projection.width() + 150 || bottom < -20 || top > projection.height() + 60)
            {
                continue;
            }
            var map = mapOf(group);
            if (map == null || viewMap.id != BaseMap.FULL && map != viewMap)
            {
                continue;
            }
            Color color = group.color != null ? group.color : DOT;
            Color fill = moved.getPlane() != projection.plane()
                ? FADED.computeIfAbsent(color, c -> RouteFeature.alpha(c, 110)) : color;
            BufferedImage arrow = arrowSprite(fill, r, device);
            double half = arrow.getWidth() / device / 2;
            double tall = arrow.getHeight() / device - 2;
            for (var p : group.points)
            {
                double x = projection.screenX(p.getX() + dx + 0.5);
                double y = projection.screenY(p.getY() + dy + 0.5);
                if (x < -r * 2 || y < -r || x > projection.width() + r * 2 || y > projection.height() + r * 3)
                {
                    continue;
                }
                PoiIcons.blit(g, arrow, x - half, y - tall);
            }
            if (zoom < -1.5)
            {
                continue;
            }
            cap(centers, 5000);
            var c = centers.computeIfAbsent(group, Group::center);
            double x = projection.screenX(c.getX() + dx + 0.5);
            double y = projection.screenY(c.getY() + dy + 0.5) - r * 3 - 4;
            BufferedImage tag = tags.computeIfAbsent(group, k -> labelSprite(tag(group), color, metrics, device));
            double width = tag.getWidth() / device;
            if (x + width / 2.0 < 0 || x - width / 2.0 > projection.width() || y < -20 || y > projection.height() + 20)
            {
                continue;
            }
            PoiIcons.blit(g, tag, x - width / 2.0 - 1, y - metrics.getHeight() - 1);
        }
    }
}

package com.hdmapreforged;

import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import java.util.regex.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.client.util.*;

/**
 * The map server's files kept on disk once seen, under the plugin's folder: the lists of a data version, and a map
 * version's map list, region table and places, and NPC pictures. A player asks the server for each file once; when
 * another version of a kind comes into use, the old version's folder goes.
 */
@Slf4j
@RequiredArgsConstructor
final class ServerCache
{
    static final Pattern NAME = Pattern.compile("[A-Za-z0-9_.-]{1,64}");
    static final Pattern KIND = Pattern.compile("[a-z]{1,16}");
    static final int MAX_BYTES = 16 * 1024 * 1024;

    final Filepath root;
    final ExecutorService io;
    /** Each kind's version in use, whose folder alone is kept. */
    final Map<String, String> inUse = new ConcurrentHashMap<>();
    /** Files (kind/version/name) whose kept copy is passed over until the server sends its own. */
    final Set<String> stale = ConcurrentHashMap.newKeySet();

    /**
     * A file's bytes: from disk when seen before, else from {@code fetch}, which asks the server and hands the bytes
     * (null when there are none) to the consumer it is given; they are kept for next time. Any thread; {@code done}
     * is called once, on any thread, with null when there are no bytes.
     */
    void bytes(String kind, String version, String name, Consumer<Consumer<byte[]>> fetch, Consumer<byte[]> done)
    {
        var file = file(kind, version, name);
        if (file == null || !later(() -> {
            String key = kind + "/" + version + "/" + name;
            var kept = stale.contains(key) ? null : read(file);
            if (kept != null)
            {
                done.accept(kept);
                prune(kind, version);
                return;
            }
            fetch.accept(bytes -> {
                if (bytes != null)
                {
                    // Passed over until the server's copy comes, so a version is never half old copies, half new.
                    stale.remove(key);
                    later(() -> keep(kind, version, file, bytes));
                }
                done.accept(bytes);
            });
        }))
        {
            fetch.accept(done);
        }
    }

    /**
     * A version's kept files passed over until the server sends its own, which overwrite them; left on disk while it
     * does not answer. Any thread.
     */
    void refetch(String kind, String version, Collection<String> names)
    {
        names.forEach(name -> stale.add(kind + "/" + version + "/" + name));
    }

    /** Null for a name that could leave the folder. */
    Filepath file(String kind, String version, String name)
    {
        return KIND.matcher(kind).matches() && MapServer.isSafeVersion(version) && NAME.matcher(name).matches()
            ? root.joinSegment(kind).joinSegment(version).joinSegment(name) : null;
    }

    boolean later(Runnable work)
    {
        return TileCache.execute(io, work);
    }

    /** IO thread. */
    static byte[] read(Filepath file)
    {
        if (!file.isFile())
        {
            return null;
        }
        try (InputStream in = file.openInputStream())
        {
            var bytes = in.readNBytes(MAX_BYTES + 1);
            return bytes.length > MAX_BYTES ? null : bytes;
        }
        catch (IOException e)
        {
            log.debug("Could not read {}", file, e);
            return null;
        }
    }

    /** IO thread. */
    void keep(String kind, String version, Filepath file, byte[] bytes)
    {
        prune(kind, version);
        try
        {
            TileCache.writeAtomically(file, bytes);
        }
        catch (IOException e)
        {
            log.debug("Could not keep {}", file, e);
        }
    }

    /** IO thread: once a kind's version changes, the other versions' folders go. */
    void prune(String kind, String version)
    {
        if (version.equals(inUse.put(kind, version)))
        {
            return;
        }
        var folder = root.joinSegment(kind);
        if (!folder.isDirectory())
        {
            return;
        }
        try (var others = folder.walk(1))
        {
            others.filter(other -> !other.equals(folder) && !other.getFileName().equals(version))
                .forEach(TileCache::deleteTree);
        }
        catch (IOException | UncheckedIOException e)
        {
            // A folder another prune removed meanwhile: what is left goes next time.
            log.debug("Could not look through {}", folder, e);
        }
    }
}

package com.hdmapreforged;

import java.util.*;
import java.util.stream.*;
import lombok.*;
import net.runelite.api.coords.*;
import net.runelite.client.events.*;

/** Talking to the Shortest Path plugin through RuneLite plugin messages (its public message format only). */
final class ShortestPathBridge
{
    static final String NAMESPACE = "shortestpath";
    static final String PATH = "path";
    static final String CLEAR = "clear";
    static final String TARGET = "target";
    /** Plugins that answer this namespace: Shortest Path, and GPS (its own name, Shortest Path's messages). */
    static final List<String> PLUGIN_NAMES = List.of("Shortest Path", "GPS");
    /** Cap per message: messages come from other plugins. */
    static final int MAX_POINTS = 64;

    /**
     * Asks it to tell which transports its path uses, so we can draw the route too (it keeps that until a clear);
     * {@code target} null keeps its route. {@code config}: overrides another plugin gave, kept.
     */
    static PluginMessage path(WorldPoint target, Map<?, ?> config)
    {
        var data = new HashMap<String, Object>();
        if (target != null)
        {
            data.put(TARGET, target);
        }
        return askingTransports(data, config);
    }

    /**
     * Another plugin's path message sent again, as it was but planned from where the player is now, asking it to
     * tell its transports: for when the planner changed after the message came (the other plugin sends it once).
     */
    static PluginMessage again(PluginMessage message)
    {
        var data = new HashMap<String, Object>(message.getData() == null ? Map.of() : message.getData());
        data.remove("start");
        return askingTransports(data, config(message));
    }

    static PluginMessage askingTransports(Map<String, Object> data, Map<?, ?> config)
    {
        var wanted = new HashMap<Object, Object>(config);
        wanted.put("postTransports", true);
        data.put("config", wanted);
        return new PluginMessage(NAMESPACE, PATH, data);
    }

    /** The config overrides a path message carries; empty when none. */
    static Map<?, ?> config(PluginMessage message)
    {
        Object config = message.getData() == null ? null : message.getData().get("config");
        return config instanceof Map<?, ?> ? (Map<?, ?>) config : Map.of();
    }

    /** A path message's avoidWilderness override (Shortest Clue turns it off for clues in the Wilderness); null when none. */
    static Boolean avoidWilderness(PluginMessage message)
    {
        Object value = config(message).get("avoidWilderness");
        if (value instanceof String && ((String) value).matches("(?i)true|false"))
        {
            value = Boolean.valueOf((String) value);
        }
        return value instanceof Boolean ? (Boolean) value : null;
    }

    /** A transport or teleport of Shortest Path's route. */
    @RequiredArgsConstructor
    static final class Jump
    {
        final WorldPoint from;
        final WorldPoint to;
        final String name;
    }

    static boolean is(PluginMessage message, String name)
    {
        return NAMESPACE.equals(message.getNamespace()) && name.equals(message.getName());
    }

    /** In order; empty when unreadable. */
    static List<Jump> jumps(PluginMessage message)
    {
        var data = message.getData();
        if (data == null || !(data.get("origin") instanceof List<?>) || !(data.get("destination") instanceof List<?>))
        {
            return Collections.emptyList();
        }
        var origins = (List<?>) data.get("origin");
        var destinations = (List<?>) data.get("destination");
        var names = data.get("displayInfo") instanceof List<?> ? (List<?>) data.get("displayInfo") : Collections.emptyList();
        var jumps = new ArrayList<Jump>();
        for (int i = 0; i < origins.size() && i < destinations.size() && jumps.size() < MAX_POINTS; i++)
        {
            var from = point(origins.get(i));
            var to = point(destinations.get(i));
            if (from == null || to == null)
            {
                continue;
            }
            Object name = i < names.size() ? names.get(i) : null;
            jumps.add(new Jump(from, to, name instanceof String && !((String) name).trim().isEmpty() ? ((String) name).trim()
                : "Transport"));
        }
        return jumps;
    }

    static PluginMessage clear()
    {
        return new PluginMessage(NAMESPACE, CLEAR);
    }

    /** A WorldPoint, a packed point, or a collection of either; empty when none or unreadable. */
    static List<WorldPoint> targets(PluginMessage message)
    {
        var data = message.getData();
        Object target = data == null ? null : data.get(TARGET);
        return (target instanceof Collection<?> ? ((Collection<?>) target).stream() : Stream.of(target))
            .map(ShortestPathBridge::point).filter(Objects::nonNull).limit(MAX_POINTS).collect(Collectors.toList());
    }

    /** A WorldPoint, or packed as x | y << 15 | plane << 30 (-1 none); null outside the game world. */
    static WorldPoint point(Object value)
    {
        WorldPoint point = null;
        if (value instanceof WorldPoint)
        {
            point = (WorldPoint) value;
        }
        else if (value instanceof Integer)
        {
            // -1 unpacks off the game world.
            int packed = (Integer) value;
            point = new WorldPoint(packed & 0x7FFF, (packed >>> 15) & 0x7FFF, (packed >>> 30) & 0x3);
        }
        return HdMapPartyLocation.plausible(point) ? point : null;
    }

    /** The target nearest the player (the first when unknown). */
    static WorldPoint nearest(List<WorldPoint> targets, WorldPoint from)
    {
        WorldPoint best = null;
        int bestDistance = Integer.MAX_VALUE;
        for (var target : targets)
        {
            int d = from == null ? 0 : target.distanceTo2D(from) + (target.getPlane() == from.getPlane() ? 0 : 1000);
            if (best == null || d < bestDistance)
            {
                best = target;
                bestDistance = d;
            }
        }
        return best;
    }
}

package com.hdmapreforged;

import com.hdmapreforged.route.*;
import java.awt.*;
import java.awt.image.*;
import java.util.*;
import java.util.List;

/** Outlined map text, rendered once then copied (each label is nine antialiased strings). Swing thread only. */
final class TextSprites
{
    static final Color OUTLINE = new Color(0, 0, 0, 200);

    /** By text, font, colour and device scale (in tenths); at most 1500. */
    final Map<List<Object>, BufferedImage> cache = new LruMap<>(256, 1500);

    /** Like {@code g.drawString} with the given font, outlined. */
    void draw(Graphics2D g, String text, Font font, float x, float y, Color color)
    {
        var transform = g.getTransform();
        double device = PoiIcons.device(transform);
        List<Object> key = List.of(text, font, color.getRGB(), (int) Math.round(device * 10));
        g.setFont(font);
        var metrics = g.getFontMetrics();
        int ascent = metrics.getAscent();
        BufferedImage sprite = cache.computeIfAbsent(key, k -> PoiIcons.sprite(metrics.stringWidth(text) + 4,
            metrics.getHeight() + 4, device, sg -> {
                sg.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
                sg.setFont(font);
                outlined(sg, text, 2, 2 + ascent, color);
            }));
        PoiIcons.blit(g, transform, sprite, x - 2, y - ascent - 2);
    }

    static void outlined(Graphics2D g, String text, float x, float y, Color color)
    {
        g.setColor(OUTLINE);
        for (int dx = -1; dx <= 1; dx++)
        {
            for (int dy = -1; dy <= 1; dy++)
            {
                if (dx != 0 || dy != 0)
                {
                    g.drawString(text, x + dx, y + dy);
                }
            }
        }
        g.setColor(color);
        g.drawString(text, x, y);
    }
}

package com.hdmapreforged;

import java.awt.*;
import java.awt.image.*;
import java.io.*;
import java.lang.ref.*;
import java.nio.file.*;
import java.util.*;
import java.util.List;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.*;
import java.util.stream.*;
import javax.imageio.*;
import javax.imageio.stream.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.client.util.*;
import okhttp3.*;

/**
 * Map tiles from our map server, in memory, optionally on disk, downloaded a few at a time. Each frame queues tiles farthest first
 * and loads at frame end, so the middle loads first; tiles scrolled away before their turn are dropped.
 */
@Slf4j
@RequiredArgsConstructor
final class TileCache
{
    static final int TILE_SIZE = 256;
    static final int MIN_ZOOM = -3;
    static final int MAX_ZOOM = 3;
    /** A tile is well under 200 KB. */
    static final int MAX_TILE_BYTES = 2 * 1024 * 1024;
    static final long MB = 1024 * 1024;
    /**
     * 128 MB of tiles in view: past it the views draw a coarser level, a quarter of the tiles (a 4K window's upper floor
     * would need 2,000 tiles, 500 MB, just above a whole zoom). A higher memory setting raises it.
     */
    static final int MAX_TILES = 512;
    /** Kept while no map is open, for the next opening. */
    static final int CLOSED_TILES = 64;

    @RequiredArgsConstructor
    @EqualsAndHashCode
    static final class Key
    {
        final int map;
        final int zoom;
        final int plane;
        final int x;
        final int y;

        String path()
        {
            return map + "/" + zoom + "/" + plane + "_" + x + "_" + y + ".png";
        }

        /** A line of missing.txt; null for a broken one. */
        static Key parse(String line)
        {
            var p = line.trim().split(" ");
            try
            {
                return p.length == 5 ? new Key(Integer.parseInt(p[0]), Integer.parseInt(p[1]), Integer.parseInt(p[2]),
                    Integer.parseInt(p[3]), Integer.parseInt(p[4])) : null;
            }
            catch (NumberFormatException e)
            {
                return null;
            }
        }
    }

    final OkHttpClient http;
    final ExecutorService io;
    final Filepath cacheRoot;
    final Runnable onLoaded;

    /** The tiles the open views need (in view and some to spare), or a few with no map open. */
    final LinkedHashMap<Key, BufferedImage> memory = new LinkedHashMap<>(256, 0.75f, true);
    /**
     * Older tiles past those, up to the memory setting, held softly: a large heap keeps them, and the JVM drops them
     * before it runs out of memory, so they never crash the client (plugins may not read the heap's size).
     */
    final LinkedHashMap<Key, SoftReference<BufferedImage>> spare = new LinkedHashMap<>();
    final Set<Key> missing = new HashSet<>();
    final Map<Key, Long> failed = new HashMap<>();
    /** Previous-version tiles shown while this version's are fetched. */
    final Set<Key> stale = new HashSet<>();
    final Deque<Key> queue = new ArrayDeque<>();
    final Set<Key> queued = new HashSet<>();
    final Set<Key> loading = new HashSet<>();
    /** Downloads under way: cancelled when the cache is cleared (the plugin stops). */
    final Set<Call> calls = ConcurrentHashMap.newKeySet();
    /** Requests still running, of any generation: {@link #clear} empties {@code loading} but not the network. */
    int inFlight;
    /** Bytes on disk as last counted, plus writes since; a trim runs once it passes the limit. */
    final AtomicLong diskBytes = new AtomicLong();
    final AtomicBoolean trimQueued = new AtomicBoolean();
    boolean configured;
    volatile String version;
    volatile boolean diskCache;
    volatile int memoryLimit = 256;
    volatile int diskLimitMb = 1000;
    /** What each open view needs; the memory cache never shrinks below their sum, or tiles in view would reload. */
    final Map<Object, Integer> needs = new HashMap<>();
    int frameNeed;
    int generation;
    /** Old versions are removed once a tile of an official version downloads, so a mistyped version never wipes the cache. */
    boolean cleanupPending;
    /** Previous version on disk, shown while the new one downloads; each old tile is removed once replaced. */
    volatile String fallbackVersion;
    /** Only then are the fallback's tiles removed: a manual version or the start-up stand-in must not wear it down. */
    volatile boolean official;

    static int tileIndex(double world, int zoom)
    {
        return (int) Math.floor(world * Math.pow(2, zoom) / TILE_SIZE);
    }

    static double worldPerTile(int zoom)
    {
        return TILE_SIZE / Math.pow(2, zoom);
    }

    void configure(boolean diskCache, int memoryLimit, int diskLimitMb)
    {
        boolean wasOn;
        boolean first;
        int oldLimit;
        synchronized (this)
        {
            wasOn = this.diskCache;
            oldLimit = this.diskLimitMb;
            first = !configured;
            configured = true;
            this.diskCache = diskCache;
            this.memoryLimit = memoryLimit;
            this.diskLimitMb = diskLimitMb;
            trim();
        }
        if (!diskCache && (wasOn || first))
        {
            execute(this::deleteCachedTiles);
        }
        else if (diskCache && wasOn && diskLimitMb < oldLimit)
        {
            requestTrim();
        }
    }

    /**
     * The tiles of {@code from} become {@code to}'s, but for those the server says changed or went, so only they are
     * fetched again: the folder is renamed, the changed tiles deleted, the tiles known missing kept but for the changed
     * ones. Before {@link #setVersion}. False when {@code from} is not on disk or {@code to} already is.
     */
    boolean upgrade(String from, String to, Set<String> changed, Set<String> removed)
    {
        var old = versionFolder(from);
        var fresh = versionFolder(to);
        if (!diskCache || !old.isDirectory() || fresh.exists())
        {
            return false;
        }
        var gone = new HashSet<String>(changed);
        gone.addAll(removed);
        synchronized (missingFile)
        {
            try
            {
                for (String path : gone)
                {
                    var p = path.split("/");
                    var tile = p.length == 3 ? old.join(p[0], p[1], p[2]) : null;
                    if (tile != null && tile.isFile())
                    {
                        diskBytes.addAndGet(-tile.size());
                        tile.delete();
                    }
                }
                var missingList = old.joinSegment(MISSING);
                if (missingList.isFile())
                {
                    StringBuilder kept = new StringBuilder();
                    try (BufferedReader in = missingList.openBufferedReader())
                    {
                        String line;
                        while ((line = in.readLine()) != null)
                        {
                            var key = Key.parse(line);
                            if (key != null && !changed.contains(key.path()))
                            {
                                kept.append(line.trim()).append('\n');
                            }
                        }
                    }
                    missingList.write(kept.toString());
                }
                old.moveTo(fresh);
                return true;
            }
            catch (IOException | RuntimeException e)
            {
                log.debug("Could not carry the tiles of {} over to {}", from, to, e);
                return false;
            }
        }
    }

    /** {@code official}: the version the map server reports, not a manual setting. */
    void setVersion(String version, boolean official)
    {
        if (version.equals(this.version))
        {
            return;
        }
        // Listed outside the lock: the map keeps painting meanwhile.
        String fallback = previousOnDisk(version);
        synchronized (this)
        {
            if (version.equals(this.version))
            {
                return;
            }
            this.version = version;
            clear();
            cleanupPending = official;
            this.official = official;
            fallbackVersion = fallback;
        }
        if (official && fallback != null)
        {
            // Older versions merge into the fallback, so their tiles still show while this version's arrive.
            execute(() -> mergeOlder(version, fallback));
        }
        execute(() -> loadMissing(version));
        requestTrim();
    }

    /** Per version, the tiles the map server has not got (open sea, the world's edge), so they aren't asked again. */
    static final String MISSING = "missing.txt";
    final Object missingFile = new Object();

    void rememberMissing(String tileVersion, Key key)
    {
        if (!diskCache)
        {
            return;
        }
        synchronized (missingFile)
        {
            try
            {
                var folder = versionFolder(tileVersion);
                folder.createDirectories();
                folder.joinSegment(MISSING).write(key.map + " " + key.zoom + " " + key.plane + " " + key.x + " " + key.y
                    + "\n", StandardOpenOption.CREATE, StandardOpenOption.APPEND);
            }
            catch (IOException | RuntimeException e)
            {
                log.debug("Could not remember missing tile {}", key.path(), e);
            }
        }
    }

    /** Background thread. */
    void loadMissing(String tileVersion)
    {
        var file = versionFolder(tileVersion).joinSegment(MISSING);
        if (!diskCache || !file.isFile())
        {
            return;
        }
        var keys = new HashSet<Key>();
        try (BufferedReader in = file.openBufferedReader())
        {
            String line;
            while ((line = in.readLine()) != null)
            {
                var key = Key.parse(line);
                if (key != null)
                {
                    keys.add(key);
                }
            }
        }
        catch (IOException | RuntimeException e)
        {
            log.debug("Could not read {}", file, e);
            return;
        }
        synchronized (this)
        {
            if (tileVersion.equals(version))
            {
                missing.addAll(keys);
            }
        }
    }

    String previousOnDisk(String current)
    {
        Filepath best = null;
        for (var dir : versionDirs())
        {
            if (!dir.getFileName().equals(current) && MapServer.isSafeVersion(dir.getFileName())
                && (best == null || modified(dir) > modified(best)))
            {
                best = dir;
            }
        }
        return best == null ? null : best.getFileName();
    }

    /** The tiles in view and half as many to spare, so panning back or zooming out reloads little. */
    static int need(int visibleTiles)
    {
        return visibleTiles + visibleTiles / 2 + 16;
    }

    /** Whether {@code view} may show {@code visibleTiles} with the cache under its cap, the other views' tiles counted. */
    synchronized boolean fits(Object view, int visibleTiles)
    {
        return need(visibleTiles) + frameNeed - needs.getOrDefault(view, 0) <= Math.max(memoryLimit, MAX_TILES);
    }

    synchronized void beginFrame(Object view, int visibleTiles)
    {
        queue.clear();
        queued.clear();
        setNeed(view, need(visibleTiles));
    }

    /**
     * {@code view} closed: with no map open only a few tiles stay, for the next opening. Another still open trims at its
     * next tile, once its own are the latest used.
     */
    synchronized void closed(Object view)
    {
        setNeed(view, 0);
        if (needs.isEmpty())
        {
            queue.clear();
            queued.clear();
            trim();
        }
    }

    void setNeed(Object view, int need)
    {
        Integer old = need > 0 ? needs.put(view, need) : needs.remove(view);
        frameNeed += need - (old == null ? 0 : old);
    }

    synchronized void endFrame()
    {
        pump();
    }

    synchronized BufferedImage peek(Key key)
    {
        var ref = spare.remove(key);
        var image = ref == null ? null : ref.get();
        if (image != null)
        {
            memory.putIfAbsent(key, image);
        }
        return memory.get(key);
    }

    /** Queue tiles farthest from the middle first. */
    synchronized BufferedImage get(Key key)
    {
        BufferedImage image = peek(key);
        Long failedAt = failed.get(key);
        if (!(image != null && !stale.contains(key) || version == null || missing.contains(key) || loading.contains(key)
            // A failed tile is tried again after 30 seconds.
            || queued.contains(key) || failedAt != null && System.currentTimeMillis() - failedAt < 30_000))
        {
            queue.addFirst(key);
            queued.add(key);
        }
        return image;
    }

    /** Decoded ({@link #decode}), and on disk when that is on. */
    BufferedImage keep(Filepath file, byte[] bytes, Color under) throws IOException
    {
        BufferedImage image = decode(bytes, under);
        if (image != null && diskCache)
        {
            write(file, bytes);
        }
        return image;
    }

    Call call(String tileVersion, Key key)
    {
        return http.newCall(new Request.Builder().url(MapServer.tile(tileVersion, key)).build());
    }

    /** Null on 404. */
    static byte[] bytes(Response response, ResponseBody body) throws IOException
    {
        if (response.code() == 404)
        {
            return null;
        }
        if (!response.isSuccessful() || body == null)
        {
            throw new IOException("HTTP " + response.code());
        }
        return readBody(body, MAX_TILE_BYTES);
    }

    /** Every tile downloaded again (the map looks wrong): those on disk go first, then those in memory. */
    void downloadAgain()
    {
        execute(() -> {
            versionDirs().forEach(TileCache::deleteTree);
            diskBytes.set(0);
            synchronized (this)
            {
                fallbackVersion = null;
                clear();
            }
        });
    }

    synchronized void clear()
    {
        generation++;
        memory.clear();
        spare.clear();
        stale.clear();
        queue.clear();
        queued.clear();
        loading.clear();
        missing.clear();
        failed.clear();
        calls.forEach(Call::cancel);
        calls.clear();
    }

    void pump()
    {
        // At most 10 at once; OkHttp itself still caps requests at 5 per host, shared with the rest of RuneLite.
        while (inFlight < 10 && !queue.isEmpty())
        {
            Key key = queue.pollFirst();
            queued.remove(key);
            loading.add(key);
            inFlight++;
            int started = generation;
            String tileVersion = version;
            if (!execute(() -> load(key, tileVersion, started)))
            {
                loading.remove(key);
                inFlight--;
                return;
            }
        }
    }

    boolean execute(Runnable task)
    {
        return execute(io, task);
    }

    /** Runs {@code task} on {@code io}; false once it refuses more work (the plugin stopping), for every such hand-off. */
    static boolean execute(Executor io, Runnable task)
    {
        try
        {
            io.execute(task);
            return true;
        }
        catch (RejectedExecutionException e)
        {
            return false;
        }
    }

    Filepath file(String tileVersion, Key key)
    {
        return versionFolder(tileVersion).join(key.path());
    }

    static final String PART_SUFFIX = ".part";

    /** Refused over {@code max} bytes whether or not the server declared the length. */
    static byte[] readBody(ResponseBody body, int max) throws IOException
    {
        long declared = body.contentLength();
        if (declared > max)
        {
            throw new IOException("Too large: " + declared + " bytes");
        }
        try (InputStream in = body.byteStream())
        {
            var bytes = in.readNBytes(max + 1);
            if (bytes.length > max)
            {
                throw new IOException("Too large: over " + max + " bytes");
            }
            return bytes;
        }
    }

    Filepath versionFolder(String tileVersion)
    {
        return cacheRoot.joinSegment(tileVersion);
    }

    /** For a map's first frame, which would otherwise show icons on black before tiles pop in; not tiles known missing. */
    BufferedImage fromDiskNow(Key key)
    {
        String current;
        synchronized (this)
        {
            current = missing.contains(key) || failed.containsKey(key) ? null : version;
        }
        BufferedImage image = current == null ? null : readCached(file(current, key), under(key));
        if (image != null)
        {
            synchronized (this)
            {
                if (current.equals(version))
                {
                    memory.put(key, image);
                    trim();
                }
            }
        }
        return image;
    }

    /** Files that are no tile are removed so they download again; a failed read leaves the file. */
    BufferedImage readCached(Filepath file, Color under)
    {
        if (!diskCache || !file.isFile())
        {
            return null;
        }
        byte[] bytes;
        try
        {
            bytes = file.size() > MAX_TILE_BYTES ? null : read(file);
        }
        catch (IOException | RuntimeException e)
        {
            log.debug("Could not read cached tile {}", file, e);
            return null;
        }
        try
        {
            BufferedImage image = bytes == null ? null : decode(bytes, under);
            if (image != null)
            {
                return image;
            }
        }
        catch (IOException | RuntimeException e)
        {
            log.debug("Unreadable cached tile {}", file, e);
        }
        delete(file);
        return null;
    }

    void load(Key key, String tileVersion, int started)
    {
        try
        {
            BufferedImage cached = readCached(file(tileVersion, key), under(key));
            if (cached != null)
            {
                finish(key, started, cached, false, false);
                return;
            }
            String previous = fallbackVersion;
            var old = previous == null ? null : file(previous, key);
            BufferedImage stale = old == null ? null : readCached(old, under(key));
            if (stale != null)
            {
                showStale(key, started, stale);
            }
            Call download = call(tileVersion, key);
            calls.add(download);
            download.enqueue(new Callback()
            {
                public void onFailure(Call call, IOException e)
                {
                    calls.remove(call);
                    log.debug("Tile download failed: {}", key.path(), e);
                    finish(key, started, null, false, false);
                }

                public void onResponse(Call call, Response response)
                {
                    calls.remove(call);
                    byte[] bytes;
                    try (var body = response.body())
                    {
                        bytes = bytes(response, body);
                    }
                    catch (IOException | RuntimeException e)
                    {
                        log.debug("Unusable tile {}", key.path(), e);
                        finish(key, started, null, false, false);
                        return;
                    }
                    // The disk work on our own thread, not OkHttp's shared callback threads.
                    if (!execute(() -> store(key, tileVersion, started, old, bytes)))
                    {
                        finish(key, started, null, false, false);
                    }
                }
            });
        }
        catch (RuntimeException e)
        {
            log.debug("Could not load tile {}", key.path(), e);
            finish(key, started, null, false, false);
        }
    }

    /** A downloaded tile kept on disk; {@code bytes} null: the map server has none in this version. */
    void store(Key key, String tileVersion, int started, Filepath old, byte[] bytes)
    {
        BufferedImage image = null;
        try
        {
            if (bytes == null)
            {
                // Gone in this version: the stale copy must not linger.
                forget(key, started);
                rememberMissing(tileVersion, key);
            }
            else
            {
                // Not an image although found: a passing fault, asked again later.
                image = keep(file(tileVersion, key), bytes, under(key));
                if (image != null && old != null && official && old.isFile())
                {
                    diskBytes.addAndGet(-old.size());
                    delete(old);
                }
            }
        }
        catch (IOException | RuntimeException e)
        {
            log.debug("Unusable tile {}", key.path(), e);
        }
        finish(key, started, image, bytes == null, image != null);
    }

    /** The key stays loading. */
    void showStale(Key key, int started, BufferedImage image)
    {
        synchronized (this)
        {
            if (started != generation || memory.containsKey(key))
            {
                return;
            }
            memory.put(key, image);
            stale.add(key);
            trim();
        }
        onLoaded.run();
    }

    synchronized void forget(Key key, int started)
    {
        if (started == generation)
        {
            memory.remove(key);
            spare.remove(key);
            stale.remove(key);
        }
    }

    void finish(Key key, int started, BufferedImage image, boolean notFound, boolean downloaded)
    {
        boolean cleanup = false;
        synchronized (this)
        {
            inFlight--;
            if (started != generation)
            {
                pump();
                return;
            }
            loading.remove(key);
            if (image != null)
            {
                memory.put(key, image);
                stale.remove(key);
                failed.remove(key);
                trim();
                if (downloaded && cleanupPending)
                {
                    cleanupPending = false;
                    cleanup = true;
                }
            }
            else if (notFound)
            {
                missing.add(key);
            }
            else
            {
                failed.put(key, System.currentTimeMillis());
            }
            pump();
        }
        if (cleanup)
        {
            String keep = version;
            String fallback = fallbackVersion;
            execute(() -> removeOtherVersions(keep, fallback));
        }
        if (image != null)
        {
            onLoaded.run();
        }
    }

    void trim()
    {
        boolean open = !needs.isEmpty();
        // Never fewer than a closed map keeps, so closing keeps the latest.
        int limit = Math.max(open ? frameNeed : 0, Math.min(memoryLimit, CLOSED_TILES));
        while (memory.size() > limit)
        {
            Key oldest = memory.keySet().iterator().next();
            var image = memory.remove(oldest);
            // An older version's tile shown meanwhile is not kept.
            if (!stale.remove(oldest) && open)
            {
                spare.put(oldest, new SoftReference<>(image));
            }
        }
        for (var it = spare.keySet().iterator(); it.hasNext() && spare.size() > (open ? memoryLimit : 0); )
        {
            it.next();
            it.remove();
        }
    }

    /**
     * What a tile shown in a view is drawn on: the ground floor is drawn on the map's background, so filled with it the
     * tile stays opaque, which Java2D scales several times faster (zoomed out most tiles have see-through parts). Upper
     * floors stay see-through: the ground floor shows under them ({@link MapView}).
     */
    static Color under(Key key)
    {
        return key.plane == 0 ? MapView.BACKGROUND : null;
    }

    /** A picture, its size checked before its pixels are read; null when it is no picture. */
    static BufferedImage readImage(byte[] bytes, BiPredicate<Integer, Integer> sizeOk) throws IOException
    {
        // In memory: ImageIO's default stream would cache to a temporary file.
        try (var in = new MemoryCacheImageInputStream(new ByteArrayInputStream(bytes)))
        {
            var readers = ImageIO.getImageReaders(in);
            if (!readers.hasNext())
            {
                return null;
            }
            var reader = readers.next();
            try
            {
                reader.setInput(in, true, true);
                int width = reader.getWidth(0);
                int height = reader.getHeight(0);
                if (!sizeOk.test(width, height))
                {
                    throw new IOException("Unexpected picture size: " + width + "x" + height);
                }
                return reader.read(0);
            }
            finally
            {
                reader.dispose();
            }
        }
    }

    /**
     * Into a type Java2D draws quickly; anything but 256x256 is refused before it is decoded. See-through parts are
     * filled with {@code under} when given ({@link #under}).
     */
    static BufferedImage decode(byte[] bytes, Color under) throws IOException
    {
        BufferedImage source = readImage(bytes, (width, height) -> width == TILE_SIZE && height == TILE_SIZE);
        if (source == null)
        {
            return null;
        }
        boolean alpha = source.getColorModel().hasAlpha();
        BufferedImage image = new BufferedImage(source.getWidth(), source.getHeight(), alpha && under == null
            ? BufferedImage.TYPE_INT_ARGB_PRE : BufferedImage.TYPE_INT_RGB);
        var g = image.createGraphics();
        if (alpha && under != null)
        {
            g.setColor(under);
            g.fillRect(0, 0, image.getWidth(), image.getHeight());
        }
        g.drawImage(source, 0, 0, null);
        g.dispose();
        return image;
    }

    void write(Filepath file, byte[] bytes)
    {
        try
        {
            writeAtomically(file, bytes);
        }
        catch (IOException | RuntimeException e)
        {
            log.debug("Could not cache tile {}", file, e);
            return;
        }
        if (diskBytes.addAndGet(bytes.length) > diskLimitMb * MB)
        {
            requestTrim();
        }
    }

    /**
     * Through an own temp file (two threads may write the same file at once), then moved over the target; makes the
     * folder, which another thread may make at the same moment.
     */
    static void writeAtomically(Filepath target, byte[] bytes) throws IOException
    {
        var folder = target.getParent();
        folder.createDirectories();
        var temp = folder.createTempFile(target.getFileName() + ".", PART_SUFFIX);
        try
        {
            temp.write(bytes);
            try
            {
                temp.moveTo(target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
            }
            catch (AtomicMoveNotSupportedException e)
            {
                temp.moveTo(target, StandardCopyOption.REPLACE_EXISTING);
            }
        }
        finally
        {
            temp.deleteIfExists();
        }
    }

    static byte[] read(Filepath file) throws IOException
    {
        try (InputStream in = file.openInputStream())
        {
            return in.readAllBytes();
        }
    }

    /** One trim at a time: the flag stays set until it ends, so writes meanwhile queue no second one. */
    void requestTrim()
    {
        if (trimQueued.compareAndSet(false, true) && !execute(this::limitDiskUse))
        {
            trimQueued.set(false);
        }
    }

    /** Moves tiles of other versions that {@code fallback} lacks into it, then removes those versions. */
    void mergeOlder(String current, String fallback)
    {
        var into = versionFolder(fallback);
        for (var dir : versionDirs())
        {
            String name = dir.getFileName();
            if (name.equals(current) || name.equals(fallback) || !MapServer.isSafeVersion(name))
            {
                continue;
            }
            for (var file : files(dir))
            {
                try
                {
                    // Tiles lie in version/map/zoom.
                    var zoom = file.getParent();
                    var map = zoom.getParent();
                    var target = into.join(map.getFileName(), zoom.getFileName(), file.getFileName());
                    if (dir.equals(map.getParent()) && !target.exists())
                    {
                        target.getParent().createDirectories();
                        file.moveTo(target);
                    }
                }
                catch (IOException | RuntimeException e)
                {
                    log.debug("Could not keep {}", file, e);
                }
            }
            deleteTree(dir);
        }
    }

    void removeOtherVersions(String keep, String fallback)
    {
        for (var dir : versionDirs())
        {
            if (!dir.getFileName().equals(keep) && !dir.getFileName().equals(fallback))
            {
                deleteTree(dir);
            }
        }
    }

    /** Snapshot: the disk may change while trimming. */
    static final class Entry
    {
        final Filepath file;
        final long modified;
        final long size;

        Entry(Filepath file) throws IOException
        {
            this.file = file;
            modified = file.getLastModifiedTime().toMillis();
            size = file.size();
        }
    }

    /** Background thread: removes oldest tiles past the limit and stale half-written files. */
    void limitDiskUse()
    {
        try
        {
            if (!diskCache)
            {
                return;
            }
            long counted = diskBytes.get();
            long now = System.currentTimeMillis();
            var entries = new ArrayList<Entry>();
            long total = 0;
            for (var file : files(cacheRoot))
            {
                String name = file.getFileName();
                try
                {
                    Entry entry = new Entry(file);
                    // Half-written files older than 10 minutes were left by a crash; newer ones may still be being
                    // written.
                    if (name.endsWith(PART_SUFFIX) && now - entry.modified > 10 * 60 * 1000L)
                    {
                        delete(file);
                        continue;
                    }
                    entries.add(entry);
                    total += entry.size;
                }
                catch (IOException e)
                {
                    // Removed meanwhile.
                }
            }
            total -= trimOldest(entries, total, diskLimitMb * MB);
            // Tiles written during the walk still count.
            diskBytes.addAndGet(total - counted);
        }
        finally
        {
            trimQueued.set(false);
        }
    }

    /** Removes the oldest files until 80% of {@code limit} is left, if over it; returns the bytes removed. */
    static long trimOldest(List<Entry> entries, long total, long limit)
    {
        long removed = 0;
        if (total > limit)
        {
            entries.sort(Comparator.comparingLong((Entry e) -> e.modified));
            for (Entry entry : entries)
            {
                if (total - removed <= limit * 8 / 10)
                {
                    break;
                }
                if (delete(entry.file))
                {
                    removed += entry.size;
                }
            }
        }
        return removed;
    }

    /** Background thread: the disk cache was switched off, so its tiles go. */
    void deleteCachedTiles()
    {
        if (diskCache)
        {
            return;
        }
        for (var dir : versionDirs())
        {
            if (MapServer.isSafeVersion(dir.getFileName()))
            {
                deleteTree(dir);
            }
        }
        diskBytes.set(0);
    }

    List<Filepath> versionDirs()
    {
        return walk(cacheRoot, 1, dir -> !dir.equals(cacheRoot) && dir.isDirectory());
    }

    /** Files below {@code dir}; symbolic links are not followed. */
    static List<Filepath> files(Filepath dir)
    {
        return walk(dir, Integer.MAX_VALUE, Filepath::isFile);
    }

    static List<Filepath> walk(Filepath dir, int depth, Predicate<Filepath> filter)
    {
        try (var found = dir.walk(depth))
        {
            return found.filter(filter).collect(Collectors.toList());
        }
        catch (IOException | UncheckedIOException e)
        {
            return Collections.emptyList();
        }
    }

    static long modified(Filepath file)
    {
        try
        {
            return file.getLastModifiedTime().toMillis();
        }
        catch (IOException e)
        {
            return 0;
        }
    }

    /** Never follows symbolic links. */
    static void deleteTree(Filepath file)
    {
        try
        {
            file.deleteRecursively();
        }
        catch (IOException e)
        {
            log.debug("Could not remove {}", file, e);
        }
    }

    static boolean delete(Filepath file)
    {
        try
        {
            file.deleteIfExists();
            return true;
        }
        catch (IOException e)
        {
            log.debug("Could not remove {}", file, e);
            return false;
        }
    }
}

package com.hdmapreforged;

import java.awt.*;
import java.util.*;
import java.util.List;
import lombok.*;
import net.runelite.api.coords.*;
import net.runelite.client.events.*;

/**
 * The route's ground tiles via HD World Markers' public plugin messages ({@code tiles}, {@code lines} and
 * {@code clear}, one owner; its guide's "For plugin developers"). It clears them on logout, world hop, connection loss
 * and a profile change: they are sent again after.
 */
final class TileMarkersBridge
{
    static final String NAMESPACE = "hd-world-markers";
    static final String OWNER = "hd-map-reforged-route";
    static final String PLUGIN_NAME = "HD World Markers";
    /** It takes at most this many tiles from one sender. */
    static final int MAX_TILES = 1000;

    /** A tile to mark, optionally labelled. */
    @AllArgsConstructor
    static final class Tile
    {
        final WorldPoint point;
        final Color color;
        /** Null: a faint fill after the colour's transparency. */
        final Color fill;
        final int width;
        final String label;

        Tile(WorldPoint point, Color color, String label)
        {
            this(point, color, null, 2, label);
        }
    }

    static PluginMessage tiles(List<Tile> tiles)
    {
        var list = new ArrayList<Map<String, Object>>();
        for (Tile tile : tiles.subList(0, Math.min(MAX_TILES, tiles.size())))
        {
            var entry = new HashMap<String, Object>();
            entry.put("point", tile.point);
            entry.put("color", tile.color);
            // Follows the colour's transparency, so fading tiles fade as a whole.
            entry.put("fill", tile.fill != null ? tile.fill : new Color(tile.color.getRed(), tile.color.getGreen(),
                tile.color.getBlue(), tile.color.getAlpha() * 50 / 255));
            entry.put("width", tile.width);
            if (tile.label != null)
            {
                entry.put("label", tile.label);
            }
            list.add(entry);
        }
        return message("tiles", list);
    }

    /**
     * The route's walks as lines through the tiles' centres ({@code lines}; points next to each other are joined, a
     * jump breaks the line), each with an arrowhead every so many tiles from its end ({@code arrows}, 0: none); an empty
     * list takes them away.
     */
    static PluginMessage lines(List<List<WorldPoint>> lines, List<Color> colors, List<Integer> arrows, int width)
    {
        var list = new ArrayList<Map<String, Object>>();
        for (int i = 0; i < lines.size(); i++)
        {
            var entry = new HashMap<String, Object>();
            entry.put("points", lines.get(i));
            entry.put("color", colors.get(i));
            entry.put("width", width);
            if (arrows.get(i) > 0)
            {
                entry.put("arrows", arrows.get(i));
            }
            list.add(entry);
        }
        return message("lines", list);
    }

    static PluginMessage clear()
    {
        return message("clear", null);
    }

    /** Ours, with {@code list} under its name (none: null). */
    static PluginMessage message(String name, Object list)
    {
        var data = new HashMap<String, Object>();
        data.put("owner", OWNER);
        if (list != null)
        {
            data.put(name, list);
        }
        return new PluginMessage(NAMESPACE, name, data);
    }
}

package com.hdmapreforged;

import com.hdmapreforged.route.*;
import java.util.*;
import java.util.stream.*;
import lombok.*;
import net.runelite.api.coords.*;

/**
 * A custom route: stops (a place, or a kind of place resolved to the nearest one) and the ways it leaves out, kept as
 * text in settings; the same text, with {@code |} between the cells, is what Export copies and Import reads.
 */
final class Tour
{
    @RequiredArgsConstructor
    static final class Stop
    {
        final String name;
        final WorldPoint point;
        /** Null for a fixed place. */
        final String kind;

        static Stop place(String name, WorldPoint point)
        {
            return new Stop(name, point, null);
        }

        static Stop kind(String kind)
        {
            return new Stop("Nearest of: " + kind, null, kind);
        }

        boolean isKind()
        {
            return kind != null;
        }

        boolean same(Stop other)
        {
            return isKind() ? kind.equals(other.kind) : !other.isKind() && point.equals(other.point);
        }
    }

    /** The fastest order is solved exactly over all of them. */
    static final int MAX_STOPS = 12;
    static final int MAX_TOURS = 50;
    static final int MAX_AVOIDED = 30;
    static final String HEADER = "# route";
    /** Between the cells of a shared route's lines, where a tab would be lost in a chat. */
    static final String SHARED = " | ";

    final String name;
    final List<Stop> stops;
    /** After the last stop, the first again. */
    final boolean loop;
    /**
     * Ways this route leaves out, as a route's steps name them ("Varrock Teleport") or every one of a kind
     * ({@link RouteSource#TYPE} + "Teleports"), in the order they were added. Swing thread.
     */
    final Set<String> avoid;

    Tour(String name, List<Stop> stops)
    {
        this(name, stops, false, Collections.emptySet());
    }

    Tour(String name, List<Stop> stops, boolean loop, Set<String> avoid)
    {
        this.name = name;
        this.stops = new ArrayList<>(stops);
        this.loop = loop;
        this.avoid = new LinkedHashSet<>(avoid);
    }

    /** A left-out way as shown: "Every Teleports" for a kind, else its name. */
    static String describe(String avoided)
    {
        return avoided.regionMatches(true, 0, RouteSource.TYPE, 0, RouteSource.TYPE.length())
            ? "Every " + avoided.substring(RouteSource.TYPE.length()) : avoided;
    }

    /** The last of {@code tours} with this name, else a new empty one added to them. */
    static Tour named(List<Tour> tours, String name)
    {
        Tour found = null;
        for (Tour t : tours)
        {
            if (t.name.equals(name))
            {
                found = t;
            }
        }
        if (found == null)
        {
            found = new Tour(name, new ArrayList<>());
            tours.add(found);
        }
        return found;
    }

    static String unique(List<Tour> tours, String name)
    {
        String candidate = name;
        for (int n = 2; ; n++)
        {
            String c = candidate;
            if (tours.stream().noneMatch(t -> t.name.equalsIgnoreCase(c)))
            {
                return candidate;
            }
            candidate = name + " " + n;
        }
    }

    /** Same as the stop before: skipped when run, but kept so it can be moved (there and back). */
    boolean repeats(int i)
    {
        return i > 0 && i < stops.size() && stops.get(i).same(stops.get(i - 1));
    }

    Tour withoutRepeats()
    {
        return new Tour(name, IntStream.range(0, stops.size()).filter(i -> !repeats(i)).mapToObj(stops::get)
            .collect(Collectors.toList()), loop, avoid);
    }

    Tour renamed(String newName)
    {
        return new Tour(newName, stops, loop, avoid);
    }

    Tour looping(boolean again)
    {
        return new Tour(name, stops, again, avoid);
    }

    /** As the crow flies, same floor first; the first place when {@code near} is unknown. */
    static WorldPoint nearest(KindIndex.Kind kind, WorldPoint near)
    {
        if (kind == null || kind.entries.isEmpty())
        {
            return null;
        }
        var best = kind.entries.get(0).point;
        if (near == null)
        {
            return best;
        }
        long bestDistance = Long.MAX_VALUE;
        for (var entry : kind.entries)
        {
            long d = away(entry.point, near);
            if (d < bestDistance)
            {
                best = entry.point;
                bestDistance = d;
            }
        }
        return best;
    }

    /** How far {@code p} is from {@code near} for "nearest": squared, as the crow flies, any on the same floor first. */
    static long away(WorldPoint p, WorldPoint near)
    {
        return SearchResults.distance(p, near) + (p.getPlane() == near.getPlane() ? 0 : 100_000_000L);
    }

    /**
     * Per route "# route\tname" ("\tloop" when it loops), then per stop "x y plane\tname" or "-\tname\tkind", and per
     * way left out "!\tname".
     */
    static String encode(List<Tour> tours)
    {
        return encode(tours, "\t");
    }

    /** The same with {@link #SHARED} between the cells: for the clipboard. */
    static String share(List<Tour> tours)
    {
        return encode(tours, SHARED);
    }

    static String encode(List<Tour> tours, String cell)
    {
        StringBuilder text = new StringBuilder();
        for (Tour tour : tours)
        {
            text.append(HEADER).append(cell).append(clean(tour.name)).append(tour.loop ? cell + "loop\n" : "\n");
            for (Stop stop : tour.stops)
            {
                if (stop.isKind())
                {
                    text.append('-').append(cell).append(clean(stop.name)).append(cell).append(clean(stop.kind));
                }
                else
                {
                    var p = stop.point;
                    text.append(p.getX()).append(' ').append(p.getY()).append(' ').append(p.getPlane()).append(cell)
                        .append(clean(stop.name));
                }
                text.append('\n');
            }
            for (String avoided : tour.avoid)
            {
                text.append('!').append(cell).append(clean(avoided)).append('\n');
            }
        }
        return text.toString();
    }

    /** Bad lines are skipped, never an error; a line's cells may be parted by tabs or by {@link #SHARED}. */
    static List<Tour> decode(String text)
    {
        var tours = new ArrayList<Tour>();
        if (text == null)
        {
            return tours;
        }
        String name = null;
        boolean loop = false;
        var stops = new ArrayList<Stop>();
        var avoid = new LinkedHashSet<String>();
        for (String line : text.split("\r?\n"))
        {
            var cells = cells(line);
            if (cells[0].equals(HEADER) && cells.length > 1)
            {
                if (name != null)
                {
                    tours.add(new Tour(name, stops, loop, avoid));
                }
                name = cells[1];
                loop = cells.length > 2 && cells[2].equals("loop");
                stops = new ArrayList<>();
                avoid = new LinkedHashSet<>();
                continue;
            }
            if (name == null || line.trim().isEmpty())
            {
                continue;
            }
            if (cells[0].equals("!"))
            {
                if (cells.length > 1 && !cells[1].isEmpty() && avoid.size() < MAX_AVOIDED)
                {
                    avoid.add(cells[1]);
                }
                continue;
            }
            if (stops.size() >= MAX_STOPS)
            {
                continue;
            }
            if (cells.length >= 3 && cells[0].equals("-") && !cells[2].isEmpty())
            {
                stops.add(new Stop(cells[1], null, cells[2]));
                continue;
            }
            int at = Tiles.parse(cells[0]);
            if (at >= 0)
            {
                var p = RouteFeature.worldPoint(at);
                stops.add(Stop.place(cells.length > 1 && !cells[1].isEmpty() ? cells[1] : p.getX() + ", " + p.getY(), p));
            }
        }
        if (name != null)
        {
            tours.add(new Tour(name, stops, loop, avoid));
        }
        return tours.size() > MAX_TOURS ? new ArrayList<>(tours.subList(0, MAX_TOURS)) : tours;
    }

    /** A line's cells, trimmed: parted by tabs, or without any by {@link #SHARED} (a bare "|" counts too). */
    static String[] cells(String line)
    {
        var cells = line.indexOf('\t') >= 0 ? line.split("\t", -1) : line.split("\\s*\\|\\s*", -1);
        for (int i = 0; i < cells.length; i++)
        {
            cells[i] = cells[i].trim();
        }
        return cells;
    }

    /** Without what would part a line's cells or end it. */
    static String clean(String text)
    {
        return text.replaceAll("\\s*[\\t\\r\\n|]+\\s*", " ").trim();
    }

    /**
     * Exact open-path order from place 0 (the player); {@code cost[a][b]} negative means impossible. Returns places
     * 1.. in order, without the start. {@code once[a][b]} (when given) is the trip's cost with a teleport that can be
     * cast once in the route (a home or minigame teleport, with its cooldown): at most one trip takes it, the rest cost
     * {@code cost}.
     */
    static List<Integer> fastestOrder(long[][] cost, long[][] once)
    {
        int n = cost.length - 1;
        if (n <= 0)
        {
            return new ArrayList<>();
        }
        if (n > MAX_STOPS)
        {
            throw new IllegalArgumentException("Too many stops: " + n);
        }
        long unreachable = Long.MAX_VALUE / 4;
        int full = 1 << n;
        // Per set of places visited, last place and whether the once-only teleport was taken (0 or 1).
        long[][][] best = new long[full][n][2];
        int[][][] from = new int[full][n][2];
        for (var row : best)
        {
            for (var used : row)
            {
                Arrays.fill(used, unreachable);
            }
        }
        for (int i = 0; i < n; i++)
        {
            best[1 << i][i][0] = weight(cost[0][i + 1], unreachable);
            from[1 << i][i][0] = -1;
            if (once != null)
            {
                best[1 << i][i][1] = weight(once[0][i + 1], unreachable);
                from[1 << i][i][1] = -1;
            }
        }
        for (int set = 1; set < full; set++)
        {
            for (int last = 0; last < n; last++)
            {
                for (int used = 0; used < 2; used++)
                {
                    long here = best[set][last][used];
                    if ((set & 1 << last) == 0 || here >= unreachable)
                    {
                        continue;
                    }
                    for (int next = 0; next < n; next++)
                    {
                        if ((set & 1 << next) != 0)
                        {
                            continue;
                        }
                        int with = set | 1 << next;
                        long via = here + weight(cost[last + 1][next + 1], unreachable);
                        if (via < best[with][next][used])
                        {
                            best[with][next][used] = via;
                            from[with][next][used] = last << 1 | used;
                        }
                        if (used == 0 && once != null)
                        {
                            long taking = here + weight(once[last + 1][next + 1], unreachable);
                            if (taking < best[with][next][1])
                            {
                                best[with][next][1] = taking;
                                from[with][next][1] = last << 1;
                            }
                        }
                    }
                }
            }
        }
        int end = 0;
        int endUsed = 0;
        for (int last = 0; last < n; last++)
        {
            for (int used = 0; used < 2; used++)
            {
                if (best[full - 1][last][used] < best[full - 1][end][endUsed])
                {
                    end = last;
                    endUsed = used;
                }
            }
        }
        var order = new ArrayList<Integer>();
        int set = full - 1;
        for (int at = end, used = endUsed; at >= 0; )
        {
            order.add(at + 1);
            int previous = from[set][at][used];
            set &= ~(1 << at);
            at = previous < 0 ? -1 : previous >> 1;
            used = previous < 0 ? 0 : previous & 1;
        }
        Collections.reverse(order);
        return order;
    }

    /** Impossible trips weigh a lot but the order still visits everything. */
    static long weight(long cost, long unreachable)
    {
        return cost < 0 ? unreachable / (MAX_STOPS + 2) : cost;
    }
}

package com.hdmapreforged;

import static com.hdmapreforged.SearchResults.*;

import java.awt.*;
import java.awt.datatransfer.*;
import java.io.*;
import java.util.*;
import java.util.List;
import java.util.function.*;
import javax.swing.*;
import lombok.*;
import net.runelite.api.coords.*;
import net.runelite.client.ui.*;

/** The "Custom routes" panel, where the search results show: pick, name, order and run the player's routes. Swing thread. */
@RequiredArgsConstructor
final class TourPanel
{
    interface Actions
    {
        List<Tour> tours();

        String editingName();

        void save(List<Tour> tours, String editing);

        void runTour(Tour tour);

        /**
         * Saves the fastest order if the stops are unchanged, then runs {@code done} even on failure or cancel. With
         * {@code everything}, as if the player had every teleport, transport, level and quest in the game.
         */
        void fastestOrder(Tour tour, boolean everything, Runnable done);

        /** A short message to the player. */
        default void toast(String text)
        {
        }

        /** Puts text on the clipboard; whether it could (another program may hold the clipboard). */
        default boolean copy(String text)
        {
            try
            {
                Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(text), null);
                return true;
            }
            catch (IllegalStateException e)
            {
                return false;
            }
        }

        /** The clipboard's text, or null. */
        default String paste()
        {
            try
            {
                var held = Toolkit.getDefaultToolkit().getSystemClipboard().getContents(null);
                return held != null && held.isDataFlavorSupported(DataFlavor.stringFlavor)
                    ? (String) held.getTransferData(DataFlavor.stringFlavor) : null;
            }
            catch (UnsupportedFlavorException | IOException | IllegalStateException e)
            {
                return null;
            }
        }

        default void cancelOrder()
        {
        }

        String runningTour();

        void clearRoute();
    }

    final Actions actions;
    final Consumer<IntFunction<JComponent>> show;
    final Consumer<WorldPoint> focus;
    @Getter
    boolean open;
    /** While the fastest order is worked out; {@link #orderings} counts runs, so a cancelled one ends nothing. */
    boolean ordering;
    int orderings;

    final String back;

    void toggle()
    {
        if (open)
        {
            close();
        }
        else
        {
            open = true;
            refresh();
        }
    }

    void close()
    {
        open = false;
        cancelOrder();
        show.accept(null);
    }

    /** A search took the card: a fastest order being worked out goes on and is saved. */
    void replaced()
    {
        open = false;
    }

    void cancelOrder()
    {
        if (ordering)
        {
            ordering = false;
            orderings++;
            actions.cancelOrder();
        }
    }

    void refresh()
    {
        if (open)
        {
            show.accept(this::section);
        }
    }

    JComponent section(int width)
    {
        JPanel panel = column();
        var tours = new ArrayList<Tour>(actions.tours());
        Tour current = Tour.named(tours, actions.editingName());

        if (back != null)
        {
            panel.add(tip(link(back, this::close, width), "Back to the list"));
            panel.add(Box.createVerticalStrut(4));
        }

        var which = new JComboBox<String>(tours.stream().map(t -> t.name).toArray(String[]::new));
        which.setSelectedItem(current.name);
        which.addActionListener(e -> {
            Object chosen = which.getSelectedItem();
            if (chosen != null && !chosen.equals(current.name))
            {
                cancelOrder();
                save(tours, chosen.toString());
            }
        });
        which.setMaximumSize(new Dimension(Math.max(100, width - 60), which.getPreferredSize().height));
        panel.add(row(which, button("New", () -> {
            if (tours.size() < Tour.MAX_TOURS)
            {
                String name = Tour.unique(tours, "Route " + (tours.size() + 1));
                tours.add(new Tour(name, new ArrayList<>()));
                save(tours, name);
            }
        })));
        JTextField name = new JTextField(current.name, 14);
        name.setToolTipText("The route's name: type and press Enter");
        FullMapWindow.typable(name);
        name.addActionListener(e -> {
            String typed = name.getText().trim();
            if (!typed.isEmpty() && !typed.equals(current.name))
            {
                var others = new ArrayList<Tour>(tours);
                others.remove(current);
                String unique = Tour.unique(others, typed);
                tours.set(tours.indexOf(current), current.renamed(unique));
                save(tours, unique);
            }
        });
        // The fastest order's answer finds its route by name: renaming meanwhile would drop it.
        name.setEnabled(!ordering);
        name.setMaximumSize(new Dimension(Math.max(100, width - 60), name.getPreferredSize().height));
        JButton delete = button("Delete", () -> {
            tours.remove(current);
            save(tours, tours.isEmpty() ? "My route" : tours.get(0).name);
        });
        // Not while the fastest order is worked out; moving or removing stops neither.
        delete.setEnabled(!ordering);
        add(panel, 4, row(name, delete));
        panel.add(Box.createVerticalStrut(8));

        if (current.stops.isEmpty())
        {
            panel.add(text("No stops yet. Right-click the map, Add to custom route, or + Stop in a card.",
                ColorScheme.LIGHT_GRAY_COLOR, width));
        }
        for (int i = 0; i < current.stops.size(); i++)
        {
            int at = i;
            var stop = current.stops.get(i);
            JPanel line = panel(new BorderLayout(4, 0));
            String label = (i + 1) + ". " + stop.name;
            line.add(current.repeats(i) ? tip(text(label, ColorScheme.MEDIUM_GRAY_COLOR, width - 90),
                "The same as the stop before it: skipped, unless you move it elsewhere")
                : stop.isKind() ? text(label, Color.WHITE, width - 90)
                : link(label, () -> focus.accept(stop.point), width - 90), BorderLayout.CENTER);
            JPanel moves = panel(new FlowLayout(FlowLayout.RIGHT, 2, 0));
            moves.add(small("↑", () -> move(tours, current, at, -1), "Earlier", i > 0));
            moves.add(small("↓", () -> move(tours, current, at, 1), "Later", i < current.stops.size() - 1));
            moves.add(small("✕", () -> {
                current.stops.remove(at);
                save(tours, current.name);
            }, "Remove this stop", true));
            line.add(moves, BorderLayout.EAST);
            panel.add(capped(line));
            panel.add(Box.createVerticalStrut(2));
        }
        JPanel go = row();
        String running = actions.runningTour();
        if (running != null)
        {
            go.add(button("Stop " + running, () -> {
                actions.clearRoute();
                refresh();
            }));
        }
        else if (!current.stops.isEmpty())
        {
            go.add(button("Run", () -> {
                actions.runTour(current);
                refresh();
            }));
        }
        if (current.stops.size() > 1)
        {
            go.add(Box.createHorizontalStrut(4));
            var loop = new JCheckBox("Loop", current.loop);
            loop.setOpaque(false);
            loop.setToolTipText("After the last stop, start again at the first");
            loop.addActionListener(e -> {
                tours.set(tours.indexOf(current), current.looping(loop.isSelected()));
                save(tours, current.name);
            });
            go.add(loop);
        }
        add(panel, 8, go);
        if (current.stops.size() > 1)
        {
            JButton withItems = button(ordering ? "Working it out…" : "Order with current items",
                () -> order(current, false));
            withItems.setEnabled(!ordering);
            JButton fastest = button("Order fastest", () -> order(current, true));
            fastest.setEnabled(!ordering);
            add(panel, 4, row(tip(withItems, "Put the stops in the quickest order from where you are, with the teleports, "
                + "transport and items you have now; a home or minigame teleport is used once at most"),
                tip(fastest, "The quickest order with every teleport and transport in the game, whatever you "
                + "have; a home or minigame teleport is used once at most")));
        }
        JButton export = choice("Export", what -> {
            item(what, "This route", () -> copy(Tour.share(List.of(current)), "\"" + current.name + "\""));
            item(what, "All routes", () -> copy(Tour.share(tours), tours.size() + " routes"));
        });
        export.setEnabled(!current.stops.isEmpty());
        JButton doImport = button("Import", () -> importRoutes(tours));
        doImport.setEnabled(!ordering);
        add(panel, 4, row(tip(export, "Copy the route as text, to keep or to share"),
            tip(doImport, "Add the routes on the clipboard, as Export copies them")));

        if (!current.avoid.isEmpty())
        {
            add(panel, 8, tip(text("Leaves out:", ColorScheme.LIGHT_GRAY_COLOR, width),
                "Ways this route never takes; chosen with ⋯ at a step while the route runs"));
            for (String avoided : new ArrayList<>(current.avoid))
            {
                JPanel line = panel(new BorderLayout(4, 0));
                line.add(text(Tour.describe(avoided), Color.WHITE, width - 40), BorderLayout.CENTER);
                line.add(small("✕", () -> {
                    current.avoid.remove(avoided);
                    save(tours, current.name);
                }, "Use it in this route again", true), BorderLayout.EAST);
                panel.add(capped(line));
            }
        }
        return panel;
    }

    void order(Tour current, boolean everything)
    {
        ordering = true;
        int run = ++orderings;
        refresh();
        actions.fastestOrder(current, everything, () -> {
            if (run == orderings)
            {
                ordering = false;
                refresh();
            }
        });
    }

    void copy(String text, String what)
    {
        actions.toast(actions.copy(text) ? what + " copied to the clipboard" : "Could not copy: the clipboard is in use");
    }

    /** Adds the routes with stops on the clipboard, each under a name not taken; the last added is the one edited. */
    void importRoutes(List<Tour> tours)
    {
        var found = Tour.decode(actions.paste());
        found.removeIf(t -> t.stops.isEmpty());
        if (found.isEmpty())
        {
            actions.toast("Nothing to import: copy a route's text first (Export makes it)");
            return;
        }
        String last = null;
        int added = 0;
        for (Tour t : found)
        {
            if (tours.size() >= Tour.MAX_TOURS)
            {
                break;
            }
            last = Tour.unique(tours, t.name);
            tours.add(t.renamed(last));
            added++;
        }
        if (last != null)
        {
            save(tours, last);
        }
        actions.toast(added < found.size() ? "Only " + Tour.MAX_TOURS + " routes can be kept: " + added + " of "
            + found.size() + " imported" : added == 1 ? "\"" + last + "\" imported" : added + " routes imported");
    }

    /** The menu last opened under a button; a test reads it, as a menu shows only under a shown button. */
    JPopupMenu lastMenu;

    /** A button that opens a menu of choices under itself, filled by {@code choices} when clicked. */
    JButton choice(String text, Consumer<JPopupMenu> choices)
    {
        var made = new JButton[1];
        made[0] = button(text, () -> {
            var menu = new JPopupMenu();
            choices.accept(menu);
            lastMenu = menu;
            if (made[0].isShowing())
            {
                menu.show(made[0], 0, made[0].getHeight());
            }
        });
        return made[0];
    }

    void move(List<Tour> tours, Tour tour, int at, int by)
    {
        int to = at + by;
        if (to < 0 || to >= tour.stops.size())
        {
            return;
        }
        tour.stops.add(to, tour.stops.remove(at));
        save(tours, tour.name);
    }

    void save(List<Tour> tours, String editing)
    {
        actions.save(tours, editing);
        refresh();
    }

    /** A row of {@code parts}, 4 pixels apart. */
    static JPanel row(JComponent... parts)
    {
        JPanel row = panel(null);
        row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
        for (var part : parts)
        {
            if (row.getComponentCount() > 0)
            {
                row.add(Box.createHorizontalStrut(4));
            }
            row.add(part);
        }
        return row;
    }

    /** Enabled when {@code usable} and not while the fastest order is worked out. */
    JButton small(String text, Runnable action, String tip, boolean usable)
    {
        JButton button = tip(button(text, action), tip);
        button.setMargin(new Insets(0, 4, 0, 4));
        button.setEnabled(usable && !ordering);
        return button;
    }

    static JLabel text(String text, Color color, int width)
    {
        return SearchResults.text(text, color, false, Math.max(60, width));
    }

    static JLabel link(String text, Runnable action, int width)
    {
        return clickable(tip(text(text, LINK, width), "Show on the map"), action, false);
    }
}

package com.hdmapreforged;

import static java.util.Locale.ROOT;
import static net.runelite.api.gameval.VarPlayerID.*;

import java.awt.Color;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import java.util.regex.*;
import net.runelite.api.*;

/**
 * The player's levels, finished quests, varbits and varps, taken on the client thread, read from any. What it cannot
 * judge counts as met, so icons are only hidden when a requirement is certainly missing.
 */
final class Unlocks
{
    /** A varbit condition ("4070=0"), or a varp one with a p ("p4130>11999"). */
    static final Pattern VAR = Pattern.compile("(p?)(\\d+)([=<>&])(\\d+)");

    final Map<String, Integer> levels = new HashMap<>();
    final Map<String, Boolean> quests = new HashMap<>();
    /** Quests begun or finished, for a requirement "Swan Song (started)" (a place open during the quest and after). */
    final Map<String, Boolean> started = new HashMap<>();
    static final String STARTED = " (started)";
    final Map<Integer, Integer> varbits = new HashMap<>();
    final Map<Integer, Integer> varps = new HashMap<>();
    final Map<Needs, Boolean> usable = new ConcurrentHashMap<>();
    static final int CACHED = 20_000;
    /** When the last home and minigame teleports were cast, in minutes since 1970 (0: never), as core's timers read them. */
    int lastHome;
    int lastMinigame;
    static final int HOME_WAIT = 30;
    static final int MINIGAME_WAIT = 20;

    /** The quests, varbits and varps the loaded requirements name, worked out once per data load. */
    static final class Watched
    {
        final Set<Quest> quests = new LinkedHashSet<>();
        /** Sorted. */
        final int[] varbits;
        final int[] varps;

        Watched(Collection<Needs> needs)
        {
            var names = new HashSet<String>();
            var ids = new TreeSet<Integer>();
            var varpIds = new TreeSet<Integer>();
            for (Needs need : needs)
            {
                for (String quest : need.quests.split(";"))
                {
                    names.add(quest.trim().toLowerCase(ROOT).replace(STARTED, ""));
                }
                ids(need.varbits, ids, varpIds);
            }
            // Not named by any table: fairy rings without a staff (RouteSource.carried).
            ids.add(LUMBRIDGE_ELITE);
            names.forEach(this::add);
            varbits = ids.stream().mapToInt(Integer::intValue).toArray();
            varps = varpIds.stream().mapToInt(Integer::intValue).toArray();
        }

        void add(String name)
        {
            for (Quest quest : Quest.values())
            {
                if (quest.getName().equalsIgnoreCase(name))
                {
                    quests.add(quest);
                }
            }
        }

        /** Whether this varbit changing can change what is usable. */
        boolean watches(int varbit)
        {
            return Arrays.binarySearch(varbits, varbit) >= 0;
        }

        boolean watchesVarp(int varp)
        {
            return Arrays.binarySearch(varps, varp) >= 0;
        }
    }

    /** Client thread only. Quests run a client script each, so unless {@code checkQuests} they come from {@code previous}. */
    static Unlocks capture(Client client, Watched watched, Unlocks previous, boolean checkQuests)
    {
        var unlocks = new Unlocks();
        for (Skill skill : Skill.values())
        {
            if (!"Overall".equals(skill.getName()))
            {
                unlocks.levels.put(skill.getName().toLowerCase(ROOT), client.getRealSkillLevel(skill));
            }
        }
        unlocks.levels.put("total", client.getTotalLevel());
        // "32 Quest" in a requirement: quest points.
        unlocks.levels.put("quest", client.getVarpValue(QP));
        Player player = client.getLocalPlayer();
        if (player != null)
        {
            unlocks.levels.put("combat", player.getCombatLevel());
        }
        if (checkQuests || previous == null)
        {
            for (Quest quest : watched.quests)
            {
                var state = quest.getState(client);
                String name = quest.getName().toLowerCase(ROOT);
                unlocks.quests.put(name, state == QuestState.FINISHED);
                unlocks.started.put(name, state != QuestState.NOT_STARTED);
            }
        }
        else
        {
            unlocks.quests.putAll(previous.quests);
            unlocks.started.putAll(previous.started);
        }
        unlocks.lastHome = client.getVarpValue(AIDE_TELE_TIMER);
        unlocks.lastMinigame = client.getVarpValue(SLUG2_REGIONUID);
        capture(watched.varbits, client::getVarbitValue, unlocks.varbits);
        capture(watched.varps, client::getVarpValue, unlocks.varps);
        return unlocks;
    }

    /** {@code read(id)} into {@code into}; gone after a game update, or otherwise unknown, counts as met. */
    static void capture(int[] ids, IntUnaryOperator read, Map<Integer, Integer> into)
    {
        for (int id : ids)
        {
            try
            {
                into.put(id, read.applyAsInt(id));
            }
            catch (RuntimeException e)
            {
                // Unknown: counts as met.
            }
        }
    }

    static void ids(String column, Set<Integer> varbits, Set<Integer> varps)
    {
        Matcher matcher = VAR.matcher(column);
        while (matcher.find())
        {
            int id = number(matcher.group(2));
            if (id >= 0)
            {
                (matcher.group(1).isEmpty() ? varbits : varps).add(id);
            }
        }
    }

    /** -1 when too long to be one (a broken line). */
    static int number(String digits)
    {
        return digits.length() <= 9 ? Integer.parseInt(digits) : -1;
    }

    boolean sameAs(Unlocks other)
    {
        return other != null && levels.equals(other.levels) && quests.equals(other.quests) && started.equals(other.started)
            && varbits.equals(other.varbits)
            && varps.equals(other.varps)
            && lastHome == other.lastHome && lastMinigame == other.lastMinigame;
    }

    /** The varps of the teleport timers; a change makes a new capture due. */
    static boolean timesTeleports(int varp)
    {
        return varp == AIDE_TELE_TIMER || varp == SLUG2_REGIONUID;
    }

    /** Whether a home or minigame teleport still waits out its cooldown at this minute (since 1970). */
    boolean waiting(String name, String group, long nowMinutes)
    {
        boolean home = name.toLowerCase(ROOT).contains("home teleport");
        boolean minigame = "Minigame teleports".equals(group);
        return home && lastHome > 0 && nowMinutes - lastHome < HOME_WAIT
            || minigame && lastMinigame > 0 && nowMinutes - lastMinigame < MINIGAME_WAIT;
    }

    /** True, false, or null when this line cannot be checked. */
    Boolean met(Requirements.Line line)
    {
        if (line.skill != null)
        {
            // "130 Attack+Strength": the levels added up (the Warriors' Guild).
            int sum = 0;
            for (String skill : line.skill.split("\\+"))
            {
                Integer level = levels.get(skill.trim().toLowerCase(ROOT));
                if (level == null)
                {
                    return null;
                }
                sum += level;
            }
            return sum >= line.level;
        }
        if (line.quest != null)
        {
            String quest = line.quest.toLowerCase(ROOT);
            if (quest.endsWith(STARTED))
            {
                String name = quest.substring(0, quest.length() - STARTED.length());
                Boolean begun = started.get(name);
                // Finished is begun; not finished alone does not say whether it was begun.
                return begun != null ? begun : Boolean.TRUE.equals(quests.get(name)) ? Boolean.TRUE : null;
            }
            return quests.get(quest);
        }
        return null;
    }

    /** False only when a requirement is certainly not met. */
    /** A quest start icon's dot: green finished, yellow started, red not; null when not read. */
    Color questColor(String name)
    {
        String key = name.toLowerCase(ROOT);
        Boolean done = quests.get(key);
        return done == null ? null : done ? Color.GREEN : Boolean.TRUE.equals(started.get(key)) ? Color.YELLOW
            : Color.RED;
    }

    boolean usable(Needs needs)
    {
        if (needs.isEmpty())
        {
            return true;
        }
        Boolean known = usable.get(needs);
        if (known != null)
        {
            return known;
        }
        boolean result = check(needs);
        if (usable.size() < CACHED)
        {
            usable.put(needs, result);
        }
        return result;
    }

    /** LUMBRIDGE_DIARY_ELITE_COMPLETE: the Lumbridge & Draynor Elite Diary is done. */
    static final int LUMBRIDGE_ELITE = 4498;

    /** Whether the Lumbridge & Draynor Elite Diary is known to be done. */
    boolean lumbridgeElite()
    {
        Integer value = varbits.get(LUMBRIDGE_ELITE);
        return value != null && value == 1;
    }

    boolean check(Needs needs)
    {
        return RouteSource.unmetLines(this, needs).isEmpty() && vars(needs.varbits, varbits, varps);
    }

    /** Conditions like {@code "4070=0;6069<3;4560&2;p4130>11999"} (a p: a varp). */
    static boolean vars(String column, Map<Integer, Integer> varbits, Map<Integer, Integer> varps)
    {
        Matcher matcher = VAR.matcher(column);
        while (matcher.find())
        {
            int id = number(matcher.group(2));
            int wanted = number(matcher.group(4));
            Integer value = id < 0 ? null : (matcher.group(1).isEmpty() ? varbits : varps).get(id);
            if (value == null || wanted < 0)
            {
                continue;
            }
            String op = matcher.group(3);
            boolean ok = op.equals("=") ? value == wanted : op.equals(">") ? value > wanted
                : op.equals("<") ? value < wanted : (value & wanted) != 0;
            if (!ok)
            {
                return false;
            }
        }
        return true;
    }
}

package com.hdmapreforged;

import okhttp3.*;

/** Links that open an OSRS Wiki page in the browser on a click; the plugin never fetches anything from the wiki. */
final class Wiki
{
    static final String WIKI = "https://oldschool.runescape.wiki";

    static String pageUrl(String title)
    {
        return HttpUrl.get(WIKI).newBuilder().addPathSegment("w").addPathSegment(title.replace(' ', '_')).build().toString();
    }

    /** Opens the page directly when the query is an exact title, otherwise the wiki's search results. */
    static String searchUrl(String query)
    {
        return HttpUrl.get(WIKI + "/w/Special:Search").newBuilder().addQueryParameter("search", query).build().toString();
    }
}

package com.hdmapreforged;

import com.google.gson.stream.*;
import java.io.*;
import java.util.*;
import java.util.function.*;
import lombok.*;
import net.runelite.api.coords.*;

/**
 * What the search finds, as our map server works it out once for every player at each wiki sync (its search.json, see
 * {@code MapServer}): each NPC name's places with how many stand there or the way in, the kind most seen and what
 * they drop; each item's shops, spots on the ground and droppers; the shops' wares; the names to suggest; and which
 * map draws each place where maps overlap, for the map version it names. Immutable.
 */
final class WorldData
{
    /** The data version's file read. */
    static final String FILE = "search";
    /** Of search.json: a file in another format (an older or newer map server) is not read. */
    static final int FORMAT = 1;
    static final WorldData NONE = new WorldData(Collections.emptyMap(), Collections.emptyMap(), Collections.emptyList(),
        new String[0], new String[0], null, Collections.emptyMap());
    /** A shop is where the server puts it: a shop icon or a card this near is that shop. */
    static final int SHOP_RADIUS = 12;
    /** The most wares of a shop. */
    static final int MAX_ITEMS = 200;
    static final int MAX_ID = 0xffff;
    static final int MAX_COORDINATE = 0x3fff;
    static final int MAX_COUNT = 1_000_000;
    static final int MAX_WORDS = 24;
    static final int MAX_NAME = 64;
    /** What {@link #number} gives for anything but a number in range. */
    static final int BAD = Integer.MIN_VALUE;
    /** A shop that never runs out. */
    static final int ENDLESS = -1;

    @RequiredArgsConstructor
    static final class Shop
    {
        final String name;
        final WorldPoint point;
        /** Its shopkeeper's NPC id, for the picture; -1 when not known. */
        final int npc;
        /** What it sells, with how many it keeps while no one trades ({@link #ENDLESS}). */
        final List<ItemSources.Ware> wares;
    }

    @RequiredArgsConstructor
    static final class Drop
    {
        final int item;
        /** The game's name of the item. */
        final String name;
        /** As the data words it: "Always", "3/128", "Common". */
        final String rarity;
        /** "5-10", "7"; empty for one. */
        final String quantity;
        /** The part of the drop table: "a" always, "r" the rare drop table, "t" tertiary, "" the main table. */
        final String part;
        /** The monster's version this row is for when not the table's own ("Catacombs of Kourend"); else "". */
        final String version;
    }

    /** One of a monster's drop tables: the monster's version ("Wilderness Slayer Cave"), a kind of loot. */
    @RequiredArgsConstructor
    static final class Table
    {
        /** Empty for a page's only table. */
        final String name;
        final List<Drop> drops;
    }

    final List<Shop> shops;
    /** By {@link #key}. */
    final Map<String, NpcSpawns> npcs;
    final Map<String, ItemSources> items;
    /** The names the suggestions choose from, with their lower-case forms in the same order ({@link #suggestions}). */
    final String[][] npcChoices;
    final String[][] itemChoices;
    /** Lower-case names the search finds: NPCs standing somewhere or with a way in ({@link #monsterName}). */
    final Set<String> monsterNames = new HashSet<>();
    /** The map version {@link #maps} is for; null for none. */
    final String mapVersion;
    /** Which map draws a place where maps overlap, by map id; null for none. */
    final Map<WorldPoint, Integer> maps;
    BaseMaps drawnFor;
    Map<WorldPoint, BaseMap> drawn = Collections.emptyMap();

    WorldData(Map<String, NpcSpawns> npcs, Map<String, ItemSources> items, List<Shop> shops, String[] npcNames,
        String[] itemNames, String mapVersion, Map<WorldPoint, Integer> maps)
    {
        this.npcs = npcs;
        this.items = items;
        this.shops = shops;
        npcChoices = choices(npcNames);
        itemChoices = choices(itemNames);
        monsterNames.addAll(Arrays.asList(npcChoices[1]));
        this.mapVersion = mapVersion;
        this.maps = maps;
    }

    /**
     * search.json, read a row at a time: a row with anything malformed or out of range is left out, and a file broken
     * part-way keeps the rows before the break. Null when it is not search.json in {@link #FORMAT}.
     */
    static WorldData parse(byte[] file)
    {
        var format = new Object[2];
        var npcs = new HashMap<String, NpcSpawns>();
        var items = new HashMap<String, ItemSources>();
        var shops = new ArrayList<Shop>();
        var names = new ArrayList<String[]>(Arrays.asList(new String[0], new String[0]));
        var maps = new HashMap<WorldPoint, Integer>();
        try (var in = new JsonReader(MapServer.text(file)))
        {
            in.beginObject();
            while (in.hasNext())
            {
                switch (in.nextName())
                {
                    case "format":
                        format[0] = value(in);
                        break;
                    case "map":
                        format[1] = value(in);
                        break;
                    case "npcs":
                        rows(in, o -> npc(o, npcs));
                        break;
                    case "items":
                        rows(in, o -> item(o, items));
                        break;
                    case "shops":
                        rows(in, o -> shop(o, shops));
                        break;
                    case "npcNames":
                        names.set(0, texts(value(in)));
                        break;
                    case "itemNames":
                        names.set(1, texts(value(in)));
                        break;
                    case "drawn":
                        rows(in, o -> {
                            int map = number(o.get("map"), -1, MAX_ID);
                            var points = map == BAD ? null : points(o.get("at"));
                            if (points != null)
                            {
                                points.forEach(p -> maps.put(p, map));
                            }
                        });
                        break;
                    case "undrawn":
                        var points = points(value(in));
                        if (points != null)
                        {
                            points.forEach(p -> maps.put(p, null));
                        }
                        break;
                    default:
                        in.skipValue();
                }
            }
        }
        catch (IOException | RuntimeException e)
        {
            // What was read stays: a file broken part-way keeps the rows before the break.
        }
        if (!Double.valueOf(FORMAT).equals(format[0]))
        {
            return null;
        }
        return new WorldData(npcs, items, Collections.unmodifiableList(shops), names.get(0), names.get(1),
            format[1] instanceof String ? (String) format[1] : null, maps);
    }

    /** {@code {name, npc, places: [{at, n | e}], tables: [{v, items}]}}: NPCs of a name, as {@link #spawns} finds them. */
    static void npc(Map<?, ?> o, Map<String, NpcSpawns> npcs)
    {
        String name = text(o, "name");
        int npc = number(o.get("npc"), 0, MAX_ID);
        var groups = new ArrayList<NpcSpawns.Group>();
        for (Object e : list(o, "places"))
        {
            var place = map(e);
            var points = points(place.get("at"));
            String entrance = text(place, "e");
            int seen = number(place.get("n"), 1, MAX_COUNT);
            if (points == null || entrance.length() > MAX_NAME || entrance.isEmpty() && seen == BAD)
            {
                return;
            }
            var group = new NpcSpawns.Group(name, "", points);
            group.entrance = !entrance.isEmpty();
            group.seen = group.entrance ? 0 : seen;
            groups.add(group.withNote(group.entrance ? "Entrance: " + entrance : seen + " here"));
        }
        var tables = new ArrayList<Table>();
        for (Object e : list(o, "tables"))
        {
            String table = text(map(e), "v");
            var drops = drops(map(e));
            if (drops == null || table.length() > MAX_NAME)
            {
                return;
            }
            tables.add(new Table(table, drops));
        }
        if (named(name) && npc != BAD && !groups.isEmpty())
        {
            npcs.put(key(name), new NpcSpawns(name, groups, npc, tables));
        }
    }

    /** {@code [{id, name, r, q, t, v}]}; null when any drop is malformed. */
    static List<Drop> drops(Map<?, ?> o)
    {
        var drops = new ArrayList<Drop>();
        for (Object d : list(o, "items"))
        {
            var drop = map(d);
            int item = number(drop.get("id"), 0, MAX_ID);
            String name = text(drop, "name");
            String rarity = text(drop, "r");
            String quantity = text(drop, "q");
            String part = text(drop, "t");
            String version = text(drop, "v");
            if (item == BAD || !named(name) || rarity.isEmpty() || rarity.length() > MAX_WORDS || quantity.length() > MAX_WORDS
                || part.length() > 1 || !"art".contains(part) || version.length() > MAX_NAME)
            {
                return null;
            }
            drops.add(new Drop(item, name, rarity, quantity, part, version));
        }
        return drops;
    }

    /**
     * {@code {name, id, shops: [{shop, at, n}], ground: [{at, n}], drops: [{npc, name, r, q, v, places, table}]}}: where
     * an item comes from, as {@link #item} finds it.
     */
    static void item(Map<?, ?> o, Map<String, ItemSources> items)
    {
        String name = text(o, "name");
        int item = number(o.get("id"), 0, MAX_ID);
        var stores = new ArrayList<ItemSources.Store>();
        for (Object e : list(o, "shops"))
        {
            var at = points(map(e).get("at"));
            String shop = text(map(e), "shop");
            int stock = stock(map(e).get("n"));
            if (at == null || at.size() != 1 || !named(shop) || stock == 0)
            {
                return;
            }
            stores.add(new ItemSources.Store(shop, at.get(0), stock));
        }
        var grounds = new ArrayList<ItemSources.Ground>();
        for (Object e : list(o, "ground"))
        {
            var at = points(map(e).get("at"));
            int count = number(map(e).get("n"), 1, MAX_COUNT);
            if (at == null || at.size() != 1 || count == BAD)
            {
                return;
            }
            grounds.add(new ItemSources.Ground(at.get(0), count));
        }
        var droppers = new ArrayList<ItemSources.Dropper>();
        for (Object e : list(o, "drops"))
        {
            var d = map(e);
            int npc = number(d.get("npc"), 0, MAX_ID);
            String npcName = text(d, "name");
            String rarity = text(d, "r");
            String quantity = text(d, "q");
            String version = text(d, "v");
            String table = text(d, "table");
            int places = number(d.get("places"), 1, MAX_COUNT);
            if (npc == BAD || !named(npcName) || rarity.isEmpty() || rarity.length() > MAX_WORDS
                || quantity.length() > MAX_WORDS || version.length() > MAX_NAME || table.length() > MAX_NAME || places == BAD)
            {
                return;
            }
            droppers.add(new ItemSources.Dropper(npc, npcName, rarity, version, quantity, places, table));
        }
        if (named(name) && item != BAD && !(stores.isEmpty() && grounds.isEmpty() && droppers.isEmpty()))
        {
            items.put(key(name), new ItemSources(name, item, stores, grounds, droppers));
        }
    }

    /** {@code {name, at, npc, items: [{id, name, n}]}}: a shop with its wares by name. */
    static void shop(Map<?, ?> o, List<Shop> shops)
    {
        String name = text(o, "name");
        var at = points(o.get("at"));
        var listed = list(o, "items");
        var wares = new ArrayList<ItemSources.Ware>();
        for (Object e : listed)
        {
            int item = number(map(e).get("id"), 0, MAX_ID);
            String itemName = text(map(e), "name");
            int stock = stock(map(e).get("n"));
            if (item == BAD || !named(itemName) || stock == 0)
            {
                return;
            }
            wares.add(new ItemSources.Ware(itemName, item, stock));
        }
        if (named(name) && at != null && at.size() == 1 && listed.size() <= MAX_ITEMS)
        {
            shops.add(new Shop(name, at.get(0), Math.max(-1, number(o.get("npc"), 0, MAX_ID)),
                Collections.unmodifiableList(wares)));
        }
    }

    /**
     * Where NPCs of this name stand (whatever its case), close spots as one place with how many stand there, and what
     * they drop; null when none stands anywhere known, as the search finds only those.
     */
    NpcSpawns spawns(String name)
    {
        return npcs.get(key(name));
    }

    /** Where this item comes from: the shops that sell it, where it lies, what drops it; null when nothing is known. */
    ItemSources item(String name)
    {
        return items.get(key(name));
    }

    /** The shop near {@code at}; null when none is known there. */
    Shop shop(WorldPoint at)
    {
        Shop best = null;
        for (Shop shop : shops)
        {
            if (shop.point.distanceTo(at) <= SHOP_RADIUS
                && (best == null || shop.point.distanceTo(at) < best.point.distanceTo(at)))
            {
                best = shop;
            }
        }
        return best;
    }

    /** What the shop near {@code at} sells, with how many it keeps; null when no shop is known there. */
    List<ItemSources.Ware> wares(WorldPoint at)
    {
        Shop shop = shop(at);
        return shop == null ? null : shop.wares;
    }

    /**
     * Which map draws each place where maps overlap, for these maps: none unless they are of the map version the
     * server worked it out for, and then the region table decides alone; a place mapped to null is drawn by none.
     */
    synchronized Map<WorldPoint, BaseMap> drawnBy(BaseMaps baseMaps)
    {
        if (baseMaps != drawnFor)
        {
            drawnFor = baseMaps;
            drawn = new HashMap<>();
            if (baseMaps != null && mapVersion != null && mapVersion.equals(baseMaps.version))
            {
                maps.forEach((point, id) -> {
                    var map = id == null ? null : baseMaps.byId(id);
                    if (id == null || map != null)
                    {
                        drawn.put(point, map);
                    }
                });
            }
        }
        return drawn;
    }

    /**
     * A map label that names a monster or NPC the search finds ("Abyssal demons", "The Nightmare"): the monster search
     * shows where they are, so the place search need not list the label as a place too.
     */
    boolean monsterName(String label)
    {
        String name = label.trim().toLowerCase(Locale.ROOT);
        return monsterNames.contains(name) || name.endsWith("s") && monsterNames.contains(name.substring(0,
            name.length() - 1));
    }

    /** NPC names starting with or containing {@code typed}, starts first. */
    List<String> npcSuggestions(String typed, int limit)
    {
        return suggestions(npcChoices, typed, limit);
    }

    /** Names of items some shop sells, that lie somewhere or that something drops, likewise. */
    List<String> itemSuggestions(String typed, int limit)
    {
        return suggestions(itemChoices, typed, limit);
    }

    /** The names as the server orders them (shortest first, then alphabetically), with their lower-case forms. */
    static String[][] choices(String[] names)
    {
        return new String[][]{names, Arrays.stream(names).map(n -> n.toLowerCase(Locale.ROOT)).toArray(String[]::new)};
    }

    /** Of {@link #choices}, those starting with {@code typed}, then those holding it: one pass, nothing sorted. */
    static List<String> suggestions(String[][] choices, String typed, int limit)
    {
        String t = typed.trim().toLowerCase(Locale.ROOT);
        var starts = new ArrayList<String>();
        var holds = new ArrayList<String>();
        for (int i = 0; i < choices[0].length && starts.size() < limit; i++)
        {
            if (choices[1][i].startsWith(t))
            {
                starts.add(choices[0][i]);
            }
            else if (holds.size() < limit && choices[1][i].contains(t))
            {
                holds.add(choices[0][i]);
            }
        }
        starts.addAll(holds);
        return starts.subList(0, Math.min(limit, starts.size()));
    }

    /** A name as the search compares names: letter by letter without case, as {@code equalsIgnoreCase} does. */
    static String key(String name)
    {
        var letters = name.trim().toCharArray();
        for (int i = 0; i < letters.length; i++)
        {
            letters[i] = Character.toLowerCase(Character.toUpperCase(letters[i]));
        }
        return new String(letters);
    }

    /** Each object of an array in turn, never the whole array at once. */
    static void rows(JsonReader in, Consumer<Map<?, ?>> row) throws IOException
    {
        in.beginArray();
        while (in.hasNext())
        {
            Object o = value(in);
            if (o instanceof Map)
            {
                row.accept((Map<?, ?>) o);
            }
        }
        in.endArray();
    }

    /** A JSON value: numbers as Double, texts, arrays as lists, objects as maps; null for anything else. */
    static Object value(JsonReader in) throws IOException
    {
        return value(in, 0);
    }

    /** Nesting deeper than 32 is skipped, so no answer can run the stack out. */
    static Object value(JsonReader in, int depth) throws IOException
    {
        switch (depth > 32 ? JsonToken.NULL : in.peek())
        {
            case NUMBER:
                return in.nextDouble();
            case STRING:
                return in.nextString();
            case BEGIN_ARRAY:
                var list = new ArrayList<Object>();
                in.beginArray();
                while (in.hasNext())
                {
                    list.add(value(in, depth + 1));
                }
                in.endArray();
                return list;
            case BEGIN_OBJECT:
                var map = new HashMap<String, Object>();
                in.beginObject();
                while (in.hasNext())
                {
                    map.put(in.nextName(), value(in, depth + 1));
                }
                in.endObject();
                return map;
            default:
                in.skipValue();
                return null;
        }
    }

    static Map<?, ?> map(Object e)
    {
        return e instanceof Map ? (Map<?, ?>) e : Collections.emptyMap();
    }

    static List<?> list(Map<?, ?> o, String key)
    {
        return list(o.get(key));
    }

    static List<?> list(Object e)
    {
        return e instanceof List ? (List<?>) e : Collections.emptyList();
    }

    static String text(Map<?, ?> o, String key)
    {
        Object e = o.get(key);
        return e instanceof String ? ((String) e).trim() : "";
    }

    static boolean named(String name)
    {
        return !name.isEmpty() && name.length() <= MAX_NAME;
    }

    /** Texts of a list; none when it is no list of texts. */
    static String[] texts(Object e)
    {
        var list = list(e);
        return list.stream().allMatch(t -> t instanceof String && named((String) t)) ? list.toArray(new String[0])
            : new String[0];
    }

    /** {@code [x, y, plane, ...]}; null when empty or malformed. */
    static List<WorldPoint> points(Object e)
    {
        var at = list(e);
        var points = new ArrayList<WorldPoint>();
        for (int i = 0; i + 2 < at.size(); i += 3)
        {
            int x = number(at.get(i), 0, MAX_COORDINATE);
            int y = number(at.get(i + 1), 0, MAX_COORDINATE);
            int plane = number(at.get(i + 2), 0, 3);
            if (x == BAD || y == BAD || plane == BAD)
            {
                return null;
            }
            points.add(new WorldPoint(x, y, plane));
        }
        return points.isEmpty() || at.size() % 3 != 0 ? null : points;
    }

    /** A stock: {@link #ENDLESS}, or how many; 0 for anything else. */
    static int stock(Object e)
    {
        return Double.valueOf(ENDLESS).equals(e) ? ENDLESS : Math.max(0, number(e, 1, MAX_COUNT));
    }

    /** A whole number from {@code min} to {@code max}; {@link #BAD} for anything else. */
    static int number(Object e, int min, int max)
    {
        double v = e instanceof Double ? (Double) e : Double.NaN;
        return v >= min && v <= max && v == Math.rint(v) ? (int) v : BAD;
    }
}

package com.hdmapreforged;

import com.hdmapreforged.route.*;
import java.util.*;
import java.util.function.*;
import java.util.stream.*;
import lombok.*;
import net.runelite.api.coords.*;

/**
 * Where the game's world map draws part of the game elsewhere (the Kalphite Lair beside the desert caves,
 * floor 2 as floor 0): turns drawn coordinates into the game's own. Also where it draws the floors above a part
 * flat on the ground floor (Keldagrim's houses). From the map version's {@code world_map_moves.tsv}.
 */
final class WorldMapMoves
{
    @RequiredArgsConstructor
    static final class Move
    {
        final int map;
        final int x;
        final int y;
        final int width;
        final int height;
        final int dx;
        final int dy;
        final int plane;
        final int planes;
    }

    /**
     * Every part listed, in the file's order, the ones drawn where they are with floors drawn flat too: for
     * {@link #floorsDrawnFlat}. Map id, x y width height, dx dy floor [floors].
     */
    static final RouteFiles.Table<List<Move>> ALL = new RouteFiles.Table<>(() -> Pathfinder.table(RouteFiles.DIR
        + "world_map_moves.tsv", c -> {
            var v = Pathfinder.ints(String.join(" ", c));
            return new Move(v[0], v[1], v[2], v[3], v[4], v[5], v[6], v[7], v.length > 8 ? v[8] : 1);
        }));
    /** The parts drawn elsewhere. */
    static final RouteFiles.Table<List<Move>> MOVES = new RouteFiles.Table<>(() -> ALL.get().stream()
        .filter(move -> move.dx != 0 || move.dy != 0 || move.plane != 0).collect(Collectors.toList()));

    /** The last move that fits: whole map squares are listed before zones, so a zone's (finer) wins, as in the game. */
    static Move last(Predicate<Move> fits)
    {
        return last(MOVES.get(), fits);
    }

    static Move last(List<Move> moves, Predicate<Move> fits)
    {
        for (int i = moves.size() - 1; i >= 0; i--)
        {
            Move move = moves.get(i);
            if (fits.test(move))
            {
                return move;
            }
        }
        return null;
    }

    static WorldPoint toWorld(int mapId, WorldPoint drawn)
    {
        Move found = last(move -> move.map == mapId && inside(move, drawn.getX(), drawn.getY()));
        if (found == null)
        {
            return drawn;
        }
        int plane = found.plane + Math.min(drawn.getPlane(), found.planes - 1);
        return new WorldPoint(drawn.getX() + found.dx, drawn.getY() + found.dy, Math.min(3, plane));
    }

    /** As the map of everything draws them: a moved part is drawn where its own map draws it. */
    static WorldPoint fromDrawnAnywhere(WorldPoint drawn)
    {
        Move found = last(move -> inside(move, drawn.getX(), drawn.getY()));
        return found == null ? drawn : toWorld(found.map, drawn);
    }

    /** Whether map {@code mapId} draws a moved part of the game at this spot (the Dagannoth Kings' lair). */
    static boolean covers(int mapId, int x, int y)
    {
        return last(move -> move.map == mapId && inside(move, x, y)) != null;
    }

    @RequiredArgsConstructor
    static final class Drawn
    {
        final int map;
        final WorldPoint point;
    }

    static WorldPoint toDrawn(int mapId, WorldPoint game)
    {
        Move found = last(move -> move.map == mapId && moves(move, game));
        return found == null ? null : drawnBy(found, game);
    }

    static Drawn drawn(WorldPoint game)
    {
        Move found = last(move -> moves(move, game));
        return found == null ? null : new Drawn(found.map, drawnBy(found, game));
    }

    static boolean moves(Move move, WorldPoint game)
    {
        int floor = game.getPlane() - move.plane;
        return inside(move, game.getX() - move.dx, game.getY() - move.dy) && floor >= 0 && floor < move.planes;
    }

    static boolean inside(Move move, int x, int y)
    {
        return x >= move.x && x < move.x + move.width && y >= move.y && y < move.y + move.height;
    }

    static WorldPoint drawnBy(Move move, WorldPoint game)
    {
        return new WorldPoint(game.getX() - move.dx, game.getY() - move.dy, game.getPlane() - move.plane);
    }

    /**
     * How many floors a map draws flat on a drawn spot, as the game's own map does (Keldagrim's houses, the God Wars
     * boss rooms' three floors): 1 where only the floor drawn there shows, every other floor there being another place.
     * The map of everything draws each part as the part's own map does: ask with that map's id.
     */
    static int floorsDrawnFlat(int mapId, int x, int y)
    {
        Move found = last(ALL.get(), move -> move.map == mapId && inside(move, x, y));
        return found == null ? 1 : found.planes;
    }
}

package com.hdmapreforged.route;

import static com.hdmapreforged.route.Route.Outcome.*;

import java.util.*;
import java.util.function.*;
import java.util.regex.*;
import lombok.*;

/**
 * A way past a bank first, for teleports and transport kept in the bank (setting, with the bank as last seen): to the
 * nearest of a few banks with what is carried, take out what the rest needs, and on from there with the bank's items
 * too. Taken instead of the way with what is carried only when it gets there notably sooner, or only it gets there.
 */
@RequiredArgsConstructor
public final class BankDetour
{
    /** How a step's detail starts when it needs something only the bank has (RouteSource names it). */
    public static final String FROM_BANK = "From the bank: ";

    /** Joins the name of the teleport or transport that takes one to the bank to what is taken there ("... Castle Wars → Bank: Dramen staff"). */
    public static final String TO_BANK = " → Bank: ";

    /** A step's name without {@link #TO_BANK} and what follows: what it is left out of a route by. */
    public static String plain(String name)
    {
        int at = name == null ? -1 : name.lastIndexOf(TO_BANK);
        return at < 0 ? name : name.substring(0, at);
    }

    /** Half ticks to open the bank and take things out. */
    static final int WITHDRAW = 6;

    /**
     * Per bank, where to stand at it: beside each of its booths or chests, nearest its icon first (or the icon). The few
     * banks quickest to reach are tried, each at its first; the way in then goes where the game walks from where it comes in.
     */
    final int[][] banks;
    /** The same search with the bank's items as well. */
    final RouteRequest withBank;
    /** Half ticks it must save: the setting's tiles, run. */
    final int saves;
    /** What the rune pouch in the bank holds, by name: taken as the pouch. */
    final Map<String, Long> pouch;

    /** The route for {@code request}: past a bank when its {@link RouteRequest#bank} makes it notably quicker. */
    public static Route find(Pathfinder pathfinder, RouteRequest request, BooleanSupplier cancelled)
    {
        Route plain = pathfinder.find(request, cancelled);
        var detour = request.bank;
        if (detour == null || plain.outcome == CANCELLED || cancelled.getAsBoolean())
        {
            return plain;
        }
        Route banked = detour.route(pathfinder, request, cancelled);
        boolean better = banked != null && (plain.outcome != FOUND
            || banked.cost + detour.saves <= plain.cost);
        return better && !cancelled.getAsBoolean() ? banked : plain;
    }

    /** To the nearest bank, then on with the bank's items; null when no bank is reached or nothing banked is used. */
    Route route(Pathfinder pathfinder, RouteRequest request, BooleanSupplier cancelled)
    {
        Route toBank = null;
        int[] stands = null;
        for (int bank : quickest(request))
        {
            Route way = pathfinder.find(request.between(request.start, banks[bank][0]), cancelled);
            if (way.outcome == FOUND && (toBank == null || way.cost < toBank.cost))
            {
                toBank = way;
                stands = banks[bank];
            }
        }
        if (toBank == null || cancelled.getAsBoolean())
        {
            return null;
        }
        int nearer = stand(pathfinder.map, stands, entry(toBank, stands[0]));
        if (nearer != stands[0])
        {
            // Another booth or side of the same bank, where the game walks from where the way comes in.
            Route way = pathfinder.find(request.between(request.start, nearer), cancelled);
            toBank = way.outcome == FOUND ? way : toBank;
        }
        int at = toBank.end >= 0 ? toBank.end : toBank.target;
        Route on = pathfinder.find(withBank.between(at, request.target), cancelled);
        if (on.outcome != FOUND)
        {
            return null;
        }
        // Only what the bank's items add (not a ladder or cave on the way, which no item opens).
        var fromBank = new HashSet<String>();
        // Not the ways back into one's house, which the plain search from inside it lacks: no item of the bank opens them.
        withBank.startEdges.stream().filter(e -> !HousePlan.contains(e.to)).forEach(e -> fromBank.add(e.name));
        withBank.edges.stream().filter(e -> !HousePlan.contains(e.to)).forEach(e -> fromBank.add(e.name));
        request.startEdges.forEach(e -> fromBank.remove(e.name));
        request.edges.forEach(e -> fromBank.remove(e.name));
        var take = new LinkedHashSet<String>();
        for (var step : on.steps)
        {
            String named = step.detail != null && step.detail.startsWith(FROM_BANK)
                ? step.detail.substring(FROM_BANK.length()) : null;
            // "items": the game had not named them yet.
            if (named != null && !named.equals("items"))
            {
                take.addAll(Arrays.asList(named.split(", ")));
            }
            else if (named != null || step.isJump() && fromBank.contains(step.name))
            {
                take.add(taken(step));
            }
        }
        if (take.isEmpty())
        {
            return null;
        }
        var taken = viaPouch(take);
        String items = String.join(", ", taken);
        var steps = new ArrayList<Route.Step>(toBank.steps);
        // The last teleport or transport on the way names what is taken at the bank.
        for (int i = steps.size() - 1; i >= 0; i--)
        {
            var s = steps.get(i);
            if (s.isJump() && s.name != null)
            {
                steps.set(i, s.withName(s.name + TO_BANK + items));
                break;
            }
        }
        steps.add(new Route.Step(Route.Step.Kind.BANK, new int[]{at, at}, "Bank: " + items, null,
            WITHDRAW, 0, List.of(), null));
        for (var s : on.steps)
        {
            // What the steps name from the bank: the pouch's runes as the pouch, as the bank step does.
            steps.add(s.detail != null && s.detail.startsWith(FROM_BANK)
                ? s.withDetail(FROM_BANK + String.join(", ", viaPouch(Arrays.asList(
                    s.detail.substring(FROM_BANK.length()).split(", "))))) : s);
        }
        return new Route(FOUND, steps, toBank.cost + WITHDRAW + on.cost, request.target, on.end, false,
            false, toBank.nodes + on.nodes);
    }

    /** What is taken: runes the pouch holds enough of (a combination rune in it counts as its two) as "Rune pouch". */
    Set<String> viaPouch(Collection<String> take)
    {
        var held = new HashMap<String, Long>();
        pouch.forEach((name, n) -> {
            if (name == null)
            {
                return;
            }
            String lower = name.toLowerCase(Locale.ROOT);
            held.merge(lower, n, Long::sum);
            for (var c : COMBINED.get())
            {
                if (lower.equals(c[0] + " rune"))
                {
                    held.merge(c[1] + " rune", n, Long::sum);
                    held.merge(c[2] + " rune", n, Long::sum);
                }
            }
        });
        var taken = new LinkedHashSet<String>();
        for (String t : take)
        {
            var m = AMOUNT.matcher(t);
            taken.add(m.matches() && held.getOrDefault(m.group(2).toLowerCase(Locale.ROOT), 0L) >= (m.group(1) == null
                ? 1 : Long.parseLong(m.group(1))) ? "Rune pouch" : t);
        }
        return taken;
    }

    /** Combination runes and the two runes each holds (list "combination runes"). */
    static final RouteFiles.Table<String[][]> COMBINED = new RouteFiles.Table<>(() -> Pathfinder.list(
        "combination runes", r -> r.split(" ")).stream().filter(c -> c.length > 2).toArray(String[][]::new));

    static final Pattern AMOUNT = Pattern.compile("(?:(\\d+) × )?(.+)");

    /** Tiles from a booth within which a way counts as come into its bank. */
    static final int ENTRY = 8;

    /** Where {@code way} first comes within {@link #ENTRY} tiles of {@code stand} on its floor; else its end. */
    static int entry(Route way, int stand)
    {
        for (var step : way.steps)
        {
            for (int point : step.kind == Route.Step.Kind.WALK ? step.points : new int[0])
            {
                if (Tiles.near(point, stand, ENTRY))
                {
                    return point;
                }
            }
        }
        return way.end >= 0 ? way.end : stand;
    }

    /**
     * Of {@code stands}, where the game walks from {@code point} to use the bank: the first its search reaches (it tries
     * west, east, south, north, then the diagonals, so not always the nearest side), else the first.
     */
    static int stand(CollisionMap map, int[] stands, int point)
    {
        int[] walk = GameWalk.path(map, point, stands);
        return walk == null ? stands[0] : walk[walk.length - 1];
    }

    /** Half ticks a guess adds for leaving the house before a teleport cast outside it. */
    static final int OUT_OF_HOUSE = 12;

    /** Banks searched for the way to one: the quickest by {@link #guess}. */
    static final int TRIED = 3;

    /**
     * The {@link #TRIED} banks (indices) quickest to reach by a guess (no search): from where the player stands (not in a house,
     * whose plan lies far off the map) and from where each way out of it lands (a teleport, a house's portal, box or
     * glory), its time plus the run on in a straight line (a tile a half tick). Underground and above are apart, so a
     * bank 6400 tiles north is not counted as near.
     */
    int[] quickest(RouteRequest request)
    {
        var from = new ArrayList<int[]>();
        int start = request.start;
        if (start >= 0 && !HousePlan.contains(start))
        {
            from.add(new int[]{start, 0});
        }
        // Ways into the house (from outside it) come before any way out of it: its time, then the walk in the plan.
        var in = new ArrayList<int[]>();
        for (Edge e : request.startEdges)
        {
            from.add(new int[]{e.to, e.cost});
            if (start >= 0 && HousePlan.contains(e.to))
            {
                in.add(new int[]{e.to, e.cost});
            }
        }
        for (Edge e : request.edges)
        {
            // Out of one's house: its portals, the box, the glory and the like; a teleport cast once out of it (a
            // minigame teleport by the house portal).
            if (e.from >= 0 && (e.kind == Edge.Kind.TELEPORT || HousePlan.contains(e.from)
                && !HousePlan.contains(e.to)))
            {
                int enter = start >= 0 && !HousePlan.contains(start) ? Integer.MAX_VALUE / 4 : 0;
                for (int[] i : in)
                {
                    enter = Math.min(enter, i[1] + Tiles.distance(i[0], e.from) * Pathfinder.RUN);
                }
                from.add(new int[]{e.to, e.cost + (e.kind == Edge.Kind.TELEPORT ? OUT_OF_HOUSE : enter)});
            }
        }
        long[] guessed = new long[banks.length];
        for (int i = 0; i < banks.length; i++)
        {
            guessed[i] = (long) guess(from, banks[i][0]) << 32 | i;
        }
        Arrays.sort(guessed);
        return Arrays.stream(guessed, 0, Math.min(TRIED, banks.length)).mapToInt(g -> (int) g).toArray();
    }

    /** Half ticks from the nearest of {@code from} ({tile, half ticks to get there}) to the bank, as the crow flies. */
    static int guess(List<int[]> from, int bank)
    {
        int best = Integer.MAX_VALUE / 2;
        for (var f : from)
        {
            if (f[0] >= 0 && Tiles.y(f[0]) / 6400 == Tiles.y(bank) / 6400)
            {
                best = Math.min(best, f[1] + Tiles.distance(f[0], bank) * Pathfinder.RUN);
            }
        }
        return best;
    }

    /**
     * What a step takes from the bank when its items are not named (a house's fairy ring): "runes" for a spell, the item
     * of a teleport ("Ring of dueling"), else "items for" what it is ("items for Fairy ring").
     */
    public static String taken(Route.Step step)
    {
        String name = step.name;
        int arrow = name.indexOf(" → ");
        name = arrow > 0 ? name.substring(0, arrow) : name;
        int colon = name.indexOf(": ");
        String what = colon > 0 ? name.substring(0, colon) : name;
        return step.category != null && step.category.endsWith("Spellbook") ? "runes"
            : step.kind == Route.Step.Kind.TELEPORT || step.kind == Route.Step.Kind.HOUSE ? what : "items for " + what;
    }
}

package com.hdmapreforged.route;

import java.io.*;
import java.util.*;
import java.util.function.*;
import java.util.zip.*;
import lombok.*;

/**
 * Where one can walk, from the bundled collision.zip: per region and floor, bitsets of walkable tiles and of walls and
 * doors on the north and east edges. Immutable after loading but for one's own house ({@link #setHouse}, replaced
 * whole), so any thread may read it.
 */
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
public final class CollisionMap
{
    public static final String RESOURCE = RouteFiles.DIR + "collision.zip";
    static final int MAGIC = 0x48444d43;
    static final int WALK = 0;
    static final int WALL_N = 64;
    static final int WALL_E = 128;
    static final int DOOR_N = 192;
    static final int DOOR_E = 256;
    static final int LAYERS = 320;
    static final int MAX_BIN_BYTES = 64 * 1024 * 1024;
    static final int MAX_TABLE_BYTES = 16 * 1024 * 1024;

    /** By {@code region * 4 + plane}: five bitsets of 64 longs, or null. */
    final long[][] floors = new long[1 << 18][];
    final List<Transition> transitions;
    /** By packed tile: "Chop-down Vines (bring an axe)". */
    final Map<Integer, String> obstacles;
    final boolean[] obstacleRegions = new boolean[1 << 16];
    /** One's own house, where no map of the game lies; replaced whole. */
    @Setter
    volatile HousePlan house;

    public static CollisionMap load() throws IOException
    {
        try (InputStream in = RouteFiles.require(RESOURCE))
        {
            return read(in);
        }
    }

    public static CollisionMap read(InputStream zipped) throws IOException
    {
        byte[] bin = null;
        var transitions = new ArrayList<Transition>();
        var obstacles = new HashMap<Integer, String>();
        var zip = new ZipInputStream(zipped);
        ZipEntry entry;
        while ((entry = zip.getNextEntry()) != null)
        {
            if ("collision.bin".equals(entry.getName()))
            {
                bin = RouteFiles.read(zip, MAX_BIN_BYTES, "collision.bin");
            }
            else if ("transitions.tsv".equals(entry.getName()))
            {
                Pathfinder.rows(new ByteArrayInputStream(RouteFiles.read(zip, MAX_TABLE_BYTES, "transitions.tsv")), 1, line -> {
                    Transition t = Transition.parse(line[0]);
                    if (t != null)
                    {
                        transitions.add(t);
                    }
                });
            }
            else if ("obstacles.tsv".equals(entry.getName()))
            {
                Pathfinder.rows(new ByteArrayInputStream(RouteFiles.read(zip, MAX_TABLE_BYTES, "obstacles.tsv")), 0,
                    parts -> obstacle(obstacles, parts));
            }
        }
        if (bin == null)
        {
            throw new IOException("No collision.bin");
        }
        var map = new CollisionMap(Collections.unmodifiableList(transitions), obstacles);
        obstacles.keySet().forEach(node -> map.obstacleRegions[region(Tiles.x(node), Tiles.y(node))] = true);
        map.decode(bin);
        return map;
    }

    void decode(byte[] bin) throws IOException
    {
        var in = new DataInputStream(new ByteArrayInputStream(bin));
        if (in.readInt() != MAGIC || in.readInt() != 1)
        {
            throw new IOException("Unknown collision data");
        }
        int count = in.readInt();
        if (count < 0 || count > 1 << 16)
        {
            throw new IOException("Bad region count " + count);
        }
        for (int i = 0; i < count; i++)
        {
            int region = in.readUnsignedShort();
            int mask = in.readUnsignedByte();
            for (int z = 0; z < 4; z++)
            {
                if ((mask & 1 << z) != 0)
                {
                    floors[region << 2 | z] = longs(in, LAYERS);
                }
            }
            // Ground floor water: only the development tools use it.
            in.skipBytes((mask & 16) != 0 ? 64 * 8 : 0);
        }
    }

    static long[] longs(DataInputStream in, int count) throws IOException
    {
        long[] longs = new long[count];
        for (int j = 0; j < count; j++)
        {
            longs[j] = in.readLong();
        }
        return longs;
    }

    /** The region of a tile, or -1 off the world. */
    static int region(int x, int y)
    {
        return (x | y) >>> 14 == 0 ? (x >> 6) << 8 | (y >> 6) : -1;
    }

    /** "x y plane <tab> name <tab> action <tab> what it takes"; bad lines are skipped. */
    static void obstacle(Map<Integer, String> obstacles, String[] parts)
    {
        if (parts.length < 4)
        {
            return;
        }
        int at = Tiles.parse(parts[0]);
        if (at < 0)
        {
            return;
        }
        String action = parts[2].isEmpty() ? parts[2] : Character.toUpperCase(parts[2].charAt(0)) + parts[2].substring(1);
        obstacles.put(at, action + " " + parts[1] + " (bring " + parts[3] + ")");
    }

    public List<Transition> transitions()
    {
        return transitions;
    }

    public String obstacle(int node)
    {
        return isObstacle(Tiles.x(node), Tiles.y(node), node) ? obstacles.get(node) : null;
    }

    public boolean isObstacle(int x, int y, int node)
    {
        int region = region(x, y);
        return region >= 0 && obstacleRegions[region] && obstacles.containsKey(node);
    }

    long[] layers(int x, int y, int z)
    {
        int region = region(x, y);
        var found = region < 0 || z < 0 || z > 3 ? null : floors[region << 2 | z];
        var plan = found == null && region >= 0 && z >= 0 && z <= 3 ? house : null;
        return plan != null ? plan.layers(region, z) : found;
    }

    public HousePlan house()
    {
        return house;
    }

    static boolean bit(long[] layers, int offset, int x, int y)
    {
        int i = (x & 63) << 6 | (y & 63);
        return (layers[offset + (i >> 6)] & 1L << (i & 63)) != 0;
    }

    public boolean walkable(int x, int y, int z)
    {
        return edge(x, y, z, WALK);
    }

    boolean edge(int x, int y, int z, int offset)
    {
        var layers = layers(x, y, z);
        return layers != null && bit(layers, offset, x, y);
    }

    public boolean canStep(int x, int y, int z, int dx, int dy)
    {
        if (!walkable(x + dx, y + dy, z))
        {
            return false;
        }
        if (dx != 0 && dy != 0)
        {
            // Diagonal: both straight routes around the corner must be open, and no door on the way.
            return walkable(x + dx, y, z) && walkable(x, y + dy, z) && clear(x, y, z, dx, 0) && clear(x + dx, y, z, 0, dy)
                && clear(x, y, z, 0, dy) && clear(x, y + dy, z, dx, 0);
        }
        return straightOpen(x, y, z, dx, dy);
    }

    boolean straightOpen(int x, int y, int z, int dx, int dy)
    {
        return !crosses(x, y, z, dx, dy, WALL_N, WALL_E);
    }

    boolean clear(int x, int y, int z, int dx, int dy)
    {
        return straightOpen(x, y, z, dx, dy) && !door(x, y, z, dx, dy);
    }

    public boolean door(int x, int y, int z, int dx, int dy)
    {
        return (dx == 1 || dx == -1 || dy == 1 || dy == -1) && crosses(x, y, z, dx, dy, DOOR_N, DOOR_E);
    }

    boolean crosses(int x, int y, int z, int dx, int dy, int north, int east)
    {
        return dx == 1 ? edge(x, y, z, east) : dx == -1 ? edge(x - 1, y, z, east)
            : dy == 1 ? edge(x, y, z, north) : edge(x, y - 1, z, north);
    }

    /** Nearest walkable tile within {@code radius} (Chebyshev rings, then straight distance), packed, or -1. */
    public int nearestWalkable(int x, int y, int z, int radius)
    {
        return nearestWalkable(x, y, z, radius, x, y);
    }

    /** Ties go farthest from {@code (awayX, awayY)}: a shortcut's near side, not a pocket between its stones. */
    public int nearestWalkable(int x, int y, int z, int radius, int awayX, int awayY)
    {
        return nearestWalkable(x, y, z, radius, awayX, awayY, null);
    }

    /** The same, but tiles {@code avoid} names (a shut-in pocket) only when no other is within reach. */
    public int nearestWalkable(int x, int y, int z, int radius, int awayX, int awayY, IntPredicate avoid)
    {
        int plain = nearest(x, y, z, radius, awayX, awayY, null);
        if (avoid == null || plain < 0 || !avoid.test(plain))
        {
            return plain;
        }
        int open = nearest(x, y, z, radius, awayX, awayY, avoid);
        return open >= 0 ? open : plain;
    }

    int nearest(int x, int y, int z, int radius, int awayX, int awayY, IntPredicate avoid)
    {
        for (int r = 0; r <= radius; r++)
        {
            int best = -1;
            double bestDistance = Double.MAX_VALUE;
            for (int dx = -r; dx <= r; dx++)
            {
                for (int dy = -r; dy <= r; dy++)
                {
                    if (Math.max(Math.abs(dx), Math.abs(dy)) != r || !walkable(x + dx, y + dy, z)
                        || avoid != null && avoid.test(Tiles.pack(x + dx, y + dy, z)))
                    {
                        continue;
                    }
                    double away = (x + dx - awayX) * (double) (x + dx - awayX) + (y + dy - awayY) * (double) (y + dy - awayY);
                    double d = (dx * dx + dy * dy) * 1e6 - away;
                    if (d < bestDistance)
                    {
                        bestDistance = d;
                        best = Tiles.pack(x + dx, y + dy, z);
                    }
                }
            }
            if (best >= 0)
            {
                return best;
            }
        }
        return -1;
    }
}

package com.hdmapreforged.route;

import lombok.*;

/** A non-walking jump in the route graph; costs in half game ticks. */
@AllArgsConstructor(access = AccessLevel.PRIVATE)
public final class Edge
{
    public enum Kind
    {
        STAIRS,
        ENTRANCE,
        TELEPORT,
        TRANSPORT,
        SHIP,
        BOARD,
        DISEMBARK,
        HOUSE
    }

    public static final int ANYWHERE = -1;

    /** {@code withFrom}: the same from another start. */
    @With
    public final int from;
    public final int to;
    public final Kind kind;
    public final String name;
    public final String detail;
    /** As the search weighs it: {@link #time} plus any extra the player asked for. */
    @With(AccessLevel.PRIVATE)
    public final int cost;
    public final int time;
    public final String category;

    public Edge(int from, int to, Kind kind, String name, String detail, int cost)
    {
        this(from, to, kind, name, detail, cost, null);
    }

    public Edge(int from, int to, Kind kind, String name, String detail, int cost, String category)
    {
        this(from, to, kind, name, detail, Math.max(1, cost), Math.max(1, cost), category);
    }

    /** Heavier in the search only ("only use a teleport when it saves at least 10 tiles"). */
    public Edge weighed(int extra)
    {
        return extra <= 0 ? this : withCost(cost + extra);
    }

    public String toString()
    {
        return kind + " " + name + " " + (from == ANYWHERE ? "anywhere" : Tiles.format(from)) + " -> " + Tiles.format(to);
    }
}

package com.hdmapreforged.route;

import lombok.*;
import java.util.*;

/**
 * The jumps starting (or ending) at each node, as indices into a list of edges; looked up without boxing. Immutable
 * once made.
 */
@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
final class EdgeIndex
{
    final IntMap slots;
    final int[][] lists;

    static EdgeIndex of(List<Edge> edges, int offset, boolean byDestination)
    {
        var slots = new IntMap(edges.size());
        int count = 0;
        int[] counts = new int[edges.size()];
        for (Edge e : edges)
        {
            int key = byDestination ? e.to : e.from;
            if (key == Edge.ANYWHERE)
            {
                continue;
            }
            int slot = slots.get(key);
            if (slot == IntMap.MISSING)
            {
                slot = count++;
                slots.put(key, slot);
            }
            counts[slot]++;
        }
        int[][] made = new int[count][];
        for (int i = 0; i < made.length; i++)
        {
            made[i] = new int[counts[i]];
            counts[i] = 0;
        }
        for (int i = 0; i < edges.size(); i++)
        {
            int key = byDestination ? edges.get(i).to : edges.get(i).from;
            if (key != Edge.ANYWHERE)
            {
                int slot = slots.get(key);
                made[slot][counts[slot]++] = offset + i;
            }
        }
        return new EdgeIndex(slots, made);
    }

    int[] get(int node)
    {
        int slot = slots.get(node);
        return slot == IntMap.MISSING ? null : lists[slot];
    }
}

package com.hdmapreforged.route;

import java.util.*;
import lombok.*;

/** Entrance fees the plugin cannot check ({@code fees.tsv}), weighed as extra time so a free way wins. */
public final class Fees
{
    static final int NEAR = 2;

    @RequiredArgsConstructor
    public static final class Fee
    {
        final int x;
        final int y;
        final int plane;
        /** Extra half ticks. */
        public final int cost;
        public final String text;
    }

    static final RouteFiles.Table<List<Fee>> FEES = new RouteFiles.Table<>(Fees::load);

    public static Fee at(int x, int y, int plane)
    {
        return FEES.get().stream().filter(fee -> fee.plane == plane && Math.abs(fee.x - x) <= NEAR
            && Math.abs(fee.y - y) <= NEAR).findFirst().orElse(null);
    }

    static List<Fee> load()
    {
        return Pathfinder.table(RouteFiles.DIR + "fees.tsv", parts -> {
            var xyz = Pathfinder.ints(parts[0]);
            return new Fee(xyz[0], xyz[1], xyz[2], Integer.parseInt(parts[1].trim()), parts[2].trim());
        });
    }
}

package com.hdmapreforged.route;

import static java.lang.Math.*;
import static com.hdmapreforged.route.Tiles.*;

import java.util.*;

/**
 * Walking the way the game walks: a breadth-first search over 128×128 tiles around the player with directions in a
 * fixed order, so the drawn route lies on the tiles the player really walks.
 */
public final class GameWalk
{
    static final int HALF = 64;
    /** Well inside the search area. */
    static final int PIECE = 48;
    static final int[] DX = {-1, 1, 0, 0, -1, 1, -1, 1};
    static final int[] DY = {0, 0, -1, 1, -1, -1, 1, 1};

    /** A route's walk as the game would take it; pieces the game cannot do as short keep the route's tiles. */
    public static int[] follow(CollisionMap map, int[] points)
    {
        if (points.length < 3 || isSea(points[0]))
        {
            return points;
        }
        int[] out = new int[points.length * 2];
        int n = 0;
        out[n++] = points[0];
        int i = 0;
        while (i < points.length - 1)
        {
            int j = i + 1;
            while (j + 1 < points.length && z(points[j + 1]) == z(points[i])
                && distance(points[i], points[j + 1]) <= PIECE)
            {
                j++;
            }
            var piece = z(points[j]) == z(points[i]) ? path(map, out[n - 1], points[j]) : null;
            if (piece == null || piece.length > j - i + 1 || newObstacle(map, piece, points, i, j))
            {
                piece = Arrays.copyOfRange(points, i, j + 1);
            }
            if (n + piece.length > out.length)
            {
                out = Arrays.copyOf(out, (n + piece.length) * 2);
            }
            System.arraycopy(piece, 1, out, n, piece.length - 1);
            n += piece.length - 1;
            i = j;
        }
        return Arrays.copyOf(out, n);
    }

    /** How far ahead one run pair (straight, then diagonal) is looked for. */
    static final int RUN = 64;

    /**
     * The walk in as few runs as the ground allows, as a player walks it: from each tile to the farthest one ahead that
     * one straight run and then one diagonal run reach in as many steps, so no time changes. That is the game's walk to
     * a clicked tile in the open: its search tries west, east, south, north before the diagonals, so the path goes
     * straight along the longer axis first, then diagonally; never diagonally first. Not through a door or onto an
     * obstacle the walk kept clear of.
     */
    static int[] straighten(CollisionMap map, int[] points)
    {
        if (points.length < 3 || isSea(points[0]))
        {
            return points;
        }
        int[] out = new int[points.length];
        int n = 0;
        out[n++] = points[0];
        int i = 0;
        while (i < points.length - 1)
        {
            int[] best = null;
            int to = i + 1;
            for (int j = min(points.length - 1, i + RUN); j > i + 1 && best == null; j--)
            {
                best = runs(map, points, i, j);
                to = j;
            }
            if (best == null)
            {
                out[n++] = points[i + 1];
                i++;
                continue;
            }
            System.arraycopy(best, 1, out, n, best.length - 1);
            n += best.length - 1;
            i = to;
        }
        return Arrays.copyOf(out, n);
    }

    /**
     * From {@code points[i]} to {@code points[j]} by one straight run and then one diagonal run, in exactly
     * {@code j - i} steps over walkable ground, crossing no door and stepping on no obstacle that {@code points[i..j]}
     * does not; else null.
     */
    static int[] runs(CollisionMap map, int[] points, int i, int j)
    {
        int from = points[i];
        int to = points[j];
        int z = z(from);
        int dx = x(to) - x(from);
        int dy = y(to) - y(from);
        int steps = max(abs(dx), abs(dy));
        if (z(to) != z || steps != j - i)
        {
            return null;
        }
        int diagonal = min(abs(dx), abs(dy));
        int sx = Integer.signum(dx);
        int sy = Integer.signum(dy);
        // The straight run goes along the longer axis.
        int ax = abs(dx) > abs(dy) ? sx : 0;
        int ay = abs(dx) > abs(dy) ? 0 : sy;
        int[] path = new int[steps + 1];
        path[0] = from;
        int x = x(from);
        int y = y(from);
        for (int k = 0; k < steps; k++)
        {
            boolean diagonalStep = k >= steps - diagonal;
            int mx = diagonalStep ? sx : ax;
            int my = diagonalStep ? sy : ay;
            if (!map.canStep(x, y, z, mx, my) || (mx == 0 || my == 0) && map.door(x, y, z, mx, my)
                && !crossed(points, i, j, x, y, mx, my))
            {
                return null;
            }
            x += mx;
            y += my;
            path[k + 1] = pack(x, y, z);
            if (newObstacle(map, new int[]{path[k + 1]}, points, i, j))
            {
                return null;
            }
        }
        return path;
    }

    /** Whether {@code points[i..j]} steps from (x, y) by (mx, my) itself (so a door it opens may be crossed). */
    static boolean crossed(int[] points, int i, int j, int x, int y, int mx, int my)
    {
        for (int k = i; k < j; k++)
        {
            if (x(points[k]) == x && y(points[k]) == y && x(points[k + 1]) == x + mx
                && y(points[k + 1]) == y + my)
            {
                return true;
            }
        }
        return false;
    }

    /** Whether {@code piece} crosses an obstacle (vines, rocks) that {@code points[i..j]} kept clear of. */
    static boolean newObstacle(CollisionMap map, int[] piece, int[] points, int i, int j)
    {
        for (int t : piece)
        {
            if (map.isObstacle(x(t), y(t), t)
                && Arrays.stream(points, i, j + 1).noneMatch(p -> p == t))
            {
                return true;
            }
        }
        return false;
    }

    /** Both ends included, or null. */
    public static int[] path(CollisionMap map, int from, int to)
    {
        return path(map, from, new int[]{to});
    }

    /**
     * The game's walk to the first of {@code goals} its search reaches (of a bank chest's sides, the one the game walks
     * to when it is clicked), both ends included; null when none is reached.
     */
    public static int[] path(CollisionMap map, int from, int[] goals)
    {
        int z = z(from);
        int ox = x(from) - HALF;
        int oy = y(from) - HALF;
        int size = HALF * 2;
        boolean[] wanted = new boolean[size * size];
        for (int to : goals)
        {
            int tx = x(to) - ox;
            int ty = y(to) - oy;
            if (z(to) == z && tx >= 0 && ty >= 0 && tx < size && ty < size)
            {
                wanted[ty * size + tx] = true;
            }
        }
        // Direction each tile was reached from; -1 not reached.
        byte[] via = new byte[size * size];
        Arrays.fill(via, (byte) -1);
        int start = HALF * size + HALF;
        via[start] = 8;
        var queue = new ArrayDeque<Integer>();
        queue.add(start);
        int goal = wanted[start] ? start : -1;
        while (!queue.isEmpty() && goal < 0)
        {
            int cell = queue.poll();
            int cx = cell % size;
            int cy = cell / size;
            for (int d = 0; d < 8; d++)
            {
                int nx = cx + DX[d];
                int ny = cy + DY[d];
                if (nx < 0 || ny < 0 || nx >= size || ny >= size || via[ny * size + nx] >= 0)
                {
                    continue;
                }
                if (goal < 0 && map.canStep(cx + ox, cy + oy, z, DX[d], DY[d]))
                {
                    via[ny * size + nx] = (byte) d;
                    queue.add(ny * size + nx);
                    goal = wanted[ny * size + nx] ? ny * size + nx : -1;
                }
            }
        }
        if (goal < 0)
        {
            return null;
        }
        // Back from the goal, each tile put before the one after it.
        var cells = new ArrayDeque<Integer>();
        for (int cell = goal; cell != start; )
        {
            cells.push(cell);
            int d = via[cell];
            cell = (cell / size - DY[d]) * size + (cell % size - DX[d]);
        }
        int[] path = new int[cells.size() + 1];
        path[0] = from;
        int k = 1;
        for (int c : cells)
        {
            path[k++] = pack(c % size + ox, c / size + oy, z);
        }
        return path;
    }
}

package com.hdmapreforged.route;

import static com.hdmapreforged.route.Tiles.*;

import java.io.*;
import java.util.*;
import java.util.stream.*;
import java.util.zip.*;

/**
 * One's own house as last seen there: where one can walk and what stands where. Its tiles are at {@link #X},
 * {@link #Y} plus the house's own place (its south-west room at chunk 2, wherever the game loads it), where no map of
 * the game lies, so routes walk through it like anywhere else ({@link CollisionMap#setHouse}); the surface map draws
 * it at {@link #DRAWN_X}, {@link #DRAWN_Y}. Immutable.
 */
public final class HousePlan
{
    public static final int X = 12800;
    public static final int Y = 12800;
    /** The game's scene, 104 tiles square: the house lies within it. */
    public static final int SIZE = 104;
    /** Where the world map draws it: the surface map's empty west edge. */
    public static final int DRAWN_X = 896;
    public static final int DRAWN_Y = 3000;
    static final int TILES = SIZE * SIZE;

    /**
     * Per floor, per tile (x * SIZE + y): 1 walkable, 2 wall north, 4 wall east, 8 door north, 16 door east, 32 part of
     * a thing west of it, 64 part of a thing south of it.
     */
    final byte[][] tiles;
    /** What stands where (by node): the portals, jewellery box, stairs and such, by their names in the game. */
    public final Map<Integer, String> things;
    /** Where one arrives: north of the exit portal. */
    public final int arrival;
    /** Per region of the plan (2 × 2) and floor: {@link CollisionMap}'s layers. */
    final long[][] layers = new long[16][];

    public HousePlan(byte[][] tiles, Map<Integer, String> things, int arrival)
    {
        this.tiles = tiles;
        this.things = Collections.unmodifiableMap(new LinkedHashMap<>(things));
        this.arrival = arrival;
        for (int z = 0; z < 4; z++)
        {
            for (int i = 0; i < TILES; i++)
            {
                int x = i / SIZE;
                int y = i % SIZE;
                int bit = (x & 63) << 6 | (y & 63);
                for (int k = 0; k < 5; k++)
                {
                    if ((tiles[z][i] & 1 << k) != 0)
                    {
                        int at = ((x >> 6) * 2 + (y >> 6)) * 4 + z;
                        if (layers[at] == null)
                        {
                            layers[at] = new long[320];
                        }
                        layers[at][k * 64 + (bit >> 6)] |= 1L << (bit & 63);
                    }
                }
            }
        }
    }

    /** Only floor one can walk to from these nodes stays walkable: grass beyond the walls is not the house. */
    public static void keepReachable(byte[][] tiles, List<Integer> from)
    {
        boolean[][] reached = new boolean[4][TILES];
        var queue = new ArrayDeque<Integer>();
        for (int node : from)
        {
            reach(tiles, reached, queue, contains(node) ? (x(node) - X) * SIZE + y(node) - Y : -1, z(node));
        }
        while (!queue.isEmpty())
        {
            int at = queue.poll();
            for (int n : steps(tiles[at / TILES], at % TILES))
            {
                reach(tiles, reached, queue, n, at / TILES);
            }
        }
        for (int z = 0; z < 4; z++)
        {
            for (int i = 0; i < TILES; i++)
            {
                tiles[z][i] &= reached[z][i] ? ~0 : ~1;
            }
        }
    }

    static void reach(byte[][] tiles, boolean[][] reached, ArrayDeque<Integer> queue, int i, int z)
    {
        if (i >= 0 && z >= 0 && z < 4 && !reached[z][i] && (tiles[z][i] & 1) != 0)
        {
            reached[z][i] = true;
            queue.add(z * TILES + i);
        }
    }

    /**
     * Where one stands to use a thing: on it (a glory on a wall), else each free tile beside its tiles with no wall
     * between (a portal against a wall is used from its room, not the next); the game walks to the first its search
     * reaches ({@link GameWalk#path}). Its tiles east and north of the first are marked 32 and 64; empty none.
     */
    public int[] approach(int node)
    {
        int z = z(node);
        int x0 = x(node) - X;
        int y0 = y(node) - Y;
        if (!contains(node) || (tiles[z][x0 * SIZE + y0] & 1) != 0)
        {
            return contains(node) ? new int[]{node} : new int[0];
        }
        int w = 1;
        int h = 1;
        while (x0 + w < SIZE && (tiles[z][(x0 + w) * SIZE + y0] & 32) != 0)
        {
            w++;
        }
        while (y0 + h < SIZE && (tiles[z][x0 * SIZE + y0 + h] & 64) != 0)
        {
            h++;
        }
        var sides = IntStream.builder();
        for (int i = 0; i < w * h; i++)
        {
            int at = (x0 + i / h) * SIZE + y0 + i % h;
            for (int n : steps(tiles[z], at))
            {
                if (n >= 0 && (tiles[z][n] & 1) != 0)
                {
                    sides.add(pack(X + n / SIZE, Y + n % SIZE, z));
                }
            }
        }
        return sides.build().toArray();
    }

    /**
     * The tiles one steps to from {@code i} (north, east, south, west), -1 where a wall is: walls stand on a tile's
     * north and east edges, and doors let one through.
     */
    static int[] steps(byte[] floor, int i)
    {
        int x = i / SIZE;
        int y = i % SIZE;
        return new int[]{y < SIZE - 1 && (floor[i] & 2) == 0 ? i + 1 : -1, x < SIZE - 1 && (floor[i] & 4) == 0 ? i + SIZE
            : -1, y > 0 && (floor[i - 1] & 2) == 0 ? i - 1 : -1, x > 0 && (floor[i - SIZE] & 4) == 0 ? i - SIZE : -1};
    }

    public static int node(int sceneX, int sceneY, int plane)
    {
        return pack(X + sceneX, Y + sceneY, plane);
    }

    public static boolean contains(int node)
    {
        return contains(x(node), y(node));
    }

    public static boolean contains(int x, int y)
    {
        return x >= X && x < X + SIZE && y >= Y && y < Y + SIZE;
    }

    long[] layers(int region, int z)
    {
        int dx = (region >> 8) - (X >> 6);
        int dy = (region & 255) - (Y >> 6);
        return dx < 0 || dx > 1 || dy < 0 || dy > 1 ? null : layers[(dx * 2 + dy) * 4 + z];
    }

    /** As kept per account: the tiles deflated in Base64, the arrival, then per thing "node TAB name". */
    public String encode()
    {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (DeflaterOutputStream out = new DeflaterOutputStream(bytes))
        {
            for (var floor : tiles)
            {
                out.write(floor);
            }
        }
        catch (IOException e)
        {
            return null;
        }
        StringBuilder text = new StringBuilder(Base64.getEncoder().encodeToString(bytes.toByteArray()))
            .append('\n').append(arrival);
        things.forEach((node, name) -> text.append('\n').append(node).append('\t').append(name));
        return text.toString();
    }

    /** Null when unreadable; things off the plan are left out. */
    public static HousePlan decode(String text)
    {
        var lines = text.split("\n");
        try (InflaterInputStream in = new InflaterInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(lines[0]))))
        {
            var all = in.readNBytes(4 * TILES + 1);
            int arrival = Integer.parseInt(lines[1]);
            if (all.length != 4 * TILES || !contains(arrival))
            {
                return null;
            }
            byte[][] tiles = new byte[4][];
            for (int z = 0; z < 4; z++)
            {
                tiles[z] = Arrays.copyOfRange(all, z * TILES, (z + 1) * TILES);
            }
            var things = new LinkedHashMap<Integer, String>();
            for (int i = 2; i < lines.length; i++)
            {
                var parts = lines[i].split("\t", 2);
                int node = Integer.parseInt(parts[0]);
                if (parts.length == 2 && contains(node) && parts[1].length() <= 2000)
                {
                    things.put(node, parts[1]);
                }
            }
            return new HousePlan(tiles, things, arrival);
        }
        catch (RuntimeException | IOException e)
        {
            return null;
        }
    }
}

package com.hdmapreforged.route;

import java.util.*;
import lombok.*;
import lombok.experimental.*;

/**
 * The player-owned house is an instance far from its town, so routes start from its ways out: the exit portal and,
 * in the player's own house only, the portals and such seen there. Teleporting in or building mode means one's own
 * house; entering by a house portal may be a friend's. Client thread only.
 */
@Accessors(fluent = true)
public final class HouseTracker
{
    /** By varbit 2187 (POH_HOUSE_LOCATION). */
    static final RouteFiles.Table<int[][]> PORTALS = new RouteFiles.Table<>(() -> Pathfinder.list("house portals",
        p -> Arrays.copyOf(Pathfinder.ints(p), 2)).toArray(int[][]::new));
    static final int PORTAL_RADIUS = 12;
    /** How long a choice at a house portal is kept: the walk to the portal, not a later visit. */
    static final int CHOICE_TICKS = 30;

    @Getter
    boolean inside;
    int lastOutside = -1;
    @Getter
    int exit = -1;
    boolean own;
    /** Varbit 2187: the town of one's own house. */
    int location;
    /** The scene is to be looked through: the house's objects load before the tick that finds the player inside. */
    boolean scan;
    /** Building mode shows empty hotspots (door and stair spaces): not looked through then. */
    boolean building;
    /** Chosen at a house portal: above 0 one's own house, below 0 a friend's; counts down to 0 every tick. */
    int chosen;
    final Set<String> features = new LinkedHashSet<>();
    boolean featuresChanged;

    public static boolean isTemplate(int x, int y)
    {
        // Where the game copies its rooms from.
        return x >= 1856 && x <= 2047 && y >= 7040 && y <= 7119;
    }

    public static int portal(int location)
    {
        var portals = PORTALS.get();
        return location > 0 && location < portals.length ? Tiles.pack(portals[location][0], portals[location][1], 0) : -1;
    }

    static int portalNear(int node)
    {
        var portals = PORTALS.get();
        for (int i = 1; i < portals.length; i++)
        {
            if (Tiles.z(node) == 0 && Math.abs(Tiles.x(node) - portals[i][0]) <= PORTAL_RADIUS
                && Math.abs(Tiles.y(node) - portals[i][1]) <= PORTAL_RADIUS)
            {
                return i;
            }
        }
        return 0;
    }

    /** Every tick. */
    public void update(int node, boolean instance, int houseLocation, boolean buildingMode)
    {
        location = houseLocation;
        building = buildingMode;
        boolean nowInside = instance && node >= 0 && isTemplate(Tiles.x(node), Tiles.y(node));
        if (nowInside && !inside)
        {
            int entered = lastOutside >= 0 ? portalNear(lastOutside) : 0;
            // Through a house portal: maybe a friend's house, unless the player chose their own there. Not known
            // where from (started in a house): not taken for one's own, or a friend's house would be kept as it.
            own = lastOutside >= 0 && (entered <= 0 || chosen > 0);
            exit = portal(own ? houseLocation : entered);
            scan = true;
            // A choice counts for one entry: back at the portal, a friend's house may be next.
            chosen = 0;
        }
        if (nowInside && buildingMode && !own)
        {
            own = true;
            scan = true;
        }
        if (!nowInside && node >= 0 && !instance)
        {
            lastOutside = node;
        }
        chosen -= Integer.signum(chosen);
        inside = nowInside;
    }

    public boolean own()
    {
        return inside && own;
    }

    /** The portal of one's own house, -1 while its town is not known. */
    public int portal()
    {
        return portal(location);
    }

    /** Whether to look through the scene for the house's features now: once per visit or reload of one's own house. */
    public boolean takeScan()
    {
        boolean due = scan && own() && !building;
        scan &= !due;
        return due;
    }

    /** At a house portal: "Home", "Build mode" or "Go to your house" (true), or a friend's house (false). */
    public void chose(boolean ownHouse)
    {
        chosen = ownHouse ? CHOICE_TICKS : -CHOICE_TICKS;
    }

    /** Looked through too early (building mode's spaces still there): again next tick. */
    public void scanAgain()
    {
        scan = true;
    }

    /** The scene loaded again: building mode, or a teleport from a friend's house (only one's own is reached so). */
    public void reloaded()
    {
        if (inside && !own)
        {
            own = true;
            exit = portal(location);
        }
        scan = inside;
    }

    /** Remembered only in the player's own house, not in building mode (its empty spaces); true when this added one. */
    public boolean seen(String objectName)
    {
        if (!own() || building || objectName == null)
        {
            return false;
        }
        String feature = feature(objectName);
        if (feature != null && features.add(feature))
        {
            featuresChanged = true;
            return true;
        }
        return false;
    }

    public static String feature(String objectName)
    {
        String n = objectName.trim();
        String lower = n.toLowerCase(Locale.ROOT);
        if (lower.endsWith(" space"))
        {
            // Building mode's empty spaces ("Jewellery box space"): nothing built there.
            return null;
        }
        if (lower.startsWith("portal nexus: "))
        {
            // A place of the nexus, as the scan names it: apart from the portals.
            return "nexus:" + n.substring("portal nexus: ".length()).trim();
        }
        if (lower.endsWith(" portal") && !lower.startsWith("exit") && !lower.equals("portal") && !lower.contains("nexus"))
        {
            return "portal:" + n.substring(0, n.length() - " portal".length()).trim();
        }
        if (lower.contains("jewellery box"))
        {
            return lower.startsWith("ornate") ? "box:ornate" : lower.startsWith("fancy") ? "box:fancy" : "box:basic";
        }
        return lower.equals("fairy ring") || lower.equals("spirit tree") || lower.equals("obelisk") ? lower
            : lower.equals("spiritual fairy tree") ? "spirit tree+fairy ring"
            : lower.contains("amulet of glory") ? "glory" : lower.contains("xeric's talisman") ? "xeric"
            : lower.contains("digsite pendant") ? "digsite" : null;
    }

    public Set<String> features()
    {
        return Collections.unmodifiableSet(features);
    }

    public void restore(Set<String> saved)
    {
        features.clear();
        var known = Pathfinder.list("house features");
        for (String f : saved)
        {
            // Without the map version's list (not come yet, or an older version) all are kept, as they are saved back.
            if (f.startsWith("portal:") || f.startsWith("nexus:") || f.startsWith("box:") || known.isEmpty()
                || known.contains(f))
            {
                features.add(f);
            }
        }
        featuresChanged = false;
    }

    public boolean takeChanged()
    {
        boolean changed = featuresChanged;
        featuresChanged = false;
        return changed;
    }

    public void replaceFeatures(Collection<String> known)
    {
        features.clear();
        features.addAll(known);
        featuresChanged = false;
    }

    public void reset()
    {
        inside = false;
        lastOutside = -1;
        exit = -1;
        own = false;
        location = 0;
        scan = false;
        chosen = 0;
        replaceFeatures(Collections.emptySet());
    }
}

package com.hdmapreforged.route;

import java.util.*;

/** Instances whose template copies a place on the map ({@code route/instance_copies.tsv}): their tiles as that place's. */
public final class InstanceCopies
{
    static final RouteFiles.Table<List<int[]>> COPIES = new RouteFiles.Table<>(InstanceCopies::load);

    static List<int[]> load()
    {
        return Pathfinder.table(RouteFiles.DIR + "instance_copies.tsv", parts -> {
            var min = Pathfinder.ints(parts[0]);
            var max = Pathfinder.ints(parts[1]);
            var by = Pathfinder.ints(parts[2]);
            return new int[]{min[0], min[1], max[0], max[1], by[0], by[1]};
        });
    }

    /** The place's tile for a template tile ({@code x y plane}), or null when no known copy holds it. */
    public static int[] place(int x, int y, int plane)
    {
        for (var c : COPIES.get())
        {
            if (x >= c[0] && y >= c[1] && x <= c[2] && y <= c[3])
            {
                return new int[]{x - c[4], y - c[5], plane};
            }
        }
        return null;
    }

    /** The template tile for a tile of a copied place, or null when no known copy holds it: what the game draws there. */
    public static int[] template(int x, int y, int plane)
    {
        for (var c : COPIES.get())
        {
            if (x >= c[0] - c[4] && y >= c[1] - c[5] && x <= c[2] - c[4] && y <= c[3] - c[5])
            {
                return new int[]{x + c[4], y + c[5], plane};
            }
        }
        return null;
    }

    /** Whether a tile of the map is the place of a known copy (the player in that instance, as drawn and routed). */
    public static boolean isPlace(int x, int y)
    {
        return template(x, y, 0) != null;
    }
}

package com.hdmapreforged.route;

import java.util.*;

/** Int keys to int values in open addressing arrays, for the search's hot loop (no boxing). Not thread-safe. */
final class IntMap
{
    /** Returned for a missing key; never a key itself. */
    static final int MISSING = Integer.MIN_VALUE;
    int[] keys;
    int[] values;
    int size;
    int mask;

    IntMap(int capacity)
    {
        allocate(Integer.highestOneBit(Math.max(16, capacity) - 1) << 1);
    }

    void allocate(int n)
    {
        keys = new int[n];
        Arrays.fill(keys, MISSING);
        values = new int[n];
        mask = n - 1;
        size = 0;
    }

    int slot(int key)
    {
        int h = key * 0x9E3779B9;
        int i = (h ^ h >>> 16) & mask;
        while (keys[i] != MISSING && keys[i] != key)
        {
            i = (i + 1) & mask;
        }
        return i;
    }

    int get(int key)
    {
        int i = slot(key);
        return keys[i] == MISSING ? MISSING : values[i];
    }

    void put(int key, int value)
    {
        int i = slot(key);
        if (keys[i] == MISSING)
        {
            if ((size + 1) * 2 > keys.length)
            {
                grow();
                i = slot(key);
            }
            keys[i] = key;
            size++;
        }
        values[i] = value;
    }

    void grow()
    {
        var oldKeys = keys;
        var oldValues = values;
        allocate(oldKeys.length * 2);
        for (int i = 0; i < oldKeys.length; i++)
        {
            if (oldKeys[i] != MISSING)
            {
                put(oldKeys[i], oldValues[i]);
            }
        }
    }
}

package com.hdmapreforged.route;

import lombok.*;
import java.util.*;
import java.util.regex.*;
import java.util.stream.*;

/**
 * Items carried and runes a worn staff gives without limit: what a route may use. The bank only through a
 * {@link BankDetour} (setting), as {@link #plus}. Immutable.
 */
@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
public final class ItemSnapshot
{
    /** Compiled once: a split on a pattern compiles it on every call, and requests check hundreds of columns. */
    public static final Pattern ALL = Pattern.compile("&&");
    public static final Pattern ANY = Pattern.compile("\\|\\|");
    public static final int AIR = 556;
    static final int WATER = 555;
    static final int EARTH = 557;
    public static final int FIRE = 554;
    /** Combination runes (steam, mist, dust, smoke, mud, lava) by id, with the two runes each counts as. */
    static final RouteFiles.Table<Map<Integer, int[]>> COMBINATIONS = new RouteFiles.Table<>(() -> Pathfinder.list(
        "combination rune ids", Pathfinder::ints).stream().filter(c -> c.length > 2)
        .collect(Collectors.toMap(c -> c[0], c -> new int[]{c[1], c[2]}, (a, b) -> a)));

    public static final ItemSnapshot NONE = new ItemSnapshot(Collections.emptyMap(), Collections.emptySet());
    public static final ItemSnapshot EVERYTHING = new ItemSnapshot(Collections.emptyMap(), Collections.emptySet());

    final Map<Integer, Long> carried;
    final Set<Integer> unlimited;

    /** Whether {@code other} carries the same (an inventory that changed back and forth is no change). */
    public boolean sameAs(ItemSnapshot other)
    {
        return other != null && carried.equals(other.carried);
    }

    /** Whether {@code other} carries the same of these items (and the same staff's runes). */
    public boolean sameFor(ItemSnapshot other, Set<Integer> ids)
    {
        return other != null && unlimited.equals(other.unlimited)
            && ids.stream().allMatch(id -> carried.getOrDefault(id, 0L).equals(other.carried.getOrDefault(id, 0L)));
    }

    public static ItemSnapshot of(Map<Integer, Long> carried, Set<Integer> unlimited)
    {
        var all = new HashMap<Integer, Long>();
        carried.forEach((id, n) -> add(all, id, n));
        return new ItemSnapshot(Collections.unmodifiableMap(all), Collections.unmodifiableSet(new HashSet<>(unlimited)));
    }

    /** These items and {@code more} (a bank's), with the same staff's runes. */
    ItemSnapshot plus(Map<Integer, Long> more)
    {
        var all = new HashMap<Integer, Long>(carried);
        more.forEach((id, n) -> add(all, id, n));
        return new ItemSnapshot(Collections.unmodifiableMap(all), unlimited);
    }

    static void add(Map<Integer, Long> into, int id, long quantity)
    {
        into.merge(id, quantity, Long::sum);
        var parts = COMBINATIONS.get().get(id);
        if (parts != null)
        {
            for (int part : parts)
            {
                into.merge(part, quantity, Long::sum);
            }
        }
    }

    public static Set<Integer> runesFromWeapon(String name)
    {
        var runes = new HashSet<Integer>();
        String n = name == null ? "" : name.toLowerCase(Locale.ROOT);
        if (!n.contains("staff") && !n.contains("tome of") && !n.contains("wand") || n.contains("(empty)")
            || n.contains("uncharged"))
        {
            return runes;
        }
        // The words that give each rune.
        var words = Pathfinder.list("staff runes");
        int[] ids = {AIR, WATER, EARTH, FIRE};
        for (int i = 0; i < Math.min(ids.length, words.size()); i++)
        {
            if (Arrays.stream(words.get(i).split(" ")).anyMatch(w -> !w.isEmpty() && n.contains(w)))
            {
                runes.add(ids[i]);
            }
        }
        return runes;
    }

    /**
     * Whether what is carried meets a column like {@code "556=3&&563=1"}. A token that is no item id counts as met:
     * only a certainly missing item rules out.
     */
    public boolean has(String column)
    {
        if (this == EVERYTHING || column == null || column.trim().isEmpty())
        {
            return true;
        }
        for (String all : ALL.split(column))
        {
            boolean any = false;
            boolean judged = false;
            for (String alternative : ANY.split(all))
            {
                var parts = alternative.trim().split("=");
                String token = parts[0].trim();
                if (token.isEmpty())
                {
                    continue;
                }
                long quantity = 1;
                if (parts.length > 1)
                {
                    try
                    {
                        quantity = Long.parseLong(parts[1].trim());
                    }
                    catch (NumberFormatException e)
                    {
                        // One then.
                    }
                }
                Integer id = token.length() <= 9 && token.chars().allMatch(Character::isDigit) ? Integer.valueOf(token)
                    : null;
                if (id == null)
                {
                    any = true;
                    continue;
                }
                judged = true;
                any |= unlimited.contains(id) || carried.getOrDefault(id, 0L) >= quantity;
            }
            if (judged && !any)
            {
                return false;
            }
        }
        return true;
    }
}

package com.hdmapreforged.route;

import java.util.*;

/** A binary min-heap of longs (priority in the high bits, node in the low bits). */
final class LongHeap
{
    long[] items = new long[1024];
    int size;

    boolean isEmpty()
    {
        return size == 0;
    }

    void push(long value)
    {
        if (size == items.length)
        {
            items = Arrays.copyOf(items, size * 2);
        }
        int i = size++;
        while (i > 0)
        {
            int parent = (i - 1) >>> 1;
            if (items[parent] <= value)
            {
                break;
            }
            items[i] = items[parent];
            i = parent;
        }
        items[i] = value;
    }

    long pop()
    {
        long top = items[0];
        long last = items[--size];
        int i = 0;
        while (true)
        {
            int child = 2 * i + 1;
            if (child >= size)
            {
                break;
            }
            if (child + 1 < size && items[child + 1] < items[child])
            {
                child++;
            }
            if (items[child] >= last)
            {
                break;
            }
            items[i] = items[child];
            i = child;
        }
        items[i] = last;
        return top;
    }
}

package com.hdmapreforged.route;

import java.util.*;

/** A map in access order (load factor 0.75) that keeps only the {@code limit} entries used last. */
public final class LruMap<K, V> extends LinkedHashMap<K, V>
{
    final int limit;

    public LruMap(int capacity, int limit)
    {
        super(capacity, 0.75f, true);
        this.limit = limit;
    }

    protected boolean removeEldestEntry(Map.Entry<K, V> eldest)
    {
        return size() > limit;
    }
}

package com.hdmapreforged.route;

import java.util.*;
import lombok.*;

/**
 * A set of nodes as bits per {@link NodeTable#block}, made as blocks are touched: a flood of the world takes 1 MB. Also
 * over blocks made elsewhere ({@link NodeTable#reached}): {@code bits[b]} holds block {@code b}'s 4,096 nodes.
 */
@AllArgsConstructor
final class NodeSet
{
    final IntMap blocks;
    long[][] bits;
    int count;

    NodeSet()
    {
        this(new IntMap(1 << 10), new long[64][], 0);
    }

    /** Whether the node was not in the set before. */
    boolean add(int node)
    {
        int key = NodeTable.block(node);
        int b = blocks.get(key);
        if (b == IntMap.MISSING)
        {
            b = count++;
            if (b == bits.length)
            {
                bits = Arrays.copyOf(bits, b * 2);
            }
            bits[b] = new long[64];
            blocks.put(key, b);
        }
        int i = NodeTable.index(node);
        long mask = 1L << i;
        if ((bits[b][i >> 6] & mask) != 0)
        {
            return false;
        }
        bits[b][i >> 6] |= mask;
        return true;
    }

    boolean contains(int node)
    {
        int b = blocks.get(NodeTable.block(node));
        int i = NodeTable.index(node);
        return b != IntMap.MISSING && (bits[b][i >> 6] & 1L << i) != 0;
    }
}

package com.hdmapreforged.route;

import java.util.*;

/**
 * Search state per node, the best cost and how it was reached, in blocks of 64 × 64 nodes made when first touched: no
 * table growing by copies, and no array large enough to weigh on the garbage collector (a flood touches about 700).
 */
final class NodeTable
{
    /** How the start was reached. A step from the neighbour in direction d is {@code -1 - d}, a jump its edge index. */
    static final int START = -9;
    static final int SIZE = 64 * 64;
    final IntMap blocks = new IntMap(1 << 11);
    int[][] costs = new int[64][];
    int[][] vias = new int[64][];
    int count;
    int size;
    /** The block last looked up (most lookups are its neighbours'). */
    int lastKey = -1;
    int last;

    int size()
    {
        return size;
    }

    /** A node's block: 64 × 64 tiles of a floor, or 64 × 64 sea blocks. */
    static int block(int node)
    {
        return Tiles.isSea(node) ? 1 << 18 | (node >> 18 & 63) << 6 | (node >> 6 & 63) : node >>> 20 << 8 | (node >> 6 & 255);
    }

    /** A node's place in its block. */
    static int index(int node)
    {
        return (node >> (Tiles.isSea(node) ? 12 : 14) & 63) << 6 | (node & 63);
    }

    /** The node's block, made when {@code make}; else -1 when there is none. */
    int at(int node, boolean make)
    {
        int key = block(node);
        if (key == lastKey)
        {
            return last;
        }
        int b = blocks.get(key);
        if (b == IntMap.MISSING)
        {
            if (!make)
            {
                return -1;
            }
            b = count++;
            if (b == costs.length)
            {
                costs = Arrays.copyOf(costs, b * 2);
                vias = Arrays.copyOf(vias, b * 2);
            }
            costs[b] = new int[SIZE];
            Arrays.fill(costs[b], Integer.MAX_VALUE);
            vias[b] = new int[SIZE];
            blocks.put(key, b);
        }
        lastKey = key;
        last = b;
        return b;
    }

    /** {@link Integer#MAX_VALUE} when not reached. */
    int cost(int node)
    {
        int b = at(node, false);
        return b < 0 ? Integer.MAX_VALUE : costs[b][index(node)];
    }

    /** Of a reached node only. */
    int via(int node)
    {
        return vias[at(node, false)][index(node)];
    }

    void put(int node, int cost, int via)
    {
        int b = at(node, true);
        int i = index(node);
        size += costs[b][i] == Integer.MAX_VALUE ? 1 : 0;
        costs[b][i] = cost;
        vias[b][i] = via;
    }

    /** The nodes reached. */
    NodeSet reached()
    {
        long[][] bits = new long[count][];
        for (int b = 0; b < count; b++)
        {
            bits[b] = new long[64];
            for (int i = 0; i < SIZE; i++)
            {
                bits[b][i >> 6] |= costs[b][i] != Integer.MAX_VALUE ? 1L << i : 0;
            }
        }
        return new NodeSet(blocks, bits, count);
    }
}

package com.hdmapreforged.route;

import java.util.*;
import lombok.*;

/** One-way passages ({@code one_way.tsv}, e.g. a slide): a passage of any source going back between the areas is left out. */
@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
public final class OneWay
{
    @RequiredArgsConstructor
    static final class Rule
    {
        final int from;
        final int to;
        final int radius;
    }

    final List<Rule> rules;

    public static OneWay load()
    {
        return new OneWay(Pathfinder.table(RouteFiles.DIR + "one_way.tsv", OneWay::parse));
    }

    /** "x y plane <tab> x y plane <tab> radius <tab> name", split at tabs; null when not a rule. */
    static Rule parse(String[] parts)
    {
        if (parts.length < 3)
        {
            return null;
        }
        int from = Tiles.parse(parts[0]);
        int to = Tiles.parse(parts[1]);
        try
        {
            return from < 0 || to < 0 ? null : new Rule(from, to, Integer.parseInt(parts[2].trim()));
        }
        catch (NumberFormatException e)
        {
            return null;
        }
    }

    public boolean against(int from, int to)
    {
        return rules.stream().anyMatch(rule -> near(from, rule.to, rule.radius) && near(to, rule.from, rule.radius));
    }

    static boolean near(int a, int b, int radius)
    {
        return !Tiles.isSea(a) && !Tiles.isSea(b) && Tiles.near(a, b, radius);
    }
}

package com.hdmapreforged.route;

import static com.hdmapreforged.route.IntMap.MISSING;
import static com.hdmapreforged.route.Route.Outcome.*;
import static java.lang.Math.*;
import static com.hdmapreforged.route.Tiles.*;

import com.hdmapreforged.route.Route.*;
import java.io.*;
import java.nio.charset.*;
import java.util.*;
import java.util.function.*;
import java.util.stream.*;
import lombok.*;

/**
 * A* over tiles, sea blocks and jumps ({@link Edge}); costs in half ticks. The heuristic stays a lower bound by folding
 * underground y onto the surface (y − 6400) and bounding far/cheap jumps with a backward search over the jumps alone.
 * Beside it a flood runs back from the goal over the same ways ({@link Backward}): the first side to run out of nodes
 * settles whether the goal is in reach at all, so a target shut off from the player (a quest's door, an island, an
 * instance) is proved out of reach after its own small area instead of after the whole world. Thread-safe: each search
 * keeps its own state; the maps are immutable (one's house is swapped whole).
 */
public final class Pathfinder
{
    /** Half ticks. */
    static final int RUN = 1;
    static final int WALK = 2;
    static final int DOOR = 2;
    /** Vines, jungle or a web: needs a tool, so walking around is better. */
    static final int OBSTACLE = 10;
    static final int SAIL = CELL;
    static final int STAIRS = 5;
    /** Through a solid object found by shape: only when no known way is much shorter. */
    static final int THROUGH = 30;
    static final String UNKNOWN_NEEDS = "May need a quest, level or item the map does not know";
    static final int SNAP_RADIUS = 12;
    static final int LONG_JUMP = 24;
    static final int BLOCK = 8;
    static final int[] DX = {1, -1, 0, 0, 1, 1, -1, -1};
    static final int[] DY = {0, 0, 1, -1, 1, -1, 1, -1};

    final CollisionMap map;
    final SeaMap sea;
    /** Every passage the planner knows besides the request's: stairs, entrances, map links and the like. */
    final List<Edge> passages;
    final List<ShortcutPassage> shortcutPassages;
    final EdgeIndex passagesByOrigin;
    /** Where the Agility shortcuts start (shortcuts.tsv, the game's passages that are one): ways out for {@link #pocket}. */
    final IntMap shortcutStarts = new IntMap(1024);
    final EdgeIndex passagesByDestination;
    /** The jumps the heuristic must know when a tile costs a half tick (running, sailing) and when it costs one. */
    final List<Edge> heuristicPassages;
    final List<Edge> walkingPassages;
    /**
     * Walking steps a gates.tsv row between two neighbouring tiles closes (a guild's door, which the game's collision has
     * as an ordinary door): per origin tile, a bit per direction of {@link #DX}; the row's own edge opens the step to
     * players who meet its needs. Read only after the constructor.
     */
    final IntMap closedSteps = new IntMap(64);
    /** The heuristic's jump bounds as last worked out, by goal and the request's jumps: re-plans and Fastest order. */
    final Map<List<Integer>, int[][]> bounds = Collections.synchronizedMap(new LruMap<>(8, BOUNDS_KEPT));
    static final int BOUNDS_KEPT = 4;

    public Pathfinder(CollisionMap map, SeaMap sea)
    {
        this.map = map;
        this.sea = sea;
        var edges = new ArrayList<Edge>();
        // Passages only from: the game's map links, hand links citing a source,
        // and cache passages: within SAME_SPOT, or far ones (into a dungeon, 6400 tiles north) that the collision tool
        // paired with a way back at the other end, unless a map link of the game's starts there and leads elsewhere.
        var mapLinks = links(map, RouteFiles.DIR + "map_link_passages.tsv");
        var handLinks = links(map, RouteFiles.DIR + "links.tsv");
        var gameLinks = gameLinkStarts();
        for (Transition t : map.transitions())
        {
            var kind = z(t.to) != t.plane && abs(y(t.to) - t.y) < 1000 ? Edge.Kind.STAIRS
                : Edge.Kind.ENTRANCE;
            String name = t.action + (t.name.isEmpty() ? "" : " " + t.name);
            var fee = Fees.at(t.x, t.y, t.plane);
            String detail = fee != null ? "Needs: " + fee.text
                : t.through ? UNKNOWN_NEEDS : null;
            int cost = STAIRS + (fee == null ? 0 : fee.cost) + (t.through ? THROUGH : 0);
            for (int origin : t.origins)
            {
                if (sameSpot(origin, t.to) || confirmed(mapLinks, origin, t.to) || confirmed(handLinks, origin, t.to)
                    || !linkedElsewhere(gameLinks, origin))
                {
                    edges.add(new Edge(origin, t.to, kind, name, detail, cost));
                }
            }
        }
        edges.addAll(mapLinks);
        edges.addAll(handLinks);
        edges.addAll(fromOpenGround(map, edges));
        var oneWay = OneWay.load();
        edges.removeIf(e -> oneWay.against(e.from, e.to));
        // A passage a gates.tsv row covers (a quest-locked city gate the game's map links have as open) is never free:
        // RouteSource offers the row's own edge to players who meet its needs.
        var gated = new ArrayList<int[]>();
        for (var parts : rows(RouteFiles.DIR + "gates.tsv"))
        {
            int a = parts.length < 3 ? -1 : parse(parts[1]);
            int b = a < 0 ? -1 : parse(parts[2]);
            if (b >= 0)
            {
                gated.add(new int[]{a, b});
                close(a, b);
            }
        }
        edges.removeIf(e -> gated.stream().anyMatch(g -> covers(g, e)));
        // Passages that are Agility shortcuts (shortcuts.tsv): added only to requests whose player meets the shortcut.
        var atShortcuts = new ArrayList<ShortcutPassage>();
        edges.removeIf(e -> {
            // Its needs are checked per request: no toll for needs the map would not know.
            var at = ShortcutPassage.of(UNKNOWN_NEEDS.equals(e.detail)
                ? new Edge(e.from, e.to, e.kind, e.name, null, e.cost - THROUGH) : e);
            return at != null && atShortcuts.add(at);
        });
        shortcutPassages = Collections.unmodifiableList(atShortcuts);
        ShortcutPassage.known().forEach(s -> shortcutStarts.put(s.origin, 0));
        atShortcuts.forEach(s -> shortcutStarts.put(s.edge.from, 0));
        passages = Collections.unmodifiableList(edges);
        passagesByOrigin = EdgeIndex.of(edges, 0, false);
        passagesByDestination = EdgeIndex.of(edges, 0, true);
        heuristicPassages = edges.stream().filter(e -> shortCut(e, RUN)).collect(Collectors.toUnmodifiableList());
        walkingPassages = edges.stream().filter(e -> shortCut(e, WALK)).collect(Collectors.toUnmodifiableList());
    }

    /** Lists the planner and its texts use (the map version's lists.tsv): by name, its items; the first of a name. */
    static final RouteFiles.Table<Map<String, List<String>>> LISTS = new RouteFiles.Table<>(() -> rows(
        RouteFiles.DIR + "lists.tsv").stream().collect(Collectors.toMap(c -> c[0], c -> List.of(c).subList(1, c.length),
        (a, b) -> a)));

    /** A list by its name; empty while the map version has none. */
    public static List<String> list(String name)
    {
        return LISTS.get().getOrDefault(name, List.of());
    }

    /** A list's items as {@code parse} reads them; an item it cannot read (throws, gives null) is left out. */
    public static <T> List<T> list(String name, Function<String, T> parse)
    {
        return each(list(name), parse);
    }

    /** A list of "key=value" items as a map, each value as {@code parse} reads it; the first of a key. */
    public static <T> Map<String, T> pairs(String list, Function<String, T> parse)
    {
        return list(list, item -> {
            var p = item.split("=", 2);
            return Map.entry(p[0], parse.apply(p[1]));
        }).stream().collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue, (a, b) -> a));
    }

    public List<ShortcutPassage> shortcutPassages()
    {
        return shortcutPassages;
    }

    /**
     * Whether a gates.tsv row (from, to) covers a passage: one going its own way, from near its start to near its end. Not
     * the way back: where a gate's two ends lie within 2 tiles of each other (Lletya's trees, Villa Lucens' entryway), the
     * passage out is near both ends too, and was taken for the gate's own (a row stands for one direction, as its closed
     * step does). Within a gate row's reach: the same floor, two tiles.
     */
    static boolean covers(int[] gate, Edge e)
    {
        return near(e.from, gate[0], 2) && near(e.to, gate[1], 2)
            && distance(e.from, gate[0]) <= distance(e.from, gate[1])
            && distance(e.to, gate[1]) <= distance(e.to, gate[0]);
    }

    /** A gates.tsv row between neighbouring tiles: that step is not walked, only taken by the row's edge. */
    void close(int from, int to)
    {
        if (z(from) != z(to) || distance(from, to) != 1)
        {
            return;
        }
        for (int d = 0; d < DX.length; d++)
        {
            if (x(to) - x(from) == DX[d] && y(to) - y(from) == DY[d])
            {
                int known = closedSteps.get(from);
                closedSteps.put(from, (known == MISSING ? 0 : known) | 1 << d);
            }
        }
    }

    static boolean sameSpot(int from, int to)
    {
        return distance(from, to) <= SAME_SPOT;
    }

    /** A cache passage this near its start is the other side of an obstacle or the same spot on another floor. */
    static final int SAME_SPOT = 10;

    /** Where the game's own map links start (route/map_link_starts.tsv): x, y, plane. */
    static List<int[]> gameLinkStarts()
    {
        return table(RouteFiles.DIR + "map_link_starts.tsv", parts -> {
            int start = parse(parts[0]);
            return start < 0 ? null : new int[]{x(start), y(start), z(start)};
        });
    }

    /** A game map link starts within 4 tiles: where it leads is the game's word, not the cache's pairing. */
    static boolean linkedElsewhere(List<int[]> starts, int origin)
    {
        return starts.stream().anyMatch(s -> s[2] == z(origin) && abs(s[0] - x(origin)) <= 4
            && abs(s[1] - y(origin)) <= 4);
    }

    /**
     * A passage whose start is a tile shut in by walls (the snapped tile behind a cave mouth) is also taken from the
     * open tiles right beside it, where one stands to use it in the game.
     */
    static List<Edge> fromOpenGround(CollisionMap map, List<Edge> edges)
    {
        var open = new HashMap<Integer, Boolean>();
        var extra = new ArrayList<Edge>();
        for (Edge e : edges)
        {
            if (e.from < 0 || isSea(e.from) || open.computeIfAbsent(e.from, n -> reaches(map, n, at -> false)))
            {
                continue;
            }
            for (int d = 0; d < 8; d++)
            {
                int x = x(e.from) + DX[d];
                int y = y(e.from) + DY[d];
                int next = pack(x, y, z(e.from));
                if (map.walkable(x, y, z(e.from)) && open.computeIfAbsent(next, n -> reaches(map, n, at -> false)))
                {
                    extra.add(e.withFrom(next));
                }
            }
        }
        return extra;
    }

    /** Tiles a walk reaches out in the open, not shut in by walls. */
    static final int OPEN = 120;

    /** Whether walking from a tile reaches {@link #OPEN} tiles, or one that {@code way} leads out of. */
    static boolean reaches(CollisionMap map, int node, IntPredicate way)
    {
        // Run for every passage at start: no boxing.
        int[] queue = new int[OPEN];
        var seen = new IntMap(2 * OPEN);
        queue[0] = node;
        seen.put(node, 0);
        for (int head = 0, tail = 1; head < tail; head++)
        {
            int at = queue[head];
            if (way.test(at))
            {
                return true;
            }
            for (int d = 0; d < 4; d++)
            {
                int next = pack(x(at) + DX[d], y(at) + DY[d], z(at));
                if (map.canStep(x(at), y(at), z(at), DX[d], DY[d]) && seen.get(next) == MISSING)
                {
                    seen.put(next, 0);
                    if (++tail >= OPEN)
                    {
                        return true;
                    }
                    queue[tail - 1] = next;
                }
            }
        }
        return false;
    }

    static boolean confirmed(List<Edge> passages, int from, int to)
    {
        return passages.stream().anyMatch(e -> near(e.from, from, 4) && near(e.to, to, 16));
    }

    static List<Edge> links(CollisionMap map, String resource)
    {
        return table(resource, parts -> {
            int a = parts.length < 3 ? -1 : parse(parts[0]);
            int b = a < 0 ? -1 : parse(parts[1]);
            int from = b < 0 ? -1 : map.nearestWalkable(x(a), y(a), z(a), 2);
            int to = from < 0 ? -1 : map.nearestWalkable(x(b), y(b), z(b), 2);
            // An optional fourth column: its cost in half ticks, where it takes longer than stairs.
            int cost = parts.length > 3 && parts[3].trim().matches("\\d{1,4}") ? Integer.parseInt(parts[3].trim()) : STAIRS;
            return to < 0 ? null : new Edge(from, to, Edge.Kind.ENTRANCE, parts[2].trim(), null, cost);
        });
    }

    /** A bundled table's lines split at tabs, without {@code #} comments; what could be read. */
    public static List<String[]> rows(String resource)
    {
        var rows = new ArrayList<String[]>();
        InputStream in = RouteFiles.open(resource);
        if (in != null)
        {
            try
            {
                rows(in, 0, rows::add);
            }
            catch (IOException e)
            {
                // Those read so far.
            }
        }
        return rows;
    }

    /** Each row of a bundled table as {@code parse} reads it; a row it cannot read (throws, gives null) is left out. */
    public static <T> List<T> table(String resource, Function<String[], T> parse)
    {
        return each(rows(resource), parse);
    }

    static <I, T> List<T> each(List<I> items, Function<I, T> parse)
    {
        var read = new ArrayList<T>();
        for (var item : items)
        {
            try
            {
                T row = parse.apply(item);
                if (row != null)
                {
                    read.add(row);
                }
            }
            catch (RuntimeException e)
            {
                // That one only.
            }
        }
        return Collections.unmodifiableList(read);
    }

    /** Each line but {@code #} comments, split as {@code line.split("\t", limit)} does; closes {@code in}. */
    static void rows(InputStream in, int limit, Consumer<String[]> each) throws IOException
    {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
        {
            for (String line = reader.readLine(); line != null; line = reader.readLine())
            {
                if (!line.startsWith("#"))
                {
                    each.accept(line.split("\t", limit));
                }
            }
        }
    }

    /** A cell's space-separated integers ("2920 4700" {@literal ->} {2920, 4700}). */
    public static int[] ints(String cell)
    {
        return Arrays.stream(cell.trim().split("\\s+")).mapToInt(Integer::parseInt).toArray();
    }

    /** Folded y: most dungeons lie 6400 tiles north of what is above them. */
    static int fy(int node)
    {
        int y = y(node);
        return y >= 6400 ? y - 6400 : y;
    }

    /** Round the fold: one step from y 6399 to 6400 goes from the top of the folded range to its bottom. */
    static int folded(int a, int b)
    {
        int dy = abs(fy(a) - fy(b));
        return max(abs(x(a) - x(b)), min(dy, 6400 - dy));
    }

    /** Jumps the heuristic must know (a tile costing {@code step}), else it would overestimate and miss the best way. */
    static boolean shortCut(Edge e, int step)
    {
        if (e.from == Edge.ANYWHERE)
        {
            return false;
        }
        int length = folded(e.from, e.to);
        return length > LONG_JUMP || e.cost < length * step;
    }

    /** {@code out}: more ways out of a pocket than the passages (a request's own: fairy rings, boats, shortcuts). */
    public int resolveGoal(int target, IntPredicate out)
    {
        if (isSea(target))
        {
            return target;
        }
        int x = x(target);
        int y = y(target);
        int z = z(target);
        if (map.walkable(x, y, z))
        {
            return target;
        }
        // No ground on this floor around the spot, but the very spot is ground on another floor (a dungeon's raised part
        // the map shows as floor 1, ours as floor 2: the Brimhaven Dungeon's at 2633 9491): that floor's spot.
        if (map.nearestWalkable(x, y, z, 2) < 0)
        {
            for (int dz = 1; dz < 4; dz++)
            {
                for (int other : new int[]{z - dz, z + dz})
                {
                    if (other >= 0 && other <= 3 && map.walkable(x, y, other) && !pocket(pack(x, y, other), out))
                    {
                        return pack(x, y, other);
                    }
                }
            }
        }
        int near = nearestOpen(x, y, z, SNAP_RADIUS, out);
        if (near >= 0 && !pocket(near, out))
        {
            return near;
        }
        if (z == 0 && sea != null && sea.sailable(x / CELL, y / CELL, 99))
        {
            // Open water with only an islet or a ledge near (a sea creature): sailed to, not walked to the islet.
            return seaAt(x, y);
        }
        // Only a pocket here: the spot may be given on another floor than the ground it marks.
        int there = otherFloor(x, y, z, 3, true, out);
        if (there >= 0 || near >= 0)
        {
            return there >= 0 ? there : near;
        }
        // A spot given on the wrong floor: the same spot on another floor first.
        near = otherFloor(x, y, z, 1, false, out);
        if (near < 0)
        {
            near = otherFloor(x, y, z, SNAP_RADIUS, false, out);
        }
        return near;
    }

    /** {@code open}: the nearest open non-pocket tile, else any walkable one. */
    int otherFloor(int x, int y, int z, int radius, boolean open, IntPredicate out)
    {
        for (int dz = 1; dz < 4; dz++)
        {
            for (int other : new int[]{z - dz, z + dz})
            {
                int near = other < 0 || other > 3 ? -1
                    : open ? nearestOpen(x, y, other, radius, out) : map.nearestWalkable(x, y, other, radius);
                if (near >= 0 && !(open && pocket(near, out)))
                {
                    return near;
                }
            }
        }
        return -1;
    }

    /** A start the data calls unwalkable (a boat's deck, a stepping stone) begins from the nearest open tile. */
    public int startNode(int start)
    {
        if (start < 0 || isSea(start) || map.walkable(x(start), y(start), z(start)))
        {
            return start;
        }
        int near = nearestOpen(x(start), y(start), z(start), 5, at -> false);
        return near >= 0 ? near : start;
    }

    /** Nearest walkable non-pocket tile, else nearest walkable, else -1. */
    int nearestOpen(int x, int y, int z, int radius, IntPredicate out)
    {
        int fallback = -1;
        for (int r = 1; r <= radius; r++)
        {
            int best = -1;
            int bestDistance = Integer.MAX_VALUE;
            for (int dx = -r; dx <= r; dx++)
            {
                for (int dy = -r; dy <= r; dy++)
                {
                    if (max(abs(dx), abs(dy)) != r || !map.walkable(x + dx, y + dy, z))
                    {
                        continue;
                    }
                    int node = pack(x + dx, y + dy, z);
                    int d = dx * dx + dy * dy;
                    if (fallback < 0)
                    {
                        fallback = node;
                    }
                    if (d < bestDistance && !pocket(node, out))
                    {
                        best = node;
                        bestDistance = d;
                    }
                }
            }
            if (best >= 0)
            {
                return best;
            }
        }
        return fallback;
    }

    /** A small shut-in area (behind bank booths) with no passages; ground left by an Agility shortcut is not one. */
    public boolean pocket(int node)
    {
        return pocket(node, at -> false);
    }

    boolean pocket(int node, IntPredicate out)
    {
        return !reaches(map, node, at -> passagesByOrigin.get(at) != null || shortcutStarts.get(at) != MISSING
            || out.test(at));
    }

    /** Where a request's own jumps start (fairy rings, boats, a shortcut's icon): ways out of a pocket for its target. */
    public static IntPredicate waysOut(RouteRequest request)
    {
        var starts = new IntMap(64);
        request.edges.forEach(e -> starts.put(e.from, 0));
        return at -> starts.get(at) != MISSING;
    }

    public Route find(RouteRequest request, BooleanSupplier cancelled)
    {
        return find(request, cancelled, Integer.MAX_VALUE);
    }

    /**
     * The same, giving up (as at the node limit, without a verdict) once no way under {@code costLimit} half ticks can
     * be found: looking for the quickest of several places, a place that cannot beat the best so far stops early.
     */
    public Route find(RouteRequest request, BooleanSupplier cancelled, int costLimit)
    {
        return outside(request, kept(request, cancelled, costLimit), cancelled, costLimit);
    }

    Route kept(RouteRequest request, BooleanSupplier cancelled, int costLimit)
    {
        Route route = walkOrSail(request, cancelled, costLimit);
        // Kept out of the Wilderness, yet no way around it gets there (the Mage Arena's bank, Entrana's dungeon without a
        // boat): through it after all, and the route says so.
        if (avoids(request) && route.keptOut && (route.outcome == NEAREST
            || route.outcome == NONE) && !cancelled.getAsBoolean())
        {
            Route through = walkOrSail(request.throughWilderness(), cancelled, costLimit);
            if (through.outcome == FOUND)
            {
                return through.withThroughWilderness(true);
            }
            // Out of reach only if the search through it tried everything too.
            return through.outcome == CANCELLED || through.exhausted ? route : route.unproved();
        }
        return route;
    }

    /**
     * A target the search proved shut off (ground the game never lets one walk, past a cave's wall: an icon drawn there):
     * the route to the nearest open ground outside it instead, which that search gave up on before getting to.
     */
    Route outside(RouteRequest request, Route route, BooleanSupplier cancelled, int costLimit)
    {
        int target = request.target;
        if (route.outcome != NEAREST || route.reached == null || !route.reached.complement || target < 0 || isSea(target))
        {
            return route;
        }
        for (int r = 1; r <= SNAP_RADIUS; r++)
        {
            for (int dx = -r; dx <= r; dx++)
            {
                for (int dy = -r; dy <= r; dy++)
                {
                    int near = pack(x(target) + dx, y(target) + dy, z(target));
                    if (max(abs(dx), abs(dy)) == r && map.walkable(x(near), y(near), z(near))
                        && route.reached.contains(near) && !pocket(near) && !cancelled.getAsBoolean())
                    {
                        var ways = route.throughWilderness ? request.throughWilderness() : request;
                        Route there = walkOrSail(ways.between(request.start, near).withBank(request.bank), cancelled,
                            costLimit);
                        // Still out of reach itself: the proof stays, so it is not searched again from here.
                        return there.outcome != FOUND ? route : there.near(route);
                    }
                }
            }
        }
        return route;
    }

    Route walkOrSail(RouteRequest request, BooleanSupplier cancelled, int costLimit)
    {
        Route route = search(request, cancelled, costLimit);
        // Left without their boat (a place on land): sail only when walking does not get there (an island).
        if (request.boat != null && (route.outcome == NEAREST || route.outcome == NONE)
            && !cancelled.getAsBoolean())
        {
            Route sailed = search(request.boat, cancelled, costLimit);
            return sailed.outcome == FOUND ? sailed : sailed.keptOut && !route.keptOut ? route.withKeptOut(true)
                : route;
        }
        return route;
    }

    /** Whether a search for this request stays out of the Wilderness: asked to, and it neither starts nor ends there. */
    boolean avoids(RouteRequest request)
    {
        int start = startNode(request.start);
        return request.avoidWilderness && !wilderness(request.target) && !(start >= 0 && wilderness(start));
    }

    Route search(RouteRequest request, BooleanSupplier cancelled, int costLimit)
    {
        int target = request.target;
        int goal = resolveGoal(target, waysOut(request));
        var all = new ArrayList<Edge>(passages.size() + request.edges.size() + request.startEdges.size());
        all.addAll(passages);
        int requestOffset = all.size();
        all.addAll(request.edges);
        int startOffset = all.size();
        all.addAll(request.startEdges);
        var requestByOrigin = EdgeIndex.of(request.edges, requestOffset, false);
        int towards = goal >= 0 ? goal : target;
        int step = request.running ? RUN : WALK;
        // Walking, each tile costs a whole tick; at sea a half one (a block of 4 tiles costs 2 ticks).
        int scale = request.sailingLevel < 0 ? step : RUN;
        var jumps = new ArrayList<Edge>(scale == RUN ? heuristicPassages : walkingPassages);
        var key = new ArrayList<Integer>(List.of(towards, scale));
        for (Edge e : request.edges)
        {
            if (shortCut(e, scale))
            {
                jumps.add(e);
                key.addAll(List.of(e.from, e.to, e.cost));
            }
        }
        var made = bounds.computeIfAbsent(key, k -> Heuristic.bounds(jumps, towards, scale));
        var heuristic = new Heuristic(towards, scale, made[0], made[1]);

        var nodes = new NodeTable();
        var open = new LongHeap();
        int start = startNode(request.start);
        // Out of the Wilderness, unless the route starts or ends there (from a house, start is -1: not in it).
        boolean avoid = avoids(request);
        if (start >= 0)
        {
            relax(nodes, open, heuristic, start, 0, NodeTable.START);
        }
        // Whether a step or jump into the Wilderness was left out (else going through it gets nowhere further).
        boolean keptOut = jumps(IntStream.range(startOffset, all.size()).toArray(), all, nodes, open, heuristic, 0, avoid);
        // Back from the goal, in turns with the search: once it runs out, the goal is in reach from exactly what it
        // flooded. No goal (no ground near the target): out of reach from anywhere.
        var back = goal >= 0 ? new Backward(goal, all, requestOffset, request, avoid) : null;
        Reached proof = goal >= 0 ? null : new Reached(new NodeSet(), true);
        int stopAt = goal >= 0 ? Integer.MAX_VALUE : NEAREST_NODES;
        int best = -1;
        long bestScore = Long.MAX_VALUE;
        int popped = 0;
        boolean limited = false;
        int found = -1;
        while (!open.isEmpty() && popped < stopAt)
        {
            long item = open.pop();
            int node = (int) item;
            int g = nodes.cost(node);
            if ((int) (item >>> 32) != g + heuristic.h(node))
            {
                continue;
            }
            if ((int) (item >>> 32) > costLimit)
            {
                // Every way left costs at least this (the heuristic never overestimates): nothing under the limit.
                limited = true;
                break;
            }
            if ((++popped & (TURN - 1)) == 0)
            {
                if (cancelled.getAsBoolean())
                {
                    return new Route(CANCELLED, Collections.emptyList(), 0, target, -1, false, false, popped);
                }
                if (back != null && back.flood(TURN))
                {
                    if (back.reaches(start, startOffset))
                    {
                        // In reach: the search alone finds the way.
                        back = null;
                    }
                    else
                    {
                        // Out of reach: on a little further for the nearest spot the way gets to, then done.
                        proof = new Reached(back.seen, true);
                        keptOut |= back.keptOut;
                        stopAt = popped + NEAREST_NODES;
                        back = null;
                    }
                }
            }
            if (node == goal)
            {
                found = node;
                break;
            }
            if (!isSea(node))
            {
                long score = (long) (distance(node, target) + (z(node) != z(target) ? 32 : 0)) << 32 | g;
                if (score < bestScore)
                {
                    bestScore = score;
                    best = node;
                }
            }
            if (nodes.size() > request.nodeLimit)
            {
                limited = true;
                break;
            }
            if (isSea(node))
            {
                int cx = cellX(node);
                int cy = cellY(node);
                for (int d = 0; d < 8; d++)
                {
                    int nx = cx + DX[d];
                    int ny = cy + DY[d];
                    if (sea.sailable(nx, ny, request.sailingLevel))
                    {
                        relax(nodes, open, heuristic, sea(nx, ny), g + SAIL, -1 - d);
                    }
                }
            }
            else
            {
                int x = x(node);
                int y = y(node);
                int z = z(node);
                int closed = closedSteps.get(node);
                for (int d = 0; d < 8; d++)
                {
                    if (closed != MISSING && (closed & 1 << d) != 0)
                    {
                        continue;
                    }
                    if (map.canStep(x, y, z, DX[d], DY[d]))
                    {
                        int next = pack(x + DX[d], y + DY[d], z);
                        if (avoid && wilderness(next))
                        {
                            keptOut = true;
                            continue;
                        }
                        int cost = step + (d < 4 && map.door(x, y, z, DX[d], DY[d]) ? DOOR : 0)
                            + (map.isObstacle(x + DX[d], y + DY[d], next) ? OBSTACLE : 0);
                        relax(nodes, open, heuristic, next, g + cost, -1 - d);
                    }
                }
                keptOut |= jumps(passagesByOrigin.get(node), all, nodes, open, heuristic, g, avoid);
            }
            keptOut |= jumps(requestByOrigin.get(node), all, nodes, open, heuristic, g, avoid);
        }
        // Tried everything, or proved from the goal's side: what was reached (or not) tells where else the target is out
        // of reach.
        boolean tried = !limited && open.isEmpty();
        boolean exhausted = found < 0 && (proof != null || tried);
        Reached reached = found >= 0 ? null : tried ? new Reached(nodes.reached(), false) : proof;
        int end = found >= 0 ? found : best;
        var steps = end < 0 ? List.<Step>of() : steps(nodes, all, startOffset, end, found >= 0 ? target : -1);
        Route route = end < 0 ? new Route(NONE, steps, 0, target, -1, exhausted, limited, popped, reached)
            : new Route(found >= 0 ? FOUND : NEAREST, steps, nodes.cost(end), target,
            steps.isEmpty() ? end : steps.get(steps.size() - 1).last(), exhausted, limited, popped, reached);
        return keptOut ? route.withKeptOut(true) : route;
    }

    /** Nodes the search pops between turns of the flood back from the goal (and checks for a cancel); a power of two. */
    static final int TURN = 4096;
    /**
     * Nodes the search goes on for once the goal is proved out of reach, for the nearest spot it gets to (the far side
     * of a locked door): the way there is what the player sees. A flood of the world would be about 1.7 million.
     */
    static final int NEAREST_NODES = 100_000;

    /**
     * The nodes the goal can be reached from, flooded back from it over the same ways the search takes forward (walking,
     * sailing, passages, the request's jumps), a turn at a time. Done, it holds them all: the goal is in reach from the
     * start or a teleport's landing only if they are in it.
     */
    final class Backward
    {
        final NodeSet seen = new NodeSet();
        int[] queue = new int[TURN];
        int head;
        int tail;
        final List<Edge> all;
        final EdgeIndex requestByDestination;
        final int sailingLevel;
        final boolean avoid;
        /** A step or jump out of the Wilderness was left out: through it, the goal may be in reach from more. */
        boolean keptOut;

        Backward(int goal, List<Edge> all, int requestOffset, RouteRequest request, boolean avoid)
        {
            this.all = all;
            requestByDestination = EdgeIndex.of(request.edges, requestOffset, true);
            sailingLevel = request.sailingLevel;
            this.avoid = avoid;
            visit(goal);
        }

        void visit(int node)
        {
            if (seen.add(node))
            {
                if (tail == queue.length)
                {
                    if (head > queue.length / 2)
                    {
                        System.arraycopy(queue, head, queue, 0, tail - head);
                        tail -= head;
                        head = 0;
                    }
                    else
                    {
                        queue = Arrays.copyOf(queue, queue.length * 2);
                    }
                }
                queue[tail++] = node;
            }
        }

        /** Floods up to {@code budget} nodes more; whether it is done (nothing more leads to the goal). */
        boolean flood(int budget)
        {
            while (head < tail && budget-- > 0)
            {
                int node = queue[head++];
                if (isSea(node))
                {
                    // Sailed into from any block around it, when it can be sailed.
                    int cx = cellX(node);
                    int cy = cellY(node);
                    if (sailingLevel >= 0 && sea.sailable(cx, cy, sailingLevel))
                    {
                        for (int d = 0; d < 8; d++)
                        {
                            visit(sea(cx + DX[d], cy + DY[d]));
                        }
                    }
                }
                else
                {
                    int x = x(node);
                    int y = y(node);
                    int z = z(node);
                    for (int d = 0; d < 8; d++)
                    {
                        int px = x - DX[d];
                        int py = y - DY[d];
                        if (!map.canStep(px, py, z, DX[d], DY[d]))
                        {
                            continue;
                        }
                        int from = pack(px, py, z);
                        int closed = closedSteps.get(from);
                        if (closed == MISSING || (closed & 1 << d) == 0)
                        {
                            visitFrom(from);
                        }
                    }
                }
                jumpsTo(passagesByDestination.get(node));
                jumpsTo(requestByDestination.get(node));
            }
            return head == tail;
        }

        void jumpsTo(int[] edges)
        {
            if (edges != null)
            {
                for (int i : edges)
                {
                    int from = all.get(i).from;
                    if (from != Edge.ANYWHERE)
                    {
                        visitFrom(from);
                    }
                }
            }
        }

        /** Kept out of the Wilderness, the search never stands there: not a node the goal is reached from. */
        void visitFrom(int from)
        {
            if (avoid && wilderness(from))
            {
                keptOut = true;
            }
            else
            {
                visit(from);
            }
        }

        /** Done: whether the goal is in reach from the start or from where a jump from anywhere lands. */
        boolean reaches(int start, int startOffset)
        {
            if (start >= 0 && seen.contains(start))
            {
                return true;
            }
            for (int i = startOffset; i < all.size(); i++)
            {
                int to = all.get(i).to;
                if (!(avoid && wilderness(to)) && seen.contains(to))
                {
                    return true;
                }
            }
            return false;
        }
    }

    /** Relaxes the jumps; whether one into the Wilderness was left out. */
    static boolean jumps(int[] edges, List<Edge> all, NodeTable nodes, LongHeap open, Heuristic heuristic, int g,
        boolean avoidWilderness)
    {
        if (edges == null)
        {
            return false;
        }
        boolean keptOut = false;
        for (int i : edges)
        {
            Edge e = all.get(i);
            if (!(avoidWilderness && wilderness(e.to)))
            {
                relax(nodes, open, heuristic, e.to, g + e.cost, i);
            }
            else
            {
                keptOut = true;
            }
        }
        return keptOut;
    }

    static void relax(NodeTable nodes, LongHeap open, Heuristic heuristic, int to, int cost, int via)
    {
        if (cost < nodes.cost(to))
        {
            nodes.put(to, cost, via);
            open.push(key(cost + heuristic.h(to), to));
        }
    }

    static long key(int f, int node)
    {
        return (long) f << 32 | (node & 0xffffffffL);
    }

    /** The node before on the way found: where its jump or step began; -1 at the start (or a jump from anywhere). */
    static int parent(NodeTable nodes, List<Edge> all, int startOffset, int node)
    {
        int via = nodes.via(node);
        int d = -1 - via;
        return via >= startOffset || via == NodeTable.START ? -1 : via >= 0 ? all.get(via).from : isSea(node)
            ? sea(cellX(node) - DX[d], cellY(node) - DY[d])
            : pack(x(node) - DX[d], y(node) - DY[d], z(node));
    }

    List<Step> steps(NodeTable nodes, List<Edge> all, int startOffset, int end, int target)
    {
        var reversed = new ArrayList<Step>();
        var run = new ArrayList<Integer>();
        int node = end;
        run.add(node);
        while (true)
        {
            int via = nodes.via(node);
            int parent = parent(nodes, all, startOffset, node);
            if (via >= 0)
            {
                flush(reversed, run, nodes);
                Edge e = all.get(via);
                int from = parent >= 0 ? parent : node;
                reversed.add(new Step(Step.Kind.valueOf(e.kind.name()), new int[]{from, node}, e.name,
                    e.detail, e.time, 0, Collections.emptyList(), e.category));
                run.clear();
            }
            if (parent < 0)
            {
                break;
            }
            run.add(parent);
            node = parent;
        }
        flush(reversed, run, nodes);
        Collections.reverse(reversed);
        int x = x(target);
        int y = y(target);
        int z = z(target);
        // A target one cannot stand on (a ladder clicked on the map): the free tiles beside it with no wall between.
        int[] beside = target < 0 || isSea(target) || map.walkable(x, y, z) ? new int[0] : IntStream.range(0, 4)
            .filter(d -> map.walkable(x + DX[d], y + DY[d], z) && map.straightOpen(x + DX[d], y + DY[d], z, -DX[d], -DY[d]))
            .map(d -> pack(x + DX[d], y + DY[d], z)).toArray();
        for (int i = 1; i <= reversed.size(); i++)
        {
            // Where the game walks as a passage (its sides) or that target is clicked where the walk to it starts.
            var walk = reversed.get(i - 1);
            var jump = i < reversed.size() ? reversed.get(i) : null;
            int[] game = walk.kind != Step.Kind.WALK ? null : GameWalk.path(map, walk.first(), jump == null ? beside
                : all.stream().filter(e -> e.from >= 0 && e.to == jump.last() && Objects.equals(e.name, jump.name))
                .mapToInt(e -> e.from).toArray());
            if (game != null && game.length <= walk.points.length)
            {
                int doors = (int) IntStream.range(1, game.length).filter(k -> map.door(x(game[k - 1]), y(game[k - 1]),
                    z(game[k]), x(game[k]) - x(game[k - 1]), y(game[k]) - y(game[k - 1]))).count();
                reversed.set(i - 1, new Step(Step.Kind.WALK, game, null, walk.detail,
                    walk.cost * (game.length - 1) / (walk.points.length - 1), doors, walk.obstacles, null));
                if (jump != null)
                {
                    jump.points[0] = game[game.length - 1];
                }
            }
        }
        return reversed;
    }

    /** {@code run} is collected backwards. */
    void flush(List<Step> reversed, List<Integer> run, NodeTable nodes)
    {
        if (run.size() >= 2)
        {
            int[] points = new int[run.size()];
            int doors = 0;
            for (int i = 0; i < points.length; i++)
            {
                points[i] = run.get(points.length - 1 - i);
            }
            for (int i = 1; i < points.length; i++)
            {
                int a = points[i - 1];
                int b = points[i];
                int dx = x(b) - x(a);
                int dy = y(b) - y(a);
                if (!isSea(a) && (dx == 0 || dy == 0) && map.door(x(a), y(a), z(a), dx, dy))
                {
                    doors++;
                }
            }
            int cost = nodes.cost(points[points.length - 1]) - nodes.cost(points[0]);
            boolean sailing = isSea(points[0]);
            var obstacles = new ArrayList<Obstacle>();
            StringBuilder detail = new StringBuilder();
            if (!sailing)
            {
                points = GameWalk.straighten(map, GameWalk.follow(map, points));
                for (int point : points)
                {
                    String obstacle = map.obstacle(point);
                    if (obstacle != null)
                    {
                        obstacles.add(new Obstacle(point, obstacle));
                        if (detail.indexOf(obstacle) < 0)
                        {
                            detail.append(detail.length() > 0 ? "; " : "").append(obstacle);
                        }
                    }
                }
            }
            reversed.add(new Step(sailing ? Step.Kind.SAIL : Step.Kind.WALK, points, null,
                sailing ? hazards(points) : detail.length() > 0 ? detail.toString() : null, cost, doors, obstacles, null));
        }
        // Only the last point stays.
        run.subList(0, max(0, run.size() - 1)).clear();
    }

    String hazards(int[] points)
    {
        var names = new LinkedHashSet<String>();
        for (int i = 0; i < points.length; i += 3)
        {
            var area = sea.nearest(x(points[i]), y(points[i]));
            if (area != null && area.level > 0 && !area.hazard.isEmpty())
            {
                names.add(area.hazard + " (" + area.name + ", " + area.level + " Sailing)");
            }
        }
        return names.isEmpty() ? null : "Crosses " + String.join(", ", names);
    }

    /** Folded distance, or via a jump's backward-searched bound; jump bounds cached per 8×8 block. */
    @RequiredArgsConstructor
    static final class Heuristic
    {
        final int goal;
        /** What a tile walked costs at least. */
        final int scale;
        final int[] origins;
        final int[] bounds;
        /** Per 128 × 128 folded tiles, its 8 × 8 blocks' bounds once worked out (-1 not yet): a flood needs 30,000. */
        final int[][] blocks = new int[1 << 14][];

        /** Per jump origin, the least cost from there to the goal by jumps, walking between them as the crow flies. */
        static int[][] bounds(List<Edge> jumps, int goal, int scale)
        {
            int n = jumps.size();
            long[] bound = new long[n];
            boolean[] done = new boolean[n];
            int[] from = new int[n];
            int[] to = new int[n];
            int[] cost = new int[n];
            for (int i = 0; i < n; i++)
            {
                Edge e = jumps.get(i);
                from[i] = e.from;
                to[i] = e.to;
                cost[i] = e.cost;
                bound[i] = (long) e.cost + scale * folded(e.to, goal);
            }
            // Backward Dijkstra over the jumps.
            for (int round = 0; round < n; round++)
            {
                int pick = -1;
                for (int i = 0; i < n; i++)
                {
                    if (!done[i] && (pick < 0 || bound[i] < bound[pick]))
                    {
                        pick = i;
                    }
                }
                done[pick] = true;
                for (int i = 0; i < n; i++)
                {
                    bound[i] = done[i] ? bound[i]
                        : min(bound[i], cost[i] + scale * folded(to[i], from[pick]) + bound[pick]);
                }
            }
            // Each origin once, in the order first met, with its least bound.
            var byOrigin = new LinkedHashMap<Integer, Integer>();
            for (int i = 0; i < n; i++)
            {
                byOrigin.merge(from[i], (int) min(Integer.MAX_VALUE, bound[i]), Math::min);
            }
            return new int[][]{byOrigin.keySet().stream().mapToInt(Integer::intValue).toArray(),
                byOrigin.values().stream().mapToInt(Integer::intValue).toArray()};
        }

        int h(int node)
        {
            int direct = scale * folded(node, goal);
            if (origins.length == 0)
            {
                return direct;
            }
            int bx = x(node) / BLOCK;
            int by = fy(node) / BLOCK;
            int block = (bx >> 4) << 7 | by >> 4;
            int cell = (bx & 15) << 4 | by & 15;
            var area = blocks[block];
            if (area == null)
            {
                area = new int[256];
                Arrays.fill(area, -1);
                blocks[block] = area;
            }
            int cached = area[cell];
            if (cached < 0)
            {
                int cx = bx * BLOCK + BLOCK / 2;
                int cy = by * BLOCK + BLOCK / 2;
                int min = Integer.MAX_VALUE;
                for (int i = 0; i < origins.length; i++)
                {
                    int d = max(abs(x(origins[i]) - cx), abs(fy(origins[i]) - cy));
                    min = min(min, scale * max(0, d - BLOCK / 2) + bounds[i]);
                }
                cached = min;
                area[cell] = cached;
            }
            return min(direct, cached);
        }
    }
}

package com.hdmapreforged.route;

import java.util.*;
import lombok.*;

/** What a route may use, taken on the client thread and read elsewhere. Immutable. */
@AllArgsConstructor(access = AccessLevel.PRIVATE)
public final class PlayerState
{
    public static final PlayerState UNKNOWN = new PlayerState(ItemSnapshot.NONE, 1, false, new int[0], true, false, -1,
        false, Collections.emptySet(), true);

    @With
    public final ItemSnapshot items;
    @With
    public final int sailingLevel;
    /** Pandemonium done: the player can sail their own boat. */
    @With
    public final boolean sailing;
    public final int[] boats;
    /** Per boat of {@link #boats}: its teleport focus, 0 none, 1 (Summon Boat), 2 greater (also Teleport to Boat). */
    @With
    public final int[] boatFocus;
    public final boolean running;
    @With
    public final boolean inHouse;
    /** In a house: where its portal leads out; outside: one's own house portal. -1 when not known. */
    public final int houseExit;
    @With
    public final boolean ownHouse;
    public final Set<String> houseFeatures;
    /** House teleports land inside (the house option Teleport Inside, as it is at first); else at the house portal. */
    public final boolean landsInside;
    /**
     * In an area whose way out leads back to where one came from (ReturnAreas: the Rune essence mine): where that is;
     * else -1.
     */
    @With
    public final int returnExit;
    /** With the bank's items too ({@link #withBank}): what is carried without them; else null. */
    @With
    public final ItemSnapshot carried;

    public PlayerState(ItemSnapshot items, int sailingLevel, boolean sailing, int[] boats, boolean running, boolean inHouse,
        int houseExit, boolean ownHouse, Set<String> houseFeatures, boolean landsInside)
    {
        this(items, sailingLevel, sailing, boats.clone(), new int[boats.length], running, inHouse, houseExit, ownHouse,
            Collections.unmodifiableSet(new LinkedHashSet<>(houseFeatures)), landsInside, -1, null);
    }

    /** The same, with other items or Sailing. */
    public PlayerState with(ItemSnapshot items, int sailingLevel, boolean sailing)
    {
        return withItems(items).withSailingLevel(sailingLevel).withSailing(sailing);
    }

    /** The same with the bank's items too, keeping what is carried apart (to say what to take out). */
    public PlayerState withBank(Map<Integer, Long> bank)
    {
        return withItems(items.plus(bank)).withCarried(items);
    }

    /**
     * The same in one's own house ({@code inside}: a route starting on its plan), or out of any house (a route's later
     * part, on from a bank, starts outside).
     */
    public PlayerState inOwnHouse(boolean inside)
    {
        return withInHouse(inside).withOwnHouse(inside);
    }
}

package com.hdmapreforged.route;

import java.io.*;
import java.util.*;

/** Where a boat lies at each Sailing port (ports.tsv, from the game cache), keyed by SAILING_BOAT_n_PORT values. */
public final class Ports
{
    public static final String RESOURCE = RouteFiles.DIR + "ports.tsv";

    /** Port id → packed tile of the boat. */
    public static Map<Integer, Integer> load() throws IOException
    {
        InputStream in = RouteFiles.require(RESOURCE);
        var ports = new HashMap<Integer, Integer>();
        Pathfinder.rows(in, 0, c -> {
            try
            {
                // Short rows and blank lines fail here too.
                var p = c[2].trim().split("\\s+");
                ports.put(Integer.parseInt(c[0].trim()), Tiles.pack(Integer.parseInt(p[0]), Integer.parseInt(p[1]), 0));
            }
            catch (NumberFormatException | ArrayIndexOutOfBoundsException e)
            {
                // Skip the row.
            }
        });
        return Collections.unmodifiableMap(ports);
    }
}

package com.hdmapreforged.route;

import lombok.*;

/**
 * Where a search proved its target out of reach from: with the same ways, from any of these nodes the target stays out
 * of reach. Either all a search that tried everything reached (what it could get to from there it got to from its
 * start), or everything but the nodes the target can be reached from, when the search flooded back from the target
 * instead ({@code complement}). Immutable once made.
 */
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
final class Reached
{
    final NodeSet nodes;
    final boolean complement;

    boolean contains(int node)
    {
        return node >= 0 && nodes.contains(node) != complement;
    }
}

package com.hdmapreforged.route;

import java.util.*;
import lombok.*;

/**
 * Areas whose way out leads back to where one came from (return_areas.tsv): the Rune essence mine's portals return one to
 * the wizard who sent one there, the Shipyard's portal to the shipwright. Read once. Immutable.
 */
public final class ReturnAreas
{
    public static final String RESOURCE = RouteFiles.DIR + "return_areas.tsv";

    @AllArgsConstructor(access = AccessLevel.PACKAGE)
    public static final class Area
    {
        public final String name;
        final int minX;
        final int minY;
        final int maxX;
        final int maxY;
        final int plane;
        /** The exit objects' tiles, packed. */
        public final int[] exits;
        /** The step's name ("Use Portal"). */
        public final String exitName;

        public boolean contains(int node)
        {
            return node >= 0 && !Tiles.isSea(node) && Tiles.z(node) == plane && Tiles.x(node) >= minX
                && Tiles.x(node) <= maxX && Tiles.y(node) >= minY && Tiles.y(node) <= maxY;
        }
    }

    static final RouteFiles.Table<List<Area>> AREAS = new RouteFiles.Table<>(ReturnAreas::read);

    /** The area holding the tile, or null. */
    public static Area at(int node)
    {
        return AREAS.get().stream().filter(area -> area.contains(node)).findFirst().orElse(null);
    }

    static List<Area> read()
    {
        return Pathfinder.table(RESOURCE, cells -> {
            var box = Pathfinder.ints(cells[1]);
            var tiles = cells[2].trim().split(";");
            int[] exits = new int[tiles.length];
            for (int i = 0; i < tiles.length; i++)
            {
                exits[i] = Tiles.parse(tiles[i].trim());
            }
            return new Area(cells[0].trim(), box[0], box[1], box[2], box[3], box[4], exits, cells[3].trim());
        });
    }
}

package com.hdmapreforged.route;

/**
 * Where the player stood before coming into an area whose way out leads back there (ReturnAreas: the Rune essence mine,
 * the Shipyard), so a route from inside knows where the exit leads. Not known when the player was inside already (logged
 * in there). Client thread only.
 */
public final class ReturnTracker
{
    int lastOutside = -1;
    ReturnAreas.Area inside;
    int exit = -1;

    public void update(int node)
    {
        var area = node < 0 ? null : ReturnAreas.at(node);
        if (area != null)
        {
            if (inside != area)
            {
                // Came in (or into another such area): from where one stood just before, if one was outside then.
                exit = inside == null && lastOutside >= 0 ? lastOutside : -1;
                inside = area;
            }
            return;
        }
        inside = null;
        exit = -1;
        if (node >= 0)
        {
            lastOutside = node;
        }
    }

    /** Where the exit of the area the player is in leads (where they came from), or -1. */
    public int exit()
    {
        return inside == null ? -1 : exit;
    }
}

package com.hdmapreforged.route;

import static com.hdmapreforged.route.Tiles.*;
import static lombok.AccessLevel.*;

import java.util.*;
import java.util.stream.*;
import lombok.*;

/** The result of a search: the steps, and how the target was reached (or why not). */
@AllArgsConstructor(access = PRIVATE)
public final class Route
{
    public enum Outcome
    {
        FOUND,
        NEAREST,
        NONE,
        CANCELLED
    }

    @AllArgsConstructor
    public static final class Obstacle
    {
        public final int at;
        public final String text;
    }

    @AllArgsConstructor
    public static final class Step
    {
        public enum Kind
        {
            WALK, SAIL, STAIRS, ENTRANCE, TELEPORT, TRANSPORT, SHIP, BOARD, DISEMBARK, HOUSE,
            /** Take from the bank what the steps after it need ({@link BankDetour}): both points the bank's tile. */
            BANK
        }

        public final Kind kind;
        /** Packed: all tiles walked or sea blocks sailed, or the two ends of a jump. */
        public final int[] points;
        @With(PACKAGE)
        public final String name;
        @With(PACKAGE)
        public final String detail;
        public final int cost;
        public final int doors;
        public final List<Obstacle> obstacles;
        /** Teleport or transport kind ("Hot air balloon"), to leave out all of that kind; or null. */
        public final String category;

        public int first()
        {
            return points[0];
        }

        public int last()
        {
            return points[points.length - 1];
        }

        public boolean isJump()
        {
            return kind != Kind.WALK && kind != Kind.SAIL;
        }
    }

    public final Outcome outcome;
    @With(PACKAGE)
    public final List<Step> steps;
    /** Half ticks. */
    public final int cost;
    public final int target;
    public final int end;
    @With(PACKAGE)
    public final boolean exhausted;
    public final boolean limited;
    public final int nodes;
    /** Where a search that proved the target out of reach proved it out of reach from; else null. */
    @With(PACKAGE)
    final Reached reached;
    /** Through the Wilderness though the player keeps out of it: no way around it gets there. */
    @With(PACKAGE)
    public final boolean throughWilderness;
    /** The search left out a step or jump into the Wilderness (kept out of it): through it, it may get further. */
    @With(PACKAGE)
    final boolean keptOut;

    /** Without the extra weight of teleports kept for longer trips. */
    public int time()
    {
        return steps.stream().mapToInt(step -> step.cost).sum();
    }

    public Route(Outcome outcome, List<Step> steps, int cost, int target, int end, boolean exhausted, boolean limited,
        int nodes)
    {
        this(outcome, steps, cost, target, end, exhausted, limited, nodes, null);
    }

    Route(Outcome outcome, List<Step> steps, int cost, int target, int end, boolean exhausted, boolean limited, int nodes,
        Reached reached)
    {
        this(outcome, Collections.unmodifiableList(steps), cost, target, end, exhausted, limited, nodes, reached, false,
            false);
    }

    /** This route, ending near the target of {@code shut}, which proved it out of reach. */
    Route near(Route shut)
    {
        return new Route(Outcome.NEAREST, steps, cost, shut.target, end, shut.exhausted, limited, nodes, shut.reached,
            throughWilderness, keptOut);
    }

    /**
     * This route, not proof that the target is out of reach: the search through the Wilderness after it stopped at the
     * node limit.
     */
    Route unproved()
    {
        return withExhausted(false).withReached(null);
    }

    public static final int NEAR = 12;

    /**
     * Up to its first teleport (or way of one's house): what comes after is drawn in the game once it is taken, so a
     * route out of the house and back in (to its fairy ring) does not draw both visits at once.
     */
    public Route untilTeleport()
    {
        for (int s = 0; s < steps.size() - 1; s++)
        {
            var kind = steps.get(s).kind;
            if (kind == Step.Kind.TELEPORT || kind == Step.Kind.HOUSE)
            {
                return withSteps(steps.subList(0, s + 1));
            }
        }
        return this;
    }

    /** What is still ahead of the player, like a navigation app; the route itself when the player is not near it. */
    public Route ahead(int player)
    {
        if (player < 0 || steps.isEmpty())
        {
            return this;
        }
        int bestStep = -1;
        int bestIndex = 0;
        long bestDistance = (long) (NEAR + 1) * (NEAR + 1);
        // Past a bank step nothing in one's house counts while one is in it: the route may go from the house to the bank
        // and back (its fairy ring), and in the house before it the bank is still to do.
        boolean banked = false;
        boolean home = HousePlan.contains(player);
        for (int s = 0; s < steps.size(); s++)
        {
            Step step = steps.get(s);
            if (step.kind == Step.Kind.BANK)
            {
                // Done only once what it takes out is used: standing at the bank it is still to do.
                banked = true;
                continue;
            }
            if (step.isJump())
            {
                int landing = step.last();
                int from = step.first();
                // Nearer where it starts (a gate, a door): not crossed yet.
                boolean before = from >= 0 && !isSea(from) && sameLevel(player, from)
                    && distance(player, from) < distance(player, landing);
                if (banked && home && HousePlan.contains(landing))
                {
                    continue;
                }
                // Into one's house (a teleport, its portal): anywhere in it, it was taken, wherever the game put one.
                boolean entered = from >= 0 && !HousePlan.contains(from) && HousePlan.contains(landing) && home;
                if (sameLevel(player, landing) && (distance(player, landing) <= 2 || entered) && !before)
                {
                    bestStep = s + 1;
                    bestIndex = 0;
                    bestDistance = 0;
                }
                continue;
            }
            for (int i = 0; i < step.points.length; i++)
            {
                int point = step.points[i];
                if (!sameLevel(player, point) || banked && home && HousePlan.contains(point))
                {
                    continue;
                }
                long dx = x(player) - x(point);
                long dy = y(player) - y(point);
                long d = dx * dx + dy * dy;
                if (isSea(point))
                {
                    d /= (long) CELL * CELL;
                }
                // Ties go to the later point, so a route passing a spot twice follows the player forward.
                if (d <= bestDistance)
                {
                    bestStep = s;
                    bestIndex = i;
                    bestDistance = d;
                }
            }
        }
        if (bestStep < 0 || bestStep == 0 && bestIndex == 0)
        {
            return this;
        }
        var left = new ArrayList<Step>();
        for (int s = bestStep; s < steps.size(); s++)
        {
            Step step = steps.get(s);
            if (s == bestStep && bestIndex > 0)
            {
                var rest = Arrays.copyOfRange(step.points, bestIndex, step.points.length);
                if (rest.length < 2)
                {
                    continue;
                }
                var obstaclesLeft = step.obstacles.stream()
                    .filter(o -> Arrays.stream(rest).anyMatch(p -> p == o.at)).collect(Collectors.toList());
                step = new Step(step.kind, rest, step.name, step.detail, step.cost * rest.length / step.points.length,
                    step.doors, obstaclesLeft, step.category);
            }
            left.add(step);
        }
        return withSteps(Collections.unmodifiableList(left)).withReached(null);
    }

    static boolean sameLevel(int a, int b)
    {
        return isSea(a) || isSea(b) || z(a) == z(b);
    }

    /**
     * Whether this search proved the target out of reach from the node too (it reached the node and tried everything,
     * or flooded back from the target and never came to the node), as long as the same ways may be used.
     */
    public boolean reached(int node)
    {
        return reached != null && reached.contains(node);
    }

    public boolean snapped()
    {
        return end >= 0 && end != target;
    }

    public boolean has(Step.Kind kind)
    {
        return first(kind) != null;
    }

    public Step first(Step.Kind kind)
    {
        return steps.stream().filter(step -> step.kind == kind).findFirst().orElse(null);
    }

    public String toString()
    {
        StringBuilder sb = new StringBuilder(outcome + " " + (cost + 1) / 2 + " ticks, " + nodes + " nodes");
        for (Step step : steps)
        {
            sb.append("\n  ").append(step.kind).append(' ').append(step.name == null ? "" : step.name).append(' ')
                .append(format(step.first())).append(" -> ").append(format(step.last()));
        }
        return sb.toString();
    }
}

package com.hdmapreforged.route;

import static com.hdmapreforged.route.Tiles.*;

import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.*;
import lombok.*;
import lombok.experimental.*;
import lombok.extern.slf4j.*;

/**
 * When to search, so it never happens too often: one search at a time; when the player strays, automatic searches
 * with a doubling pause, at most {@link #MAX_AUTOMATIC} in a row (again once back on the way, or walked on toward the
 * target), none where a search proved the target out of reach (until a user action, or until the ways it may use
 * change) and none in instances other than the house (their positions are template copies). Called on one thread
 * (Swing); results come back through {@code callbacks}, also when a search fails.
 */
@Slf4j
@RequiredArgsConstructor
@Accessors(fluent = true)
public final class RouteController
{
    static final long FIRST_BACKOFF_MS = 3_000;
    static final long MAX_BACKOFF_MS = 60_000;
    static final int MAX_AUTOMATIC = 6;
    /** Tiles from the route before the player counts as having left it: 10 away, as Shortest Path. */
    public static final int STRAY = 9;

    final Executor searches;
    final Executor callbacks;
    final Pathfinder pathfinder;
    /** Builds a search for a target, or null when there is no start. */
    final IntFunction<RouteRequest> requests;
    final Consumer<RouteController> changed;
    final LongSupplier clock;

    @Getter
    int target = -1;
    @Getter
    Route route;
    /** Where the route starts, or -1: before a first teleport the player stands there, on none of its steps. */
    int from = -1;
    /** What the route's search was asked; whether it was an automatic search asked the same ways as the one before. */
    RouteRequest asked;
    /** Whether the route came from an automatic search with the same ways as the one before: only the player moved. */
    @Getter
    boolean onlyMoved;
    AtomicBoolean running;
    /** A user search asked for while another ran; started when that one ends. */
    boolean pendingUser;
    int automatic;
    long backoff = FIRST_BACKOFF_MS;
    long nextAutomatic;
    /** Where the player was when an automatic search was last thought of, and the tick before; -1 none. */
    int searchedAt = -1;
    int lastPlayer = -1;
    /** The last tick's move was a jump; a jump from a steady spot (a teleport) not yet searched from. */
    boolean jumped;
    boolean teleported;
    /**
     * A search that tried everything without getting there, and what it was asked: from anywhere it reached, the
     * target stays out of reach while the same ways may be used.
     */
    Route unreachable;
    RouteRequest unreachableAsked;
    /** A message instead of a route, or null. */
    @Getter
    String status;
    /** A search could not start for want of a position, and when to try again. */
    boolean noStart;
    long nextStartTry;

    public void setTarget(int target)
    {
        userAction();
        this.target = target;
        route = null;
        status = "Searching…";
        start(true);
        changed.accept(this);
    }

    /** A route planned already (a custom route's next part, from {@code from}): shown as found, without a search. */
    public void show(int target, int from, Route planned)
    {
        userAction();
        cancelRunning();
        this.target = target;
        this.from = from;
        route = planned;
        status = null;
        changed.accept(this);
    }

    public void clear()
    {
        userAction();
        target = -1;
        route = null;
        status = null;
        noStart = false;
        cancelRunning();
        changed.accept(this);
    }

    public void cancelRunning()
    {
        if (running != null)
        {
            running.set(true);
            running = null;
        }
        pendingUser = false;
    }

    /** A setting that changes routes (or unlocks, bank) changed: search again once. */
    public void settingsChanged()
    {
        userAction();
        if (target >= 0)
        {
            start(true);
        }
    }

    void userAction()
    {
        unreachable = null;
        unreachableAsked = null;
        asked = null;
        onlyMoved = false;
        searchedAt = -1;
        freshWaits();
    }

    /** Automatic searches may start at once again, and wait as for the first. */
    void freshWaits()
    {
        automatic = 0;
        backoff = FIRST_BACKOFF_MS;
        nextAutomatic = 0;
    }

    /**
     * The player went into or out of the house: the ways from here are others (its portal, box and fairy ring first), so
     * any search runs again from here at once, without the waits of a stray; only the route's own next jump from
     * where one was (its teleport into the house, its fairy ring out), landed where it lands, keeps the route.
     */
    public void placeChanged(int player)
    {
        var next = route == null || running != null ? null
            : route.ahead(lastPlayer).steps.stream().filter(Route.Step::isJump).findFirst().orElse(null);
        if (target >= 0 && (next == null || player < 0 || !near(player, next.last(), STRAY)))
        {
            freshWaits();
            start(true);
        }
    }

    /** {@code player} packed or -1; starts a search when the player left the route. */
    public void playerMoved(int player, boolean automaticAllowed)
    {
        int before = lastPlayer;
        lastPlayer = player;
        // Teleported (or up or down) from a steady spot: off the route there it is searched at once, also when a search
        // ran then; a position jumping about every tick keeps its waits.
        boolean jump = before >= 0 && player >= 0 && !near(player, before, STRAY);
        if (jump)
        {
            teleported = !jumped;
        }
        jumped = jump;
        if (target >= 0 && running == null && route == null && noStart && player >= 0 && automaticAllowed)
        {
            // Asked for where the position was unknown: retried now and then once it is known.
            long now = clock.getAsLong();
            if (now >= nextStartTry)
            {
                nextStartTry = now + FIRST_BACKOFF_MS;
                status = "Searching…";
                start(true);
                changed.accept(this);
            }
            return;
        }
        if (jump && teleported && running != null && target >= 0 && automaticAllowed && player >= 0)
        {
            // Teleported (into the house, say) while a search from the old spot runs: it is for where one no longer
            // is, so it is replaced at once by one from here (the house's own ways first).
            start(true);
            return;
        }
        if (target < 0 || running != null || !automaticAllowed || player < 0 || route == null)
        {
            return;
        }
        if (onRoute(player))
        {
            // Back on the way: long trips get their automatic searches again.
            backoff = FIRST_BACKOFF_MS;
            automatic = 0;
            teleported = false;
            return;
        }
        long now = clock.getAsLong();
        if (teleported)
        {
            teleported = false;
            freshWaits();
        }
        if (searchedAt >= 0 && before >= 0 && near(player, before, 4) && !near(player, searchedAt, STRAY)
            && Pathfinder.folded(player, target) < Pathfinder.folded(searchedAt, target))
        {
            // Walked on toward the target past where the last search began (its route came too late to be on): a new
            // stray, no wait. Walking elsewhere keeps the waits and the cap, as does jumping about (a glitching position).
            freshWaits();
        }
        if (automatic >= MAX_AUTOMATIC || now < nextAutomatic)
        {
            return;
        }
        searchedAt = player;
        nextAutomatic = now + backoff;
        var request = requests.apply(target);
        // A search that tried everything reached where this one would start, with the same ways.
        if (request != null && unreachable != null && unreachableAsked.sameWays(request)
            && unreachable.reached(pathfinder.startNode(request.start)))
        {
            // Out of reach from here with these ways (proved): looked at again after the wait, not searched.
            return;
        }
        automatic++;
        backoff = Math.min(MAX_BACKOFF_MS, backoff * 2);
        start(request, false);
    }

    public static final int ARRIVED = 3;

    /** Within {@link #ARRIVED} tiles of the route's end (or the tile asked for), on the same floor. */
    public boolean arrived(int player)
    {
        if (player < 0 || route == null || isSea(player))
        {
            return false;
        }
        // A route that cannot get there ends where it gets stuck: no arrival.
        int end = route.outcome != Route.Outcome.FOUND ? -1 : route.end >= 0 ? route.end : target;
        return end >= 0 && Tiles.near(player, end, ARRIVED) || target >= 0 && Tiles.near(player, target, ARRIVED);
    }

    boolean onRoute(int player)
    {
        // With no steps: already there, or no start found, which a later position may fix. Its start: before a first
        // teleport.
        if (route.end >= 0 && near(player, route.end, STRAY) || from >= 0 && near(player, from, STRAY))
        {
            return true;
        }
        for (var step : route.steps)
        {
            if (step.isJump())
            {
                if (near(player, step.last(), STRAY) || step.first() != step.last() && near(player, step.first(), STRAY))
                {
                    return true;
                }
                continue;
            }
            for (int point : step.points)
            {
                if (near(player, point, isSea(point) ? STRAY + CELL : STRAY))
                {
                    return true;
                }
            }
        }
        return false;
    }

    static boolean near(int a, int b, int radius)
    {
        return Route.sameLevel(a, b) && distance(a, b) <= radius;
    }

    void start(boolean user)
    {
        if (running != null)
        {
            if (user)
            {
                // The newest user request wins: start it when the old one ends.
                running.set(true);
                pendingUser = true;
            }
            return;
        }
        start(requests.apply(target), user);
    }

    void start(RouteRequest request, boolean user)
    {
        noStart = request == null;
        if (request == null)
        {
            status = "Your position is not known here; try again outside";
            changed.accept(this);
            return;
        }
        var cancel = new AtomicBoolean();
        running = cancel;
        int searched = target;
        try
        {
            searches.execute(() -> {
                Route result = null;
                try
                {
                    result = BankDetour.find(pathfinder, request, cancel::get);
                }
                catch (Throwable e)
                {
                    log.warn("Route search to {} failed", format(searched), e);
                }
                finally
                {
                    Route done = result != null ? result : new Route(Route.Outcome.NONE,
                        Collections.emptyList(), 0, searched, -1, false, false, 0);
                    callbacks.execute(() -> finished(cancel, searched, request, user, done));
                }
            });
        }
        catch (RejectedExecutionException e)
        {
            running = null;
        }
    }

    void finished(AtomicBoolean search, int searched, RouteRequest request, boolean user, Route result)
    {
        if (running == search)
        {
            running = null;
        }
        if (pendingUser && running == null)
        {
            pendingUser = false;
            if (target >= 0)
            {
                start(true);
                return;
            }
        }
        if (search.get() || searched != target || result.outcome == Route.Outcome.CANCELLED)
        {
            return;
        }
        onlyMoved = !user && asked != null && asked.sameWays(request);
        route = result;
        from = request.start;
        asked = request;
        if (result.exhausted && result.outcome != Route.Outcome.FOUND)
        {
            unreachable = result;
            unreachableAsked = request;
        }
        status = null;
        changed.accept(this);
    }
}

package com.hdmapreforged.route;

import java.io.*;
import java.util.*;
import java.util.function.*;
import java.util.zip.*;
import lombok.*;

/**
 * The route planner's tables (passages, gates, the collision map, ...): a map version's route.zip from the map server,
 * so they are fixed without a plugin update; before one is given (tests, development tools) the classpath.
 */
public final class RouteFiles
{
    /** Where the route tables lie on the classpath; a route.zip holds them by their file names alone. */
    public static final String DIR = "/com/hdmapreforged/route/";
    static final int MAX_FILE_BYTES = 16 * 1024 * 1024;
    static final int MAX_TOTAL_BYTES = 32 * 1024 * 1024;
    static final int MAX_FILES = 100;
    static volatile Map<String, byte[]> files;
    /** Counts the route.zips used, so tables read from them are read again. */
    static volatile int generation;

    /** Uses a map version's route.zip: its files by name ("links.tsv", "collision.zip"). */
    public static void use(byte[] zip) throws IOException
    {
        var read = new HashMap<String, byte[]>();
        long total = 0;
        try (ZipInputStream in = new ZipInputStream(new ByteArrayInputStream(zip)))
        {
            for (ZipEntry entry; (entry = in.getNextEntry()) != null; )
            {
                if (!entry.isDirectory())
                {
                    var bytes = read(in, MAX_FILE_BYTES, entry.getName());
                    total += bytes.length;
                    if (total > MAX_TOTAL_BYTES || read.size() >= MAX_FILES)
                    {
                        throw new IOException("Route data too large");
                    }
                    read.put(entry.getName().substring(entry.getName().lastIndexOf('/') + 1), bytes);
                }
            }
        }
        files = read;
        generation++;
    }

    /** The rest of a zip entry; more than {@code max} bytes is an error, so a small zip never fills the memory. */
    static byte[] read(InputStream in, int max, String name) throws IOException
    {
        var bytes = in.readNBytes(max + 1);
        if (bytes.length > max)
        {
            throw new IOException("Route file too large: " + name);
        }
        return bytes;
    }

    /** Whether the tables can be read: a route.zip is in use, or the classpath has them (tests, development tools). */
    public static boolean available()
    {
        if (files != null)
        {
            return true;
        }
        try (InputStream in = RouteFiles.class.getResourceAsStream(CollisionMap.RESOURCE))
        {
            return in != null;
        }
        catch (IOException e)
        {
            return false;
        }
    }

    /** A table by its resource path ("/com/hdmapreforged/route/links.tsv"); null when there is none. */
    public static InputStream open(String resource)
    {
        var given = files;
        if (given == null)
        {
            return RouteFiles.class.getResourceAsStream(resource);
        }
        var bytes = given.get(resource.substring(resource.lastIndexOf('/') + 1));
        return bytes == null ? null : new ByteArrayInputStream(bytes);
    }

    /** The same, where a missing table is an error. */
    static InputStream require(String resource) throws IOException
    {
        InputStream in = open(resource);
        if (in == null)
        {
            throw new IOException("Missing " + resource);
        }
        return in;
    }

    /**
     * What is read from a table, read again once another route.zip is used; without a lock once read (the planner asks
     * in its inner loop).
     */
    @RequiredArgsConstructor
    public static final class Table<T>
    {
        final Supplier<T> read;
        volatile int readAt = -1;
        volatile T value;

        public T get()
        {
            int now = generation;
            if (readAt != now)
            {
                synchronized (this)
                {
                    if (readAt != now)
                    {
                        try
                        {
                            value = read.get();
                        }
                        finally
                        {
                            // Once per route.zip, also when the read fails: then what was read before stays.
                            readAt = now;
                        }
                    }
                }
            }
            return value;
        }
    }
}

package com.hdmapreforged.route;

import java.util.*;
import lombok.*;

/** Immutable. */
@AllArgsConstructor
public final class RouteRequest
{
    /**
     * Past it the search stops where it is, without a verdict. A flood of the world is about 1.7 million nodes (and
     * the search table about 100 MB), which only a far trip with no way there at all still takes: a target shut off
     * from the player is proved out of reach from its own side (Pathfinder's flood back from the goal).
     */
    public static final int DEFAULT_NODE_LIMIT = 3_000_000;

    /** -1 when the route can only start with {@link #startEdges} (in a house). */
    public final int start;
    public final int target;
    /** Teleports, and the ways out of a player-owned house. */
    public final List<Edge> startEdges;
    public final List<Edge> edges;
    /** -1 when they cannot sail their own boat. */
    public final int sailingLevel;
    public final boolean running;
    public final int nodeLimit;
    /**
     * Stay out of the Wilderness, unless the route starts or ends in it; when no way around it gets there, the route goes
     * through it ({@link #throughWilderness()}).
     */
    public final boolean avoidWilderness;
    /**
     * The same with their boat, searched when this one (left without it) does not arrive; else null. {@code withBoat}:
     * this one with it.
     */
    @With
    public final RouteRequest boat;
    /** A way past a bank first, for what is kept there (setting); else null. {@code withBank}: the same with one. */
    @With
    public final BankDetour bank;

    public RouteRequest(int start, int target, List<Edge> startEdges, List<Edge> edges, int sailingLevel, boolean running,
        int nodeLimit)
    {
        this(start, target, startEdges, edges, sailingLevel, running, nodeLimit, false);
    }

    public RouteRequest(int start, int target, List<Edge> startEdges, List<Edge> edges, int sailingLevel, boolean running,
        int nodeLimit, boolean avoidWilderness)
    {
        this(start, target, Collections.unmodifiableList(startEdges), Collections.unmodifiableList(edges), sailingLevel,
            running, nodeLimit, avoidWilderness, null, null);
    }

    /** The same ways between other ends. */
    public RouteRequest between(int start, int target)
    {
        return new RouteRequest(start, target, startEdges, edges, sailingLevel, running, nodeLimit, avoidWilderness,
            boat == null ? null : boat.between(start, target), null);
    }

    /** The same ways, through the Wilderness too: searched when staying out of it does not arrive. */
    public RouteRequest throughWilderness()
    {
        return new RouteRequest(start, target, startEdges, edges, sailingLevel, running, nodeLimit, false,
            boat == null ? null : boat.throughWilderness(), bank);
    }

    /** Whether a search may use the same ways as with {@code other} (jumps and sea): what it reaches differs by start only. */
    boolean sameWays(RouteRequest other)
    {
        return sailingLevel == other.sailingLevel && avoidWilderness == other.avoidWilderness
            && (boat == null) == (other.boat == null) && same(edges, other.edges)
            && same(startEdges, other.startEdges);
    }

    static boolean same(List<Edge> a, List<Edge> b)
    {
        for (int i = 0; i < a.size() && a.size() == b.size(); i++)
        {
            if (a.get(i).from != b.get(i).from || a.get(i).to != b.get(i).to)
            {
                return false;
            }
        }
        return a.size() == b.size();
    }
}

package com.hdmapreforged.route;

import static com.hdmapreforged.route.Tiles.CELL;

import java.io.*;
import java.util.*;
import lombok.*;

/**
 * Where a boat can sail: ground floor water in CELL×CELL blocks, open sea when mostly water (boats keep off rivers
 * and shores). Each block takes the hazard level of the nearest named sea (approximate near borders). Made once per
 * map version by the map server (the version's sea.bin), with its seas (sea_areas.tsv). Immutable.
 */
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
public final class SeaMap
{
    static final String AREAS = RouteFiles.DIR + "sea_areas.tsv";
    /** No sea here. */
    static final byte NONE = -2;
    /** Sea no boat can cross yet. */
    static final byte CLOSED = -1;

    @RequiredArgsConstructor(access = AccessLevel.PACKAGE)
    public static final class Area
    {
        public final String name;
        public final int x;
        public final int y;
        final String hazard;
        /** 0 for none, -1 when it cannot be crossed. */
        public final int level;
    }

    /** Per region, per 16×16 block: the level needed, NONE or CLOSED; null when no sea. */
    final byte[][] blocks = new byte[1 << 15][];
    final List<Area> areas;

    /**
     * Per region with sea, sea.bin holds its number (two bytes) and its 256 blocks. A map version without one (up to
     * cache-2727.40) has no sea: no sailing, but the planner still loads.
     */
    public static SeaMap load() throws IOException
    {
        var sea = new SeaMap(Collections.unmodifiableList(readAreas(RouteFiles.require(AREAS))));
        try (var in = new DataInputStream(RouteFiles.require(RouteFiles.DIR + "sea.bin")))
        {
            for (int high; (high = in.read()) >= 0; )
            {
                byte[] cells = new byte[256];
                int region = high << 8 | in.readUnsignedByte();
                in.readFully(cells);
                sea.blocks[region] = cells;
            }
        }
        catch (IOException | RuntimeException e)
        {
            // What was read.
        }
        return sea;
    }

    /** The seas {@code in} lists; closes it. */
    static List<Area> readAreas(InputStream in) throws IOException
    {
        var areas = new ArrayList<Area>();
        Pathfinder.rows(in, -1, c -> {
            // Blank lines are short rows too.
            if (c.length < 6)
            {
                return;
            }
            try
            {
                // Name, ocean (not used), x, y, hazard, level.
                areas.add(new Area(c[0], Integer.parseInt(c[2].trim()), Integer.parseInt(c[3].trim()), c[4],
                    Integer.parseInt(c[5].trim())));
            }
            catch (NumberFormatException e)
            {
                // Skip the row.
            }
        });
        return areas;
    }

    public Area nearest(int x, int y)
    {
        Area best = null;
        long bestDistance = Long.MAX_VALUE;
        for (Area area : areas)
        {
            long dx = area.x - x;
            long dy = area.y - y;
            long d = dx * dx + dy * dy;
            if (d < bestDistance)
            {
                bestDistance = d;
                best = area;
            }
        }
        return best;
    }

    /** The level a block needs, NONE or CLOSED. */
    int level(int cellX, int cellY)
    {
        if (cellX < 0 || cellY < 0 || cellX >= 1 << 12 || cellY >= 1 << 12)
        {
            return NONE;
        }
        int region = (cellX >> 4) << 8 | (cellY >> 4);
        if (region >= 1 << 15)
        {
            return NONE;
        }
        var cells = blocks[region];
        return cells == null ? NONE : cells[(cellX & 15) << 4 | (cellY & 15)];
    }

    public boolean sailable(int cellX, int cellY, int sailingLevel)
    {
        int level = level(cellX, cellY);
        return level >= 0 && sailingLevel >= level;
    }

    /** The nearest sailable block within {@code radius} tiles, as a packed sea node, or -1. */
    public int nearestBlock(int x, int y, int radius, int sailingLevel)
    {
        int best = -1;
        long bestDistance = Long.MAX_VALUE;
        for (int cx = (x - radius) / CELL; cx <= (x + radius) / CELL; cx++)
        {
            for (int cy = (y - radius) / CELL; cy <= (y + radius) / CELL; cy++)
            {
                if (!sailable(cx, cy, sailingLevel))
                {
                    continue;
                }
                long dx = cx * CELL + CELL / 2 - x;
                long dy = cy * CELL + CELL / 2 - y;
                long d = dx * dx + dy * dy;
                if (d < bestDistance && d <= (long) radius * radius)
                {
                    bestDistance = d;
                    best = Tiles.sea(cx, cy);
                }
            }
        }
        return best;
    }
}

package com.hdmapreforged.route;

import java.io.*;
import java.nio.charset.*;
import java.util.*;
import java.util.stream.*;
import lombok.*;

/**
 * A planner passage that is an Agility shortcut (shortcuts.tsv). It knows nothing of the shortcut's level, so
 * RouteSource adds it per request only when the requirements are met.
 */
public final class ShortcutPassage
{
    /** How near the shortcut's start (or end) the passage must be, in tiles. */
    static final int RADIUS = 3;

    public final Edge edge;
    /**
     * Each row's Needs columns (skills, items, quests, varbits), first row first: any one met will do (a grapple
     * shortcut with its grapple, or bare-handed at a higher Agility level).
     */
    public final List<String[]> ways;

    ShortcutPassage(Edge edge, List<Shortcut> shortcuts)
    {
        this.edge = edge;
        ways = shortcuts.stream().map(s -> s.way).collect(Collectors.toUnmodifiableList());
    }

    @RequiredArgsConstructor
    static final class Shortcut
    {
        /** Lower case: "Rocks (Waterbirth Island)" is "rocks". */
        final String object;
        final int origin;
        final int destination;
        final String[] way;

        /** It starts or ends here, and its name names the object (looked at only then: 15,000 passages, 200 shortcuts). */
        boolean stands(Edge e)
        {
            return e.name != null && (near(e.from, origin) || near(e.to, origin) || destination >= 0
                && (near(e.from, destination) || near(e.to, destination))) && e.name.toLowerCase(Locale.ROOT).contains(object);
        }

        static boolean near(int a, int b)
        {
            return Tiles.near(a, b, RADIUS);
        }
    }

    static final RouteFiles.Table<List<Shortcut>> ALL = new RouteFiles.Table<>(ShortcutPassage::shortcuts);

    /**
     * The Agility shortcut a passage crosses (one of the cache's, say), with what the shortcut needs; null when it
     * crosses none.
     */
    public static ShortcutPassage of(Edge edge)
    {
        var standing = known().stream().filter(s -> s.stands(edge)).collect(Collectors.toList());
        return standing.isEmpty() ? null : new ShortcutPassage(edge, standing);
    }

    /** Every row's Needs columns (skills, items, quests, varbits): what the requirements read must watch. */
    public static List<String[]> allWays()
    {
        return known().stream().map(s -> s.way).collect(Collectors.toList());
    }

    static List<Shortcut> known()
    {
        return ALL.get();
    }

    /** "Rocks (Waterbirth Island)" → "rocks"; "Pillar Jump (Easy) (Revenant Caves)" → "pillar". */
    static String object(String name)
    {
        String plain = name.replaceAll("\\s*\\(.*$", "").trim().toLowerCase(Locale.ROOT);
        return plain.startsWith("pillar jump") ? "pillar" : plain;
    }

    static List<Shortcut> shortcuts()
    {
        InputStream in = RouteFiles.open("/com/hdmapreforged/data/shortcuts.tsv");
        if (in == null)
        {
            return Collections.emptyList();
        }
        var list = new ArrayList<Shortcut>();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
        {
            String[] header = null;
            String line;
            while ((line = reader.readLine()) != null)
            {
                if (line.startsWith("# Name"))
                {
                    header = line.substring(2).split("\t", -1);
                    continue;
                }
                if (line.startsWith("#") || line.trim().isEmpty() || header == null)
                {
                    continue;
                }
                var cells = line.split("\t", -1);
                String object = object(cell(header, cells, "Name"));
                int origin = Tiles.parse(cell(header, cells, "Origin"));
                // An empty object name would match every edge nearby.
                if (origin < 0 || object.isEmpty())
                {
                    continue;
                }
                list.add(new Shortcut(object, origin, Tiles.parse(cell(header, cells, "Destination")), new String[]{
                    cell(header, cells, "Skills"), cell(header, cells, "Items"), cell(header, cells, "Quests"),
                    cell(header, cells, "Varbits")}));
            }
        }
        catch (IOException | RuntimeException e)
        {
            return list;
        }
        return list;
    }

    static String cell(String[] header, String[] cells, String column)
    {
        for (int i = 0; i < header.length; i++)
        {
            if (header[i].trim().equals(column))
            {
                return i < cells.length ? cells[i].trim() : "";
            }
        }
        return "";
    }
}

package com.hdmapreforged.route;

import java.util.*;

/** Route graph nodes as ints: a game tile, or with {@link #SEA} set a 4×4 block of sea tiles on the ground floor. */
public final class Tiles
{
    public static final int SEA = 1 << 30;
    public static final int CELL = 4;

    /**
     * The Wilderness's safe zones and the ground south of its edge (the map version's wilderness.tsv); a row of fewer
     * than four numbers holds no tile.
     */
    static final RouteFiles.Table<List<int[]>> ZONES = new RouteFiles.Table<>(() -> Pathfinder.table(RouteFiles.DIR
        + "wilderness.tsv", c -> Arrays.copyOf(Pathfinder.ints(c[1]), 4)));

    public static int pack(int x, int y, int z)
    {
        return (z & 3) << 28 | (x & 0x3fff) << 14 | (y & 0x3fff);
    }

    public static int x(int node)
    {
        return isSea(node) ? cellX(node) * CELL + CELL / 2 : node >> 14 & 0x3fff;
    }

    public static int y(int node)
    {
        return isSea(node) ? cellY(node) * CELL + CELL / 2 : node & 0x3fff;
    }

    public static int z(int node)
    {
        return isSea(node) ? 0 : node >> 28 & 3;
    }

    public static boolean isSea(int node)
    {
        return (node & SEA) != 0;
    }

    public static int sea(int cellX, int cellY)
    {
        return SEA | (cellX & 0xfff) << 12 | (cellY & 0xfff);
    }

    public static int cellX(int node)
    {
        return node >> 12 & 0xfff;
    }

    public static int cellY(int node)
    {
        return node & 0xfff;
    }

    public static int seaAt(int x, int y)
    {
        return sea(x / CELL, y / CELL);
    }

    /** {@code "x y plane"} packed; -1 when it is not one. */
    public static int parse(String text)
    {
        var xyz = text.trim().split("\\s+");
        if (xyz.length != 3)
        {
            return -1;
        }
        for (String part : xyz)
        {
            // Too many digits: not a tile (and no overflow).

            if (part.isEmpty() || part.length() > 5 || !part.chars().allMatch(Character::isDigit))
            {
                return -1;
            }
        }
        int x = Integer.parseInt(xyz[0]);
        int y = Integer.parseInt(xyz[1]);
        int z = Integer.parseInt(xyz[2]);
        return x < 1 << 14 && y < 1 << 14 && z < 4 ? pack(x, y, z) : -1;
    }

    public static String format(int node)
    {
        return x(node) + ", " + y(node) + ", " + z(node) + (isSea(node) ? " (sea)" : "");
    }

    /**
     * In the Wilderness: above ground x 2944-3391, y 3520-3967, and its dungeons 6400 tiles north of that; not its safe
     * zones, nor the ground south of its edge ({@link #ZONES}).
     */
    public static boolean wilderness(int node)
    {
        if (isSea(node))
        {
            return false;
        }
        int x = x(node);
        int y = y(node);
        return x >= 2944 && x <= 3391 && (y >= 3520 && y <= 3967 || y >= 9920 && y <= 10367)
            && !within(ZONES.get(), x, y);
    }

    static boolean within(List<int[]> zones, int x, int y)
    {
        for (var zone : zones)
        {
            if (x >= zone[0] && x <= zone[1] && y >= zone[2] && y <= zone[3])
            {
                return true;
            }
        }
        return false;
    }

    /** On the same floor (the sea's is 0) and within {@code radius} tiles. */
    public static boolean near(int a, int b, int radius)
    {
        return z(a) == z(b) && distance(a, b) <= radius;
    }

    /** Chebyshev distance in tiles, ignoring floors. */
    public static int distance(int a, int b)
    {
        return Math.max(Math.abs(x(a) - x(b)), Math.abs(y(a) - y(b)));
    }
}

package com.hdmapreforged.route;

import lombok.*;

/** A ladder, staircase, trapdoor or entrance from the game cache: an object's footprint and where it leads. */
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
public final class Transition
{
    public final int x;
    public final int y;
    public final int plane;
    public final int sizeX;
    public final int sizeY;
    public final int to;
    public final String name;
    public final String action;
    public final int[] origins;
    /** A solid object walked through (a gate, a gap), found by shape: it may ask for a quest or level. */
    public final boolean through;

    /** {@code "x y plane sizeX sizeY <tab> x y plane <tab> name <tab> action <tab> x y;x y"}; null for bad lines. */
    static Transition parse(String line)
    {
        if (line.isEmpty() || line.startsWith("#"))
        {
            return null;
        }
        var cols = line.split("\t");
        if (cols.length < 5)
        {
            return null;
        }
        try
        {
            var from = Pathfinder.ints(cols[0]);
            var to = Pathfinder.ints(cols[1]);
            int z = from[2];
            if (from.length != 5 || to.length != 3 || !valid(from[0], from[1], z) || !valid(to[0], to[1], to[2])
                || from[3] < 1 || from[4] < 1 || from[3] > 16 || from[4] > 16)
            {
                return null;
            }
            var tiles = cols[4].trim().split(";");
            int[] origins = new int[tiles.length];
            for (int i = 0; i < tiles.length; i++)
            {
                var xy = Pathfinder.ints(tiles[i]);
                if (xy.length != 2 || !valid(xy[0], xy[1], z))
                {
                    return null;
                }
                origins[i] = Tiles.pack(xy[0], xy[1], z);
            }
            return new Transition(from[0], from[1], z, from[3], from[4], Tiles.pack(to[0], to[1], to[2]), cols[2].trim(),
                cols[3].trim(), origins, cols.length > 5 && "through".equals(cols[5].trim()));
        }
        catch (NumberFormatException | ArrayIndexOutOfBoundsException e)
        {
            return null;
        }
    }

    static boolean valid(int x, int y, int z)
    {
        return x >= 0 && y >= 0 && x < 1 << 14 && y < 1 << 14 && z >= 0 && z < 4;
    }
}

package com.hdmapreforged.route;

import java.util.*;

/** How far a dungeon, cave or room reaches on its floor, to fit the map to the dungeon one enters. */
public final class WalkableArea
{

    /** {minX, minY, maxX, maxY} of the tiles walkable from a point, or null when none or over {@code limit} tiles. */
    public static int[] bounds(CollisionMap map, int x, int y, int z, int limit)
    {
        int start = map.walkable(x, y, z) ? Tiles.pack(x, y, z) : map.nearestWalkable(x, y, z, 4);
        if (start < 0)
        {
            return null;
        }
        BitSet seen = new BitSet();
        // Dungeons never span more than this.
        int size = 1024;
        int sx = Tiles.x(start);
        int sy = Tiles.y(start);
        int ox = sx - size / 2;
        int oy = sy - size / 2;
        var open = new ArrayDeque<int[]>();
        open.add(new int[]{sx, sy});
        seen.set((sx - ox) * size + (sy - oy));
        int[] b = {sx, sy, sx, sy};
        int count = 0;
        while (!open.isEmpty())
        {
            var p = open.poll();
            if (++count > limit)
            {
                return null;
            }
            b[0] = Math.min(b[0], p[0]);
            b[1] = Math.min(b[1], p[1]);
            b[2] = Math.max(b[2], p[0]);
            b[3] = Math.max(b[3], p[1]);
            for (int d = 0; d < 8; d++)
            {
                int nx = p[0] + Pathfinder.DX[d];
                int ny = p[1] + Pathfinder.DY[d];
                int wx = nx - ox;
                int wy = ny - oy;
                if (wx < 0 || wy < 0 || wx >= size || wy >= size || seen.get(wx * size + wy)
                    || !map.canStep(p[0], p[1], z, Pathfinder.DX[d], Pathfinder.DY[d]))
                {
                    continue;
                }
                seen.set(wx * size + wy);
                open.add(new int[]{nx, ny});
            }
        }
        return b;
    }
}
